INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000000','Apa definisi utama dari petrofisika dalam konteks teknik perminyakan?','option','PFM000000001','a:4:{i:0;s:86:"Studi mengenai sifat fisik dan kimia batuan serta interaksinya dengan fluida reservoir";i:1;s:59:"Analisis mekanika fluida pada pipa produksi bawah permukaan";i:2;s:57:"Perhitungan cadangan minyak menggunakan metode volumetrik";i:3;s:51:"Studi mengenai desain pemboran sumur minyak dan gas";}','','Studi mengenai sifat fisik dan kimia batuan serta interaksinya dengan fluida reservoir','What is the primary definition of petrophysics in the context of petroleum engineering?','a:4:{i:0;s:98:"The study of physical and chemical properties of rocks and their interaction with reservoir fluids";i:1;s:59:"Analysis of fluid mechanics in subsurface production tubing";i:2;s:52:"Calculation of oil reserves using volumetric methods";i:3;s:41:"Study of oil and gas well drilling design";}','The study of physical and chemical properties of rocks and their interaction with reservoir fluids','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000001','Parameter petrofisika manakah yang termasuk dalam kategori sifat fisik batuan reservoir yang utama?','multi','PFM000000001','a:4:{i:0;s:9:"Porositas";i:1;s:13:"Permeabilitas";i:2;s:19:"Tekanan hidrostatik";i:3;s:17:"Viskositas lumpur";}','','a:2:{i:0;s:9:"Porositas";i:1;s:13:"Permeabilitas";}','Which petrophysical parameters are included in the primary physical properties of reservoir rocks?','a:4:{i:0;s:8:"Porosity";i:1;s:12:"Permeability";i:2;s:20:"Hydrostatic pressure";i:3;s:13:"Mud viscosity";}','a:2:{i:0;s:8:"Porosity";i:1;s:12:"Permeability";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000002','Data yang diperoleh langsung dari pengambilan sampel batuan di bawah permukaan disebut sebagai:','option','PFM000000001','a:4:{i:0;s:9:"Data Core";i:1;s:8:"Data Log";i:2;s:11:"Data Mudlog";i:3;s:13:"Data Produksi";}','','Data Core','Data obtained directly from subsurface rock samples is referred to as:','a:4:{i:0;s:9:"Core data";i:1;s:8:"Log data";i:2;s:11:"Mudlog data";i:3;s:15:"Production data";}','Core data','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000003','Manakah pernyataan yang paling tepat mengenai tujuan utama petrofisika?','option','PFM000000001','a:4:{i:0;s:69:"Menentukan potensi penyimpanan dan kemampuan alir fluida dalam batuan";i:1;s:42:"Mengatur laju produksi harian sumur minyak";i:2;s:37:"Mendesain casing dan semen pada sumur";i:3;s:37:"Menentukan biaya operasional pemboran";}','','Menentukan potensi penyimpanan dan kemampuan alir fluida dalam batuan','Which statement is the most accurate regarding the primary objective of petrophysics?','a:4:{i:0;s:66:"Determining the storage potential and fluid flow capacity in rocks";i:1;s:42:"Regulating daily oil well production rates";i:2;s:40:"Designing casing and cementing for wells";i:3;s:38:"Determining drilling operational costs";}','Determining the storage potential and fluid flow capacity in rocks','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000004','Peralatan atau metode apa yang umum digunakan untuk mendapatkan data log resistivitas di dalam lubang bor?','option','PFM000000001','a:4:{i:0;s:21:"Wireline logging tool";i:1;s:20:"Bit cutting analysis";i:2;s:11:"Core barrel";i:3;s:15:"Drill stem test";}','','Wireline logging tool','What tool or method is commonly used to obtain resistivity log data inside a borehole?','a:4:{i:0;s:21:"Wireline logging tool";i:1;s:20:"Bit cutting analysis";i:2;s:11:"Core barrel";i:3;s:15:"Drill stem test";}','Wireline logging tool','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000005','Parameter batuan manakah yang paling menentukan kapasitas penyimpanan fluida dalam suatu reservoar?','option','PFM000000002','a:4:{i:0;s:13:"Permeabilitas";i:1;s:9:"Porositas";i:2;s:15:"Tekanan kapiler";i:3;s:12:"Resistivitas";}','','Porositas','Which rock parameter primarily determines the fluid storage capacity in a reservoir?','a:4:{i:0;s:12:"Permeability";i:1;s:8:"Porosity";i:2;s:18:"Capillary pressure";i:3;s:11:"Resistivity";}','Porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000006','Apa peran utama ahli petrofisika dalam kolaborasi dengan insinyur reservoar?','multi','PFM000000002','a:4:{i:0;s:31:"Menentukan saturasi hidrokarbon";i:1;s:49:"Menentukan distribusi porositas dan permeabilitas";i:2;s:37:"Melakukan pengeboran sumur eksplorasi";i:3;s:40:"Menghitung cadangan minyak secara statis";}','','a:3:{i:0;s:31:"Menentukan saturasi hidrokarbon";i:1;s:49:"Menentukan distribusi porositas dan permeabilitas";i:2;s:40:"Menghitung cadangan minyak secara statis";}','What is the primary role of a petrophysicist in collaboration with reservoir engineers?','a:4:{i:0;s:34:"Determining hydrocarbon saturation";i:1;s:50:"Determining porosity and permeability distribution";i:2;s:36:"Performing exploratory well drilling";i:3;s:31:"Calculating static oil reserves";}','a:3:{i:0;s:34:"Determining hydrocarbon saturation";i:1;s:50:"Determining porosity and permeability distribution";i:2;s:31:"Calculating static oil reserves";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000007','Alat ukur logging manakah yang paling efektif digunakan untuk membedakan zona hidrokarbon dari zona air?','option','PFM000000002','a:4:{i:0;s:9:"Gamma Ray";i:1;s:12:"Resistivitas";i:2;s:8:"Densitas";i:3;s:7:"Neutron";}','','Resistivitas','Which logging tool is most effectively used to distinguish hydrocarbon zones from water zones?','a:4:{i:0;s:9:"Gamma Ray";i:1;s:11:"Resistivity";i:2;s:7:"Density";i:3;s:7:"Neutron";}','Resistivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000008','Dalam fase pengembangan lapangan, data petrofisika digunakan untuk tujuan apa?','option','PFM000000002','a:4:{i:0;s:47:"Menentukan lokasi pengeboran sumur pengembangan";i:1;s:37:"Menentukan strategi EOR di masa depan";i:2;s:42:"Menganalisis fasies batuan secara regional";i:3;s:19:"Semua jawaban benar";}','','Semua jawaban benar','During the field development phase, petrophysical data is used for what purpose?','a:4:{i:0;s:47:"Determining development well drilling locations";i:1;s:33:"Determining future EOR strategies";i:2;s:32:"Analyzing rock facies regionally";i:3;s:23:"All answers are correct";}','All answers are correct','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000009','Log Gamma Ray pada evaluasi formasi biasanya digunakan untuk menentukan parameter apa?','option','PFM000000002','a:4:{i:0;s:12:"Saturasi air";i:1;s:28:"Volume serpih (shale volume)";i:2;s:17:"Porositas efektif";i:3;s:15:"Tekanan formasi";}','','Volume serpih (shale volume)','The Gamma Ray log in formation evaluation is typically used to determine what parameter?','a:4:{i:0;s:16:"Water saturation";i:1;s:12:"Shale volume";i:2;s:18:"Effective porosity";i:3;s:18:"Formation pressure";}','Shale volume','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000010','Manakah di antara berikut ini yang merupakan karakteristik utama dari reservoir batuan klastik (sandstone)?','option','PFM000000003','a:4:{i:0;s:56:"Porositas primer yang dominan terbentuk saat pengendapan";i:1;s:51:"Sistem pori yang didominasi oleh rekahan (fracture)";i:2;s:70:"Kualitas reservoir yang sangat bergantung pada proses diagenesis kimia";i:3;s:40:"Struktur batuan yang bersifat non-porous";}','','Porositas primer yang dominan terbentuk saat pengendapan','Which of the following is the main characteristic of a clastic (sandstone) reservoir?','a:4:{i:0;s:50:"Dominant primary porosity formed during deposition";i:1;s:34:"Pore system dominated by fractures";i:2;s:57:"Reservoir quality highly dependent on chemical diagenesis";i:3;s:25:"Non-porous rock structure";}','Dominant primary porosity formed during deposition','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000011','Apa yang menyebabkan heterogenitas yang tinggi pada reservoir batuan karbonat seperti limestone dan dolomite?','multi','PFM000000003','a:4:{i:0;s:30:"Proses pelarutan (dissolution)";i:1;s:24:"Pembentukan dolomitisasi";i:2;s:38:"Proses sedimentasi yang sangat seragam";i:3;s:31:"Aktivitas tektonik yang minimal";}','','a:2:{i:0;s:30:"Proses pelarutan (dissolution)";i:1;s:24:"Pembentukan dolomitisasi";}','What causes high heterogeneity in carbonate reservoirs such as limestone and dolomite?','a:4:{i:0;s:21:"Dissolution processes";i:1;s:14:"Dolomitization";i:2;s:36:"Very uniform sedimentation processes";i:3;s:25:"Minimal tectonic activity";}','a:2:{i:0;s:21:"Dissolution processes";i:1;s:14:"Dolomitization";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000012','Istilah apa yang digunakan untuk menggambarkan batuan karbonat yang mengalami perubahan dari kalsit menjadi mineral yang lebih berpori?','option','PFM000000003','a:4:{i:0;s:12:"Dolomitisasi";i:1;s:9:"Sementasi";i:2;s:8:"Kompaksi";i:3;s:14:"Rekristalisasi";}','','Dolomitisasi','What term is used to describe the carbonate rock process where calcite changes into a more porous mineral?','a:4:{i:0;s:14:"Dolomitization";i:1;s:11:"Cementation";i:2;s:10:"Compaction";i:3;s:17:"Recrystallization";}','Dolomitization','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000013','Manakah faktor yang paling signifikan dalam menentukan kualitas reservoir pada batuan sandstone?','option','PFM000000003','a:4:{i:0;s:36:"Ukuran butir dan pemilahan (sorting)";i:1;s:45:"Kandungan mineral karbonat yang sangat tinggi";i:2;s:38:"Kedalaman penguburan yang dangkal saja";i:3;s:28:"Keberadaan fosil-fosil makro";}','','Ukuran butir dan pemilahan (sorting)','Which factor is the most significant in determining reservoir quality in sandstone?','a:4:{i:0;s:22:"Grain size and sorting";i:1;s:35:"Very high carbonate mineral content";i:2;s:25:"Shallow burial depth only";i:3;s:25:"Presence of macro fossils";}','Grain size and sorting','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000014','Dalam batuan karbonat, tipe porositas apa yang sering terbentuk akibat proses pelarutan batuan oleh air tanah?','option','PFM000000003','a:4:{i:0;s:15:"Porositas vuggy";i:1;s:30:"Porositas intergranular primer";i:2;s:37:"Porositas antar butir (interparticle)";i:3;s:23:"Porositas intragranular";}','','Porositas vuggy','In carbonate rocks, what type of porosity is often formed due to the dissolution of rock by groundwater?','a:4:{i:0;s:14:"Vuggy porosity";i:1;s:30:"Primary intergranular porosity";i:2;s:22:"Interparticle porosity";i:3;s:22:"Intragranular porosity";}','Vuggy porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000015','Bagaimana pengaruh tingkat pemilahan (sorting) yang buruk terhadap kualitas sifat petrofisika batuan reservoar?','option','PFM000000004','a:4:{i:0;s:46:"Mengurangi porositas efektif dan permeabilitas";i:1;s:46:"Meningkatkan porositas total secara signifikan";i:2;s:44:"Tidak memberikan pengaruh pada permeabilitas";i:3;s:38:"Hanya memengaruhi densitas batuan saja";}','','Mengurangi porositas efektif dan permeabilitas','How does poor sorting affect the petrophysical properties of a reservoir rock?','a:4:{i:0;s:43:"Reduces effective porosity and permeability";i:1;s:38:"Significantly increases total porosity";i:2;s:29:"Has no effect on permeability";i:3;s:25:"Only affects rock density";}','Reduces effective porosity and permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000016','Pilih faktor-faktor tekstur batuan yang secara langsung memengaruhi nilai permeabilitas dalam media berpori.','multi','PFM000000004','a:4:{i:0;s:25:"Ukuran butir (grain size)";i:1;s:29:"Tingkat kebundaran (rounding)";i:2;s:13:"Warna mineral";i:3;s:19:"Pemilahan (sorting)";}','','a:2:{i:0;s:25:"Ukuran butir (grain size)";i:1;s:19:"Pemilahan (sorting)";}','Select the rock texture factors that directly influence the permeability value in porous media.','a:4:{i:0;s:10:"Grain size";i:1;s:8:"Rounding";i:2;s:13:"Mineral color";i:3;s:7:"Sorting";}','a:2:{i:0;s:10:"Grain size";i:1;s:7:"Sorting";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000017','Apa dampak utama dari proses sementasi atau konsolidasi yang kuat pada batuan pasir?','option','PFM000000004','a:4:{i:0;s:44:"Penurunan porositas primer dan permeabilitas";i:1;s:35:"Peningkatan konektivitas antar pori";i:2;s:45:"Peningkatan porositas sekunder secara drastis";i:3;s:36:"Tidak mengubah sifat fisik reservoar";}','','Penurunan porositas primer dan permeabilitas','What is the primary impact of strong cementation or consolidation on sandstone?','a:4:{i:0;s:45:"Decrease in primary porosity and permeability";i:1;s:29:"Increase in pore connectivity";i:2;s:38:"Drastic increase in secondary porosity";i:3;s:56:"Does not change the physical properties of the reservoir";}','Decrease in primary porosity and permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000018','Lingkungan pengendapan yang memiliki energi arus tinggi, seperti saluran sungai (channel), cenderung menghasilkan batuan reservoar dengan karakteristik yang bagaimana?','option','PFM000000004','a:4:{i:0;s:32:"Butiran kasar dan pemilahan baik";i:1;s:33:"Butiran halus dan pemilahan buruk";i:2;s:50:"Batuan dengan kandungan lempung yang sangat tinggi";i:3;s:49:"Struktur batuan yang sangat padat dan impermeable";}','','Butiran kasar dan pemilahan baik','Depositional environments with high energy currents, such as river channels, tend to produce reservoir rocks with what characteristics?','a:4:{i:0;s:30:"Coarse grains and good sorting";i:1;s:28:"Fine grains and poor sorting";i:2;s:33:"Rocks with very high clay content";i:3;s:41:"Very dense and impermeable rock structure";}','Coarse grains and good sorting','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000019','Manakah pernyataan yang paling tepat mengenai hubungan antara kebundaran (rounding) butiran dengan efisiensi aliran fluida?','option','PFM000000004','a:4:{i:0;s:88:"Butiran yang lebih bundar cenderung memiliki porositas dan permeabilitas yang lebih baik";i:1;s:63:"Kebundaran butiran tidak memiliki hubungan dengan geometri pori";i:2;s:77:"Butiran yang bersudut tajam selalu memberikan permeabilitas yang lebih tinggi";i:3;s:78:"Efisiensi aliran hanya bergantung pada viskositas fluida, bukan bentuk butiran";}','','Butiran yang lebih bundar cenderung memiliki porositas dan permeabilitas yang lebih baik','Which statement is most accurate regarding the relationship between grain rounding and fluid flow efficiency?','a:4:{i:0;s:65:"More rounded grains tend to have better porosity and permeability";i:1;s:53:"Grain rounding has no relationship with pore geometry";i:2;s:49:"Angular grains always provide higher permeability";i:3;s:64:"Flow efficiency depends only on fluid viscosity, not grain shape";}','More rounded grains tend to have better porosity and permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000020','Manakah batuan yang memiliki karakteristik utama sebagai source rock dalam sistem hidrokarbon?','option','PFM000000005','a:4:{i:0;s:29:"Batupasir berporositas tinggi";i:1;s:36:"Serpih (shale) kaya material organik";i:2;s:21:"Batugamping kristalin";i:3;s:20:"Batuan beku intrusif";}','','Serpih (shale) kaya material organik','Which rock type has the primary characteristics of a source rock in a hydrocarbon system?','a:4:{i:0;s:23:"High porosity sandstone";i:1;s:18:"Organic-rich shale";i:2;s:21:"Crystalline limestone";i:3;s:22:"Intrusive igneous rock";}','Organic-rich shale','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000021','Elemen apa saja yang diperlukan untuk membentuk akumulasi hidrokarbon yang ekonomis?','multi','PFM000000005','a:4:{i:0;s:11:"Source rock";i:1;s:9:"Reservoir";i:2;s:4:"Seal";i:3;s:9:"Awan debu";}','','a:3:{i:0;s:11:"Source rock";i:1;s:9:"Reservoir";i:2;s:4:"Seal";}','Which elements are required to form an economical hydrocarbon accumulation?','a:4:{i:0;s:11:"Source rock";i:1;s:9:"Reservoir";i:2;s:4:"Seal";i:3;s:10:"Dust cloud";}','a:3:{i:0;s:11:"Source rock";i:1;s:9:"Reservoir";i:2;s:4:"Seal";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000022','Apakah fungsi utama dari batuan penutup (seal) dalam sistem hidrokarbon?','option','PFM000000005','a:4:{i:0;s:36:"Meningkatkan permeabilitas reservoir";i:1;s:50:"Mencegah migrasi hidrokarbon keluar dari reservoir";i:2;s:45:"Menyediakan material organik untuk pematangan";i:3;s:39:"Meningkatkan porositas batuan reservoir";}','','Mencegah migrasi hidrokarbon keluar dari reservoir','What is the main function of a seal rock in a hydrocarbon system?','a:4:{i:0;s:33:"Increasing reservoir permeability";i:1;s:53:"Preventing hydrocarbon migration out of the reservoir";i:2;s:41:"Providing organic material for maturation";i:3;s:34:"Increasing reservoir rock porosity";}','Preventing hydrocarbon migration out of the reservoir','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000023','Proses pergerakan hidrokarbon dari batuan induk (source rock) menuju batuan reservoir disebut sebagai?','option','PFM000000005','a:4:{i:0;s:5:"Erosi";i:1;s:11:"Sedimentasi";i:2;s:7:"Migrasi";i:3;s:8:"Kompaksi";}','','Migrasi','The process of hydrocarbon movement from the source rock to the reservoir rock is known as?','a:4:{i:0;s:7:"Erosion";i:1;s:13:"Sedimentation";i:2;s:9:"Migration";i:3;s:10:"Compaction";}','Migration','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000024','Manakah dari berikut ini yang merupakan contoh dari jebakan (trap) struktural?','option','PFM000000005','a:4:{i:0;s:8:"Antiklin";i:1;s:17:"Channel sandstone";i:2;s:12:"Unconformity";i:3;s:12:"Reef buildup";}','','Antiklin','Which of the following is an example of a structural trap?','a:4:{i:0;s:9:"Anticline";i:1;s:17:"Channel sandstone";i:2;s:12:"Unconformity";i:3;s:12:"Reef buildup";}','Anticline','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000025','Manakah dari berikut ini yang merupakan contoh klasik dari jebakan struktural pada batuan reservoar?','option','PFM000000006','a:4:{i:0;s:8:"Antiklin";i:1;s:9:"Pinch-out";i:2;s:12:"Unconformity";i:3;s:4:"Reef";}','','Antiklin','Which of the following is a classic example of a structural trap in reservoir rocks?','a:4:{i:0;s:9:"Anticline";i:1;s:9:"Pinch-out";i:2;s:12:"Unconformity";i:3;s:4:"Reef";}','Anticline','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000026','Apa yang dimaksud dengan OWC (Oil-Water Contact) dalam sistem akumulasi hidrokarbon?','option','PFM000000006','a:4:{i:0;s:37:"Batas antara zona gas dan zona minyak";i:1;s:70:"Bidang horisontal yang memisahkan akumulasi minyak dan air di bawahnya";i:2;s:38:"Titik terdalam dari struktur reservoar";i:3;s:46:"Zona transisi di mana permeabilitas batuan nol";}','','Bidang horisontal yang memisahkan akumulasi minyak dan air di bawahnya','What is the OWC (Oil-Water Contact) in a hydrocarbon accumulation system?','a:4:{i:0;s:50:"The boundary between the gas zone and the oil zone";i:1;s:77:"The horizontal plane separating the oil accumulation and the underlying water";i:2;s:44:"The deepest point of the reservoir structure";i:3;s:51:"The transition zone where rock permeability is zero";}','The horizontal plane separating the oil accumulation and the underlying water','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000027','Jebakan stratigrafi terbentuk utamanya karena:','multi','PFM000000006','a:4:{i:0;s:39:"Perubahan lateral dalam litologi batuan";i:1;s:32:"Adanya proses tektonik pelipatan";i:2;s:56:"Penyempitan atau pemutusan lapisan reservoar (pinch-out)";i:3;s:40:"Adanya sesar normal yang memotong batuan";}','','a:2:{i:0;s:39:"Perubahan lateral dalam litologi batuan";i:1;s:56:"Penyempitan atau pemutusan lapisan reservoar (pinch-out)";}','Stratigraphic traps are primarily formed due to:','a:4:{i:0;s:33:"Lateral changes in rock lithology";i:1;s:26:"Tectonic folding processes";i:2;s:32:"Pinch-out of the reservoir layer";i:3;s:38:"Normal faults cutting through the rock";}','a:2:{i:0;s:33:"Lateral changes in rock lithology";i:1;s:32:"Pinch-out of the reservoir layer";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000028','Dalam konteks tekanan reservoar, apa yang terjadi pada hidrokarbon jika tekanan berada di bawah tekanan gelembung (bubble point pressure)?','option','PFM000000006','a:4:{i:0;s:45:"Gas akan mulai terlepas dari fase cair minyak";i:1;s:32:"Minyak akan menjadi lebih kental";i:2;s:46:"Porositas batuan akan meningkat secara drastis";i:3;s:37:"Kontak OWC akan naik ke atas struktur";}','','Gas akan mulai terlepas dari fase cair minyak','In the context of reservoir pressure, what happens to hydrocarbons if the pressure is below the bubble point pressure?','a:4:{i:0;s:50:"Gas will begin to evolve from the liquid oil phase";i:1;s:28:"Oil will become more viscous";i:2;s:39:"Rock porosity will increase drastically";i:3;s:42:"The OWC contact will rise up the structure";}','Gas will begin to evolve from the liquid oil phase','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000029','Jebakan kombinasi didefinisikan sebagai jebakan yang:','option','PFM000000006','a:4:{i:0;s:32:"Hanya bergantung pada sesar saja";i:1;s:42:"Terbentuk murni karena pengendapan sedimen";i:2;s:61:"Melibatkan elemen struktural dan stratigrafi secara bersamaan";i:3;s:36:"Hanya ditemukan pada batuan karbonat";}','','Melibatkan elemen struktural dan stratigrafi secara bersamaan','A combination trap is defined as a trap that:','a:4:{i:0;s:26:"Depends solely on faulting";i:1;s:36:"Formed purely by sediment deposition";i:2;s:66:"Involves both structural and stratigraphic elements simultaneously";i:3;s:32:"Is only found in carbonate rocks";}','Involves both structural and stratigraphic elements simultaneously','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000030','Apakah definisi matematis dari porositas batuan yang paling tepat?','option','PFM000000007','a:4:{i:0;s:63:"Perbandingan antara volume pori total dengan volume bulk batuan";i:1;s:53:"Perbandingan antara volume butiran dengan volume pori";i:2;s:57:"Perbandingan antara volume bulk batuan dengan volume pori";i:3;s:62:"Perbandingan antara volume air dengan volume minyak dalam pori";}','','Perbandingan antara volume pori total dengan volume bulk batuan','What is the most accurate mathematical definition of rock porosity?','a:4:{i:0;s:50:"The ratio of total pore volume to bulk rock volume";i:1;s:40:"The ratio of grain volume to pore volume";i:2;s:44:"The ratio of bulk rock volume to pore volume";i:3;s:56:"The ratio of water volume to oil volume within the pores";}','The ratio of total pore volume to bulk rock volume','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000031','Manakah pernyataan yang benar mengenai perbedaan antara porositas total dan porositas efektif?','multi','PFM000000007','a:4:{i:0;s:79:"Porositas total mencakup seluruh pori baik yang saling berhubungan maupun tidak";i:1;s:68:"Porositas efektif hanya menghitung pori-pori yang saling berhubungan";i:2;s:61:"Porositas total selalu lebih kecil daripada porositas efektif";i:3;s:66:"Porositas efektif mencakup pori yang terisolasi dari sistem aliran";}','','a:2:{i:0;s:79:"Porositas total mencakup seluruh pori baik yang saling berhubungan maupun tidak";i:1;s:68:"Porositas efektif hanya menghitung pori-pori yang saling berhubungan";}','Which statements are correct regarding the difference between total porosity and effective porosity?','a:4:{i:0;s:63:"Total porosity includes all pores whether interconnected or not";i:1;s:51:"Effective porosity only counts interconnected pores";i:2;s:56:"Total porosity is always smaller than effective porosity";i:3;s:63:"Effective porosity includes pores isolated from the flow system";}','a:2:{i:0;s:63:"Total porosity includes all pores whether interconnected or not";i:1;s:51:"Effective porosity only counts interconnected pores";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000032','Jenis porositas yang terbentuk bersamaan dengan proses pengendapan sedimen disebut sebagai:','option','PFM000000007','a:4:{i:0;s:16:"Porositas primer";i:1;s:18:"Porositas sekunder";i:2;s:15:"Porositas vuggy";i:3;s:17:"Porositas fraktur";}','','Porositas primer','The type of porosity formed simultaneously with the sediment deposition process is called:','a:4:{i:0;s:16:"Primary porosity";i:1;s:18:"Secondary porosity";i:2;s:14:"Vuggy porosity";i:3;s:17:"Fracture porosity";}','Primary porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000033','Apa dampak utama dari proses pelarutan atau diagenesis lanjut terhadap porositas batuan?','option','PFM000000007','a:4:{i:0;s:28:"Membentuk porositas sekunder";i:1;s:69:"Mengurangi porositas primer secara permanen tanpa membentuk pori baru";i:2;s:45:"Mengubah saturasi air menjadi saturasi minyak";i:3;s:56:"Menghilangkan permeabilitas tanpa mempengaruhi porositas";}','','Membentuk porositas sekunder','What is the primary impact of dissolution or advanced diagenesis processes on rock porosity?','a:4:{i:0;s:24:"Forms secondary porosity";i:1;s:63:"Permanently reduces primary porosity without creating new pores";i:2;s:44:"Changes water saturation into oil saturation";i:3;s:50:"Eliminates permeability without affecting porosity";}','Forms secondary porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000034','Jika diketahui volume bulk batuan adalah 100 cc dan volume pori adalah 20 cc, berapakah porositas batuan tersebut?','option','PFM000000007','a:4:{i:0;s:3:"20%";i:1;s:3:"25%";i:2;s:3:"80%";i:3;s:2:"5%";}','','20%','If the bulk rock volume is 100 cc and the pore volume is 20 cc, what is the rock porosity?','a:4:{i:0;s:3:"20%";i:1;s:3:"25%";i:2;s:3:"80%";i:3;s:2:"5%";}','20%','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000035','Manakah dari faktor berikut yang secara signifikan dapat menurunkan porositas sekunder pada batuan karbonat?','option','PFM000000008','a:4:{i:0;s:31:"Pelarutan mineral (dissolution)";i:1;s:16:"Sementasi kalsit";i:2;s:19:"Proses dolomitisasi";i:3;s:20:"Rekahan (fracturing)";}','','Sementasi kalsit','Which of the following factors can significantly reduce secondary porosity in carbonate rocks?','a:4:{i:0;s:11:"Dissolution";i:1;s:19:"Calcite cementation";i:2;s:14:"Dolomitization";i:3;s:10:"Fracturing";}','Calcite cementation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000036','Pilih dua faktor yang secara langsung mempengaruhi porositas primer pada batuan klastik saat deposisi.','multi','PFM000000008','a:4:{i:0;s:28:"Penyusunan butiran (packing)";i:1;s:17:"Sementasi mineral";i:2;s:27:"Pemilahan butiran (sorting)";i:3;s:16:"Tekanan tektonik";}','','a:2:{i:0;s:28:"Penyusunan butiran (packing)";i:1;s:27:"Pemilahan butiran (sorting)";}','Select two factors that directly influence primary porosity in clastic rocks during deposition.','a:4:{i:0;s:7:"Packing";i:1;s:19:"Mineral cementation";i:2;s:7:"Sorting";i:3;s:17:"Tectonic pressure";}','a:2:{i:0;s:7:"Packing";i:1;s:7:"Sorting";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000037','Metode laboratorium manakah yang paling akurat digunakan untuk mengukur porositas efektif pada sampel core batuan?','option','PFM000000008','a:4:{i:0;s:36:"Metode saturasi fluida (Boyle''s Law)";i:1;s:26:"Interpretasi log Gamma Ray";i:2;s:25:"Analisis log resistivitas";i:3;s:38:"Pengukuran densitas bulk secara visual";}','','Metode saturasi fluida (Boyle''s Law)','Which laboratory method is most accurately used to measure effective porosity in rock core samples?','a:4:{i:0;s:37:"Fluid saturation method (Boyle''s Law)";i:1;s:28:"Gamma Ray log interpretation";i:2;s:24:"Resistivity log analysis";i:3;s:31:"Visual bulk density measurement";}','Fluid saturation method (Boyle''s Law)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000038','Bagaimana pengaruh proses kompaksi yang semakin intensif terhadap porositas batuan sedimen?','option','PFM000000008','a:4:{i:0;s:48:"Meningkatkan porositas karena pengurangan volume";i:1;s:40:"Tidak memberikan pengaruh pada porositas";i:2;s:57:"Menurunkan porositas akibat pengurangan volume ruang pori";i:3;s:44:"Meningkatkan permeabilitas secara signifikan";}','','Menurunkan porositas akibat pengurangan volume ruang pori','How does an increasingly intensive compaction process affect the porosity of sedimentary rocks?','a:4:{i:0;s:42:"Increases porosity due to volume reduction";i:1;s:25:"Has no effect on porosity";i:2;s:53:"Decreases porosity due to pore space volume reduction";i:3;s:36:"Significantly increases permeability";}','Decreases porosity due to pore space volume reduction','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000039','Log fisik batuan manakah yang paling umum digunakan untuk estimasi porositas batuan secara in-situ?','option','PFM000000008','a:4:{i:0;s:30:"Log Spontaneous Potential (SP)";i:1;s:26:"Log Densitas (Density Log)";i:2;s:11:"Log Caliper";i:3;s:14:"Log Temperatur";}','','Log Densitas (Density Log)','Which physical rock log is most commonly used for in-situ rock porosity estimation?','a:4:{i:0;s:30:"Spontaneous Potential (SP) log";i:1;s:11:"Density Log";i:2;s:11:"Caliper log";i:3;s:15:"Temperature log";}','Density Log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000040','Parameter utama yang menunjukkan kemampuan batuan berpori untuk mengalirkan fluida di bawah pengaruh perbedaan tekanan adalah?','option','PFM000000009','a:4:{i:0;s:13:"Permeabilitas";i:1;s:9:"Porositas";i:2;s:8:"Saturasi";i:3;s:15:"Tekanan Kapiler";}','','Permeabilitas','The main parameter indicating the ability of a porous rock to transmit fluids under a pressure differential is?','a:4:{i:0;s:12:"Permeability";i:1;s:8:"Porosity";i:2;s:10:"Saturation";i:3;s:18:"Capillary Pressure";}','Permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000041','Manakah pernyataan yang tepat mengenai Hukum Darcy dalam aliran fluida di media berpori?','multi','PFM000000009','a:4:{i:0;s:51:"Laju alir berbanding lurus dengan perbedaan tekanan";i:1;s:54:"Laju alir berbanding terbalik dengan viskositas fluida";i:2;s:49:"Permeabilitas batuan tidak mempengaruhi laju alir";i:3;s:57:"Hukum Darcy hanya berlaku untuk fluida yang sangat kental";}','','a:2:{i:0;s:51:"Laju alir berbanding lurus dengan perbedaan tekanan";i:1;s:54:"Laju alir berbanding terbalik dengan viskositas fluida";}','Which statements are correct regarding Darcy''s Law in fluid flow through porous media?','a:4:{i:0;s:57:"Flow rate is directly proportional to pressure difference";i:1;s:54:"Flow rate is inversely proportional to fluid viscosity";i:2;s:43:"Rock permeability does not affect flow rate";i:3;s:49:"Darcy''s Law only applies to highly viscous fluids";}','a:2:{i:0;s:57:"Flow rate is directly proportional to pressure difference";i:1;s:54:"Flow rate is inversely proportional to fluid viscosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000042','Berapakah konversi yang benar untuk satuan permeabilitas 1 Darcy ke dalam milidarcy (mD)?','option','PFM000000009','a:4:{i:0;s:5:"10 mD";i:1;s:6:"100 mD";i:2;s:8:"1.000 mD";i:3;s:9:"10.000 mD";}','','1.000 mD','What is the correct conversion for 1 Darcy to millidarcy (mD)?','a:4:{i:0;s:5:"10 mD";i:1;s:6:"100 mD";i:2;s:8:"1,000 mD";i:3;s:9:"10,000 mD";}','1,000 mD','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000043','Faktor fisik batuan yang paling signifikan mempengaruhi nilai permeabilitas absolut adalah?','option','PFM000000009','a:4:{i:0;s:44:"Ukuran dan keterhubungan (konektivitas) pori";i:1;s:12:"Warna batuan";i:2;s:17:"Kedalaman formasi";i:3;s:23:"Densitas matriks batuan";}','','Ukuran dan keterhubungan (konektivitas) pori','Which physical rock factor most significantly influences absolute permeability values?','a:4:{i:0;s:26:"Pore size and connectivity";i:1;s:10:"Rock color";i:2;s:15:"Formation depth";i:3;s:19:"Rock matrix density";}','Pore size and connectivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000044','Dalam persamaan Hukum Darcy untuk aliran linear, apa yang terjadi pada laju alir jika panjang media (L) diperbesar dua kali lipat dengan tekanan yang tetap?','option','PFM000000009','a:4:{i:0;s:32:"Laju alir menjadi dua kali lipat";i:1;s:29:"Laju alir menjadi setengahnya";i:2;s:23:"Laju alir tetap konstan";i:3;s:34:"Laju alir menjadi empat kali lipat";}','','Laju alir menjadi setengahnya','In the Darcy''s Law equation for linear flow, what happens to the flow rate if the media length (L) is doubled while keeping pressure constant?','a:4:{i:0;s:17:"Flow rate doubles";i:1;s:19:"Flow rate is halved";i:2;s:26:"Flow rate remains constant";i:3;s:20:"Flow rate quadruples";}','Flow rate is halved','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000045','Manakah pernyataan yang benar mengenai permeabilitas absolut dalam media berpori?','option','PFM000000010','a:4:{i:0;s:61:"Permeabilitas saat batuan dijenuhi oleh dua atau lebih fluida";i:1;s:84:"Permeabilitas batuan yang hanya mengandung satu fasa fluida yang 100% menjenuhi pori";i:2;s:71:"Permeabilitas yang bergantung pada arah aliran dalam batuan anisotropik";i:3;s:68:"Permeabilitas yang nilainya selalu sama dengan permeabilitas efektif";}','','Permeabilitas batuan yang hanya mengandung satu fasa fluida yang 100% menjenuhi pori','Which statement is correct regarding absolute permeability in porous media?','a:4:{i:0;s:57:"Permeability when rock is saturated by two or more fluids";i:1;s:82:"Permeability of rock containing only one fluid phase that 100% saturates the pores";i:2;s:63:"Permeability that depends on flow direction in anisotropic rock";i:3;s:66:"Permeability whose value is always equal to effective permeability";}','Permeability of rock containing only one fluid phase that 100% saturates the pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000046','Mengapa pengukuran permeabilitas menggunakan gas sering kali menghasilkan nilai yang lebih tinggi dibandingkan menggunakan cairan (liquid)?','option','PFM000000010','a:4:{i:0;s:55:"Adanya efek Klinkenberg atau slip gas pada dinding pori";i:1;s:62:"Gas memiliki viskositas yang jauh lebih tinggi daripada cairan";i:2;s:55:"Cairan menyebabkan pengembangan lempung (clay swelling)";i:3;s:58:"Gas bereaksi secara kimiawi dengan mineral penyusun batuan";}','','Adanya efek Klinkenberg atau slip gas pada dinding pori','Why does permeability measurement using gas often result in higher values compared to using liquid?','a:4:{i:0;s:72:"The existence of the Klinkenberg effect or gas slippage at the pore wall";i:1;s:41:"Gas has much higher viscosity than liquid";i:2;s:27:"Liquid causes clay swelling";i:3;s:52:"Gas chemically reacts with the rock-forming minerals";}','The existence of the Klinkenberg effect or gas slippage at the pore wall','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000047','Pilihlah parameter yang memengaruhi besarnya permeabilitas relatif (k_r) dalam suatu sistem reservoar.','multi','PFM000000010','a:4:{i:0;s:28:"Saturasi fluida dalam batuan";i:1;s:15:"Tekanan kapiler";i:2;s:18:"Wettability batuan";i:3;s:17:"Kedalaman formasi";}','','a:2:{i:0;s:28:"Saturasi fluida dalam batuan";i:1;s:18:"Wettability batuan";}','Select parameters that affect the magnitude of relative permeability (k_r) in a reservoir system.','a:4:{i:0;s:28:"Fluid saturation in the rock";i:1;s:18:"Capillary pressure";i:2;s:16:"Rock wettability";i:3;s:15:"Formation depth";}','a:2:{i:0;s:28:"Fluid saturation in the rock";i:1;s:16:"Rock wettability";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000048','Dalam batuan anisotropik, manakah pernyataan yang tepat mengenai permeabilitas arah?','option','PFM000000010','a:4:{i:0;s:40:"Permeabilitas selalu sama ke segala arah";i:1;s:77:"Permeabilitas horizontal biasanya lebih kecil daripada permeabilitas vertikal";i:2;s:83:"Permeabilitas vertikal sering kali lebih rendah akibat adanya laminasi atau bedding";i:3;s:58:"Permeabilitas arah tidak dipengaruhi oleh struktur sedimen";}','','Permeabilitas vertikal sering kali lebih rendah akibat adanya laminasi atau bedding','In anisotropic rock, which statement is correct regarding directional permeability?','a:4:{i:0;s:49:"Permeability is always the same in all directions";i:1;s:69:"Horizontal permeability is usually smaller than vertical permeability";i:2;s:66:"Vertical permeability is often lower due to laminations or bedding";i:3;s:66:"Directional permeability is not affected by sedimentary structures";}','Vertical permeability is often lower due to laminations or bedding','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000049','Permeabilitas efektif didefinisikan sebagai kemampuan batuan untuk mengalirkan satu fasa fluida tertentu jika:','option','PFM000000010','a:4:{i:0;s:46:"Batuan berada dalam kondisi tekanan atmosferik";i:1;s:64:"Batuan dijenuhi oleh dua atau lebih fasa fluida secara bersamaan";i:2;s:62:"Batuan telah dibersihkan dari seluruh kandungan minyak dan air";i:3;s:42:"Aliran fluida bersifat turbulen sepenuhnya";}','','Batuan dijenuhi oleh dua atau lebih fasa fluida secara bersamaan','Effective permeability is defined as the ability of the rock to conduct a specific fluid phase when:','a:4:{i:0;s:49:"The rock is under atmospheric pressure conditions";i:1;s:64:"The rock is saturated by two or more fluid phases simultaneously";i:2;s:54:"The rock has been cleaned of all oil and water content";i:3;s:29:"Fluid flow is fully turbulent";}','The rock is saturated by two or more fluid phases simultaneously','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000050','Manakah pernyataan yang benar mengenai definisi saturasi fluida dalam pori-pori batuan reservoar?','option','PFM000000011','a:4:{i:0;s:64:"Perbandingan volume fluida spesifik terhadap volume total batuan";i:1;s:63:"Perbandingan volume fluida spesifik terhadap volume pori batuan";i:2;s:60:"Perbandingan volume pori batuan terhadap volume total batuan";i:3;s:53:"Perbandingan berat fluida terhadap berat total batuan";}','','Perbandingan volume fluida spesifik terhadap volume pori batuan','Which statement is correct regarding the definition of fluid saturation within reservoir rock pores?','a:4:{i:0;s:51:"Ratio of specific fluid volume to total rock volume";i:1;s:57:"Ratio of specific fluid volume to pore volume of the rock";i:2;s:41:"Ratio of pore volume to total rock volume";i:3;s:42:"Ratio of fluid weight to total rock weight";}','Ratio of specific fluid volume to pore volume of the rock','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000051','Jika diketahui volume pori batuan adalah 500 cc dan volume air di dalam pori tersebut adalah 100 cc, berapakah nilai saturasi air (Sw)?','option','PFM000000011','a:4:{i:0;s:3:"10%";i:1;s:3:"20%";i:2;s:3:"25%";i:3;s:3:"50%";}','','20%','If the rock pore volume is 500 cc and the water volume within those pores is 100 cc, what is the water saturation (Sw) value?','a:4:{i:0;s:3:"10%";i:1;s:3:"20%";i:2;s:3:"25%";i:3;s:3:"50%";}','20%','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000052','Saturasi air koneat (Swc) dalam sistem reservoar didefinisikan sebagai:','option','PFM000000011','a:4:{i:0;s:58:"Saturasi air maksimum yang dapat diproduksi dari reservoar";i:1;s:83:"Saturasi air yang tertahan di dalam pori oleh gaya kapiler dan tidak dapat bergerak";i:2;s:62:"Saturasi air yang terukur saat air terinjeksi ke dalam formasi";i:3;s:51:"Saturasi air yang berada di zona transisi reservoar";}','','Saturasi air yang tertahan di dalam pori oleh gaya kapiler dan tidak dapat bergerak','Connate water saturation (Swc) in a reservoir system is defined as:','a:4:{i:0;s:45:"Maximum water saturation that can be produced";i:1;s:66:"Water saturation held in pores by capillary forces and is immobile";i:2;s:67:"Water saturation measured when water is injected into the formation";i:3;s:64:"Water saturation located in the transition zone of the reservoir";}','Water saturation held in pores by capillary forces and is immobile','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000053','Dalam suatu elemen volume batuan reservoar, jumlah dari saturasi fluida yang ada harus memenuhi kondisi berikut:','multi','PFM000000011','a:4:{i:0;s:16:"Sw + So + Sg = 1";i:1;s:19:"Sw + So + Sg = 100%";i:2;s:16:"Sw + So + Sg > 1";i:3;s:24:"Sw + So + Sg = porositas";}','','a:2:{i:0;s:16:"Sw + So + Sg = 1";i:1;s:19:"Sw + So + Sg = 100%";}','In a given reservoir rock volume element, the sum of the fluid saturations present must satisfy the following conditions:','a:4:{i:0;s:16:"Sw + So + Sg = 1";i:1;s:19:"Sw + So + Sg = 100%";i:2;s:16:"Sw + So + Sg > 1";i:3;s:23:"Sw + So + Sg = porosity";}','a:2:{i:0;s:16:"Sw + So + Sg = 1";i:1;s:19:"Sw + So + Sg = 100%";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000054','Apa perbedaan mendasar antara Bulk Volume (Vb) dan Pore Volume (Vp) dalam petrofisika?','option','PFM000000011','a:4:{i:0;s:105:"Vb adalah volume batuan total termasuk matriks dan pori, sedangkan Vp adalah ruang kosong di dalam batuan";i:1;s:62:"Vp adalah volume total batuan, sedangkan Vb adalah volume pori";i:2;s:59:"Vb selalu lebih kecil dari Vp karena adanya saturasi fluida";i:3;s:62:"Vb diukur dalam satuan cP, sedangkan Vp diukur dalam satuan mD";}','','Vb adalah volume batuan total termasuk matriks dan pori, sedangkan Vp adalah ruang kosong di dalam batuan','What is the fundamental difference between Bulk Volume (Vb) and Pore Volume (Vp) in petrophysics?','a:4:{i:0;s:98:"Vb is the total rock volume including matrix and pores, while Vp is the void space within the rock";i:1;s:56:"Vp is the total rock volume, while Vb is the pore volume";i:2;s:52:"Vb is always smaller than Vp due to fluid saturation";i:3;s:60:"Vb is measured in cP units, while Vp is measured in mD units";}','Vb is the total rock volume including matrix and pores, while Vp is the void space within the rock','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000055','Berdasarkan persamaan Kozeny-Carman, bagaimana hubungan antara porositas efektif dan permeabilitas pada batuan reservoir?','option','PFM000000012','a:4:{i:0;s:55:"Permeabilitas berbanding lurus dengan kuadrat porositas";i:1;s:99:"Permeabilitas berbanding lurus dengan pangkat tiga porositas dibagi kuadrat luas permukaan spesifik";i:2;s:46:"Permeabilitas tidak dipengaruhi oleh porositas";i:3;s:50:"Permeabilitas berbanding terbalik dengan porositas";}','','Permeabilitas berbanding lurus dengan pangkat tiga porositas dibagi kuadrat luas permukaan spesifik','Based on the Kozeny-Carman equation, what is the relationship between effective porosity and permeability in reservoir rock?','a:4:{i:0;s:63:"Permeability is directly proportional to the square of porosity";i:1;s:108:"Permeability is directly proportional to the cube of porosity divided by the square of specific surface area";i:2;s:42:"Permeability is not influenced by porosity";i:3;s:50:"Permeability is inversely proportional to porosity";}','Permeability is directly proportional to the cube of porosity divided by the square of specific surface area','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000056','Faktor apa saja yang mempengaruhi permeabilitas efektif suatu fase fluida dalam media berpori?','multi','PFM000000012','a:4:{i:0;s:15:"Saturasi fluida";i:1;s:13:"Geometri pori";i:2;s:18:"Wettability batuan";i:3;s:20:"Temperatur reservoir";}','','a:3:{i:0;s:15:"Saturasi fluida";i:1;s:13:"Geometri pori";i:2;s:18:"Wettability batuan";}','Which factors influence the effective permeability of a fluid phase in porous media?','a:4:{i:0;s:16:"Fluid saturation";i:1;s:13:"Pore geometry";i:2;s:16:"Rock wettability";i:3;s:21:"Reservoir temperature";}','a:3:{i:0;s:16:"Fluid saturation";i:1;s:13:"Pore geometry";i:2;s:16:"Rock wettability";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000057','Apa yang dimaksud dengan kompresibilitas batuan (rock compressibility) dalam konteks sifat fisik reservoir?','option','PFM000000012','a:4:{i:0;s:49:"Perubahan saturasi air terhadap perubahan tekanan";i:1;s:85:"Perubahan volume pori batuan akibat perubahan tekanan overburden atau tekanan formasi";i:2;s:74:"Kemampuan batuan untuk mengalirkan minyak pada kondisi saturasi air rendah";i:3;s:59:"Rasio antara permeabilitas absolut dengan viskositas fluida";}','','Perubahan volume pori batuan akibat perubahan tekanan overburden atau tekanan formasi','What is meant by rock compressibility in the context of reservoir physical properties?','a:4:{i:0;s:58:"Change in water saturation with respect to pressure change";i:1;s:77:"Change in rock pore volume due to changes in overburden or formation pressure";i:2;s:66:"The ability of rock to flow oil at low water saturation conditions";i:3;s:53:"The ratio of absolute permeability to fluid viscosity";}','Change in rock pore volume due to changes in overburden or formation pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000058','Jika saturasi air (Sw) meningkat dalam batuan reservoir, apa yang terjadi pada permeabilitas efektif minyak (kro)?','option','PFM000000012','a:4:{i:0;s:43:"Permeabilitas efektif minyak akan meningkat";i:1;s:47:"Permeabilitas efektif minyak akan tetap konstan";i:2;s:41:"Permeabilitas efektif minyak akan menurun";i:3;s:54:"Permeabilitas efektif minyak akan menjadi nol seketika";}','','Permeabilitas efektif minyak akan menurun','If water saturation (Sw) increases in a reservoir rock, what happens to the effective oil permeability (kro)?','a:4:{i:0;s:40:"Effective oil permeability will increase";i:1;s:47:"Effective oil permeability will remain constant";i:2;s:40:"Effective oil permeability will decrease";i:3;s:53:"Effective oil permeability will instantly become zero";}','Effective oil permeability will decrease','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000059','Dalam korelasi Kozeny-Carman, variabel apa yang paling signifikan dalam menentukan nilai permeabilitas selain porositas?','option','PFM000000012','a:4:{i:0;s:15:"Densitas fluida";i:1;s:38:"Luas permukaan spesifik butiran batuan";i:2;s:15:"Tekanan kapiler";i:3;s:19:"Indeks resistivitas";}','','Luas permukaan spesifik butiran batuan','In the Kozeny-Carman correlation, what variable is most significant in determining permeability values besides porosity?','a:4:{i:0;s:13:"Fluid density";i:1;s:36:"Specific surface area of rock grains";i:2;s:18:"Capillary pressure";i:3;s:17:"Resistivity index";}','Specific surface area of rock grains','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000060','Pada diagram fase tekanan-temperatur (P-T) fluida reservoar, titik di mana gelembung gas pertama kali muncul dari minyak saat tekanan diturunkan disebut sebagai','option','PFM000000013','a:4:{i:0;s:12:"Titik kritis";i:1;s:15:"Titik gelembung";i:2;s:11:"Titik embun";i:3;s:20:"Titik cricondentherm";}','','Titik gelembung','On a reservoir fluid pressure-temperature (P-T) phase diagram, the point at which the first gas bubble emerges from the oil as pressure is reduced is called','a:4:{i:0;s:14:"Critical point";i:1;s:12:"Bubble point";i:2;s:9:"Dew point";i:3;s:20:"Cricondentherm point";}','Bubble point','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000061','Manakah pernyataan berikut yang benar mengenai karakteristik reservoir gas kondensat?','multi','PFM000000013','a:4:{i:0;s:65:"Temperatur reservoar berada di antara kritikal dan cricondentherm";i:1;s:68:"Terjadi kondensasi retrograd saat tekanan turun di bawah titik embun";i:2;s:68:"Fluida reservoar berupa gas kering sepenuhnya pada kondisi permukaan";i:3;s:54:"Tekanan reservoar awal selalu di bawah titik gelembung";}','','a:2:{i:0;s:65:"Temperatur reservoar berada di antara kritikal dan cricondentherm";i:1;s:68:"Terjadi kondensasi retrograd saat tekanan turun di bawah titik embun";}','Which of the following statements are true regarding the characteristics of a gas condensate reservoir?','a:4:{i:0;s:64:"Reservoir temperature is between the critical and cricondentherm";i:1;s:70:"Retrograde condensation occurs when pressure drops below the dew point";i:2;s:57:"Reservoir fluid is entirely dry gas at surface conditions";i:3;s:59:"Initial reservoir pressure is always below the bubble point";}','a:2:{i:0;s:64:"Reservoir temperature is between the critical and cricondentherm";i:1;s:70:"Retrograde condensation occurs when pressure drops below the dew point";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000062','Dalam penggolongan fluida reservoar, jenis fluida yang memiliki komposisi didominasi oleh hidrokarbon rantai panjang dan berat dengan sedikit fraksi ringan disebut','option','PFM000000013','a:4:{i:0;s:10:"Gas kering";i:1;s:9:"Gas basah";i:2;s:24:"Minyak hitam (black oil)";i:3;s:13:"Gas kondensat";}','','Minyak hitam (black oil)','In reservoir fluid classification, the type of fluid whose composition is dominated by long-chain and heavy hydrocarbons with few light fractions is called','a:4:{i:0;s:7:"Dry gas";i:1;s:7:"Wet gas";i:2;s:9:"Black oil";i:3;s:14:"Gas condensate";}','Black oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000063','Temperatur tertinggi di mana fase gas dan fase cair dapat hidup berdampingan dalam kesetimbangan pada diagram fase P-T dikenal dengan istilah','option','PFM000000013','a:4:{i:0;s:12:"Cricondenbar";i:1;s:14:"Cricondentherm";i:2;s:14:"Titik kritikal";i:3;s:26:"Temperatur pseudo-kritikal";}','','Cricondentherm','The highest temperature at which gas and liquid phases can coexist in equilibrium on a P-T phase diagram is known as','a:4:{i:0;s:12:"Cricondenbar";i:1;s:14:"Cricondentherm";i:2;s:14:"Critical point";i:3;s:27:"Pseudo-critical temperature";}','Cricondentherm','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000064','Pada reservoar gas kering (dry gas), kondisi temperatur reservoir berada pada posisi','option','PFM000000013','a:4:{i:0;s:37:"Di sebelah kanan titik cricondentherm";i:1;s:43:"Di antara titik kritikal dan cricondentherm";i:2;s:30:"Di bawah garis titik gelembung";i:3;s:31:"Sama dengan temperatur kritikal";}','','Di sebelah kanan titik cricondentherm','In a dry gas reservoir, the reservoir temperature condition is located','a:4:{i:0;s:34:"To the right of the cricondentherm";i:1;s:49:"Between the critical point and the cricondentherm";i:2;s:27:"Below the bubble point line";i:3;s:33:"Equal to the critical temperature";}','To the right of the cricondentherm','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000065','Jenis fluida reservoar yang memiliki karakteristik penurunan tekanan di bawah tekanan titik embun (dew point) di dalam reservoar sehingga terbentuk kondensat cair disebut sebagai','option','PFM000000014','a:4:{i:0;s:9:"Black oil";i:1;s:12:"Volatile oil";i:2;s:14:"Retrograde gas";i:3;s:7:"Dry gas";}','','Retrograde gas','The type of reservoir fluid that exhibits a pressure drop below the dew point pressure within the reservoir resulting in the formation of liquid condensate is known as','a:4:{i:0;s:9:"Black oil";i:1;s:12:"Volatile oil";i:2;s:14:"Retrograde gas";i:3;s:7:"Dry gas";}','Retrograde gas','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000066','Pilih kriteria yang mencirikan fluida jenis Black Oil','multi','PFM000000014','a:4:{i:0;s:36:"Initial GOR kurang dari 2000 scf/stb";i:1;s:39:"Warna cairan cenderung gelap atau hitam";i:2;s:39:"Kandungan komponen berat lebih dari 20%";i:3;s:51:"Memiliki suhu kritikal jauh di bawah suhu reservoar";}','','a:2:{i:0;s:36:"Initial GOR kurang dari 2000 scf/stb";i:1;s:39:"Warna cairan cenderung gelap atau hitam";}','Select the criteria that characterize Black Oil type fluid','a:4:{i:0;s:34:"Initial GOR less than 2000 scf/stb";i:1;s:37:"Fluid color tends to be dark or black";i:2;s:40:"Heavy component content is more than 20%";i:3;s:55:"Critical temperature is far below reservoir temperature";}','a:2:{i:0;s:34:"Initial GOR less than 2000 scf/stb";i:1;s:37:"Fluid color tends to be dark or black";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000067','Pada diagram fase P-T, zona di mana hanya terdapat fase gas pada kondisi reservoar untuk jenis dry gas berada di sebelah mana dari kurva saturasi?','option','PFM000000014','a:4:{i:0;s:26:"Di dalam kurva amplop fase";i:1;s:32:"Di sebelah kanan garis dew point";i:2;s:34:"Di sebelah kiri garis bubble point";i:3;s:22:"Di atas titik kritikal";}','','Di sebelah kanan garis dew point','In a P-T phase diagram, the zone where only the gas phase exists under reservoir conditions for dry gas is located where relative to the saturation curve?','a:4:{i:0;s:25:"Inside the phase envelope";i:1;s:34:"To the right of the dew point line";i:2;s:36:"To the left of the bubble point line";i:3;s:24:"Above the critical point";}','To the right of the dew point line','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000068','Gas yang tidak mengalami kondensasi saat tekanan turun baik di dalam reservoar maupun di permukaan karena komposisinya didominasi oleh metana disebut','option','PFM000000014','a:4:{i:0;s:7:"Wet gas";i:1;s:14:"Retrograde gas";i:2;s:7:"Dry gas";i:3;s:12:"Volatile oil";}','','Dry gas','Gas that does not condense when pressure drops either in the reservoir or at the surface because its composition is dominated by methane is called','a:4:{i:0;s:7:"Wet gas";i:1;s:14:"Retrograde gas";i:2;s:7:"Dry gas";i:3;s:12:"Volatile oil";}','Dry gas','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000069','Manakah pernyataan yang paling tepat mengenai perbedaan antara Volatile oil dan Black oil?','option','PFM000000014','a:4:{i:0;s:62:"Volatile oil memiliki GOR yang lebih rendah daripada Black oil";i:1;s:100:"Black oil memiliki penyusutan volume cairan (shrinkage) yang jauh lebih tinggi daripada Volatile oil";i:2;s:66:"Volatile oil memiliki GOR berkisar antara 2000 hingga 3300 scf/stb";i:3;s:40:"Volatile oil selalu berwarna hitam pekat";}','','Volatile oil memiliki GOR berkisar antara 2000 hingga 3300 scf/stb','Which statement is most accurate regarding the difference between Volatile oil and Black oil?','a:4:{i:0;s:43:"Volatile oil has a lower GOR than Black oil";i:1;s:67:"Black oil has much higher liquid volume shrinkage than Volatile oil";i:2;s:56:"Volatile oil has a GOR ranging from 2000 to 3300 scf/stb";i:3;s:34:"Volatile oil is always pitch black";}','Volatile oil has a GOR ranging from 2000 to 3300 scf/stb','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000070','Apa yang dimaksud dengan faktor volume formasi minyak (Bo) pada kondisi tekanan dan temperatur reservoar?','option','PFM000000015','a:4:{i:0;s:73:"Perbandingan volume minyak di permukaan dengan volume minyak di reservoar";i:1;s:73:"Perbandingan volume minyak di reservoar dengan volume minyak di permukaan";i:2;s:70:"Perbandingan volume gas di reservoar dengan volume minyak di permukaan";i:3;s:70:"Perbandingan densitas minyak di reservoar dengan densitas di permukaan";}','','Perbandingan volume minyak di reservoar dengan volume minyak di permukaan','What is the definition of the oil formation volume factor (Bo) at reservoir pressure and temperature conditions?','a:4:{i:0;s:57:"Ratio of oil volume at surface to oil volume at reservoir";i:1;s:57:"Ratio of oil volume at reservoir to oil volume at surface";i:2;s:57:"Ratio of gas volume at reservoir to oil volume at surface";i:3;s:55:"Ratio of oil density at reservoir to density at surface";}','Ratio of oil volume at reservoir to oil volume at surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000071','Faktor apa saja yang memengaruhi nilai kelarutan gas (Rs) dalam minyak mentah di bawah kondisi reservoar?','multi','PFM000000015','a:4:{i:0;s:17:"Tekanan reservoar";i:1;s:20:"Temperatur reservoar";i:2;s:20:"Permeabilitas batuan";i:3;s:21:"Komposisi hidrokarbon";}','','a:3:{i:0;s:17:"Tekanan reservoar";i:1;s:20:"Temperatur reservoar";i:2;s:21:"Komposisi hidrokarbon";}','Which factors influence the gas solubility (Rs) in crude oil under reservoir conditions?','a:4:{i:0;s:18:"Reservoir pressure";i:1;s:21:"Reservoir temperature";i:2;s:17:"Rock permeability";i:3;s:23:"Hydrocarbon composition";}','a:3:{i:0;s:18:"Reservoir pressure";i:1;s:21:"Reservoir temperature";i:2;s:23:"Hydrocarbon composition";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000072','Bagaimana pengaruh kenaikan tekanan terhadap nilai kompresibilitas isotermal minyak di bawah titik jenuh (bubble point)?','option','PFM000000015','a:4:{i:0;s:61:"Semakin tinggi tekanan, kompresibilitas minyak akan meningkat";i:1;s:59:"Semakin tinggi tekanan, kompresibilitas minyak akan menurun";i:2;s:63:"Kompresibilitas minyak tetap konstan terhadap perubahan tekanan";i:3;s:72:"Kompresibilitas minyak akan menjadi nol pada tekanan di atas titik jenuh";}','','Semakin tinggi tekanan, kompresibilitas minyak akan menurun','How does an increase in pressure affect the isothermal compressibility of oil below the bubble point?','a:4:{i:0;s:58:"The higher the pressure, the oil compressibility increases";i:1;s:58:"The higher the pressure, the oil compressibility decreases";i:2;s:58:"Oil compressibility remains constant with pressure changes";i:3;s:68:"Oil compressibility becomes zero at pressures above the bubble point";}','The higher the pressure, the oil compressibility decreases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000073','Manakah pernyataan yang benar mengenai faktor volume formasi gas (Bg)?','option','PFM000000015','a:4:{i:0;s:41:"Bg bernilai konstan untuk semua jenis gas";i:1;s:28:"Bg selalu lebih kecil dari 1";i:2;s:83:"Bg merepresentasikan volume gas di reservoar per satuan volume standar di permukaan";i:3;s:56:"Bg tidak dipengaruhi oleh faktor kompresibilitas gas (z)";}','','Bg merepresentasikan volume gas di reservoar per satuan volume standar di permukaan','Which statement is correct regarding the gas formation volume factor (Bg)?','a:4:{i:0;s:37:"Bg is constant for all types of gases";i:1;s:24:"Bg is always less than 1";i:2;s:78:"Bg represents the reservoir gas volume per unit standard volume at the surface";i:3;s:56:"Bg is not affected by the gas compressibility factor (z)";}','Bg represents the reservoir gas volume per unit standard volume at the surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000074','Data PVT sangat krusial dalam rekayasa reservoar untuk keperluan apa saja?','multi','PFM000000015','a:4:{i:0;s:32:"Perhitungan cadangan hidrokarbon";i:1;s:26:"Simulasi numerik reservoar";i:2;s:26:"Penentuan porositas batuan";i:3;s:26:"Analisis performa produksi";}','','a:3:{i:0;s:32:"Perhitungan cadangan hidrokarbon";i:1;s:26:"Simulasi numerik reservoar";i:2;s:26:"Analisis performa produksi";}','PVT data is crucial in reservoir engineering for which of the following purposes?','a:4:{i:0;s:32:"Hydrocarbon reserve calculations";i:1;s:30:"Numerical reservoir simulation";i:2;s:30:"Determination of rock porosity";i:3;s:31:"Production performance analysis";}','a:3:{i:0;s:32:"Hydrocarbon reserve calculations";i:1;s:30:"Numerical reservoir simulation";i:2;s:31:"Production performance analysis";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000075','Bagaimana pengaruh peningkatan temperatur terhadap viskositas minyak mentah dalam kondisi reservoir?','option','PFM000000016','a:4:{i:0;s:38:"Viskositas meningkat secara signifikan";i:1;s:18:"Viskositas menurun";i:2;s:24:"Viskositas tetap konstan";i:3;s:37:"Viskositas meningkat kemudian menurun";}','','Viskositas menurun','How does an increase in temperature affect the viscosity of crude oil under reservoir conditions?','a:4:{i:0;s:33:"Viscosity increases significantly";i:1;s:19:"Viscosity decreases";i:2;s:26:"Viscosity remains constant";i:3;s:34:"Viscosity increases then decreases";}','Viscosity decreases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000076','Faktor apa saja yang menyebabkan perubahan densitas minyak bumi?','multi','PFM000000016','a:4:{i:0;s:17:"Tekanan reservoir";i:1;s:27:"Komposisi kimia hidrokarbon";i:2;s:17:"Temperatur sistem";i:3;s:24:"Tingkat porositas batuan";}','','a:3:{i:0;s:17:"Tekanan reservoir";i:1;s:27:"Komposisi kimia hidrokarbon";i:2;s:17:"Temperatur sistem";}','What factors cause changes in crude oil density?','a:4:{i:0;s:18:"Reservoir pressure";i:1;s:36:"Chemical composition of hydrocarbons";i:2;s:18:"System temperature";i:3;s:19:"Rock porosity level";}','a:3:{i:0;s:18:"Reservoir pressure";i:1;s:36:"Chemical composition of hydrocarbons";i:2;s:18:"System temperature";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000077','Sebuah minyak memiliki API gravity sebesar 35 derajat. Dalam klasifikasi standar, minyak ini termasuk dalam kategori apa?','option','PFM000000016','a:4:{i:0;s:15:"Extra heavy oil";i:1;s:9:"Heavy oil";i:2;s:10:"Medium oil";i:3;s:9:"Light oil";}','','Medium oil','An oil has an API gravity of 35 degrees. In standard classification, what category does this oil fall into?','a:4:{i:0;s:15:"Extra heavy oil";i:1;s:9:"Heavy oil";i:2;s:10:"Medium oil";i:3;s:9:"Light oil";}','Medium oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000078','Apa yang terjadi pada viskositas gas jika tekanan meningkat di atas titik jenuh (bubble point) pada temperatur konstan?','option','PFM000000016','a:4:{i:0;s:20:"Viskositas meningkat";i:1;s:18:"Viskositas menurun";i:2;s:24:"Viskositas tidak berubah";i:3;s:22:"Viskositas menjadi nol";}','','Viskositas meningkat','What happens to gas viscosity if the pressure increases above the bubble point at constant temperature?','a:4:{i:0;s:19:"Viscosity increases";i:1;s:19:"Viscosity decreases";i:2;s:25:"Viscosity does not change";i:3;s:22:"Viscosity becomes zero";}','Viscosity increases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000079','Bagaimana hubungan antara derajat API dengan densitas minyak mentah?','option','PFM000000016','a:4:{i:0;s:16:"Berbanding lurus";i:1;s:19:"Berbanding terbalik";i:2;s:17:"Tidak berhubungan";i:3;s:29:"Hubungan eksponensial positif";}','','Berbanding terbalik','What is the relationship between API gravity and crude oil density?','a:4:{i:0;s:21:"Directly proportional";i:1;s:22:"Inversely proportional";i:2;s:9:"Unrelated";i:3;s:33:"Positive exponential relationship";}','Inversely proportional','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000080','Bagaimana pengaruh peningkatan temperatur terhadap nilai resistivitas air formasi (Rw) pada salinitas yang tetap?','option','PFM000000017','a:4:{i:0;s:23:"Nilai Rw akan meningkat";i:1;s:21:"Nilai Rw akan menurun";i:2;s:22:"Nilai Rw tidak berubah";i:3;s:32:"Nilai Rw menjadi tidak terhingga";}','','Nilai Rw akan menurun','How does an increase in temperature affect the formation water resistivity (Rw) value at a constant salinity?','a:4:{i:0;s:22:"Rw value will increase";i:1;s:22:"Rw value will decrease";i:2;s:30:"Rw value will remain unchanged";i:3;s:29:"Rw value will become infinite";}','Rw value will decrease','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000081','Faktor utama apa saja yang menentukan besarnya nilai resistivitas air formasi (Rw)?','multi','PFM000000017','a:4:{i:0;s:46:"Konsentrasi total padatan terlarut (salinitas)";i:1;s:18:"Temperatur formasi";i:2;s:22:"Tekanan kapiler batuan";i:3;s:17:"Viskositas fluida";}','','a:2:{i:0;s:46:"Konsentrasi total padatan terlarut (salinitas)";i:1;s:18:"Temperatur formasi";}','What are the primary factors that determine the value of formation water resistivity (Rw)?','a:4:{i:0;s:47:"Total dissolved solids concentration (salinity)";i:1;s:21:"Formation temperature";i:2;s:23:"Rock capillary pressure";i:3;s:15:"Fluid viscosity";}','a:2:{i:0;s:47:"Total dissolved solids concentration (salinity)";i:1;s:21:"Formation temperature";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000082','Jika salinitas air formasi meningkat, apa yang terjadi pada nilai resistivitas air (Rw) tersebut?','option','PFM000000017','a:4:{i:0;s:41:"Resistivitas akan meningkat secara linear";i:1;s:75:"Resistivitas akan menurun karena meningkatnya jumlah ion penghantar listrik";i:2;s:61:"Resistivitas tetap konstan karena tidak dipengaruhi salinitas";i:3;s:47:"Resistivitas akan meningkat secara eksponensial";}','','Resistivitas akan menurun karena meningkatnya jumlah ion penghantar listrik','If the formation water salinity increases, what happens to the water resistivity (Rw) value?','a:4:{i:0;s:34:"Resistivity will increase linearly";i:1;s:64:"Resistivity will decrease due to the increase in conductive ions";i:2;s:61:"Resistivity remains constant as it is independent of salinity";i:3;s:39:"Resistivity will increase exponentially";}','Resistivity will decrease due to the increase in conductive ions','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000083','Dalam persamaan Archie, parameter apakah yang merepresentasikan hambatan listrik dari air formasi yang mengisi pori-pori batuan?','option','PFM000000017','a:4:{i:0;s:9:"Porositas";i:1;s:14:"Faktor formasi";i:2;s:29:"Resistivitas air formasi (Rw)";i:3;s:17:"Saturasi air (Sw)";}','','Resistivitas air formasi (Rw)','In the Archie equation, which parameter represents the electrical resistance of the formation water filling the rock pores?','a:4:{i:0;s:8:"Porosity";i:1;s:16:"Formation factor";i:2;s:32:"Formation water resistivity (Rw)";i:3;s:21:"Water saturation (Sw)";}','Formation water resistivity (Rw)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000084','Mengapa penting untuk mengoreksi nilai Rw terhadap temperatur saat melakukan interpretasi log resistivitas?','option','PFM000000017','a:4:{i:0;s:88:"Karena resistivitas air sangat sensitif terhadap perubahan temperatur di bawah permukaan";i:1;s:56:"Karena temperatur tidak mempengaruhi konduktivitas ionik";i:2;s:58:"Karena alat log resistivitas hanya bekerja pada suhu ruang";i:3;s:52:"Karena Rw selalu konstan pada setiap kedalaman sumur";}','','Karena resistivitas air sangat sensitif terhadap perubahan temperatur di bawah permukaan','Why is it important to correct Rw values for temperature when interpreting resistivity logs?','a:4:{i:0;s:79:"Because water resistivity is highly sensitive to subsurface temperature changes";i:1;s:54:"Because temperature does not affect ionic conductivity";i:2;s:63:"Because resistivity logging tools only work at room temperature";i:3;s:49:"Because Rw is always constant at every well depth";}','Because water resistivity is highly sensitive to subsurface temperature changes','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000085','Manakah pernyataan yang paling tepat mengenai hubungan resistivitas batuan (Ro) yang terisi air formasi 100% terhadap resistivitas air formasi (Rw)?','option','PFM000000018','a:4:{i:0;s:32:"Ro berbanding terbalik dengan Rw";i:1;s:46:"Ro sama dengan Rw dikalikan faktor formasi (F)";i:2;s:36:"Ro adalah hasil bagi antara F dan Rw";i:3;s:28:"Ro tidak dipengaruhi oleh Rw";}','','Ro sama dengan Rw dikalikan faktor formasi (F)','Which statement best describes the relationship between the resistivity of a 100% water-saturated rock (Ro) and the formation water resistivity (Rw)?','a:4:{i:0;s:34:"Ro is inversely proportional to Rw";i:1;s:56:"Ro is equal to Rw multiplied by the formation factor (F)";i:2;s:30:"Ro is the quotient of F and Rw";i:3;s:23:"Ro is independent of Rw";}','Ro is equal to Rw multiplied by the formation factor (F)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000086','Faktor apa saja yang memengaruhi nilai faktor formasi (F) menurut rumus Archie?','multi','PFM000000018','a:4:{i:0;s:16:"Porositas batuan";i:1;s:12:"Saturasi air";i:2;s:18:"Tortuositas batuan";i:3;s:19:"Resistivitas lumpur";}','','a:2:{i:0;s:16:"Porositas batuan";i:1;s:18:"Tortuositas batuan";}','What factors influence the formation factor (F) according to Archie''s formula?','a:4:{i:0;s:13:"Rock porosity";i:1;s:16:"Water saturation";i:2;s:15:"Rock tortuosity";i:3;s:15:"Mud resistivity";}','a:2:{i:0;s:13:"Rock porosity";i:1;s:15:"Rock tortuosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000087','Bagaimana pengaruh kehadiran mineral clay atau shale pada pengukuran resistivitas batuan?','option','PFM000000018','a:4:{i:0;s:32:"Meningkatkan resistivitas batuan";i:1;s:52:"Menurunkan resistivitas batuan (excess conductivity)";i:2;s:45:"Tidak memiliki pengaruh terhadap resistivitas";i:3;s:61:"Hanya memengaruhi nilai porositas tanpa mengubah resistivitas";}','','Menurunkan resistivitas batuan (excess conductivity)','How does the presence of clay minerals or shale affect rock resistivity measurements?','a:4:{i:0;s:26:"Increases rock resistivity";i:1;s:48:"Decreases rock resistivity (excess conductivity)";i:2;s:28:"Has no effect on resistivity";i:3;s:57:"Only affects porosity values without changing resistivity";}','Decreases rock resistivity (excess conductivity)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000088','Jika sebuah formasi mengandung shale, nilai resistivitas yang terukur (Rt) akan cenderung memberikan estimasi saturasi air (Sw) yang bagaimana?','option','PFM000000018','a:4:{i:0;s:33:"Lebih rendah dari yang seharusnya";i:1;s:33:"Lebih tinggi dari yang seharusnya";i:2;s:32:"Tetap akurat tanpa perlu koreksi";i:3;s:22:"Tidak dapat ditentukan";}','','Lebih tinggi dari yang seharusnya','If a formation contains shale, how will the measured resistivity (Rt) tend to affect the estimation of water saturation (Sw)?','a:4:{i:0;s:23:"Lower than it should be";i:1;s:24:"Higher than it should be";i:2;s:35:"Remains accurate without correction";i:3;s:20:"Cannot be determined";}','Higher than it should be','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000089','Metode atau model manakah yang umum digunakan untuk melakukan koreksi pengaruh shale pada perhitungan saturasi air?','option','PFM000000018','a:4:{i:0;s:12:"Model Archie";i:1;s:33:"Model Simandoux atau Waxman-Smits";i:2;s:11:"Model Darcy";i:3;s:16:"Model Buckingham";}','','Model Simandoux atau Waxman-Smits','Which models or methods are commonly used to correct for the effect of shale in water saturation calculations?','a:4:{i:0;s:12:"Archie model";i:1;s:32:"Simandoux or Waxman-Smits models";i:2;s:11:"Darcy model";i:3;s:16:"Buckingham model";}','Simandoux or Waxman-Smits models','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000090','Log radioaktif mana yang paling umum digunakan untuk membedakan lapisan serpih (shale) dari batuan reservoir berdasarkan konsentrasi isotop alami?','option','PFM000000019','a:4:{i:0;s:13:"Log Gamma Ray";i:1;s:16:"Log Resistivitas";i:2;s:12:"Log Densitas";i:3;s:11:"Log Neutron";}','','Log Gamma Ray','Which radioactive log is commonly used to distinguish shale layers from reservoir rocks based on natural isotope concentrations?','a:4:{i:0;s:13:"Gamma Ray Log";i:1;s:15:"Resistivity Log";i:2;s:11:"Density Log";i:3;s:11:"Neutron Log";}','Gamma Ray Log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000091','Manakah dari metode logging berikut yang diklasifikasikan sebagai log listrik (electrical logs)?','multi','PFM000000019','a:4:{i:0;s:16:"Log Resistivitas";i:1;s:30:"Log Spontaneous Potential (SP)";i:2;s:11:"Log Akustik";i:3;s:11:"Log Neutron";}','','a:2:{i:0;s:16:"Log Resistivitas";i:1;s:30:"Log Spontaneous Potential (SP)";}','Which of the following logging methods are classified as electrical logs?','a:4:{i:0;s:15:"Resistivity Log";i:1;s:30:"Spontaneous Potential (SP) Log";i:2;s:12:"Acoustic Log";i:3;s:11:"Neutron Log";}','a:2:{i:0;s:15:"Resistivity Log";i:1;s:30:"Spontaneous Potential (SP) Log";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000092','Apa fungsi utama dari Log Akustik (Sonic Log) dalam evaluasi formasi?','option','PFM000000019','a:4:{i:0;s:64:"Mengukur waktu tempuh gelombang suara untuk menentukan porositas";i:1;s:43:"Mengukur konsentrasi unsur radioaktif alami";i:2;s:43:"Mengukur perbedaan potensial listrik batuan";i:3;s:29:"Mengukur densitas bulk batuan";}','','Mengukur waktu tempuh gelombang suara untuk menentukan porositas','What is the primary function of the Sonic Log in formation evaluation?','a:4:{i:0;s:54:"Measuring sound wave travel time to determine porosity";i:1;s:51:"Measuring natural radioactive element concentration";i:2;s:54:"Measuring the electrical potential difference of rocks";i:3;s:31:"Measuring bulk density of rocks";}','Measuring sound wave travel time to determine porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000093','Log yang mengukur kemampuan formasi dalam menghantarkan arus listrik untuk menentukan saturasi air adalah...','option','PFM000000019','a:4:{i:0;s:16:"Log Resistivitas";i:1;s:13:"Log Gamma Ray";i:2;s:11:"Log Neutron";i:3;s:24:"Log Photoelectric Factor";}','','Log Resistivitas','The log that measures the formation''s ability to conduct electrical current to determine water saturation is...','a:4:{i:0;s:15:"Resistivity Log";i:1;s:13:"Gamma Ray Log";i:2;s:11:"Neutron Log";i:3;s:24:"Photoelectric Factor Log";}','Resistivity Log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000094','Dalam konteks wireline logging, apa yang dimaksud dengan proses pengukuran ''open hole''?','option','PFM000000019','a:4:{i:0;s:60:"Pengukuran dilakukan di lubang bor sebelum pemasangan casing";i:1;s:57:"Pengukuran dilakukan setelah casing terpasang dan disemen";i:2;s:84:"Pengukuran yang dilakukan dengan menggunakan alat yang ditarik melalui pipa produksi";i:3;s:44:"Pengukuran tekanan reservoir secara langsung";}','','Pengukuran dilakukan di lubang bor sebelum pemasangan casing','In the context of wireline logging, what is meant by the ''open hole'' measurement process?','a:4:{i:0;s:64:"Measurement conducted in the wellbore before casing installation";i:1;s:64:"Measurement conducted after the casing is installed and cemented";i:2;s:66:"Measurement conducted using tools pulled through production tubing";i:3;s:37:"Direct reservoir pressure measurement";}','Measurement conducted in the wellbore before casing installation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000095','Apa fungsi utama dari log Gamma Ray dalam evaluasi formasi?','option','PFM000000020','a:4:{i:0;s:25:"Mengukur porositas batuan";i:1;s:40:"Membedakan litologi batupasir dan serpih";i:2;s:23:"Menentukan saturasi air";i:3;s:28:"Mengukur diameter lubang bor";}','','Membedakan litologi batupasir dan serpih','What is the primary function of the Gamma Ray log in formation evaluation?','a:4:{i:0;s:23:"Measuring rock porosity";i:1;s:53:"Differentiating between sandstone and shale lithology";i:2;s:28:"Determining water saturation";i:3;s:27:"Measuring borehole diameter";}','Differentiating between sandstone and shale lithology','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000096','Indikasi keberadaan mudcake pada log Caliper ditandai dengan hal berikut:','option','PFM000000020','a:4:{i:0;s:49:"Diameter lubang lebih besar daripada ukuran pahat";i:1;s:40:"Diameter lubang sama dengan ukuran pahat";i:2;s:49:"Diameter lubang lebih kecil daripada ukuran pahat";i:3;s:45:"Pembacaan log Gamma Ray menjadi sangat rendah";}','','Diameter lubang lebih kecil daripada ukuran pahat','The indication of mudcake presence on a Caliper log is characterized by:','a:4:{i:0;s:42:"Borehole diameter larger than the bit size";i:1;s:39:"Borehole diameter equal to the bit size";i:2;s:43:"Borehole diameter smaller than the bit size";i:3;s:38:"Gamma Ray log reading becomes very low";}','Borehole diameter smaller than the bit size','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000097','Manakah di antara faktor berikut yang mempengaruhi pembacaan log Gamma Ray dan memerlukan koreksi lingkungan?','multi','PFM000000020','a:4:{i:0;s:24:"Densitas lumpur pemboran";i:1;s:19:"Diameter lubang bor";i:2;s:32:"Konsentrasi kalium dalam formasi";i:3;s:17:"Ketebalan mudcake";}','','a:3:{i:0;s:24:"Densitas lumpur pemboran";i:1;s:19:"Diameter lubang bor";i:2;s:17:"Ketebalan mudcake";}','Which of the following factors affect Gamma Ray log readings and require environmental corrections?','a:4:{i:0;s:20:"Drilling mud density";i:1;s:17:"Borehole diameter";i:2;s:40:"Potassium concentration in the formation";i:3;s:17:"Mudcake thickness";}','a:3:{i:0;s:20:"Drilling mud density";i:1;s:17:"Borehole diameter";i:2;s:17:"Mudcake thickness";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000098','Apa yang dimaksud dengan kondisi washout pada log Caliper?','option','PFM000000020','a:4:{i:0;s:36:"Terbentuknya kerak lumpur yang tebal";i:1;s:60:"Diameter lubang bor membesar akibat runtuhnya dinding lubang";i:2;s:55:"Diameter lubang bor mengecil akibat pembengkakan serpih";i:3;s:41:"Lubang bor memiliki diameter yang konstan";}','','Diameter lubang bor membesar akibat runtuhnya dinding lubang','What is meant by washout condition on a Caliper log?','a:4:{i:0;s:28:"Formation of a thick mudcake";i:1;s:47:"Borehole diameter enlarges due to wall collapse";i:2;s:49:"Borehole diameter decreases due to shale swelling";i:3;s:32:"Borehole has a constant diameter";}','Borehole diameter enlarges due to wall collapse','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000099','Log Gamma Ray mengukur radiasi alami yang dipancarkan terutama oleh unsur:','option','PFM000000020','a:4:{i:0;s:29:"Karbon, Hidrogen, dan Oksigen";i:1;s:30:"Potasium, Uranium, dan Thorium";i:2;s:28:"Kalsium, Magnesium, dan Besi";i:3;s:27:"Silika, Alumina, dan Sulfat";}','','Potasium, Uranium, dan Thorium','The Gamma Ray log measures natural radiation emitted primarily by which elements?','a:4:{i:0;s:28:"Carbon, Hydrogen, and Oxygen";i:1;s:31:"Potassium, Uranium, and Thorium";i:2;s:28:"Calcium, Magnesium, and Iron";i:3;s:28:"Silica, Alumina, and Sulfate";}','Potassium, Uranium, and Thorium','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000100','Manakah dari komponen berikut yang berperan utama dalam pembentukan potensial listrik pada log SP melalui mekanisme perbedaan mobilitas ion antara filtrat lumpur dan air formasi?','option','PFM000000021','a:4:{i:0;s:44:"Potensial difusi (liquid junction potential)";i:1;s:33:"Potensial induksi elektromagnetik";i:2;s:28:"Potensial radiasi radioaktif";i:3;s:26:"Potensial gravitasi batuan";}','','Potensial difusi (liquid junction potential)','Which of the following components plays a major role in the generation of electrical potential in an SP log through the mechanism of ion mobility differences between mud filtrate and formation water?','a:4:{i:0;s:25:"Liquid junction potential";i:1;s:35:"Electromagnetic induction potential";i:2;s:31:"Radioactive radiation potential";i:3;s:22:"Rock gravity potential";}','Liquid junction potential','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000101','Kapan defleksi log SP ke arah kiri (negatif) terjadi pada sumur bor?','option','PFM000000021','a:4:{i:0;s:75:"Ketika salinitas air formasi lebih tinggi daripada salinitas filtrat lumpur";i:1;s:75:"Ketika salinitas filtrat lumpur lebih tinggi daripada salinitas air formasi";i:2;s:54:"Ketika zona batuan bersifat impermeabel (serpih/shale)";i:3;s:74:"Ketika terjadi kontak langsung antara fluida hidrokarbon dengan lubang bor";}','','Ketika salinitas air formasi lebih tinggi daripada salinitas filtrat lumpur','When does a negative (leftward) SP log deflection occur in a borehole?','a:4:{i:0;s:66:"When formation water salinity is higher than mud filtrate salinity";i:1;s:66:"When mud filtrate salinity is higher than formation water salinity";i:2;s:41:"When the rock zone is impermeable (shale)";i:3;s:71:"When there is direct contact between hydrocarbon fluid and the borehole";}','When formation water salinity is higher than mud filtrate salinity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000102','Faktor apa saja yang memengaruhi besarnya defleksi SP pada zona permeabel?','multi','PFM000000021','a:4:{i:0;s:24:"Ketebalan lapisan batuan";i:1;s:57:"Perbedaan salinitas antara air formasi dan filtrat lumpur";i:2;s:46:"Derajat invasi filtrat lumpur ke dalam formasi";i:3;s:41:"Kandungan mineral radioaktif dalam batuan";}','','a:3:{i:0;s:24:"Ketebalan lapisan batuan";i:1;s:57:"Perbedaan salinitas antara air formasi dan filtrat lumpur";i:2;s:46:"Derajat invasi filtrat lumpur ke dalam formasi";}','Which factors influence the magnitude of SP deflection in a permeable zone?','a:4:{i:0;s:13:"Bed thickness";i:1;s:58:"Salinity contrast between formation water and mud filtrate";i:2;s:50:"Degree of mud filtrate invasion into the formation";i:3;s:39:"Radioactive mineral content in the rock";}','a:3:{i:0;s:13:"Bed thickness";i:1;s:58:"Salinity contrast between formation water and mud filtrate";i:2;s:50:"Degree of mud filtrate invasion into the formation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000103','Mengapa log SP tidak dapat digunakan untuk mengukur porositas secara langsung?','option','PFM000000021','a:4:{i:0;s:91:"Karena log SP didasarkan pada arus elektrokimia, bukan sifat fisik batuan seperti porositas";i:1;s:69:"Karena alat SP hanya bekerja pada lubang bor yang tidak berisi lumpur";i:2;s:62:"Karena log SP hanya merespon kehadiran mineral logam konduktif";i:3;s:67:"Karena log SP memerlukan sumber energi eksternal yang sangat tinggi";}','','Karena log SP didasarkan pada arus elektrokimia, bukan sifat fisik batuan seperti porositas','Why can the SP log not be used to measure porosity directly?','a:4:{i:0;s:99:"Because the SP log is based on electrochemical currents, not physical rock properties like porosity";i:1;s:55:"Because the SP tool only works in boreholes without mud";i:2;s:80:"Because the SP log only responds to the presence of conductive metallic minerals";i:3;s:62:"Because the SP log requires a very high external energy source";}','Because the SP log is based on electrochemical currents, not physical rock properties like porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000104','Apa yang ditunjukkan oleh garis dasar (shale baseline) pada rekaman log SP?','option','PFM000000021','a:4:{i:0;s:36:"Zona yang impermeabel seperti serpih";i:1;s:32:"Zona dengan permeabilitas tinggi";i:2;s:35:"Zona dengan saturasi air 100 persen";i:3;s:29:"Zona yang mengandung gas alam";}','','Zona yang impermeabel seperti serpih','What is indicated by the shale baseline on an SP log recording?','a:4:{i:0;s:31:"Impermeable zones such as shale";i:1;s:28:"Zones with high permeability";i:2;s:39:"Zones with 100 percent water saturation";i:3;s:28:"Zones containing natural gas";}','Impermeable zones such as shale','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000105','Manakah pernyataan yang benar mengenai hubungan antara resistivitas formasi (Rt) dengan saturasi air (Sw) berdasarkan Hukum Archie?','option','PFM000000022','a:4:{i:0;s:29:"Rt berbanding lurus dengan Sw";i:1;s:32:"Rt berbanding terbalik dengan Sw";i:2;s:28:"Rt tidak dipengaruhi oleh Sw";i:3;s:37:"Rt berbanding lurus dengan kuadrat Sw";}','','Rt berbanding terbalik dengan Sw','Which statement is correct regarding the relationship between true formation resistivity (Rt) and water saturation (Sw) based on Archie''s Law?','a:4:{i:0;s:33:"Rt is directly proportional to Sw";i:1;s:34:"Rt is inversely proportional to Sw";i:2;s:26:"Rt is not influenced by Sw";i:3;s:47:"Rt is directly proportional to the square of Sw";}','Rt is inversely proportional to Sw','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000106','Faktor apa saja yang memengaruhi pembacaan resistivitas pada zona invasi (invaded zone)?','multi','PFM000000022','a:4:{i:0;s:27:"Resistivitas filtrat lumpur";i:1;s:30:"Saturasi air formasi yang asli";i:2;s:25:"Resistivitas formasi (Rt)";i:3;s:29:"Tingkat invasi filtrat lumpur";}','','a:2:{i:0;s:27:"Resistivitas filtrat lumpur";i:1;s:29:"Tingkat invasi filtrat lumpur";}','What factors influence the resistivity reading in the invaded zone?','a:4:{i:0;s:24:"Mud filtrate resistivity";i:1;s:35:"Original formation water saturation";i:2;s:31:"True formation resistivity (Rt)";i:3;s:30:"Depth of mud filtrate invasion";}','a:2:{i:0;s:24:"Mud filtrate resistivity";i:1;s:30:"Depth of mud filtrate invasion";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000107','Jenis log resistivitas manakah yang paling efektif digunakan pada lubang bor yang berisi lumpur berbasis minyak (oil-based mud)?','option','PFM000000022','a:4:{i:0;s:13:"Induction log";i:1;s:11:"Lateral log";i:2;s:9:"Laterolog";i:3;s:21:"Micro-resistivity pad";}','','Induction log','Which type of resistivity log is most effective for use in boreholes containing oil-based mud?','a:4:{i:0;s:13:"Induction log";i:1;s:11:"Lateral log";i:2;s:9:"Laterolog";i:3;s:21:"Micro-resistivity pad";}','Induction log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000108','Pada zona flusher (flushed zone), saturasi fluida di dalam pori didominasi oleh:','option','PFM000000022','a:4:{i:0;s:11:"Air formasi";i:1;s:11:"Minyak bumi";i:2;s:14:"Filtrat lumpur";i:3;s:8:"Gas bumi";}','','Filtrat lumpur','In the flushed zone, the fluid saturation within the pores is dominated by:','a:4:{i:0;s:15:"Formation water";i:1;s:9:"Crude oil";i:2;s:12:"Mud filtrate";i:3;s:11:"Natural gas";}','Mud filtrate','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000109','Apa fungsi utama dari alat Induction Log dalam pengukuran resistivitas?','option','PFM000000022','a:4:{i:0;s:50:"Mengukur resistivitas dengan arus listrik langsung";i:1;s:62:"Mengukur konduktivitas formasi melalui induksi elektromagnetik";i:2;s:41:"Mengukur porositas batuan secara langsung";i:3;s:40:"Mengukur densitas elektron dalam formasi";}','','Mengukur konduktivitas formasi melalui induksi elektromagnetik','What is the primary function of the Induction Log tool in resistivity measurement?','a:4:{i:0;s:51:"Measuring resistivity via direct electrical current";i:1;s:66:"Measuring formation conductivity through electromagnetic induction";i:2;s:32:"Measuring rock porosity directly";i:3;s:43:"Measuring electron density in the formation";}','Measuring formation conductivity through electromagnetic induction','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000110','Log densitas mengukur kerapatan elektron formasi yang kemudian dikonversi menjadi densitas bulk. Faktor utama yang mempengaruhi pembacaan alat densitas adalah:','option','PFM000000023','a:4:{i:0;s:23:"Indeks hidrogen formasi";i:1;s:25:"Kerapatan elektron batuan";i:2;s:27:"Resistivitas fluida formasi";i:3;s:20:"Saturasi air formasi";}','','Kerapatan elektron batuan','The density log measures the electron density of the formation which is then converted to bulk density. The main factor affecting the density tool reading is:','a:4:{i:0;s:24:"Formation hydrogen index";i:1;s:28:"Electron density of the rock";i:2;s:27:"Formation fluid resistivity";i:3;s:26:"Formation water saturation";}','Electron density of the rock','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000111','Log neutron utamanya digunakan untuk menentukan porositas dengan merespons:','option','PFM000000023','a:4:{i:0;s:23:"Kandungan mineral berat";i:1;s:29:"Indeks hidrogen dalam formasi";i:2;s:27:"Kecepatan gelombang seismik";i:3;s:28:"Konduktivitas listrik batuan";}','','Indeks hidrogen dalam formasi','The neutron log is primarily used to determine porosity by responding to:','a:4:{i:0;s:21:"Heavy mineral content";i:1;s:31:"Hydrogen index in the formation";i:2;s:21:"Seismic wave velocity";i:3;s:28:"Rock electrical conductivity";}','Hydrogen index in the formation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000112','Jika terjadi efek crossover pada log densitas dan neutron (kurva densitas berada di sebelah kiri kurva neutron), indikasi yang paling mungkin adalah:','option','PFM000000023','a:4:{i:0;s:19:"Zona mengandung gas";i:1;s:24:"Zona mengandung air asin";i:2;s:19:"Zona serpih (shale)";i:3;s:18:"Zona batuan kompak";}','','Zona mengandung gas','If a crossover effect occurs on the density and neutron logs (density curve is to the left of the neutron curve), the most likely indication is:','a:4:{i:0;s:16:"Gas-bearing zone";i:1;s:18:"Brine-bearing zone";i:2;s:10:"Shale zone";i:3;s:15:"Tight rock zone";}','Gas-bearing zone','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000113','Manakah pernyataan yang benar mengenai keterbatasan log neutron dalam mengevaluasi porositas?','multi','PFM000000023','a:4:{i:0;s:57:"Dipengaruhi oleh mineral lempung yang mengandung hidrogen";i:1;s:45:"Tidak dapat mendeteksi keberadaan minyak bumi";i:2;s:38:"Sangat sensitif terhadap kehadiran gas";i:3;s:35:"Sangat akurat dalam batuan vulkanik";}','','a:2:{i:0;s:57:"Dipengaruhi oleh mineral lempung yang mengandung hidrogen";i:1;s:38:"Sangat sensitif terhadap kehadiran gas";}','Which statements are correct regarding the limitations of the neutron log in porosity evaluation?','a:4:{i:0;s:47:"Influenced by clay minerals containing hydrogen";i:1;s:33:"Cannot detect the presence of oil";i:2;s:39:"Highly sensitive to the presence of gas";i:3;s:31:"Very accurate in volcanic rocks";}','a:2:{i:0;s:47:"Influenced by clay minerals containing hydrogen";i:1;s:39:"Highly sensitive to the presence of gas";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000114','Faktor fotolistrik (Photoelectric Factor/PEF) pada log densitas digunakan untuk:','option','PFM000000023','a:4:{i:0;s:31:"Menghitung saturasi hidrokarbon";i:1;s:32:"Mengidentifikasi litologi batuan";i:2;s:30:"Mengukur permeabilitas absolut";i:3;s:28:"Menentukan viskositas fluida";}','','Mengidentifikasi litologi batuan','The Photoelectric Factor (PEF) on the density log is used to:','a:4:{i:0;s:32:"Calculate hydrocarbon saturation";i:1;s:23:"Identify rock lithology";i:2;s:29:"Measure absolute permeability";i:3;s:25:"Determine fluid viscosity";}','Identify rock lithology','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000115','Parameter utama yang diukur oleh alat log sonic untuk menentukan kecepatan gelombang suara dalam formasi adalah','option','PFM000000024','a:4:{i:0;s:21:"Interval transit time";i:1;s:19:"Resistivitas batuan";i:2;s:17:"Densitas elektron";i:3;s:17:"Potensial spontan";}','','Interval transit time','The primary parameter measured by the sonic logging tool to determine the sound wave velocity in a formation is','a:4:{i:0;s:21:"Interval transit time";i:1;s:16:"Rock resistivity";i:2;s:16:"Electron density";i:3;s:21:"Spontaneous potential";}','Interval transit time','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000116','Manakah dari pernyataan berikut yang benar mengenai Persamaan Wyllie Time-Average?','multi','PFM000000024','a:4:{i:0;s:54:"Digunakan untuk menghitung porositas dari transit time";i:1;s:46:"Mengasumsikan batuan bersih dan terkonsolidasi";i:2;s:59:"Sangat akurat untuk batuan dengan porositas sekunder tinggi";i:3;s:48:"Memerlukan nilai transit time matriks dan fluida";}','','a:3:{i:0;s:54:"Digunakan untuk menghitung porositas dari transit time";i:1;s:46:"Mengasumsikan batuan bersih dan terkonsolidasi";i:2;s:48:"Memerlukan nilai transit time matriks dan fluida";}','Which of the following statements are true regarding the Wyllie Time-Average Equation?','a:4:{i:0;s:44:"Used to calculate porosity from transit time";i:1;s:35:"Assumes clean and consolidated rock";i:2;s:54:"Highly accurate for rocks with high secondary porosity";i:3;s:45:"Requires matrix and fluid transit time values";}','a:3:{i:0;s:44:"Used to calculate porosity from transit time";i:1;s:35:"Assumes clean and consolidated rock";i:2;s:45:"Requires matrix and fluid transit time values";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000117','Dalam aplikasi geofisika, data sonic log sering digunakan untuk melakukan kalibrasi terhadap','option','PFM000000024','a:4:{i:0;s:12:"Data seismik";i:1;s:14:"Data gravitasi";i:2;s:13:"Data magnetik";i:3;s:18:"Data pemboran arah";}','','Data seismik','In geophysical applications, sonic log data is often used to calibrate','a:4:{i:0;s:12:"Seismic data";i:1;s:12:"Gravity data";i:2;s:13:"Magnetic data";i:3;s:25:"Directional drilling data";}','Seismic data','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000118','Properti mekanika batuan (mechanical properties) yang dapat diturunkan dari kombinasi data sonic log dan densitas adalah','option','PFM000000024','a:4:{i:0;s:13:"Modulus Young";i:1;s:21:"Permeabilitas absolut";i:2;s:12:"Saturasi air";i:3;s:15:"Tekanan kapiler";}','','Modulus Young','The mechanical property of rock that can be derived from the combination of sonic log and density data is','a:4:{i:0;s:15:"Young''s modulus";i:1;s:21:"Absolute permeability";i:2;s:16:"Water saturation";i:3;s:18:"Capillary pressure";}','Young''s modulus','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000119','Apa efek utama dari gas (gas effect) pada pembacaan transit time di log sonic?','option','PFM000000024','a:4:{i:0;s:48:"Transit time menjadi lebih lama (cycle skipping)";i:1;s:32:"Transit time menjadi lebih cepat";i:2;s:38:"Transit time tidak mengalami perubahan";i:3;s:24:"Transit time menjadi nol";}','','Transit time menjadi lebih lama (cycle skipping)','What is the primary effect of gas (gas effect) on the transit time reading in a sonic log?','a:4:{i:0;s:39:"Transit time increases (cycle skipping)";i:1;s:27:"Transit time becomes faster";i:2;s:28:"Transit time does not change";i:3;s:25:"Transit time becomes zero";}','Transit time increases (cycle skipping)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000120','Manakah parameter utama yang diperlukan untuk menghitung volume shale (Vsh) menggunakan metode indeks gamma ray linear?','option','PFM000000025','a:4:{i:0;s:30:"GR log, GR shale, dan GR clean";i:1;s:44:"Resistivitas batuan, porositas, dan densitas";i:2;s:44:"Indeks pori, saturasi air, dan permeabilitas";i:3;s:45:"Tekanan kapiler, viskositas, dan suhu formasi";}','','GR log, GR shale, dan GR clean','Which main parameters are required to calculate shale volume (Vsh) using the linear gamma ray index method?','a:4:{i:0;s:30:"GR log, GR shale, and GR clean";i:1;s:39:"Rock resistivity, porosity, and density";i:2;s:46:"Pore index, water saturation, and permeability";i:3;s:56:"Capillary pressure, viscosity, and formation temperature";}','GR log, GR shale, and GR clean','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000121','Pilihlah faktor-faktor yang dipengaruhi oleh keberadaan volume shale (Vsh) dalam evaluasi formasi.','multi','PFM000000025','a:4:{i:0;s:32:"Pembacaan porositas log densitas";i:1;s:26:"Nilai resistivitas formasi";i:2;s:34:"Laju aliran fluida dalam reservoir";i:3;s:31:"Titik didih fluida di permukaan";}','','a:2:{i:0;s:32:"Pembacaan porositas log densitas";i:1;s:26:"Nilai resistivitas formasi";}','Select the factors that are influenced by the presence of shale volume (Vsh) in formation evaluation.','a:4:{i:0;s:28:"Density log porosity reading";i:1;s:27:"Formation resistivity value";i:2;s:28:"Fluid flow rate in reservoir";i:3;s:30:"Fluid boiling point at surface";}','a:2:{i:0;s:28:"Density log porosity reading";i:1;s:27:"Formation resistivity value";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000122','Mengapa korelasi Larionov lebih sering digunakan dibandingkan model linear untuk menghitung Vsh dari log GR?','option','PFM000000025','a:4:{i:0;s:60:"Model linear cenderung mengestimasi nilai Vsh terlalu tinggi";i:1;s:47:"Model Larionov lebih sederhana secara matematis";i:2;s:48:"Model linear hanya berlaku untuk batuan karbonat";i:3;s:45:"Model Larionov tidak memerlukan data GR clean";}','','Model linear cenderung mengestimasi nilai Vsh terlalu tinggi','Why is the Larionov correlation more commonly used than the linear model to calculate Vsh from GR logs?','a:4:{i:0;s:49:"The linear model tends to overestimate Vsh values";i:1;s:44:"The Larionov model is mathematically simpler";i:2;s:48:"The linear model only applies to carbonate rocks";i:3;s:49:"The Larionov model does not require GR clean data";}','The linear model tends to overestimate Vsh values','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000123','Dalam konteks evaluasi log SP, apa yang terjadi pada defleksi kurva SP ketika volume shale (Vsh) meningkat?','option','PFM000000025','a:4:{i:0;s:46:"Defleksi SP berkurang menuju garis dasar shale";i:1;s:43:"Defleksi SP meningkat tajam ke arah negatif";i:2;s:41:"Kurva SP menjadi datar dan tidak sensitif";i:3;s:58:"Kurva SP menunjukkan nilai resistivitas yang sangat tinggi";}','','Defleksi SP berkurang menuju garis dasar shale','In the context of SP log evaluation, what happens to the SP curve deflection as shale volume (Vsh) increases?','a:4:{i:0;s:49:"SP deflection decreases toward the shale baseline";i:1;s:57:"SP deflection increases sharply in the negative direction";i:2;s:41:"The SP curve becomes flat and insensitive";i:3;s:47:"The SP curve shows very high resistivity values";}','SP deflection decreases toward the shale baseline','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000124','Koreksi efek shale pada porositas log densitas diperlukan karena shale memiliki densitas yang umumnya...','option','PFM000000025','a:4:{i:0;s:50:"Lebih tinggi dibandingkan matriks batupasir bersih";i:1;s:33:"Sama persis dengan fluida formasi";i:2;s:43:"Lebih rendah dibandingkan porositas efektif";i:3;s:47:"Tidak memiliki pengaruh terhadap pembacaan alat";}','','Lebih tinggi dibandingkan matriks batupasir bersih','Shale effect correction on density log porosity is necessary because shale generally has a density that is...','a:4:{i:0;s:38:"Higher than the clean sandstone matrix";i:1;s:35:"Exactly the same as formation fluid";i:2;s:33:"Lower than the effective porosity";i:3;s:36:"Having no influence on tool readings";}','Higher than the clean sandstone matrix','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000125','Manakah pernyataan yang paling tepat mengenai pengaruh keberadaan clay terhadap perhitungan porositas dari alat log densitas?','option','PFM000000026','a:4:{i:0;s:107:"Clay cenderung meningkatkan densitas bulk sehingga porositas yang dihitung tampak lebih rendah dari aslinya";i:1;s:56:"Clay tidak berpengaruh terhadap pengukuran densitas bulk";i:2;s:105:"Clay cenderung menurunkan densitas bulk sehingga porositas yang dihitung tampak lebih tinggi dari aslinya";i:3;s:83:"Keberadaan clay hanya memengaruhi pembacaan log neutron dan tidak pada log densitas";}','','Clay cenderung menurunkan densitas bulk sehingga porositas yang dihitung tampak lebih tinggi dari aslinya','Which statement is most accurate regarding the effect of clay presence on porosity calculations from density logs?','a:4:{i:0;s:96:"Clay tends to increase bulk density, making calculated porosity appear lower than it actually is";i:1;s:47:"Clay has no effect on bulk density measurements";i:2;s:97:"Clay tends to decrease bulk density, making calculated porosity appear higher than it actually is";i:3;s:75:"The presence of clay only affects neutron log readings and not density logs";}','Clay tends to decrease bulk density, making calculated porosity appear higher than it actually is','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000126','Dalam penentuan porositas efektif, faktor apa saja yang harus dikurangi dari porositas total?','multi','PFM000000026','a:4:{i:0;s:22:"Volume shale atau clay";i:1;s:40:"Air terikat pada clay (clay-bound water)";i:2;s:28:"Kapasitas fluida hidrokarbon";i:3;s:21:"Permeabilitas absolut";}','','a:2:{i:0;s:22:"Volume shale atau clay";i:1;s:40:"Air terikat pada clay (clay-bound water)";}','In determining effective porosity, which factors must be subtracted from total porosity?','a:4:{i:0;s:20:"Shale or clay volume";i:1;s:16:"Clay-bound water";i:2;s:26:"Hydrocarbon fluid capacity";i:3;s:21:"Absolute permeability";}','a:2:{i:0;s:20:"Shale or clay volume";i:1;s:16:"Clay-bound water";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000127','Jika log neutron dan densitas diplot pada skala yang sama (misalnya batu gamping), efek apa yang terlihat jika formasi mengandung gas?','option','PFM000000026','a:4:{i:0;s:95:"Terjadi cross-over di mana porositas neutron tampak rendah dan porositas densitas tampak tinggi";i:1;s:37:"Kedua kurva berhimpit secara sempurna";i:2;s:88:"Porositas neutron tampak sangat tinggi sedangkan porositas densitas tampak sangat rendah";i:3;s:47:"Tidak ada perubahan signifikan pada kedua kurva";}','','Terjadi cross-over di mana porositas neutron tampak rendah dan porositas densitas tampak tinggi','If neutron and density logs are plotted on the same scale (e.g., limestone), what effect is observed if the formation contains gas?','a:4:{i:0;s:88:"A cross-over occurs where neutron porosity appears low and density porosity appears high";i:1;s:29:"Both curves overlap perfectly";i:2;s:74:"Neutron porosity appears very high while density porosity appears very low";i:3;s:45:"There is no significant change in both curves";}','A cross-over occurs where neutron porosity appears low and density porosity appears high','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000128','Berapakah rumus kombinasi porositas yang umum digunakan untuk meminimalkan efek gas dalam estimasi porositas total (phi_ND)?','option','PFM000000026','a:4:{i:0;s:28:"phi_ND = (phi_N + phi_D) / 2";i:1;s:54:"phi_ND = akar pangkat dua dari (phi_N^2 + phi_D^2) / 2";i:2;s:28:"phi_ND = (phi_N - phi_D) * 2";i:3;s:22:"phi_ND = phi_N * phi_D";}','','phi_ND = akar pangkat dua dari (phi_N^2 + phi_D^2) / 2','What is the common porosity combination formula used to minimize gas effects in total porosity estimation (phi_ND)?','a:4:{i:0;s:28:"phi_ND = (phi_N + phi_D) / 2";i:1;s:47:"phi_ND = square root of (phi_N^2 + phi_D^2) / 2";i:2;s:28:"phi_ND = (phi_N - phi_D) * 2";i:3;s:22:"phi_ND = phi_N * phi_D";}','phi_ND = square root of (phi_N^2 + phi_D^2) / 2','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000129','Alat log manakah yang prinsip kerjanya berdasarkan waktu tempuh gelombang akustik untuk menentukan porositas?','option','PFM000000026','a:4:{i:0;s:11:"Density Log";i:1;s:9:"Sonic Log";i:2;s:11:"Neutron Log";i:3;s:15:"Resistivity Log";}','','Sonic Log','Which logging tool uses the travel time of acoustic waves as its working principle to determine porosity?','a:4:{i:0;s:11:"Density Log";i:1;s:9:"Sonic Log";i:2;s:11:"Neutron Log";i:3;s:15:"Resistivity Log";}','Sonic Log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000130','Dalam persamaan Archie, berapakah nilai eksponen sementasi m yang umumnya diasumsikan untuk batuan pasir (sandstone) yang terkonsolidasi dengan baik?','option','PFM000000027','a:4:{i:0;s:3:"1.0";i:1;s:3:"2.0";i:2;s:3:"3.0";i:3;s:3:"4.0";}','','2.0','In the Archie equation, what is the cementation exponent m value typically assumed for well-consolidated sandstone?','a:4:{i:0;s:3:"1.0";i:1;s:3:"2.0";i:2;s:3:"3.0";i:3;s:3:"4.0";}','2.0','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000131','Parameter apa saja yang secara langsung mempengaruhi besarnya faktor formasi (F) dalam model Archie?','multi','PFM000000027','a:4:{i:0;s:16:"Porositas batuan";i:1;s:18:"Eksponen sementasi";i:2;s:12:"Saturasi air";i:3;s:28:"Resistivitas lumpur pemboran";}','','a:2:{i:0;s:16:"Porositas batuan";i:1;s:18:"Eksponen sementasi";}','Which parameters directly influence the formation factor (F) in the Archie model?','a:4:{i:0;s:13:"Rock porosity";i:1;s:20:"Cementation exponent";i:2;s:16:"Water saturation";i:3;s:24:"Drilling mud resistivity";}','a:2:{i:0;s:13:"Rock porosity";i:1;s:20:"Cementation exponent";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000132','Apa yang terjadi pada faktor formasi (F) jika porositas batuan meningkat sementara parameter lainnya tetap?','option','PFM000000027','a:4:{i:0;s:25:"F meningkat secara linear";i:1;s:9:"F menurun";i:2;s:15:"F tidak berubah";i:3;s:31:"F meningkat secara eksponensial";}','','F menurun','What happens to the formation factor (F) if the rock porosity increases while other parameters remain constant?','a:4:{i:0;s:20:"F increases linearly";i:1;s:11:"F decreases";i:2;s:19:"F remains unchanged";i:3;s:25:"F increases exponentially";}','F decreases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000133','Eksponen saturasi (n) dalam hukum Archie digunakan untuk menghitung parameter apa?','option','PFM000000027','a:4:{i:0;s:19:"Indeks resistivitas";i:1;s:17:"Porositas efektif";i:2;s:21:"Permeabilitas absolut";i:3;s:20:"Saturasi minyak sisa";}','','Indeks resistivitas','The saturation exponent (n) in Archie''s law is used to calculate which parameter?','a:4:{i:0;s:17:"Resistivity index";i:1;s:18:"Effective porosity";i:2;s:21:"Absolute permeability";i:3;s:23:"Residual oil saturation";}','Resistivity index','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000134','Persamaan Archie (F = a / phi^m) mendefinisikan faktor formasi sebagai perbandingan antara:','option','PFM000000027','a:4:{i:0;s:72:"Resistivitas formasi jenuh air (Ro) dengan resistivitas air formasi (Rw)";i:1;s:61:"Resistivitas air formasi (Rw) dengan resistivitas batuan (Rt)";i:2;s:40:"Porositas total dengan porositas efektif";i:3;s:57:"Resistivitas batuan (Rt) dengan resistivitas lumpur (Rmf)";}','','Resistivitas formasi jenuh air (Ro) dengan resistivitas air formasi (Rw)','The Archie equation (F = a / phi^m) defines the formation factor as the ratio between:','a:4:{i:0;s:81:"Resistivity of water-saturated formation (Ro) to formation water resistivity (Rw)";i:1;s:57:"Formation water resistivity (Rw) to rock resistivity (Rt)";i:2;s:36:"Total porosity to effective porosity";i:3;s:46:"Rock resistivity (Rt) to mud resistivity (Rmf)";}','Resistivity of water-saturated formation (Ro) to formation water resistivity (Rw)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000135','Dalam kondisi batuan bersih (clean sand), parameter manakah dalam persamaan Archie yang merepresentasikan konstanta tortuositas?','option','PFM000000028','a:4:{i:0;s:1:"a";i:1;s:1:"m";i:2;s:1:"n";i:3;s:2:"Rw";}','','a','In clean sand conditions, which parameter in the Archie equation represents the tortuosity constant?','a:4:{i:0;s:1:"a";i:1;s:1:"m";i:2;s:1:"n";i:3;s:2:"Rw";}','a','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000136','Manakah di antara metode berikut yang digunakan untuk melakukan koreksi pengaruh kandungan lempung (shale) dalam perhitungan saturasi air?','multi','PFM000000028','a:4:{i:0;s:19:"Persamaan Indonesia";i:1;s:19:"Persamaan Simandoux";i:2;s:16:"Persamaan Archie";i:3;s:22:"Persamaan Waxman-Smits";}','','a:3:{i:0;s:19:"Persamaan Indonesia";i:1;s:19:"Persamaan Simandoux";i:2;s:22:"Persamaan Waxman-Smits";}','Which of the following methods are used to correct for the effect of shale content in water saturation calculations?','a:4:{i:0;s:18:"Indonesia Equation";i:1;s:18:"Simandoux Equation";i:2;s:15:"Archie Equation";i:3;s:21:"Waxman-Smits Equation";}','a:3:{i:0;s:18:"Indonesia Equation";i:1;s:18:"Simandoux Equation";i:2;s:21:"Waxman-Smits Equation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000137','Jika diketahui saturasi air (Sw) pada suatu zona adalah 0.25, berapakah nilai saturasi minyak (So) pada zona tersebut?','option','PFM000000028','a:4:{i:0;s:4:"0.25";i:1;s:4:"0.50";i:2;s:4:"0.75";i:3;s:4:"1.00";}','','0.75','If the water saturation (Sw) in a zone is known to be 0.25, what is the oil saturation (So) value in that zone?','a:4:{i:0;s:4:"0.25";i:1;s:4:"0.50";i:2;s:4:"0.75";i:3;s:4:"1.00";}','0.75','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000138','Apa kepanjangan dari HCPV dalam evaluasi formasi?','option','PFM000000028','a:4:{i:0;s:23:"Hydrocarbon Pore Volume";i:1;s:30:"Hydrocarbon Permeability Value";i:2;s:29:"Hydrated Clay Porosity Volume";i:3;s:26:"Hydrocarbon Pressure Value";}','','Hydrocarbon Pore Volume','What does HCPV stand for in formation evaluation?','a:4:{i:0;s:23:"Hydrocarbon Pore Volume";i:1;s:30:"Hydrocarbon Permeability Value";i:2;s:29:"Hydrated Clay Porosity Volume";i:3;s:26:"Hydrocarbon Pressure Value";}','Hydrocarbon Pore Volume','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000139','Parameter ''n'' dalam persamaan Archie merepresentasikan apa?','option','PFM000000028','a:4:{i:0;s:16:"Porositas batuan";i:1;s:17:"Eksponen saturasi";i:2;s:16:"Faktor sementasi";i:3;s:24:"Resistivitas air formasi";}','','Eksponen saturasi','What does the parameter ''n'' in the Archie equation represent?','a:4:{i:0;s:13:"Rock porosity";i:1;s:19:"Saturation exponent";i:2;s:18:"Cementation factor";i:3;s:27:"Formation water resistivity";}','Saturation exponent','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000140','Parameter utama yang paling umum digunakan dalam penentuan batas (cut-off) untuk memisahkan batuan reservoir dari non-reservoir adalah','option','PFM000000029','a:4:{i:0;s:9:"Porositas";i:1;s:15:"Saturasi minyak";i:2;s:21:"Permeabilitas relatif";i:3;s:15:"Tekanan formasi";}','','Porositas','Which main parameter is most commonly used in determining the cut-off to distinguish reservoir rock from non-reservoir rock?','a:4:{i:0;s:8:"Porosity";i:1;s:14:"Oil saturation";i:2;s:21:"Relative permeability";i:3;s:18:"Formation pressure";}','Porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000141','Manakah pernyataan yang benar mengenai hubungan antara Net Reservoir dan Net Pay?','multi','PFM000000029','a:4:{i:0;s:55:"Net Reservoir harus memenuhi kriteria cut-off porositas";i:1;s:57:"Net Pay harus memenuhi kriteria cut-off saturasi air (Sw)";i:2;s:45:"Net Reservoir selalu lebih kecil dari Net Pay";i:3;s:85:"Net Pay adalah bagian dari Net Reservoir yang memiliki saturasi hidrokarbon produktif";}','','a:3:{i:0;s:55:"Net Reservoir harus memenuhi kriteria cut-off porositas";i:1;s:57:"Net Pay harus memenuhi kriteria cut-off saturasi air (Sw)";i:2;s:85:"Net Pay adalah bagian dari Net Reservoir yang memiliki saturasi hidrokarbon produktif";}','Which statements are correct regarding the relationship between Net Reservoir and Net Pay?','a:4:{i:0;s:53:"Net Reservoir must meet the porosity cut-off criteria";i:1;s:60:"Net Pay must meet the water saturation (Sw) cut-off criteria";i:2;s:44:"Net Reservoir is always smaller than Net Pay";i:3;s:82:"Net Pay is the portion of Net Reservoir that has productive hydrocarbon saturation";}','a:3:{i:0;s:53:"Net Reservoir must meet the porosity cut-off criteria";i:1;s:60:"Net Pay must meet the water saturation (Sw) cut-off criteria";i:2;s:82:"Net Pay is the portion of Net Reservoir that has productive hydrocarbon saturation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000142','Rasio antara ketebalan net pay dengan ketebalan total formasi (gross thickness) dikenal dengan istilah','option','PFM000000029','a:4:{i:0;s:18:"Net-to-Gross (NTG)";i:1;s:18:"Porosity-thickness";i:2;s:21:"Volume of Shale (Vsh)";i:3;s:22:"Water saturation index";}','','Net-to-Gross (NTG)','The ratio between net pay thickness and total formation thickness (gross thickness) is known as','a:4:{i:0;s:18:"Net-to-Gross (NTG)";i:1;s:18:"Porosity-thickness";i:2;s:21:"Volume of Shale (Vsh)";i:3;s:22:"Water saturation index";}','Net-to-Gross (NTG)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000143','Dalam evaluasi formasi, mengapa batasan Volume of Shale (Vsh) diterapkan sebagai cut-off?','option','PFM000000029','a:4:{i:0;s:71:"Untuk membatasi kandungan lempung yang mengurangi permeabilitas efektif";i:1;s:44:"Untuk meningkatkan nilai resistivitas batuan";i:2;s:42:"Untuk mempermudah perhitungan saturasi air";i:3;s:38:"Untuk mengurangi nilai porositas total";}','','Untuk membatasi kandungan lempung yang mengurangi permeabilitas efektif','In formation evaluation, why is a Volume of Shale (Vsh) cut-off applied?','a:4:{i:0;s:57:"To limit clay content that reduces effective permeability";i:1;s:38:"To increase the rock resistivity value";i:2;s:41:"To simplify water saturation calculations";i:3;s:34:"To reduce the total porosity value";}','To limit clay content that reduces effective permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000144','Apa dampak utama dari pemilihan nilai cut-off yang terlalu ketat (terlalu tinggi) pada perhitungan Original Oil In Place (OOIP)?','option','PFM000000029','a:4:{i:0;s:51:"OOIP akan terestimasi lebih rendah (underestimated)";i:1;s:50:"OOIP akan terestimasi lebih tinggi (overestimated)";i:2;s:36:"Tidak berpengaruh pada estimasi OOIP";i:3;s:31:"Hanya mempengaruhi saturasi air";}','','OOIP akan terestimasi lebih rendah (underestimated)','What is the main impact of selecting a cut-off value that is too strict (too high) on the Original Oil In Place (OOIP) calculation?','a:4:{i:0;s:27:"OOIP will be underestimated";i:1;s:26:"OOIP will be overestimated";i:2;s:35:"It has no effect on OOIP estimation";i:3;s:32:"It only affects water saturation";}','OOIP will be underestimated','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000145','Metode korelasi log yang paling umum digunakan untuk menghubungkan karakteristik lapisan antar sumur dalam satu lapangan adalah dengan menggunakan marker utama berupa lapisan yang memiliki?','option','PFM000000030','a:4:{i:0;s:24:"Variasi porositas tinggi";i:1;s:80:"Sifat batuan yang kontinu dan mudah diidentifikasi (seperti lapisan shale tebal)";i:2;s:37:"Nilai resistivitas yang sangat rendah";i:3;s:34:"Nilai gamma ray yang tidak menentu";}','','Sifat batuan yang kontinu dan mudah diidentifikasi (seperti lapisan shale tebal)','The most common log correlation method used to connect layer characteristics between wells in a field is by using primary markers that have?','a:4:{i:0;s:24:"High porosity variations";i:1;s:82:"Continuous rock properties that are easily identified (such as thick shale layers)";i:2;s:27:"Very low resistivity values";i:3;s:30:"Unpredictable gamma ray values";}','Continuous rock properties that are easily identified (such as thick shale layers)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000146','Manakah di antara log berikut yang paling efektif digunakan untuk menentukan kontak fluida (seperti Oil-Water Contact) dalam formasi reservoir?','multi','PFM000000030','a:4:{i:0;s:16:"Log Resistivitas";i:1;s:13:"Log Gamma Ray";i:2;s:11:"Log Neutron";i:3;s:25:"Log Spontaneous Potential";}','','a:2:{i:0;s:16:"Log Resistivitas";i:1;s:25:"Log Spontaneous Potential";}','Which of the following logs are most effective for determining fluid contacts (such as Oil-Water Contact) in a reservoir formation?','a:4:{i:0;s:15:"Resistivity Log";i:1;s:13:"Gamma Ray Log";i:2;s:11:"Neutron Log";i:3;s:25:"Spontaneous Potential Log";}','a:2:{i:0;s:15:"Resistivity Log";i:1;s:25:"Spontaneous Potential Log";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000147','Apa tujuan utama dari melakukan zonasi reservoir dalam evaluasi formasi?','option','PFM000000030','a:4:{i:0;s:47:"Untuk meningkatkan biaya operasional pengeboran";i:1;s:114:"Untuk memisahkan lapisan berdasarkan karakteristik petrofisika yang seragam agar perhitungan cadangan lebih akurat";i:2;s:53:"Untuk menghilangkan kebutuhan melakukan core analysis";i:3;s:63:"Untuk menyamakan nilai permeabilitas di seluruh kedalaman sumur";}','','Untuk memisahkan lapisan berdasarkan karakteristik petrofisika yang seragam agar perhitungan cadangan lebih akurat','What is the primary objective of performing reservoir zoning in formation evaluation?','a:4:{i:0;s:38:"To increase drilling operational costs";i:1;s:104:"To separate layers based on uniform petrophysical characteristics for more accurate reserve calculations";i:2;s:39:"To eliminate the need for core analysis";i:3;s:60:"To equalize permeability values across the entire well depth";}','To separate layers based on uniform petrophysical characteristics for more accurate reserve calculations','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000148','Dalam korelasi sumur, jika ditemukan pergeseran lapisan secara vertikal pada kedalaman yang berbeda di sumur yang berdekatan, hal ini kemungkinan besar mengindikasikan adanya?','option','PFM000000030','a:4:{i:0;s:25:"Perubahan densitas lumpur";i:1;s:45:"Adanya struktur geologi seperti sesar (fault)";i:2;s:28:"Kesalahan pembacaan tool log";i:3;s:24:"Peningkatan suhu formasi";}','','Adanya struktur geologi seperti sesar (fault)','In well correlation, if a vertical layer displacement is observed at different depths in adjacent wells, this most likely indicates?','a:4:{i:0;s:22:"Changes in mud density";i:1;s:53:"The presence of geological structures such as a fault";i:2;s:19:"Tool reading errors";i:3;s:33:"Increase in formation temperature";}','The presence of geological structures such as a fault','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000149','Penyajian hasil interpretasi log yang komprehensif (composite log) biasanya memuat data berikut, kecuali?','option','PFM000000030','a:4:{i:0;s:32:"Kurva gamma ray dan resistivitas";i:1;s:44:"Hasil perhitungan porositas dan saturasi air";i:2;s:30:"Log aktivitas seismik regional";i:3;s:21:"Interpretasi litologi";}','','Log aktivitas seismik regional','A comprehensive log interpretation presentation (composite log) typically includes the following data, except?','a:4:{i:0;s:32:"Gamma ray and resistivity curves";i:1;s:49:"Porosity and water saturation calculation results";i:2;s:29:"Regional seismic activity log";i:3;s:24:"Lithology interpretation";}','Regional seismic activity log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000150','Berdasarkan persamaan tekanan kapiler Pc = (2 * sigma * cos(theta)) / r, variabel apa yang berbanding terbalik dengan besarnya tekanan kapiler?','option','PFM000000031','a:4:{i:0;s:27:"Tegangan antar muka (sigma)";i:1;s:20:"Sudut kontak (theta)";i:2;s:18:"Jari-jari pori (r)";i:3;s:15:"Densitas fluida";}','','Jari-jari pori (r)','Based on the capillary pressure equation Pc = (2 * sigma * cos(theta)) / r, which variable is inversely proportional to the magnitude of capillary pressure?','a:4:{i:0;s:27:"Interfacial tension (sigma)";i:1;s:21:"Contact angle (theta)";i:2;s:15:"Pore radius (r)";i:3;s:13:"Fluid density";}','Pore radius (r)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000151','Fenomena di mana kurva tekanan kapiler saat proses drainase berbeda dengan kurva saat proses imbibisi disebut sebagai apa?','option','PFM000000031','a:4:{i:0;s:7:"Isoterm";i:1;s:10:"Histeresis";i:2;s:8:"Transisi";i:3;s:11:"Kapasitansi";}','','Histeresis','The phenomenon where the capillary pressure curve during a drainage process differs from the curve during an imbibition process is known as what?','a:4:{i:0;s:8:"Isotherm";i:1;s:10:"Hysteresis";i:2;s:10:"Transition";i:3;s:11:"Capacitance";}','Hysteresis','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000152','Faktor apa saja yang memengaruhi besarnya tekanan kapiler dalam sistem pori batuan?','multi','PFM000000031','a:4:{i:0;s:14:"Jari-jari pori";i:1;s:19:"Tegangan antar muka";i:2;s:17:"Viskositas fluida";i:3;s:12:"Sudut kontak";}','','a:3:{i:0;s:14:"Jari-jari pori";i:1;s:19:"Tegangan antar muka";i:2;s:12:"Sudut kontak";}','Which factors influence the magnitude of capillary pressure in a rock pore system?','a:4:{i:0;s:11:"Pore radius";i:1;s:19:"Interfacial tension";i:2;s:15:"Fluid viscosity";i:3;s:13:"Contact angle";}','a:3:{i:0;s:11:"Pore radius";i:1;s:19:"Interfacial tension";i:2;s:13:"Contact angle";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000153','Pada grafik hubungan tekanan kapiler terhadap saturasi air (Sw), apa yang terjadi pada tekanan kapiler saat nilai saturasi air semakin menurun?','option','PFM000000031','a:4:{i:0;s:23:"Tekanan kapiler menurun";i:1;s:25:"Tekanan kapiler meningkat";i:2;s:29:"Tekanan kapiler tetap konstan";i:3;s:27:"Tekanan kapiler menjadi nol";}','','Tekanan kapiler meningkat','In a plot of capillary pressure versus water saturation (Sw), what happens to the capillary pressure as the water saturation value decreases?','a:4:{i:0;s:28:"Capillary pressure decreases";i:1;s:28:"Capillary pressure increases";i:2;s:35:"Capillary pressure remains constant";i:3;s:31:"Capillary pressure becomes zero";}','Capillary pressure increases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000154','Apakah yang dimaksud dengan tekanan ambang (threshold pressure) pada kurva tekanan kapiler?','option','PFM000000031','a:4:{i:0;s:62:"Tekanan minimum agar fluida non-wetting masuk ke pori terbesar";i:1;s:39:"Tekanan saat saturasi air mencapai 100%";i:2;s:48:"Tekanan saat permeabilitas relatif mencapai satu";i:3;s:43:"Tekanan saat tegangan permukaan menjadi nol";}','','Tekanan minimum agar fluida non-wetting masuk ke pori terbesar','What is meant by threshold pressure in a capillary pressure curve?','a:4:{i:0;s:64:"Minimum pressure for non-wetting fluid to enter the largest pore";i:1;s:43:"Pressure when water saturation reaches 100%";i:2;s:49:"Pressure when relative permeability reaches unity";i:3;s:42:"Pressure when surface tension becomes zero";}','Minimum pressure for non-wetting fluid to enter the largest pore','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000155','Jika sudut kontak (contact angle) antara tetesan air dan permukaan batuan di dalam minyak adalah 30 derajat, maka batuan tersebut dikategorikan sebagai:','option','PFM000000032','a:4:{i:0;s:9:"Water-wet";i:1;s:7:"Oil-wet";i:2;s:16:"Intermediate-wet";i:3;s:11:"Non-wetting";}','','Water-wet','If the contact angle between a water droplet and the rock surface in oil is 30 degrees, the rock is categorized as:','a:4:{i:0;s:9:"Water-wet";i:1;s:7:"Oil-wet";i:2;s:16:"Intermediate-wet";i:3;s:11:"Non-wetting";}','Water-wet','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000156','Manakah faktor yang mempengaruhi distribusi saturasi fluida di atas Free Water Level (FWL)?','multi','PFM000000032','a:4:{i:0;s:15:"Tekanan kapiler";i:1;s:25:"Perbedaan densitas fluida";i:2;s:21:"Permeabilitas absolut";i:3;s:19:"Ketinggian vertikal";}','','a:3:{i:0;s:15:"Tekanan kapiler";i:1;s:25:"Perbedaan densitas fluida";i:2;s:19:"Ketinggian vertikal";}','Which factors influence the fluid saturation distribution above the Free Water Level (FWL)?','a:4:{i:0;s:18:"Capillary pressure";i:1;s:24:"Fluid density difference";i:2;s:21:"Absolute permeability";i:3;s:15:"Vertical height";}','a:3:{i:0;s:18:"Capillary pressure";i:1;s:24:"Fluid density difference";i:2;s:15:"Vertical height";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000157','Pada kondisi reservoir water-wet, manakah pernyataan yang benar mengenai tekanan kapiler (Pc)?','option','PFM000000032','a:4:{i:0;s:19:"Pc bernilai positif";i:1;s:19:"Pc bernilai negatif";i:2;s:25:"Pc selalu nol di atas FWL";i:3;s:37:"Pc tidak bergantung pada sudut kontak";}','','Pc bernilai positif','In water-wet reservoir conditions, which statement is correct regarding capillary pressure (Pc)?','a:4:{i:0;s:14:"Pc is positive";i:1;s:14:"Pc is negative";i:2;s:27:"Pc is always zero above FWL";i:3;s:34:"Pc is independent of contact angle";}','Pc is positive','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000158','Apa yang terjadi pada Free Water Level (FWL) dalam sebuah sistem reservoir?','option','PFM000000032','a:4:{i:0;s:28:"Tekanan kapiler bernilai nol";i:1;s:32:"Saturasi air bernilai 100 persen";i:2;s:62:"Tekanan hidrostatik minyak sama dengan tekanan hidrostatik air";i:3;s:19:"Semua jawaban benar";}','','Semua jawaban benar','What happens at the Free Water Level (FWL) in a reservoir system?','a:4:{i:0;s:26:"Capillary pressure is zero";i:1;s:31:"Water saturation is 100 percent";i:2;s:58:"Oil hydrostatic pressure equals water hydrostatic pressure";i:3;s:16:"All of the above";}','All of the above','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000159','Bagaimana pengaruh kenaikan ketinggian (h) di atas FWL terhadap saturasi air (Sw) pada zona transisi?','option','PFM000000032','a:4:{i:0;s:20:"Saturasi air menurun";i:1;s:22:"Saturasi air meningkat";i:2;s:26:"Saturasi air tetap konstan";i:3;s:34:"Tidak ada hubungan antara h dan Sw";}','','Saturasi air menurun','How does an increase in height (h) above the FWL affect the water saturation (Sw) in the transition zone?','a:4:{i:0;s:26:"Water saturation decreases";i:1;s:26:"Water saturation increases";i:2;s:33:"Water saturation remains constant";i:3;s:41:"There is no relationship between h and Sw";}','Water saturation decreases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000160','Metode pengukuran tekanan kapiler yang menggunakan merkuri sebagai fase non-wetting dan sering digunakan karena kecepatannya adalah','option','PFM000000033','a:4:{i:0;s:17:"Mercury Injection";i:1;s:12:"Porous Plate";i:2;s:10:"Centrifuge";i:3;s:14:"Restored State";}','','Mercury Injection','The capillary pressure measurement method that uses mercury as the non-wetting phase and is often used due to its speed is','a:4:{i:0;s:17:"Mercury Injection";i:1;s:12:"Porous Plate";i:2;s:10:"Centrifuge";i:3;s:14:"Restored State";}','Mercury Injection','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000161','Kelemahan utama dari metode Porous Plate dalam menentukan tekanan kapiler adalah','option','PFM000000033','a:4:{i:0;s:61:"Memerlukan waktu yang sangat lama untuk mencapai keseimbangan";i:1;s:37:"Tidak akurat pada saturasi air rendah";i:2;s:49:"Hanya dapat digunakan untuk batuan unconsolidated";i:3;s:34:"Menggunakan merkuri yang berbahaya";}','','Memerlukan waktu yang sangat lama untuk mencapai keseimbangan','The main drawback of the Porous Plate method in determining capillary pressure is','a:4:{i:0;s:46:"Requires a very long time to reach equilibrium";i:1;s:36:"Not accurate at low water saturation";i:2;s:41:"Can only be used for unconsolidated rocks";i:3;s:22:"Uses dangerous mercury";}','Requires a very long time to reach equilibrium','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000162','Parameter apa saja yang dapat ditentukan melalui analisis data tekanan kapiler di laboratorium?','multi','PFM000000033','a:4:{i:0;s:24:"Saturasi air konat (Swc)";i:1;s:21:"Permeabilitas absolut";i:2;s:22:"Distribusi ukuran pori";i:3;s:17:"Viskositas fluida";}','','a:2:{i:0;s:24:"Saturasi air konat (Swc)";i:1;s:22:"Distribusi ukuran pori";}','Which parameters can be determined through laboratory capillary pressure data analysis?','a:4:{i:0;s:30:"Connate water saturation (Swc)";i:1;s:21:"Absolute permeability";i:2;s:22:"Pore size distribution";i:3;s:15:"Fluid viscosity";}','a:2:{i:0;s:30:"Connate water saturation (Swc)";i:1;s:22:"Pore size distribution";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000163','Dalam metode centrifuge untuk pengukuran tekanan kapiler, gaya yang digunakan untuk memindahkan fluida dari pori-pori batuan adalah','option','PFM000000033','a:4:{i:0;s:16:"Gaya sentrifugal";i:1;s:14:"Gaya gravitasi";i:2;s:20:"Gaya elektromagnetik";i:3;s:12:"Gaya osmotik";}','','Gaya sentrifugal','In the centrifuge method for capillary pressure measurement, the force used to displace fluids from rock pores is','a:4:{i:0;s:17:"Centrifugal force";i:1;s:19:"Gravitational force";i:2;s:21:"Electromagnetic force";i:3;s:13:"Osmotic force";}','Centrifugal force','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000164','Mengapa Mercury Injection Capillary Pressure (MICP) dianggap kurang representatif untuk kondisi reservoir sebenarnya dibandingkan Porous Plate?','option','PFM000000033','a:4:{i:0;s:66:"Perbedaan sifat fisik fluida (tegangan antarmuka dan sudut kontak)";i:1;s:39:"Karena ukuran sampel yang terlalu besar";i:2;s:52:"Tidak dapat mengukur tekanan kapiler di atas 100 psi";i:3;s:44:"Merkuri bereaksi kimia dengan mineral batuan";}','','Perbedaan sifat fisik fluida (tegangan antarmuka dan sudut kontak)','Why is Mercury Injection Capillary Pressure (MICP) considered less representative of actual reservoir conditions compared to the Porous Plate method?','a:4:{i:0;s:80:"Differences in fluid physical properties (interfacial tension and contact angle)";i:1;s:36:"Because the sample size is too large";i:2;s:47:"Cannot measure capillary pressure above 100 psi";i:3;s:44:"Mercury reacts chemically with rock minerals";}','Differences in fluid physical properties (interfacial tension and contact angle)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000165','Pada kurva tekanan kapiler (Pc) versus saturasi air (Sw), apa yang direpresentasikan oleh nilai Swc (Connate Water Saturation)?','option','PFM000000034','a:4:{i:0;s:70:"Saturasi air minimum yang tertahan oleh gaya kapiler dalam pori batuan";i:1;s:48:"Saturasi air maksimum saat minyak mulai mengalir";i:2;s:42:"Titik di mana tekanan kapiler bernilai nol";i:3;s:48:"Volume air yang dapat diproduksi secara ekonomis";}','','Saturasi air minimum yang tertahan oleh gaya kapiler dalam pori batuan','On a capillary pressure (Pc) versus water saturation (Sw) curve, what does the Swc (Connate Water Saturation) value represent?','a:4:{i:0;s:75:"The minimum water saturation held by capillary forces within the rock pores";i:1;s:52:"The maximum water saturation when oil begins to flow";i:2;s:42:"The point where capillary pressure is zero";i:3;s:53:"The volume of water that can be produced economically";}','The minimum water saturation held by capillary forces within the rock pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000166','Faktor apa saja yang dikorelasikan oleh Leverett J-function untuk menyatukan data tekanan kapiler dari berbagai sampel batuan?','multi','PFM000000034','a:4:{i:0;s:15:"Tekanan kapiler";i:1;s:9:"Porositas";i:2;s:13:"Permeabilitas";i:3;s:17:"Viskositas minyak";}','','a:3:{i:0;s:15:"Tekanan kapiler";i:1;s:9:"Porositas";i:2;s:13:"Permeabilitas";}','Which factors are correlated by the Leverett J-function to normalize capillary pressure data from different rock samples?','a:4:{i:0;s:18:"Capillary pressure";i:1;s:8:"Porosity";i:2;s:12:"Permeability";i:3;s:13:"Oil viscosity";}','a:3:{i:0;s:18:"Capillary pressure";i:1;s:8:"Porosity";i:2;s:12:"Permeability";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000167','Apa yang terjadi pada zona transisi dalam kurva tekanan kapiler terhadap kedalaman reservoir?','option','PFM000000034','a:4:{i:0;s:59:"Saturasi air berubah secara bertahap dari 100 persen ke Swc";i:1;s:47:"Saturasi air konstan di sepanjang zona tersebut";i:2;s:39:"Tekanan kapiler selalu bernilai negatif";i:3;s:47:"Tidak ada minyak yang terjebak di zona tersebut";}','','Saturasi air berubah secara bertahap dari 100 persen ke Swc','What happens in the transition zone of a capillary pressure curve relative to reservoir depth?','a:4:{i:0;s:58:"Water saturation changes gradually from 100 percent to Swc";i:1;s:53:"Water saturation remains constant throughout the zone";i:2;s:37:"Capillary pressure is always negative";i:3;s:29:"No oil is trapped in the zone";}','Water saturation changes gradually from 100 percent to Swc','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000168','Manakah pernyataan yang benar mengenai hubungan antara permeabilitas dan kurva tekanan kapiler?','option','PFM000000034','a:4:{i:0;s:76:"Batuan dengan permeabilitas lebih tinggi memiliki kurva Pc yang lebih landai";i:1;s:75:"Batuan dengan permeabilitas lebih tinggi memiliki kurva Pc yang lebih curam";i:2;s:61:"Permeabilitas tidak mempengaruhi bentuk kurva tekanan kapiler";i:3;s:49:"Kurva Pc tidak bergantung pada ukuran pori batuan";}','','Batuan dengan permeabilitas lebih tinggi memiliki kurva Pc yang lebih landai','Which statement is true regarding the relationship between permeability and the capillary pressure curve?','a:4:{i:0;s:54:"Rocks with higher permeability have a flatter Pc curve";i:1;s:54:"Rocks with higher permeability have a steeper Pc curve";i:2;s:70:"Permeability does not affect the shape of the capillary pressure curve";i:3;s:45:"The Pc curve is independent of rock pore size";}','Rocks with higher permeability have a flatter Pc curve','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000169','Dalam konteks J-function, bagaimana pengaruh peningkatan nilai J terhadap saturasi air (Sw) pada sistem oil-water?','option','PFM000000034','a:4:{i:0;s:31:"Nilai Sw akan cenderung menurun";i:1;s:31:"Nilai Sw akan meningkat drastis";i:2;s:37:"Tidak ada perubahan pada saturasi air";i:3;s:34:"Saturasi air menjadi tidak terukur";}','','Nilai Sw akan cenderung menurun','In the context of the J-function, how does an increase in the J-value affect water saturation (Sw) in an oil-water system?','a:4:{i:0;s:34:"The Sw value will tend to decrease";i:1;s:38:"The Sw value will increase drastically";i:2;s:38:"There is no change in water saturation";i:3;s:37:"Water saturation becomes unmeasurable";}','The Sw value will tend to decrease','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000170','Apa yang dimaksud dengan permeabilitas relatif (Kr) dalam sistem reservoir?','option','PFM000000035','a:4:{i:0;s:76:"Rasio permeabilitas efektif suatu fase terhadap permeabilitas absolut batuan";i:1;s:62:"Nilai permeabilitas mutlak batuan tanpa adanya saturasi fluida";i:2;s:56:"Perubahan permeabilitas akibat adanya tekanan overburden";i:3;s:63:"Kecepatan aliran fluida dalam media berpori menurut Hukum Darcy";}','','Rasio permeabilitas efektif suatu fase terhadap permeabilitas absolut batuan','What is meant by relative permeability (Kr) in a reservoir system?','a:4:{i:0;s:83:"Ratio of effective permeability of a phase to the absolute permeability of the rock";i:1;s:64:"Absolute permeability value of the rock without fluid saturation";i:2;s:46:"Permeability change due to overburden pressure";i:3;s:60:"Fluid flow velocity in porous media according to Darcy''s Law";}','Ratio of effective permeability of a phase to the absolute permeability of the rock','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000171','Faktor apa saja yang memengaruhi perbedaan bentuk kurva permeabilitas relatif antara proses drainage dan imbibisi?','multi','PFM000000035','a:4:{i:0;s:10:"Histeresis";i:1;s:23:"Saturasi air awal (Swc)";i:2;s:26:"Kelarutan gas dalam minyak";i:3;s:18:"Wettability batuan";}','','a:2:{i:0;s:10:"Histeresis";i:1;s:18:"Wettability batuan";}','Which factors influence the difference in the shape of relative permeability curves between drainage and imbibition processes?','a:4:{i:0;s:10:"Hysteresis";i:1;s:30:"Initial water saturation (Swc)";i:2;s:21:"Gas solubility in oil";i:3;s:16:"Rock wettability";}','a:2:{i:0;s:10:"Hysteresis";i:1;s:16:"Rock wettability";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000172','Pada kondisi saturasi air irredusibel (Swc), berapakah nilai permeabilitas relatif minyak (Kro) secara teoritis?','option','PFM000000035','a:4:{i:0;s:40:"Mencapai nilai maksimum atau mendekati 1";i:1;s:12:"Bernilai nol";i:2;s:33:"Sama dengan permeabilitas absolut";i:3;s:31:"Bergantung pada tekanan kapiler";}','','Mencapai nilai maksimum atau mendekati 1','At irreducible water saturation (Swc), what is the theoretical value of the relative permeability of oil (Kro)?','a:4:{i:0;s:35:"Reaches maximum value or close to 1";i:1;s:13:"Equal to zero";i:2;s:30:"Equal to absolute permeability";i:3;s:29:"Depends on capillary pressure";}','Reaches maximum value or close to 1','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000173','Apa yang terjadi pada permeabilitas relatif minyak (Kro) ketika saturasi air (Sw) meningkat menuju saturasi minyak residual (Sor)?','option','PFM000000035','a:4:{i:0;s:50:"Kro menurun secara signifikan hingga mendekati nol";i:1;s:27:"Kro meningkat secara linear";i:2;s:17:"Kro tetap konstan";i:3;s:27:"Kro menjadi sama dengan Krw";}','','Kro menurun secara signifikan hingga mendekati nol','What happens to the relative permeability of oil (Kro) as water saturation (Sw) increases toward residual oil saturation (Sor)?','a:4:{i:0;s:40:"Kro decreases significantly towards zero";i:1;s:22:"Kro increases linearly";i:2;s:20:"Kro remains constant";i:3;s:24:"Kro becomes equal to Krw";}','Kro decreases significantly towards zero','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000174','Proses perpindahan fluida di mana fase non-wetting (minyak) mendesak fase wetting (air) keluar dari pori-pori batuan disebut sebagai:','option','PFM000000035','a:4:{i:0;s:8:"Drainage";i:1;s:8:"Imbibisi";i:2;s:8:"Kompaksi";i:3;s:15:"Injeksi polimer";}','','Drainage','The fluid displacement process where the non-wetting phase (oil) forces the wetting phase (water) out of the rock pores is known as:','a:4:{i:0;s:8:"Drainage";i:1;s:10:"Imbibition";i:2;s:10:"Compaction";i:3;s:17:"Polymer injection";}','Drainage','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000175','Metode manakah yang melibatkan injeksi fluida pendesak ke dalam core secara terus menerus hingga mencapai kondisi kesetimbangan tekanan dan saturasi pada setiap titik di sepanjang core?','option','PFM000000036','a:4:{i:0;s:21:"Unsteady-state method";i:1;s:19:"Steady-state method";i:2;s:17:"Centrifuge method";i:3;s:24:"Mercury injection method";}','','Steady-state method','Which method involves continuous injection of displacing fluid into the core until pressure and saturation equilibrium is reached at every point along the core?','a:4:{i:0;s:21:"Unsteady-state method";i:1;s:19:"Steady-state method";i:2;s:17:"Centrifuge method";i:3;s:24:"Mercury injection method";}','Steady-state method','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000176','Manakah pernyataan yang benar mengenai metode Unsteady-state dalam pengukuran permeabilitas relatif (kr)?','multi','PFM000000036','a:4:{i:0;s:52:"Sering menggunakan teknik interpretasi Jaccard-Welge";i:1;s:69:"Memerlukan waktu pengujian yang lebih cepat dibandingkan steady-state";i:2;s:59:"Memerlukan tekanan kapiler yang diabaikan untuk perhitungan";i:3;s:56:"Hanya dapat digunakan untuk batuan yang homogen sempurna";}','','a:2:{i:0;s:52:"Sering menggunakan teknik interpretasi Jaccard-Welge";i:1;s:69:"Memerlukan waktu pengujian yang lebih cepat dibandingkan steady-state";}','Which statements are correct regarding the Unsteady-state method in relative permeability (kr) measurement?','a:4:{i:0;s:53:"Often uses the Jaccard-Welge interpretation technique";i:1;s:53:"Requires faster testing time compared to steady-state";i:2;s:59:"Requires capillary pressure to be neglected for calculation";i:3;s:48:"Can only be used for perfectly homogeneous rocks";}','a:2:{i:0;s:53:"Often uses the Jaccard-Welge interpretation technique";i:1;s:53:"Requires faster testing time compared to steady-state";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000177','Dalam persamaan fractional flow (fw), parameter manakah yang secara langsung mempengaruhi bentuk kurva fw terhadap saturasi air (Sw)?','option','PFM000000036','a:4:{i:0;s:35:"Permeabilitas absolut dan porositas";i:1;s:43:"Viskositas fluida dan permeabilitas relatif";i:2;s:38:"Densitas batuan dan tekanan overburden";i:3;s:39:"Komposisi mineral dan salinitas formasi";}','','Viskositas fluida dan permeabilitas relatif','In the fractional flow (fw) equation, which parameters directly influence the shape of the fw versus water saturation (Sw) curve?','a:4:{i:0;s:34:"Absolute permeability and porosity";i:1;s:41:"Fluid viscosity and relative permeability";i:2;s:36:"Rock density and overburden pressure";i:3;s:42:"Mineral composition and formation salinity";}','Fluid viscosity and relative permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000178','Pada teori Buckley-Leverett, apa yang merepresentasikan titik singgung garis dari saturasi awal (Swi) ke kurva fractional flow?','option','PFM000000036','a:4:{i:0;s:40:"Saturasi air rata-rata di belakang front";i:1;s:27:"Saturasi air di depan front";i:2;s:30:"Permeabilitas relatif maksimum";i:3;s:19:"Tekanan kapiler nol";}','','Saturasi air rata-rata di belakang front','In Buckley-Leverett theory, what does the tangent point of the line from initial water saturation (Swi) to the fractional flow curve represent?','a:4:{i:0;s:41:"Average water saturation behind the front";i:1;s:35:"Water saturation ahead of the front";i:2;s:29:"Maximum relative permeability";i:3;s:23:"Zero capillary pressure";}','Average water saturation behind the front','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000179','Mengapa pengukuran permeabilitas relatif (kr) sangat krusial dalam simulasi reservoir?','option','PFM000000036','a:4:{i:0;s:41:"Untuk menentukan porositas efektif batuan";i:1;s:69:"Untuk memprediksi perolehan minyak (recovery factor) dan laju injeksi";i:2;s:43:"Untuk mengukur resistivitas listrik formasi";i:3;s:41:"Untuk menghitung nilai tekanan overburden";}','','Untuk memprediksi perolehan minyak (recovery factor) dan laju injeksi','Why is the measurement of relative permeability (kr) crucial in reservoir simulation?','a:4:{i:0;s:47:"To determine the effective porosity of the rock";i:1;s:50:"To predict oil recovery factor and injection rates";i:2;s:54:"To measure the electrical resistivity of the formation";i:3;s:42:"To calculate the overburden pressure value";}','To predict oil recovery factor and injection rates','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000180','Dalam rumus volumetrik OOIP = (7758 * A * h * phi * So) / Bo, apakah satuan yang digunakan untuk luas area (A) dan ketebalan reservoir (h)?','option','PFM000000037','a:4:{i:0;s:20:"Acre dan kaki (feet)";i:1;s:16:"Hektar dan meter";i:2;s:14:"Barat dan inci";i:3;s:14:"Acre dan meter";}','','Acre dan kaki (feet)','In the volumetric OOIP formula = (7758 * A * h * phi * So) / Bo, what are the units used for reservoir area (A) and thickness (h)?','a:4:{i:0;s:14:"Acres and feet";i:1;s:19:"Hectares and meters";i:2;s:18:"Barrels and inches";i:3;s:16:"Acres and meters";}','Acres and feet','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000181','Parameter apa saja yang diperlukan untuk menghitung Original Oil In Place (OOIP) dengan metode volumetrik?','multi','PFM000000037','a:4:{i:0;s:14:"Luas reservoir";i:1;s:7:"Net pay";i:2;s:9:"Porositas";i:3;s:17:"Viskositas fluida";}','','a:3:{i:0;s:14:"Luas reservoir";i:1;s:7:"Net pay";i:2;s:9:"Porositas";}','Which parameters are required to calculate Original Oil In Place (OOIP) using the volumetric method?','a:4:{i:0;s:14:"Reservoir area";i:1;s:7:"Net pay";i:2;s:8:"Porosity";i:3;s:15:"Fluid viscosity";}','a:3:{i:0;s:14:"Reservoir area";i:1;s:7:"Net pay";i:2;s:8:"Porosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000182','Apa fungsi dari faktor volume formasi minyak (Bo) dalam perhitungan cadangan minyak awal?','option','PFM000000037','a:4:{i:0;s:75:"Mengubah volume minyak di kondisi reservoir ke kondisi standar (stock tank)";i:1;s:42:"Menghitung tekanan kapiler di dalam batuan";i:2;s:40:"Mengukur kecepatan aliran minyak di pori";i:3;s:37:"Menentukan kejenuhan air di reservoir";}','','Mengubah volume minyak di kondisi reservoir ke kondisi standar (stock tank)','What is the function of the oil formation volume factor (Bo) in initial oil reserve calculations?','a:4:{i:0;s:83:"To convert oil volume from reservoir conditions to standard (stock tank) conditions";i:1;s:43:"To calculate capillary pressure in the rock";i:2;s:33:"To measure oil flow rate in pores";i:3;s:46:"To determine water saturation in the reservoir";}','To convert oil volume from reservoir conditions to standard (stock tank) conditions','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000183','Jika diketahui porositas (phi) adalah 0,20, saturasi minyak (So) adalah 0,70, luas area (A) 100 acre, dan net pay (h) 50 kaki, berapakah perkiraan OOIP jika Bo = 1,2 (dalam barrel)?','option','PFM000000037','a:4:{i:0;s:14:"452.550 barrel";i:1;s:17:"45.255.000 barrel";i:2;s:16:"4.525.500 barrel";i:3;s:18:"452.550.000 barrel";}','','4.525.500 barrel','Given porosity (phi) = 0.20, oil saturation (So) = 0.70, area (A) = 100 acres, and net pay (h) = 50 feet, what is the estimated OOIP if Bo = 1.2 (in barrels)?','a:4:{i:0;s:15:"452,550 barrels";i:1;s:18:"45,255,000 barrels";i:2;s:17:"4,525,500 barrels";i:3;s:19:"452,550,000 barrels";}','4,525,500 barrels','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000184','Metode volumetrik untuk menghitung OGIP (Original Gas In Place) menggunakan faktor gas (Bg) sebagai pembagi. Apa arti dari Bg?','option','PFM000000037','a:4:{i:0;s:27:"Gas Formation Volume Factor";i:1;s:21:"Gas Saturation Factor";i:2;s:18:"Gas Gravity Factor";i:3;s:20:"Gas Expansion Factor";}','','Gas Formation Volume Factor','The volumetric method for calculating OGIP (Original Gas In Place) uses the gas factor (Bg) as a divisor. What does Bg stand for?','a:4:{i:0;s:27:"Gas Formation Volume Factor";i:1;s:21:"Gas Saturation Factor";i:2;s:18:"Gas Gravity Factor";i:3;s:20:"Gas Expansion Factor";}','Gas Formation Volume Factor','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000185','Manakah dari parameter berikut yang merupakan sumber ketidakpastian utama dalam perhitungan volume hidrokarbon awal di tempat (OIIP/OGIP)?','multi','PFM000000038','a:4:{i:0;s:9:"Porositas";i:1;s:12:"Saturasi air";i:2;s:16:"Kepadatan batuan";i:3;s:17:"Ketebalan formasi";}','','a:3:{i:0;s:9:"Porositas";i:1;s:12:"Saturasi air";i:2;s:17:"Ketebalan formasi";}','Which of the following parameters are the primary sources of uncertainty in the calculation of initial hydrocarbon volumes in place (OIIP/OGIP)?','a:4:{i:0;s:8:"Porosity";i:1;s:16:"Water saturation";i:2;s:12:"Rock density";i:3;s:19:"Formation thickness";}','a:3:{i:0;s:8:"Porosity";i:1;s:16:"Water saturation";i:2;s:19:"Formation thickness";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000186','Metode estimasi yang menggunakan distribusi probabilitas untuk setiap variabel input guna menghasilkan rentang hasil akhir adalah definisi dari:','option','PFM000000038','a:4:{i:0;s:24:"Pendekatan deterministik";i:1;s:24:"Pendekatan probabilistik";i:2;s:29:"Analisis sensitivitas tunggal";i:3;s:22:"Estimasi titik tunggal";}','','Pendekatan probabilistik','An estimation method that uses probability distributions for each input variable to generate a range of final outcomes is the definition of:','a:4:{i:0;s:22:"Deterministic approach";i:1;s:22:"Probabilistic approach";i:2;s:27:"Single sensitivity analysis";i:3;s:23:"Single-point estimation";}','Probabilistic approach','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000187','Apa tujuan utama dari melakukan analisis sensitivitas pada perhitungan cadangan hidrokarbon?','option','PFM000000038','a:4:{i:0;s:33:"Untuk menentukan biaya pengeboran";i:1;s:82:"Untuk mengidentifikasi parameter mana yang paling berpengaruh terhadap hasil akhir";i:2;s:33:"Untuk menggantikan data log sumur";i:3;s:52:"Untuk mengubah nilai porositas menjadi permeabilitas";}','','Untuk mengidentifikasi parameter mana yang paling berpengaruh terhadap hasil akhir','What is the main objective of performing a sensitivity analysis on hydrocarbon reserve calculations?','a:4:{i:0;s:27:"To determine drilling costs";i:1;s:81:"To identify which parameters have the most significant impact on the final result";i:2;s:24:"To replace well log data";i:3;s:44:"To convert porosity values into permeability";}','To identify which parameters have the most significant impact on the final result','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000188','Dalam pendekatan deterministik, parameter input biasanya direpresentasikan sebagai:','option','PFM000000038','a:4:{i:0;s:48:"Nilai tunggal atau skenario best-case/worst-case";i:1;s:17:"Distribusi normal";i:2;s:22:"Distribusi Monte Carlo";i:3;s:30:"Nilai acak yang tidak terbatas";}','','Nilai tunggal atau skenario best-case/worst-case','In a deterministic approach, input parameters are typically represented as:','a:4:{i:0;s:47:"Single values or best-case/worst-case scenarios";i:1;s:19:"Normal distribution";i:2;s:24:"Monte Carlo distribution";i:3;s:23:"Unbounded random values";}','Single values or best-case/worst-case scenarios','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000189','Mengapa ketidakpastian dalam penentuan luas reservoir (area) dapat menyebabkan risiko yang signifikan pada estimasi volume?','option','PFM000000038','a:4:{i:0;s:59:"Karena luas reservoir tidak mempengaruhi perhitungan volume";i:1;s:57:"Karena luas reservoir biasanya konstan di semua kedalaman";i:2;s:91:"Karena batas reservoir seringkali sulit ditentukan secara presisi dari data seismik dan log";i:3;s:61:"Karena luas reservoir hanya bergantung pada tekanan reservoir";}','','Karena batas reservoir seringkali sulit ditentukan secara presisi dari data seismik dan log','Why does uncertainty in the determination of reservoir area cause significant risk in volume estimation?','a:4:{i:0;s:58:"Because reservoir area does not affect volume calculations";i:1;s:56:"Because reservoir area is usually constant at all depths";i:2;s:97:"Because reservoir boundaries are often difficult to determine precisely from seismic and log data";i:3;s:57:"Because reservoir area depends only on reservoir pressure";}','Because reservoir boundaries are often difficult to determine precisely from seismic and log data','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000190','Apa tujuan utama dari proses kalibrasi data log sumur dengan data core dalam studi petrofisika?','option','PFM000000039','a:4:{i:0;s:45:"Menentukan kedalaman reservoir secara absolut";i:1;s:76:"Memastikan akurasi pembacaan log terhadap sifat fisik batuan yang sebenarnya";i:2;s:39:"Mengurangi biaya operasional pengeboran";i:3;s:38:"Mengubah data seismik menjadi data log";}','','Memastikan akurasi pembacaan log terhadap sifat fisik batuan yang sebenarnya','What is the main purpose of the well log calibration process with core data in petrophysical studies?','a:4:{i:0;s:36:"Determining absolute reservoir depth";i:1;s:69:"Ensuring log reading accuracy against actual rock physical properties";i:2;s:35:"Reducing drilling operational costs";i:3;s:37:"Converting seismic data into log data";}','Ensuring log reading accuracy against actual rock physical properties','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000191','Komponen petrofisika apa saja yang paling krusial untuk diintegrasikan ke dalam model geologi 3D guna estimasi volume hidrokarbon?','multi','PFM000000039','a:4:{i:0;s:17:"Porositas efektif";i:1;s:12:"Saturasi air";i:2;s:12:"Warna batuan";i:3;s:26:"Ketebalan bersih (net pay)";}','','a:3:{i:0;s:17:"Porositas efektif";i:1;s:12:"Saturasi air";i:2;s:26:"Ketebalan bersih (net pay)";}','Which petrophysical components are most crucial to be integrated into a 3D geological model for hydrocarbon volume estimation?','a:4:{i:0;s:18:"Effective porosity";i:1;s:16:"Water saturation";i:2;s:10:"Rock color";i:3;s:17:"Net pay thickness";}','a:3:{i:0;s:18:"Effective porosity";i:1;s:16:"Water saturation";i:2;s:17:"Net pay thickness";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000192','Dalam integrasi data seismik dan petrofisika, parameter apa yang menghubungkan densitas batuan dengan impedansi akustik?','option','PFM000000039','a:4:{i:0;s:21:"Permeabilitas absolut";i:1;s:27:"Kecepatan gelombang seismik";i:2;s:15:"Tekanan kapiler";i:3;s:15:"Saturasi minyak";}','','Kecepatan gelombang seismik','In seismic and petrophysical data integration, what parameter links rock density to acoustic impedance?','a:4:{i:0;s:21:"Absolute permeability";i:1;s:21:"Seismic wave velocity";i:2;s:18:"Capillary pressure";i:3;s:14:"Oil saturation";}','Seismic wave velocity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000193','Mengapa konsistensi skala (scale dependency) antara data log dan data seismik harus diperhatikan dalam pemodelan reservoar?','option','PFM000000039','a:4:{i:0;s:72:"Karena log memiliki resolusi vertikal yang lebih tinggi daripada seismik";i:1;s:57:"Karena seismik tidak membutuhkan data log untuk kalibrasi";i:2;s:56:"Karena kecepatan suara selalu konstan di semua kedalaman";i:3;s:37:"Karena data core tidak memiliki skala";}','','Karena log memiliki resolusi vertikal yang lebih tinggi daripada seismik','Why must scale dependency between log data and seismic data be considered in reservoir modeling?','a:4:{i:0;s:62:"Because logs have higher vertical resolution than seismic data";i:1;s:57:"Because seismic does not require log data for calibration";i:2;s:55:"Because sound velocity is always constant at all depths";i:3;s:30:"Because core data has no scale";}','Because logs have higher vertical resolution than seismic data','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000194','Apa dampak utama jika data petrofisika tidak dikalibrasi dengan data laboratorium core sebelum digunakan dalam pemodelan 3D?','option','PFM000000039','a:4:{i:0;s:32:"Peningkatan kecepatan pengeboran";i:1;s:47:"Estimasi cadangan hidrokarbon yang tidak akurat";i:2;s:28:"Penurunan harga minyak dunia";i:3;s:49:"Peningkatan resolusi data seismik secara otomatis";}','','Estimasi cadangan hidrokarbon yang tidak akurat','What is the main impact if petrophysical data is not calibrated with core laboratory data before being used in 3D modeling?','a:4:{i:0;s:24:"Increased drilling speed";i:1;s:41:"Inaccurate hydrocarbon reserve estimation";i:2;s:24:"Global oil price decline";i:3;s:45:"Automatic increase in seismic data resolution";}','Inaccurate hydrocarbon reserve estimation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000195','Apa fungsi utama dari proses depth shifting dalam tahap kontrol kualitas data log sebelum interpretasi?','option','PFM000000040','a:4:{i:0;s:97:"Menyelaraskan kedalaman antar kurva log yang berbeda agar sesuai pada kedalaman formasi yang sama";i:1;s:51:"Mengonversi nilai porositas dari unit kaki ke meter";i:2;s:63:"Menghilangkan noise pada data resistivitas akibat efek borehole";i:3;s:48:"Meningkatkan resolusi vertikal dari alat logging";}','','Menyelaraskan kedalaman antar kurva log yang berbeda agar sesuai pada kedalaman formasi yang sama','What is the main function of the depth shifting process in the log data quality control stage before interpretation?','a:4:{i:0;s:71:"Aligning different log curves to correspond to the same formation depth";i:1;s:46:"Converting porosity values from feet to meters";i:2;s:61:"Removing noise in resistivity data caused by borehole effects";i:3;s:54:"Increasing the vertical resolution of the logging tool";}','Aligning different log curves to correspond to the same formation depth','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000196','Manakah pernyataan yang benar mengenai penggunaan crossplot Density-Neutron untuk analisis petrofisika?','multi','PFM000000040','a:4:{i:0;s:47:"Mendeteksi adanya zona gas (crossover efek gas)";i:1;s:33:"Mengidentifikasi litologi formasi";i:2;s:50:"Mengukur permeabilitas secara langsung di lapangan";i:3;s:32:"Menentukan saturasi air residual";}','','a:2:{i:0;s:47:"Mendeteksi adanya zona gas (crossover efek gas)";i:1;s:33:"Mengidentifikasi litologi formasi";}','Which statements are correct regarding the use of a Density-Neutron crossplot for petrophysical analysis?','a:4:{i:0;s:42:"Detecting gas zones (gas effect crossover)";i:1;s:31:"Identifying formation lithology";i:2;s:44:"Directly measuring permeability in the field";i:3;s:37:"Determining residual water saturation";}','a:2:{i:0;s:42:"Detecting gas zones (gas effect crossover)";i:1;s:31:"Identifying formation lithology";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000197','Mengapa normalisasi data log diperlukan dalam alur kerja petrofisika pada sumur yang memiliki data lama dan baru?','option','PFM000000040','a:4:{i:0;s:68:"Untuk menghilangkan bias akibat perbedaan kalibrasi alat antar sumur";i:1;s:50:"Untuk mengubah unit pengukuran dari SI ke Imperial";i:2;s:61:"Untuk mempercepat waktu komputasi saat pembuatan model statis";i:3;s:46:"Untuk meningkatkan nilai permeabilitas formasi";}','','Untuk menghilangkan bias akibat perbedaan kalibrasi alat antar sumur','Why is log data normalization necessary in the petrophysical workflow for wells with old and new data?','a:4:{i:0;s:70:"To eliminate bias due to differences in tool calibration between wells";i:1;s:48:"To convert measurement units from SI to Imperial";i:2;s:59:"To speed up computational time during static model creation";i:3;s:44:"To increase the formation permeability value";}','To eliminate bias due to differences in tool calibration between wells','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000198','Apa tujuan utama dari pembuatan laporan petrofisika (petrophysical summary report) setelah proses QC selesai?','option','PFM000000040','a:4:{i:0;s:98:"Memberikan dokumentasi parameter, asumsi, dan hasil interpretasi untuk estimasi volume hidrokarbon";i:1;s:56:"Menentukan lokasi pengeboran sumur eksplorasi berikutnya";i:2;s:59:"Menggantikan kebutuhan akan pengujian drill stem test (DST)";i:3;s:58:"Melakukan kalibrasi mekanis pada alat logging di permukaan";}','','Memberikan dokumentasi parameter, asumsi, dan hasil interpretasi untuk estimasi volume hidrokarbon','What is the primary objective of creating a petrophysical summary report after the QC process is complete?','a:4:{i:0;s:112:"Providing documentation of parameters, assumptions, and interpretation results for hydrocarbon volume estimation";i:1;s:63:"Determining the drilling location for the next exploration well";i:2;s:45:"Replacing the need for drill stem tests (DST)";i:3;s:65:"Performing mechanical calibration on logging tools at the surface";}','Providing documentation of parameters, assumptions, and interpretation results for hydrocarbon volume estimation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000199','Pada plot Density-Neutron, apa yang terjadi jika formasi mengandung batuan dengan densitas matriks yang sangat berat seperti barite?','option','PFM000000040','a:4:{i:0;s:74:"Kurva densitas akan bergeser ke arah porositas yang lebih tinggi (ke kiri)";i:1;s:70:"Kurva neutron akan menunjukkan nilai yang mendekati nol secara konstan";i:2;s:54:"Data akan menunjukkan anomali negatif yang tidak logis";i:3;s:47:"Tidak ada pengaruh terhadap pembacaan porositas";}','','Kurva densitas akan bergeser ke arah porositas yang lebih tinggi (ke kiri)','On a Density-Neutron plot, what happens if the formation contains rock with very heavy matrix density such as barite?','a:4:{i:0;s:66:"The density curve will shift towards higher porosity (to the left)";i:1;s:62:"The neutron curve will show values constantly approaching zero";i:2;s:47:"The data will show illogical negative anomalies";i:3;s:39:"There is no effect on porosity readings";}','The density curve will shift towards higher porosity (to the left)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000200','Dalam penentuan volume shale (Vsh) menggunakan log Gamma Ray, manakah parameter yang harus ditentukan terlebih dahulu sebelum menghitung indeks GR?','option','PFM000000041','a:4:{i:0;s:36:"Nilai GR bersih (clean) dan GR shale";i:1;s:38:"Porositas efektif dan densitas matriks";i:2;s:42:"Saturasi air irreducible dan permeabilitas";i:3;s:39:"Tekanan reservoir dan viskositas fluida";}','','Nilai GR bersih (clean) dan GR shale','In determining the shale volume (Vsh) using Gamma Ray logs, which parameter must be determined first before calculating the GR index?','a:4:{i:0;s:28:"Clean GR and shale GR values";i:1;s:37:"Effective porosity and matrix density";i:2;s:45:"Irreducible water saturation and permeability";i:3;s:38:"Reservoir pressure and fluid viscosity";}','Clean GR and shale GR values','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000201','Faktor apa saja yang memengaruhi perhitungan porositas (phi) dari log densitas?','multi','PFM000000041','a:4:{i:0;s:23:"Densitas matriks batuan";i:1;s:28:"Densitas fluida pengisi pori";i:2;s:24:"Saturasi minyak residual";i:3;s:15:"Laju pengeboran";}','','a:2:{i:0;s:23:"Densitas matriks batuan";i:1;s:28:"Densitas fluida pengisi pori";}','What factors affect the porosity (phi) calculation from density logs?','a:4:{i:0;s:19:"Rock matrix density";i:1;s:18:"Pore fluid density";i:2;s:23:"Residual oil saturation";i:3;s:13:"Drilling rate";}','a:2:{i:0;s:19:"Rock matrix density";i:1;s:18:"Pore fluid density";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000202','Jika sebuah zona reservoir memiliki nilai resistivitas yang tinggi dan porositas yang baik, interpretasi kualitatif yang paling mungkin adalah?','option','PFM000000041','a:4:{i:0;s:27:"Zona mengandung hidrokarbon";i:1;s:29:"Zona air formasi (water zone)";i:2;s:16:"Zona shale padat";i:3;s:29:"Zona dengan permeabilitas nol";}','','Zona mengandung hidrokarbon','If a reservoir zone has high resistivity values and good porosity, what is the most likely qualitative interpretation?','a:4:{i:0;s:24:"Hydrocarbon-bearing zone";i:1;s:10:"Water zone";i:2;s:16:"Tight shale zone";i:3;s:22:"Zero permeability zone";}','Hydrocarbon-bearing zone','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000203','Dalam penentuan net pay, kriteria manakah yang umumnya digunakan sebagai ambang batas (cut-off) untuk memisahkan reservoir produktif dari non-produktif?','option','PFM000000041','a:4:{i:0;s:32:"Vsh, porositas, dan saturasi air";i:1;s:39:"Tekanan kapiler dan interfacial tension";i:2;s:27:"Kedalaman sumur dan deviasi";i:3;s:24:"Laju alir dan viskositas";}','','Vsh, porositas, dan saturasi air','In determining net pay, which criteria are generally used as cut-off thresholds to distinguish productive reservoir from non-productive ones?','a:4:{i:0;s:35:"Vsh, porosity, and water saturation";i:1;s:42:"Capillary pressure and interfacial tension";i:2;s:24:"Well depth and deviation";i:3;s:23:"Flow rate and viscosity";}','Vsh, porosity, and water saturation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000204','Persamaan Archie digunakan untuk menghitung saturasi air (Sw) dengan variabel utama berupa?','option','PFM000000041','a:4:{i:0;s:60:"Resistivitas air formasi, porositas, dan resistivitas batuan";i:1;s:49:"Densitas bulk, densitas matriks, dan shale volume";i:2;s:43:"Permeabilitas absolut dan tekanan reservoir";i:3;s:35:"Laju injeksi dan viskositas polimer";}','','Resistivitas air formasi, porositas, dan resistivitas batuan','The Archie equation is used to calculate water saturation (Sw) with which primary variables?','a:4:{i:0;s:59:"Formation water resistivity, porosity, and rock resistivity";i:1;s:46:"Bulk density, matrix density, and shale volume";i:2;s:44:"Absolute permeability and reservoir pressure";i:3;s:36:"Injection rate and polymer viscosity";}','Formation water resistivity, porosity, and rock resistivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000205','Jika diketahui volume bulk batuan adalah 1000 m3 dan volume pori adalah 200 m3, berapakah nilai porositas batuan tersebut?','option','PFM000000042','a:4:{i:0;s:3:"10%";i:1;s:3:"20%";i:2;s:3:"25%";i:3;s:3:"30%";}','','20%','If the bulk volume of the rock is 1000 m3 and the pore volume is 200 m3, what is the porosity value of the rock?','a:4:{i:0;s:3:"10%";i:1;s:3:"20%";i:2;s:3:"25%";i:3;s:3:"30%";}','20%','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000206','Manakah parameter yang secara langsung mempengaruhi perhitungan volume hidrokarbon di tempat (OOIP) dalam suatu reservoir?','multi','PFM000000042','a:4:{i:0;s:17:"Porositas efektif";i:1;s:12:"Saturasi air";i:2;s:21:"Permeabilitas absolut";i:3;s:19:"Luas area reservoir";}','','a:3:{i:0;s:17:"Porositas efektif";i:1;s:12:"Saturasi air";i:2;s:19:"Luas area reservoir";}','Which parameters directly affect the calculation of original oil in place (OOIP) in a reservoir?','a:4:{i:0;s:18:"Effective porosity";i:1;s:16:"Water saturation";i:2;s:21:"Absolute permeability";i:3;s:14:"Reservoir area";}','a:3:{i:0;s:18:"Effective porosity";i:1;s:16:"Water saturation";i:2;s:14:"Reservoir area";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000207','Pada grafik log resistivitas, jika zona tersebut memiliki nilai resistivitas yang sangat tinggi dibandingkan zona basah air (Rw), apa indikasi utamanya?','option','PFM000000042','a:4:{i:0;s:38:"Adanya saturasi minyak yang signifikan";i:1;s:20:"Batuan sangat kompak";i:2;s:33:"Adanya kandungan clay yang tinggi";i:3;s:23:"Porositas mendekati nol";}','','Adanya saturasi minyak yang signifikan','On a resistivity log, if a zone has a very high resistivity value compared to the water-saturated zone (Rw), what is the primary indication?','a:4:{i:0;s:26:"Significant oil saturation";i:1;s:21:"Highly compacted rock";i:2;s:17:"High clay content";i:3;s:18:"Porosity near zero";}','Significant oil saturation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000208','Sebuah reservoir memiliki saturasi air (Sw) sebesar 30%. Berapakah saturasi hidrokarbon (Sh) pada reservoir tersebut?','option','PFM000000042','a:4:{i:0;s:3:"30%";i:1;s:3:"50%";i:2;s:3:"70%";i:3;s:4:"100%";}','','70%','A reservoir has a water saturation (Sw) of 30%. What is the hydrocarbon saturation (Sh) in that reservoir?','a:4:{i:0;s:3:"30%";i:1;s:3:"50%";i:2;s:3:"70%";i:3;s:4:"100%";}','70%','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000209','Dalam interpretasi data log gamma ray, manakah dari pilihan berikut yang biasanya mengindikasikan kehadiran serpih (shale) yang tinggi?','option','PFM000000042','a:4:{i:0;s:22:"Defleksi kurva ke kiri";i:1;s:21:"Nilai API yang rendah";i:2;s:23:"Defleksi kurva ke kanan";i:3;s:31:"Resistivitas yang sangat tinggi";}','','Defleksi kurva ke kanan','In gamma ray log interpretation, which of the following typically indicates the presence of high shale content?','a:4:{i:0;s:28:"Curve deflection to the left";i:1;s:13:"Low API value";i:2;s:29:"Curve deflection to the right";i:3;s:21:"Very high resistivity";}','Curve deflection to the right','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000210','Manakah mekanisme pendorong alami yang menjadi karakteristik utama pada tahap primary recovery?','option','PFM000000043','a:4:{i:0;s:21:"Ekspansi gas terlarut";i:1;s:15:"Injeksi polimer";i:2;s:15:"Injeksi gas CO2";i:3;s:13:"Waterflooding";}','','Ekspansi gas terlarut','Which natural drive mechanism is the main characteristic of the primary recovery stage?','a:4:{i:0;s:23:"Dissolved gas expansion";i:1;s:17:"Polymer injection";i:2;s:17:"CO2 gas injection";i:3;s:13:"Waterflooding";}','Dissolved gas expansion','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000211','Apa tujuan utama dari penerapan secondary recovery pada suatu lapangan minyak?','option','PFM000000043','a:4:{i:0;s:43:"Menjaga tekanan reservoir agar tetap tinggi";i:1;s:35:"Mengurangi viskositas minyak mentah";i:2;s:31:"Mengubah sifat kebasahan batuan";i:3;s:54:"Menghilangkan tegangan antar muka (IFT) secara drastis";}','','Menjaga tekanan reservoir agar tetap tinggi','What is the primary objective of implementing secondary recovery in an oil field?','a:4:{i:0;s:30:"Maintaining reservoir pressure";i:1;s:28:"Reducing crude oil viscosity";i:2;s:25:"Changing rock wettability";i:3;s:46:"Drastically reducing interfacial tension (IFT)";}','Maintaining reservoir pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000212','Manakah dari metode berikut yang dikategorikan sebagai metode Tertiary Recovery atau Enhanced Oil Recovery (EOR)?','multi','PFM000000043','a:4:{i:0;s:15:"Injeksi polimer";i:1;s:27:"Injeksi uap panas (thermal)";i:2;s:13:"Waterflooding";i:3;s:17:"Natural depletion";}','','a:2:{i:0;s:15:"Injeksi polimer";i:1;s:27:"Injeksi uap panas (thermal)";}','Which of the following methods are categorized as Tertiary Recovery or Enhanced Oil Recovery (EOR)?','a:4:{i:0;s:17:"Polymer injection";i:1;s:23:"Thermal steam injection";i:2;s:13:"Waterflooding";i:3;s:17:"Natural depletion";}','a:2:{i:0;s:17:"Polymer injection";i:1;s:23:"Thermal steam injection";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000213','Apa hambatan utama yang menyebabkan minyak masih tertinggal di reservoir setelah tahap secondary recovery selesai?','option','PFM000000043','a:4:{i:0;s:54:"Gaya kapiler yang memerangkap minyak dalam pori batuan";i:1;s:57:"Kurangnya jumlah sumurangnya cadangan minyak di reservoir";i:2;s:52:"Tekanan reservoir yang terlalu rendah untuk mengalir";i:3;s:34:"Viskositas air yang terlalu tinggi";}','','Gaya kapiler yang memerangkap minyak dalam pori batuan','What is the main obstacle that causes oil to remain trapped in the reservoir after secondary recovery is completed?','a:4:{i:0;s:43:"Capillary forces trapping oil in rock pores";i:1;s:37:"Lack of oil reserves in the reservoir";i:2;s:34:"Reservoir pressure too low to flow";i:3;s:24:"Water viscosity too high";}','Capillary forces trapping oil in rock pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000214','Pada urutan tahapan produksi minyak, manakah yang merupakan tahapan dengan efisiensi perolehan paling rendah?','option','PFM000000043','a:4:{i:0;s:16:"Primary recovery";i:1;s:18:"Secondary recovery";i:2;s:17:"Tertiary recovery";i:3;s:11:"EOR kimiawi";}','','Primary recovery','In the sequence of oil production stages, which one has the lowest recovery efficiency?','a:4:{i:0;s:16:"Primary recovery";i:1;s:18:"Secondary recovery";i:2;s:17:"Tertiary recovery";i:3;s:12:"Chemical EOR";}','Primary recovery','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000215','Manakah pernyataan yang paling tepat mendefinisikan Faktor Perolehan (Recovery Factor) dalam konteks reservoir minyak?','option','PFM000000044','a:4:{i:0;s:80:"Rasio volume minyak yang diproduksi terhadap volume minyak awal di tempat (OOIP)";i:1;s:76:"Total volume air yang diinjeksikan ke dalam reservoir untuk mendorong minyak";i:2;s:82:"Perbandingan antara viskositas minyak dengan viskositas air pada kondisi reservoir";i:3;s:57:"Kecepatan rata-rata fluida bergerak melalui media berpori";}','','Rasio volume minyak yang diproduksi terhadap volume minyak awal di tempat (OOIP)','Which statement best defines the Recovery Factor (RF) in the context of an oil reservoir?','a:4:{i:0;s:68:"The ratio of produced oil volume to the original oil in place (OOIP)";i:1;s:61:"Total volume of water injected into the reservoir to push oil";i:2;s:75:"The ratio between oil viscosity and water viscosity at reservoir conditions";i:3;s:57:"The average velocity of fluid moving through porous media";}','The ratio of produced oil volume to the original oil in place (OOIP)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000216','Faktor perolehan (RF) secara umum merupakan hasil perkalian dari komponen-komponen utama berikut:','multi','PFM000000044','a:4:{i:0;s:38:"Efisiensi penyapuan (Sweep Efficiency)";i:1;s:47:"Efisiensi perpindahan (Displacement Efficiency)";i:2;s:54:"Faktor volume formasi minyak (Formation Volume Factor)";i:3;s:21:"Permeabilitas absolut";}','','a:2:{i:0;s:38:"Efisiensi penyapuan (Sweep Efficiency)";i:1;s:47:"Efisiensi perpindahan (Displacement Efficiency)";}','The recovery factor (RF) is generally the product of which of the following main components?','a:4:{i:0;s:16:"Sweep Efficiency";i:1;s:23:"Displacement Efficiency";i:2;s:27:"Oil Formation Volume Factor";i:3;s:21:"Absolute permeability";}','a:2:{i:0;s:16:"Sweep Efficiency";i:1;s:23:"Displacement Efficiency";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000217','Efisiensi penyapuan (sweep efficiency) dalam reservoir terutama dipengaruhi oleh faktor-faktor berikut, kecuali:','option','PFM000000044','a:4:{i:0;s:31:"Heterogenitas formasi reservoir";i:1;s:42:"Pola penempatan sumur produksi dan injeksi";i:2;s:62:"Tegangan antarmuka (interfacial tension) antara minyak dan air";i:3;s:36:"Mobilitas fluida yang tidak seimbang";}','','Tegangan antarmuka (interfacial tension) antara minyak dan air','Sweep efficiency in a reservoir is primarily influenced by the following factors, except:','a:4:{i:0;s:33:"Reservoir formation heterogeneity";i:1;s:56:"Well placement pattern of production and injection wells";i:2;s:41:"Interfacial tension between oil and water";i:3;s:26:"Unfavorable fluid mobility";}','Interfacial tension between oil and water','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000218','Efisiensi perpindahan (displacement efficiency) pada skala mikroskopik sangat bergantung pada:','option','PFM000000044','a:4:{i:0;s:47:"Tegangan antarmuka (IFT) dan wettability batuan";i:1;s:42:"Kedalaman reservoir dan tekanan overburden";i:2;s:33:"Jumlah sumur dalam satu pola grid";i:3;s:29:"Laju alir fluida di permukaan";}','','Tegangan antarmuka (IFT) dan wettability batuan','Displacement efficiency at the microscopic scale heavily depends on:','a:4:{i:0;s:46:"Interfacial tension (IFT) and rock wettability";i:1;s:39:"Reservoir depth and overburden pressure";i:2;s:33:"Number of wells in a grid pattern";i:3;s:30:"Fluid flow rate at the surface";}','Interfacial tension (IFT) and rock wettability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000219','Manakah dari berikut ini yang merepresentasikan upaya untuk meningkatkan efisiensi penyapuan makroskopik?','option','PFM000000044','a:4:{i:0;s:42:"Mengoptimalkan geometri pola injeksi sumur";i:1;s:57:"Menambahkan surfaktan untuk menurunkan tegangan antarmuka";i:2;s:61:"Menggunakan polimer untuk meningkatkan viskositas air injeksi";i:3;s:37:"Injeksi gas CO2 untuk swelling minyak";}','','Mengoptimalkan geometri pola injeksi sumur','Which of the following represents an effort to improve macroscopic sweep efficiency?','a:4:{i:0;s:42:"Optimizing injection well pattern geometry";i:1;s:48:"Adding surfactants to reduce interfacial tension";i:2;s:52:"Using polymers to increase injection water viscosity";i:3;s:34:"CO2 gas injection for oil swelling";}','Optimizing injection well pattern geometry','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000220','Mekanisme pendorong reservoar manakah yang umumnya memberikan nilai Recovery Factor (RF) paling rendah pada tahap produksi primer?','option','PFM000000045','a:4:{i:0;s:15:"Depletion drive";i:1;s:11:"Water drive";i:2;s:13:"Gas cap drive";i:3;s:16:"Gravity drainage";}','','Depletion drive','Which reservoir drive mechanism generally provides the lowest Recovery Factor (RF) during the primary production stage?','a:4:{i:0;s:15:"Depletion drive";i:1;s:11:"Water drive";i:2;s:13:"Gas cap drive";i:3;s:16:"Gravity drainage";}','Depletion drive','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000221','Faktor apa saja yang memengaruhi efisiensi perolehan minyak pada mekanisme water drive?','multi','PFM000000045','a:4:{i:0;s:20:"Permeabilitas batuan";i:1;s:17:"Viskositas minyak";i:2;s:21:"Kecepatan injeksi gas";i:3;s:17:"Saturasi air awal";}','','a:2:{i:0;s:20:"Permeabilitas batuan";i:1;s:17:"Viskositas minyak";}','What factors influence oil recovery efficiency in a water drive mechanism?','a:4:{i:0;s:17:"Rock permeability";i:1;s:13:"Oil viscosity";i:2;s:18:"Gas injection rate";i:3;s:24:"Initial water saturation";}','a:2:{i:0;s:17:"Rock permeability";i:1;s:13:"Oil viscosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000222','Apa dampak utama dari keberadaan gas cap yang aktif dalam suatu reservoar terhadap performa produksi?','option','PFM000000045','a:4:{i:0;s:41:"Menurunkan tekanan reservoar dengan cepat";i:1;s:41:"Membantu mempertahankan tekanan reservoar";i:2;s:45:"Meningkatkan viskositas minyak secara drastis";i:3;s:44:"Menghentikan aliran fluida melalui porositas";}','','Membantu mempertahankan tekanan reservoar','What is the primary impact of an active gas cap in a reservoir on production performance?','a:4:{i:0;s:37:"Rapid depletion of reservoir pressure";i:1;s:33:"Helps maintain reservoir pressure";i:2;s:35:"Drastically increases oil viscosity";i:3;s:33:"Stops fluid flow through porosity";}','Helps maintain reservoir pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000223','Mekanisme pendorong yang memanfaatkan perbedaan densitas antara minyak dan gas untuk mengalirkan minyak ke lubang sumur disebut?','option','PFM000000045','a:4:{i:0;s:18:"Solution gas drive";i:1;s:11:"Water drive";i:2;s:16:"Gravity drainage";i:3;s:17:"Combination drive";}','','Gravity drainage','The drive mechanism that utilizes the density difference between oil and gas to move oil toward the wellbore is called?','a:4:{i:0;s:18:"Solution gas drive";i:1;s:11:"Water drive";i:2;s:16:"Gravity drainage";i:3;s:17:"Combination drive";}','Gravity drainage','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000224','Pada reservoar dengan mekanisme pendorong kombinasi (combination drive), sumber energi utama untuk menggerakkan minyak berasal dari?','option','PFM000000045','a:4:{i:0;s:43:"Ekspansi gas terlarut, gas cap, dan akuifer";i:1;s:32:"Hanya injeksi air dari permukaan";i:2;s:37:"Hanya tekanan hidrostatik dari batuan";i:3;s:25:"Hanya dari gravitasi saja";}','','Ekspansi gas terlarut, gas cap, dan akuifer','In a reservoir with a combination drive mechanism, the primary source of energy to move oil comes from?','a:4:{i:0;s:47:"Expansion of solution gas, gas cap, and aquifer";i:1;s:37:"Only water injection from the surface";i:2;s:39:"Only hydrostatic pressure from the rock";i:3;s:17:"Only from gravity";}','Expansion of solution gas, gas cap, and aquifer','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000225','Apa yang dimaksud dengan Residual Oil Saturation (Sor) dalam konteks reservoir minyak?','option','PFM000000046','a:4:{i:0;s:112:"Saturasi minyak yang tersisa setelah proses pengurasan atau pendesakan yang tidak dapat diproduksi secara teknis";i:1;s:76:"Jumlah minyak awal yang terdapat di dalam reservoir sebelum produksi dimulai";i:2;s:87:"Volume minyak yang dapat diproduksi secara ekonomis menggunakan metode primary recovery";i:3;s:82:"Persentase minyak yang mengalir bebas melalui pori-pori batuan menuju lubang sumur";}','','Saturasi minyak yang tersisa setelah proses pengurasan atau pendesakan yang tidak dapat diproduksi secara teknis','What is meant by Residual Oil Saturation (Sor) in the context of an oil reservoir?','a:4:{i:0;s:106:"The oil saturation remaining after a depletion or displacement process that cannot be technically produced";i:1;s:77:"The initial amount of oil contained in the reservoir before production begins";i:2;s:82:"The volume of oil that can be economically produced using primary recovery methods";i:3;s:78:"The percentage of oil that flows freely through rock pores toward the wellbore";}','The oil saturation remaining after a depletion or displacement process that cannot be technically produced','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000226','Faktor-faktor utama yang menyebabkan minyak terjebak sebagai Residual Oil Saturation di dalam pori-pori batuan adalah?','multi','PFM000000046','a:4:{i:0;s:52:"Gaya kapiler yang menahan minyak di dalam pori kecil";i:1;s:53:"Adanya gaya gravitasi yang membantu pergerakan minyak";i:2;s:45:"Hambatan viskositas minyak yang sangat rendah";i:3;s:54:"Heterogenitas batuan reservoir yang menyebabkan bypass";}','','a:2:{i:0;s:52:"Gaya kapiler yang menahan minyak di dalam pori kecil";i:1;s:54:"Heterogenitas batuan reservoir yang menyebabkan bypass";}','What are the main factors that cause oil to be trapped as Residual Oil Saturation within rock pores?','a:4:{i:0;s:49:"Capillary forces that hold oil within small pores";i:1;s:45:"Gravitational forces that assist oil movement";i:2;s:33:"Very low oil viscosity resistance";i:3;s:43:"Reservoir rock heterogeneity causing bypass";}','a:2:{i:0;s:49:"Capillary forces that hold oil within small pores";i:1;s:43:"Reservoir rock heterogeneity causing bypass";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000227','Dalam aplikasi Enhanced Oil Recovery (EOR), mengapa target utama EOR adalah mengurangi nilai Sor?','option','PFM000000046','a:4:{i:0;s:76:"Karena nilai Sor yang rendah menunjukkan bahwa minyak sudah habis sepenuhnya";i:1;s:87:"Karena Sor mewakili cadangan minyak yang tidak dapat diambil dengan metode konvensional";i:2;s:70:"Karena mengurangi Sor akan menurunkan tekanan reservoir secara drastis";i:3;s:73:"Karena Sor harus ditingkatkan agar efisiensi pendesakan minyak lebih baik";}','','Karena Sor mewakili cadangan minyak yang tidak dapat diambil dengan metode konvensional','In Enhanced Oil Recovery (EOR) applications, why is the primary target of EOR to reduce the Sor value?','a:4:{i:0;s:75:"Because a low Sor value indicates that the oil has been completely depleted";i:1;s:84:"Because Sor represents oil reserves that cannot be recovered by conventional methods";i:2;s:62:"Because reducing Sor will drastically lower reservoir pressure";i:3;s:75:"Because Sor must be increased so that oil displacement efficiency is better";}','Because Sor represents oil reserves that cannot be recovered by conventional methods','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000228','Bagaimana pengaruh Interfacial Tension (IFT) terhadap nilai Sor pada proses pendesakan minyak?','option','PFM000000046','a:4:{i:0;s:79:"Semakin tinggi IFT, semakin rendah nilai Sor karena minyak lebih mudah bergerak";i:1;s:74:"Semakin rendah IFT, semakin rendah nilai Sor karena gaya kapiler berkurang";i:2;s:65:"IFT tidak memiliki pengaruh terhadap nilai saturasi minyak residu";i:3;s:87:"Semakin rendah IFT, semakin tinggi nilai Sor karena minyak terdispersi minyak meningkat";}','','Semakin rendah IFT, semakin rendah nilai Sor karena gaya kapiler berkurang','How does Interfacial Tension (IFT) affect the Sor value during an oil displacement process?','a:4:{i:0;s:73:"The higher the IFT, the lower the Sor value because oil moves more easily";i:1;s:79:"The lower the IFT, the lower the Sor value because capillary forces are reduced";i:2;s:57:"IFT has no influence on the residual oil saturation value";i:3;s:76:"The lower the IFT, the higher the Sor value because oil dispersion increases";}','The lower the IFT, the lower the Sor value because capillary forces are reduced','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000229','Pada kondisi waterflood (pendesakan air), berapakah kisaran umum nilai Sor yang tersisa di reservoir setelah air mencapai saturasi residual?','option','PFM000000046','a:4:{i:0;s:20:"Antara 5% hingga 10%";i:1;s:21:"Antara 20% hingga 40%";i:2;s:21:"Antara 60% hingga 80%";i:3;s:11:"Di atas 90%";}','','Antara 20% hingga 40%','In waterflood conditions, what is the typical range of Sor values remaining in the reservoir after water reaches residual saturation?','a:4:{i:0;s:17:"Between 5% to 10%";i:1;s:18:"Between 20% to 40%";i:2;s:18:"Between 60% to 80%";i:3;s:9:"Above 90%";}','Between 20% to 40%','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000230','Metode EOR mana yang terutama bekerja dengan cara menurunkan tegangan antarmuka (interfacial tension) antara minyak dan air untuk meningkatkan perolehan minyak?','option','PFM000000047','a:4:{i:0;s:19:"Surfactant flooding";i:1;s:16:"Polymer flooding";i:2;s:15:"Steam injection";i:3;s:22:"Gas miscible injection";}','','Surfactant flooding','Which EOR method primarily works by reducing the interfacial tension between oil and water to improve oil recovery?','a:4:{i:0;s:19:"Surfactant flooding";i:1;s:16:"Polymer flooding";i:2;s:15:"Steam injection";i:3;s:22:"Gas miscible injection";}','Surfactant flooding','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000231','Manakah dari pernyataan berikut yang merupakan mekanisme utama dari metode thermal EOR?','multi','PFM000000047','a:4:{i:0;s:27:"Penurunan viskositas minyak";i:1;s:32:"Ekspansi termal fluida reservoir";i:2;s:39:"Peningkatan saturasi air secara drastis";i:3;s:28:"Peningkatan porositas batuan";}','','a:2:{i:0;s:27:"Penurunan viskositas minyak";i:1;s:32:"Ekspansi termal fluida reservoir";}','Which of the following statements are the primary mechanisms of thermal EOR methods?','a:4:{i:0;s:26:"Reduction of oil viscosity";i:1;s:37:"Thermal expansion of reservoir fluids";i:2;s:36:"Drastic increase in water saturation";i:3;s:25:"Increase in rock porosity";}','a:2:{i:0;s:26:"Reduction of oil viscosity";i:1;s:37:"Thermal expansion of reservoir fluids";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000232','Tujuan utama penambahan polimer ke dalam fluida injeksi pada proses polymer flooding adalah untuk:','option','PFM000000047','a:4:{i:0;s:35:"Meningkatkan viskositas air injeksi";i:1;s:36:"Menurunkan tegangan permukaan batuan";i:2;s:45:"Mengubah sifat kebasahan (wettability) batuan";i:3;s:31:"Menguapkan fraksi minyak ringan";}','','Meningkatkan viskositas air injeksi','The primary objective of adding polymers to the injection fluid in polymer flooding is to:','a:4:{i:0;s:41:"Increase the viscosity of injection water";i:1;s:27:"Reduce rock surface tension";i:2;s:22:"Alter rock wettability";i:3;s:28:"Vaporize light oil fractions";}','Increase the viscosity of injection water','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000233','Proses injeksi gas yang mencapai kondisi miscible dengan minyak reservoir akan menghasilkan:','option','PFM000000047','a:4:{i:0;s:25:"Peniadaan tekanan kapiler";i:1;s:42:"Peningkatan viskositas minyak secara tajam";i:2;s:30:"Penurunan densitas air formasi";i:3;s:43:"Penggantian cadangan minyak dengan air laut";}','','Peniadaan tekanan kapiler','Gas injection processes that achieve miscibility with reservoir oil will result in:','a:4:{i:0;s:33:"Elimination of capillary pressure";i:1;s:31:"Sharp increase in oil viscosity";i:2;s:35:"Decrease in formation water density";i:3;s:41:"Replacement of oil reserves with seawater";}','Elimination of capillary pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000234','Metode MEOR (Microbial Enhanced Oil Recovery) memanfaatkan aktivitas mikroorganisme untuk:','option','PFM000000047','a:4:{i:0;s:51:"Memproduksi biosurfaktan dan gas di dalam reservoir";i:1;s:49:"Meningkatkan tekanan injeksi pompa secara mekanis";i:2;s:42:"Menyumbat pori-pori batuan secara permanen";i:3;s:45:"Menggantikan seluruh volume minyak dengan air";}','','Memproduksi biosurfaktan dan gas di dalam reservoir','MEOR (Microbial Enhanced Oil Recovery) methods utilize microorganism activity to:','a:4:{i:0;s:51:"Produce biosurfactants and gas within the reservoir";i:1;s:45:"Mechanically increase injection pump pressure";i:2;s:27:"Permanently plug rock pores";i:3;s:40:"Replace the entire oil volume with water";}','Produce biosurfactants and gas within the reservoir','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000235','Metode EOR mana yang paling disarankan untuk reservoir minyak berat (heavy oil) dengan viskositas di atas 100 cP namun kurang dari 1000 cP?','option','PFM000000048','a:4:{i:0;s:26:"Waterflooding konvensional";i:1;s:24:"Gas injection (Miscible)";i:2;s:33:"Thermal recovery (steam flooding)";i:3;s:27:"Chemical flooding (polymer)";}','','Thermal recovery (steam flooding)','Which EOR method is most recommended for heavy oil reservoirs with viscosity above 100 cP but less than 1000 cP?','a:4:{i:0;s:26:"Conventional waterflooding";i:1;s:22:"Miscible gas injection";i:2;s:33:"Thermal recovery (steam flooding)";i:3;s:27:"Chemical flooding (polymer)";}','Thermal recovery (steam flooding)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000236','Faktor fisik reservoir apa saja yang menjadi kriteria utama dalam melakukan screening awal metode EOR?','multi','PFM000000048','a:4:{i:0;s:9:"Porositas";i:1;s:13:"Permeabilitas";i:2;s:19:"Kedalaman reservoir";i:3;s:17:"Warna minyak bumi";}','','a:3:{i:0;s:9:"Porositas";i:1;s:13:"Permeabilitas";i:2;s:19:"Kedalaman reservoir";}','Which physical reservoir factors are the primary criteria for conducting an initial EOR screening?','a:4:{i:0;s:8:"Porosity";i:1;s:12:"Permeability";i:2;s:15:"Reservoir depth";i:3;s:15:"Crude oil color";}','a:3:{i:0;s:8:"Porosity";i:1;s:12:"Permeability";i:2;s:15:"Reservoir depth";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000237','Berapakah batas ambang minimum permeabilitas (k) yang umumnya disyaratkan untuk aplikasi polymer flooding agar tidak terjadi penyumbatan (plugging)?','option','PFM000000048','a:4:{i:0;s:4:"5 mD";i:1;s:5:"10 mD";i:2;s:5:"50 mD";i:3;s:6:"500 mD";}','','10 mD','What is the minimum permeability (k) threshold generally required for polymer flooding applications to prevent plugging?','a:4:{i:0;s:4:"5 mD";i:1;s:5:"10 mD";i:2;s:5:"50 mD";i:3;s:6:"500 mD";}','10 mD','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000238','Dalam screening EOR, mengapa salinitas air formasi menjadi parameter penting bagi aplikasi chemical flooding?','option','PFM000000048','a:4:{i:0;s:51:"Karena salinitas tinggi akan merusak sensor tekanan";i:1;s:70:"Karena salinitas tinggi mempengaruhi efektivitas polimer dan surfaktan";i:2;s:65:"Karena salinitas tinggi menurunkan viskositas minyak secara alami";i:3;s:59:"Karena salinitas tinggi menghambat aliran gas ke dalam pori";}','','Karena salinitas tinggi mempengaruhi efektivitas polimer dan surfaktan','In EOR screening, why is formation water salinity an important parameter for chemical flooding applications?','a:4:{i:0;s:46:"Because high salinity damages pressure sensors";i:1;s:66:"Because high salinity affects polymer and surfactant effectiveness";i:2;s:52:"Because high salinity naturally lowers oil viscosity";i:3;s:50:"Because high salinity prevents gas flow into pores";}','Because high salinity affects polymer and surfactant effectiveness','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000239','Metode EOR gas injection (miscible) umumnya memerlukan syarat kedalaman minimum agar tekanan reservoir dapat mencapai tekanan misibilitas minimum (MMP). Berapakah kedalaman tersebut?','option','PFM000000048','a:4:{i:0;s:20:"Lebih dari 1000 kaki";i:1;s:20:"Lebih dari 2000 kaki";i:2;s:20:"Lebih dari 4000 kaki";i:3;s:22:"Lebih dari 10.000 kaki";}','','Lebih dari 4000 kaki','Miscible gas injection EOR methods generally require a minimum depth to ensure the reservoir pressure can reach the Minimum Miscibility Pressure (MMP). What is that depth?','a:4:{i:0;s:20:"Greater than 1000 ft";i:1;s:20:"Greater than 2000 ft";i:2;s:20:"Greater than 4000 ft";i:3;s:22:"Greater than 10,000 ft";}','Greater than 4000 ft','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000240','Apa fungsi utama penambahan polimer ke dalam fluida injeksi pada proses Polymer Flooding?','option','PFM000000049','a:4:{i:0;s:32:"Menaikkan viskositas air injeksi";i:1;s:36:"Menurunkan tegangan antar muka (IFT)";i:2;s:31:"Mengubah sifat kebasahan batuan";i:3;s:27:"Melarutkan mineral karbonat";}','','Menaikkan viskositas air injeksi','What is the primary function of adding polymer to the injection fluid in the Polymer Flooding process?','a:4:{i:0;s:36:"Increasing injection water viscosity";i:1;s:34:"Reducing interfacial tension (IFT)";i:2;s:25:"Altering rock wettability";i:3;s:29:"Dissolving carbonate minerals";}','Increasing injection water viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000241','Pilih dua tujuan teknis utama dari penurunan mobility ratio (M) menjadi kurang dari 1 pada Polymer Flooding.','multi','PFM000000049','a:4:{i:0;s:50:"Memperbaiki efisiensi penyapuan (sweep efficiency)";i:1;s:41:"Meningkatkan permeabilitas absolut batuan";i:2;s:35:"Memperkecil risiko fingering fluida";i:3;s:41:"Mengubah saturasi minyak sisa menjadi nol";}','','a:2:{i:0;s:50:"Memperbaiki efisiensi penyapuan (sweep efficiency)";i:1;s:35:"Memperkecil risiko fingering fluida";}','Select two main technical goals of reducing the mobility ratio (M) to less than 1 in Polymer Flooding.','a:4:{i:0;s:26:"Improving sweep efficiency";i:1;s:37:"Increasing absolute rock permeability";i:2;s:29:"Reducing fluid fingering risk";i:3;s:40:"Changing residual oil saturation to zero";}','a:2:{i:0;s:26:"Improving sweep efficiency";i:1;s:29:"Reducing fluid fingering risk";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000242','Bagaimana pengaruh peningkatan viskositas air injeksi terhadap mobilitas air (water mobility) dalam reservoir?','option','PFM000000049','a:4:{i:0;s:21:"Mobilitas air menurun";i:1;s:23:"Mobilitas air meningkat";i:2;s:27:"Mobilitas air tetap konstan";i:3;s:37:"Mobilitas air menjadi tidak terhingga";}','','Mobilitas air menurun','How does the increase in injection water viscosity affect water mobility in the reservoir?','a:4:{i:0;s:24:"Water mobility decreases";i:1;s:24:"Water mobility increases";i:2;s:31:"Water mobility remains constant";i:3;s:31:"Water mobility becomes infinite";}','Water mobility decreases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000243','Apa yang terjadi pada profil aliran fluida di dalam reservoir ketika mobility ratio lebih kecil dari 1?','option','PFM000000049','a:4:{i:0;s:39:"Aliran menjadi lebih stabil dan seragam";i:1;s:45:"Terjadi fenomena viscous fingering yang parah";i:2;s:57:"Aliran air lebih cepat menembus zona permeabilitas tinggi";i:3;s:36:"Tekanan injeksi turun secara drastis";}','','Aliran menjadi lebih stabil dan seragam','What happens to the fluid flow profile in the reservoir when the mobility ratio is less than 1?','a:4:{i:0;s:36:"Flow becomes more stable and uniform";i:1;s:31:"Severe viscous fingering occurs";i:2;s:56:"Water flow breaks through high permeability zones faster";i:3;s:36:"Injection pressure drops drastically";}','Flow becomes more stable and uniform','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000244','Mengapa polimer dapat memperbaiki efisiensi penyapuan (sweep efficiency) secara volumetrik?','option','PFM000000049','a:4:{i:0;s:58:"Karena polimer mengarahkan air ke zona yang kurang tersapu";i:1;s:61:"Karena polimer secara drastis mengurangi saturasi minyak sisa";i:2;s:58:"Karena polimer menaikkan tekanan kapiler secara signifikan";i:3;s:59:"Karena polimer bereaksi secara kimiawi dengan butiran pasir";}','','Karena polimer mengarahkan air ke zona yang kurang tersapu','Why can polymers improve volumetric sweep efficiency?','a:4:{i:0;s:49:"Because polymers direct water to less swept zones";i:1;s:59:"Because polymers drastically reduce residual oil saturation";i:2;s:58:"Because polymers significantly increase capillary pressure";i:3;s:50:"Because polymers chemically react with sand grains";}','Because polymers direct water to less swept zones','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000245','Berapakah nilai rasio mobilitas (M) yang ideal agar proses pendesakan fluida di dalam reservoir dikatakan efisien dan stabil?','option','PFM000000050','a:4:{i:0;s:22:"M lebih besar dari 2.0";i:1;s:34:"M kurang dari atau sama dengan 1.0";i:2;s:24:"M sama dengan tak hingga";i:3;s:33:"M berkisar antara 5.0 hingga 10.0";}','','M kurang dari atau sama dengan 1.0','What is the ideal mobility ratio (M) value for the fluid displacement process in a reservoir to be considered efficient and stable?','a:4:{i:0;s:18:"M greater than 2.0";i:1;s:27:"M less than or equal to 1.0";i:2;s:19:"M equal to infinity";i:3;s:25:"M ranges from 5.0 to 10.0";}','M less than or equal to 1.0','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000246','Faktor apa saja yang dipengaruhi secara langsung oleh nilai rasio mobilitas (M) dalam proses pendesakan fluida?','multi','PFM000000050','a:4:{i:0;s:22:"Areal sweep efficiency";i:1;s:25:"Vertical sweep efficiency";i:2;s:21:"Tekanan injeksi pompa";i:3;s:16:"Porositas batuan";}','','a:2:{i:0;s:22:"Areal sweep efficiency";i:1;s:25:"Vertical sweep efficiency";}','Which factors are directly affected by the mobility ratio (M) value in a fluid displacement process?','a:4:{i:0;s:22:"Areal sweep efficiency";i:1;s:25:"Vertical sweep efficiency";i:2;s:23:"Pump injection pressure";i:3;s:13:"Rock porosity";}','a:2:{i:0;s:22:"Areal sweep efficiency";i:1;s:25:"Vertical sweep efficiency";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000247','Jika rasio mobilitas (M) lebih besar dari 1, fenomena apa yang kemungkinan besar akan terjadi di dalam reservoir?','option','PFM000000050','a:4:{i:0;s:37:"Penyapuan yang merata di seluruh area";i:1;s:38:"Viscous fingering (penerobosan fluida)";i:2;s:40:"Peningkatan perolehan minyak yang instan";i:3;s:43:"Penurunan viskositas minyak secara otomatis";}','','Viscous fingering (penerobosan fluida)','If the mobility ratio (M) is greater than 1, what phenomenon is most likely to occur within the reservoir?','a:4:{i:0;s:33:"Uniform sweep throughout the area";i:1;s:17:"Viscous fingering";i:2;s:35:"Instantaneous oil recovery increase";i:3;s:33:"Automatic oil viscosity reduction";}','Viscous fingering','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000248','Mengapa penambahan polimer ke dalam air injeksi dapat memperbaiki efisiensi penyapuan?','option','PFM000000050','a:4:{i:0;s:48:"Karena polimer meningkatkan permeabilitas batuan";i:1;s:48:"Karena polimer menurunkan viskositas air injeksi";i:2;s:78:"Karena polimer meningkatkan viskositas air sehingga menurunkan rasio mobilitas";i:3;s:58:"Karena polimer mengubah wettability batuan menjadi oil-wet";}','','Karena polimer meningkatkan viskositas air sehingga menurunkan rasio mobilitas','Why does the addition of polymer to injection water improve sweep efficiency?','a:4:{i:0;s:43:"Because polymer increases rock permeability";i:1;s:51:"Because polymer decreases injection water viscosity";i:2;s:78:"Because polymer increases water viscosity, thereby lowering the mobility ratio";i:3;s:51:"Because polymer changes rock wettability to oil-wet";}','Because polymer increases water viscosity, thereby lowering the mobility ratio','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000249','Dalam konteks rasio mobilitas M = (krw/μw) / (kro/μo), apa yang terjadi jika viskositas fluida pendesak (μw) meningkat?','option','PFM000000050','a:4:{i:0;s:22:"Nilai M akan meningkat";i:1;s:20:"Nilai M akan menurun";i:2;s:21:"Nilai M tetap konstan";i:3;s:33:"Nilai M menjadi tidak terdefinisi";}','','Nilai M akan menurun','In the context of the mobility ratio M = (krw/μw) / (kro/μo), what happens if the viscosity of the displacing fluid (μw) increases?','a:4:{i:0;s:28:"The value of M will increase";i:1;s:28:"The value of M will decrease";i:2;s:31:"The value of M remains constant";i:3;s:32:"The value of M becomes undefined";}','The value of M will decrease','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000250','Manakah pernyataan yang benar mengenai pengaruh salinitas terhadap viskositas larutan HPAM dalam aplikasi Chemical EOR?','option','PFM000000051','a:4:{i:0;s:95:"Peningkatan salinitas menyebabkan rantai polimer tergulung (coiled) sehingga viskositas menurun";i:1;s:100:"Peningkatan salinitas menyebabkan rantai polimer terbentang (extended) sehingga viskositas meningkat";i:2;s:69:"Salinitas tidak memiliki pengaruh terhadap viskositas larutan polimer";i:3;s:96:"Viskositas larutan HPAM akan selalu meningkat seiring dengan peningkatan konsentrasi ion klorida";}','','Peningkatan salinitas menyebabkan rantai polimer tergulung (coiled) sehingga viskositas menurun','Which statement is correct regarding the effect of salinity on the viscosity of HPAM solutions in Chemical EOR applications?','a:4:{i:0;s:86:"Increasing salinity causes the polymer chain to coil, resulting in decreased viscosity";i:1;s:88:"Increasing salinity causes the polymer chain to extend, resulting in increased viscosity";i:2;s:60:"Salinity has no effect on the viscosity of polymer solutions";i:3;s:84:"HPAM solution viscosity will always increase as chloride ion concentration increases";}','Increasing salinity causes the polymer chain to coil, resulting in decreased viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000251','Faktor apa saja yang menyebabkan degradasi termal pada polimer HPAM di dalam reservoir?','multi','PFM000000051','a:4:{i:0;s:32:"Temperatur reservoir yang tinggi";i:1;s:27:"Keberadaan oksigen terlarut";i:2;s:29:"Kecepatan injeksi yang rendah";i:3;s:25:"Tingginya tekanan kapiler";}','','a:2:{i:0;s:32:"Temperatur reservoir yang tinggi";i:1;s:27:"Keberadaan oksigen terlarut";}','What factors cause thermal degradation of HPAM polymers in the reservoir?','a:4:{i:0;s:26:"High reservoir temperature";i:1;s:28:"Presence of dissolved oxygen";i:2;s:18:"Low injection rate";i:3;s:23:"High capillary pressure";}','a:2:{i:0;s:26:"High reservoir temperature";i:1;s:28:"Presence of dissolved oxygen";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000252','Apa keunggulan utama Xanthan gum dibandingkan dengan HPAM dalam aplikasi lapangan?','option','PFM000000051','a:4:{i:0;s:62:"Tahan terhadap degradasi salinitas dan ion divalen yang tinggi";i:1;s:57:"Harga yang jauh lebih murah dibandingkan sintetik polimer";i:2;s:81:"Viskositas yang tetap stabil meskipun pada temperatur di atas 150 derajat Celcius";i:3;s:64:"Kemampuan untuk berikatan silang secara spontan tanpa agen kimia";}','','Tahan terhadap degradasi salinitas dan ion divalen yang tinggi','What is the main advantage of Xanthan gum compared to HPAM in field applications?','a:4:{i:0;s:71:"Resistant to degradation in high salinity and divalent ion environments";i:1;s:45:"Significantly cheaper than synthetic polymers";i:2;s:71:"Viscosity remains stable even at temperatures above 150 degrees Celsius";i:3;s:58:"Ability to crosslink spontaneously without chemical agents";}','Resistant to degradation in high salinity and divalent ion environments','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000253','Proses hidrolisis pada polimer HPAM melibatkan perubahan gugus fungsi kimia yang berdampak pada sifat kelarutan dan sensitivitas ion. Gugus fungsi apa yang terbentuk?','option','PFM000000051','a:4:{i:0;s:24:"Gugus karboksilat (COO-)";i:1;s:20:"Gugus hidroksil (OH)";i:2;s:17:"Gugus amina (NH2)";i:3;s:18:"Gugus eter (R-O-R)";}','','Gugus karboksilat (COO-)','The hydrolysis process of HPAM polymers involves changes in chemical functional groups that impact solubility and ion sensitivity. What functional group is formed?','a:4:{i:0;s:24:"Carboxylate group (COO-)";i:1;s:19:"Hydroxyl group (OH)";i:2;s:17:"Amine group (NH2)";i:3;s:19:"Ether group (R-O-R)";}','Carboxylate group (COO-)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000254','Dalam konteks rheologi, bagaimana hubungan antara konsentrasi polimer dan viskositas larutan dalam kondisi Newtonian?','option','PFM000000051','a:4:{i:0;s:81:"Viskositas meningkat secara eksponensial seiring bertambahnya konsentrasi polimer";i:1;s:57:"Viskositas berbanding terbalik dengan konsentrasi polimer";i:2;s:71:"Viskositas tetap konstan berapapun konsentrasi polimer yang ditambahkan";i:3;s:62:"Viskositas hanya dipengaruhi oleh laju alir, bukan konsentrasi";}','','Viskositas meningkat secara eksponensial seiring bertambahnya konsentrasi polimer','In the context of rheology, what is the relationship between polymer concentration and solution viscosity under Newtonian conditions?','a:4:{i:0;s:68:"Viscosity increases exponentially as polymer concentration increases";i:1;s:60:"Viscosity is inversely proportional to polymer concentration";i:2;s:72:"Viscosity remains constant regardless of the added polymer concentration";i:3;s:58:"Viscosity is only affected by flow rate, not concentration";}','Viscosity increases exponentially as polymer concentration increases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000255','Fenomena di mana viskositas larutan polimer menurun seiring dengan meningkatnya laju geser (shear rate) pada media berpori disebut sebagai','option','PFM000000052','a:4:{i:0;s:14:"Shear thinning";i:1;s:16:"Shear thickening";i:2;s:16:"Degradasi termal";i:3;s:26:"Residual Resistance Factor";}','','Shear thinning','The phenomenon where the viscosity of a polymer solution decreases as the shear rate increases in porous media is known as','a:4:{i:0;s:14:"Shear thinning";i:1;s:16:"Shear thickening";i:2;s:19:"Thermal degradation";i:3;s:26:"Residual Resistance Factor";}','Shear thinning','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000256','Faktor-faktor utama yang dapat menyebabkan degradasi polimer di dalam reservoir adalah','multi','PFM000000052','a:4:{i:0;s:14:"Oksidasi kimia";i:1;s:17:"Aktivitas mikroba";i:2;s:28:"Laju alir yang sangat rendah";i:3;s:15:"Tekanan kapiler";}','','a:2:{i:0;s:14:"Oksidasi kimia";i:1;s:17:"Aktivitas mikroba";}','The main factors that can cause polymer degradation within a reservoir are','a:4:{i:0;s:18:"Chemical oxidation";i:1;s:18:"Microbial activity";i:2;s:23:"Extremely low flow rate";i:3;s:18:"Capillary pressure";}','a:2:{i:0;s:18:"Chemical oxidation";i:1;s:18:"Microbial activity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000257','Apa yang dimaksud dengan Residual Resistance Factor (RRF) dalam konteks injeksi polimer?','option','PFM000000052','a:4:{i:0;s:62:"Perbandingan mobilitas air sebelum dan sesudah injeksi polimer";i:1;s:54:"Penurunan permeabilitas batuan akibat adsorpsi polimer";i:2;s:38:"Viskositas polimer pada shear rate nol";i:3;s:50:"Laju degradasi mekanik polimer di dekat lubang bor";}','','Penurunan permeabilitas batuan akibat adsorpsi polimer','What is meant by the Residual Resistance Factor (RRF) in the context of polymer flooding?','a:4:{i:0;s:58:"Ratio of water mobility before and after polymer injection";i:1;s:56:"Reduction in rock permeability due to polymer adsorption";i:2;s:36:"Polymer viscosity at zero shear rate";i:3;s:56:"Mechanical degradation rate of polymer near the wellbore";}','Reduction in rock permeability due to polymer adsorption','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000258','Degradasi mekanik pada polimer biasanya terjadi di area dengan laju geser yang sangat tinggi, yaitu pada','option','PFM000000052','a:4:{i:0;s:35:"Zona reservoir jauh dari lubang bor";i:1;s:33:"Area sekitar perforasi lubang bor";i:2;s:25:"Zona saturasi minyak sisa";i:3;s:32:"Tingkat tekanan reservoir statis";}','','Area sekitar perforasi lubang bor','Mechanical degradation of polymers typically occurs in areas with very high shear rates, specifically at','a:4:{i:0;s:37:"Reservoir zones far from the wellbore";i:1;s:36:"Area around the wellbore perforation";i:2;s:28:"Residual oil saturation zone";i:3;s:32:"Static reservoir pressure levels";}','Area around the wellbore perforation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000259','Viskositas polimer yang terukur di dalam media berpori dikenal sebagai','option','PFM000000052','a:4:{i:0;s:18:"Apparent viscosity";i:1;s:14:"Bulk viscosity";i:2;s:19:"Intrinsic viscosity";i:3;s:18:"Relative viscosity";}','','Apparent viscosity','The viscosity of a polymer measured within porous media is known as','a:4:{i:0;s:18:"Apparent viscosity";i:1;s:14:"Bulk viscosity";i:2;s:19:"Intrinsic viscosity";i:3;s:18:"Relative viscosity";}','Apparent viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000260','Manakah parameter utama yang paling memengaruhi viskositas larutan polimer HPAM di dalam reservoir?','option','PFM000000053','a:4:{i:0;s:21:"Salinitas air formasi";i:1;s:16:"Porositas batuan";i:2;s:15:"Tekanan injeksi";i:3;s:13:"Kelarutan gas";}','','Salinitas air formasi','Which main parameter most significantly affects the viscosity of HPAM polymer solution within the reservoir?','a:4:{i:0;s:24:"Formation water salinity";i:1;s:13:"Rock porosity";i:2;s:18:"Injection pressure";i:3;s:14:"Gas solubility";}','Formation water salinity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000261','Faktor apa saja yang harus dipertimbangkan dalam menentukan ukuran slug polimer (dalam PV) agar efisien secara teknis dan ekonomis?','multi','PFM000000053','a:4:{i:0;s:38:"Adsorpsi polimer pada permukaan batuan";i:1;s:22:"Mobilisasi minyak sisa";i:2;s:29:"Biaya operasional bahan kimia";i:3;s:23:"Laju aliran injeksi air";}','','a:2:{i:0;s:38:"Adsorpsi polimer pada permukaan batuan";i:1;s:29:"Biaya operasional bahan kimia";}','What factors must be considered in determining the polymer slug size (in PV) to be technically and economically efficient?','a:4:{i:0;s:35:"Polymer adsorption on rock surfaces";i:1;s:25:"Residual oil mobilization";i:2;s:26:"Chemical operational costs";i:3;s:20:"Water injection rate";}','a:2:{i:0;s:35:"Polymer adsorption on rock surfaces";i:1;s:26:"Chemical operational costs";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000262','Bagaimana pengaruh peningkatan salinitas air injeksi terhadap efektivitas polimer tipe HPAM?','option','PFM000000053','a:4:{i:0;s:44:"Viskositas polimer menurun secara signifikan";i:1;s:36:"Viskositas polimer meningkat drastis";i:2;s:28:"Adsorpsi polimer menjadi nol";i:3;s:34:"Tidak ada pengaruh pada viskositas";}','','Viskositas polimer menurun secara signifikan','How does the increase in injection water salinity affect the effectiveness of HPAM type polymers?','a:4:{i:0;s:41:"Polymer viscosity decreases significantly";i:1;s:39:"Polymer viscosity increases drastically";i:2;s:31:"Polymer adsorption becomes zero";i:3;s:31:"There is no effect on viscosity";}','Polymer viscosity decreases significantly','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000263','Dalam desain injeksi polimer, apa dampak dari laju injeksi yang terlalu tinggi terhadap performa polimer di dekat lubang sumur?','option','PFM000000053','a:4:{i:0;s:68:"Terjadinya degradasi mekanis (shear degradation) pada rantai polimer";i:1;s:51:"Meningkatnya efisiensi penyapuan (sweep efficiency)";i:2;s:39:"Menurunnya tekanan injeksi di permukaan";i:3;s:44:"Memperbaiki mobilitas minyak secara permanen";}','','Terjadinya degradasi mekanis (shear degradation) pada rantai polimer','In polymer injection design, what is the impact of an excessively high injection rate on polymer performance near the wellbore?','a:4:{i:0;s:46:"Mechanical shear degradation of polymer chains";i:1;s:26:"Increased sweep efficiency";i:2;s:36:"Decreased surface injection pressure";i:3;s:37:"Permanent improvement in oil mobility";}','Mechanical shear degradation of polymer chains','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000264','Tujuan utama optimasi konsentrasi polimer dalam desain CEOR adalah untuk mencapai:','option','PFM000000053','a:4:{i:0;s:68:"Rasio mobilitas air-minyak yang mendekati atau lebih kecil dari satu";i:1;s:47:"Peningkatan permeabilitas batuan secara drastis";i:2;s:36:"Penurunan tekanan kapiler hingga nol";i:3;s:58:"Peningkatan saturasi air yang seragam di seluruh reservoir";}','','Rasio mobilitas air-minyak yang mendekati atau lebih kecil dari satu','The main goal of polymer concentration optimization in CEOR design is to achieve:','a:4:{i:0;s:55:"Water-oil mobility ratio approaching or less than unity";i:1;s:37:"Drastic increase in rock permeability";i:2;s:39:"Reduction of capillary pressure to zero";i:3;s:61:"Uniform increase in water saturation throughout the reservoir";}','Water-oil mobility ratio approaching or less than unity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000265','Komponen utama dalam fasilitas permukaan (polymer plant) yang berfungsi untuk melarutkan polimer bubuk ke dalam air injeksi secara kontinu adalah','option','PFM000000054','a:4:{i:0;s:22:"Polymer hydration unit";i:1;s:20:"Production separator";i:2;s:14:"Gas compressor";i:3;s:12:"Water heater";}','','Polymer hydration unit','The main component in surface facilities (polymer plant) that functions to continuously dissolve powder polymer into injection water is','a:4:{i:0;s:22:"Polymer hydration unit";i:1;s:20:"Production separator";i:2;s:14:"Gas compressor";i:3;s:12:"Water heater";}','Polymer hydration unit','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000266','Parameter utama yang harus dimonitor secara berkala selama injeksi polimer untuk memastikan efisiensi mobilitas adalah','multi','PFM000000054','a:4:{i:0;s:26:"Viskositas larutan polimer";i:1;s:15:"Tekanan injeksi";i:2;s:20:"Saturasi minyak sisa";i:3;s:37:"Konsentrasi polimer di sumur produksi";}','','a:3:{i:0;s:26:"Viskositas larutan polimer";i:1;s:15:"Tekanan injeksi";i:2;s:37:"Konsentrasi polimer di sumur produksi";}','The main parameters that must be monitored periodically during polymer injection to ensure mobility efficiency are','a:4:{i:0;s:26:"Polymer solution viscosity";i:1;s:18:"Injection pressure";i:2;s:23:"Residual oil saturation";i:3;s:41:"Polymer concentration at production wells";}','a:3:{i:0;s:26:"Polymer solution viscosity";i:1;s:18:"Injection pressure";i:2;s:41:"Polymer concentration at production wells";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000267','Salah satu alasan utama kegagalan injeksi polimer di lapangan yang memiliki suhu reservoir tinggi adalah','option','PFM000000054','a:4:{i:0;s:32:"Degradasi termal molekul polimer";i:1;s:24:"Peningkatan saturasi air";i:2;s:26:"Penurunan porositas batuan";i:3;s:32:"Terlalu rendahnya pH air injeksi";}','','Degradasi termal molekul polimer','One of the main reasons for polymer injection failure in reservoirs with high temperatures is','a:4:{i:0;s:40:"Thermal degradation of polymer molecules";i:1;s:28:"Increase in water saturation";i:2;s:25:"Decrease in rock porosity";i:3;s:34:"Excessively low injection water pH";}','Thermal degradation of polymer molecules','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000268','Indikator keberhasilan (performance evaluation) dari proyek polymer flooding yang paling umum digunakan adalah','option','PFM000000054','a:4:{i:0;s:32:"Penurunan rasio air-minyak (WOR)";i:1;s:29:"Peningkatan biaya operasional";i:2;s:33:"Peningkatan permeabilitas absolut";i:3;s:25:"Penurunan densitas minyak";}','','Penurunan rasio air-minyak (WOR)','The most common indicator of success (performance evaluation) for a polymer flooding project is','a:4:{i:0;s:33:"Decrease in water-oil ratio (WOR)";i:1;s:29:"Increase in operational costs";i:2;s:33:"Increase in absolute permeability";i:3;s:23:"Decrease in oil density";}','Decrease in water-oil ratio (WOR)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000269','Apa dampak utama dari injeksi polimer terhadap mobilitas fluida di dalam reservoir?','option','PFM000000054','a:4:{i:0;s:24:"Menurunkan mobilitas air";i:1;s:29:"Meningkatkan mobilitas minyak";i:2;s:39:"Menurunkan permeabilitas relatif minyak";i:3;s:26:"Menghilangkan gaya kapiler";}','','Menurunkan mobilitas air','What is the main impact of polymer injection on fluid mobility within the reservoir?','a:4:{i:0;s:25:"Decreasing water mobility";i:1;s:23:"Increasing oil mobility";i:2;s:36:"Decreasing oil relative permeability";i:3;s:28:"Eliminating capillary forces";}','Decreasing water mobility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000270','Apa fungsi utama penambahan surfaktan dalam proses Chemical Enhanced Oil Recovery (CEOR)?','option','PFM000000055','a:4:{i:0;s:57:"Menurunkan tegangan antarmuka (IFT) antara minyak dan air";i:1;s:53:"Meningkatkan viskositas air injeksi secara signifikan";i:2;s:61:"Mengubah wettability batuan menjadi water-wet secara permanen";i:3;s:61:"Menambah tekanan reservoir agar minyak terdesak ke lubang bor";}','','Menurunkan tegangan antarmuka (IFT) antara minyak dan air','What is the main function of adding surfactants in the Chemical Enhanced Oil Recovery (CEOR) process?','a:4:{i:0;s:60:"Reducing the interfacial tension (IFT) between oil and water";i:1;s:60:"Significantly increasing the viscosity of the injected water";i:2;s:50:"Permanently changing rock wettability to water-wet";i:3;s:59:"Increasing reservoir pressure to push oil into the wellbore";}','Reducing the interfacial tension (IFT) between oil and water','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000271','Berapa nilai tegangan antarmuka (IFT) yang dikategorikan sebagai ultralow yang efektif untuk memobilisasi minyak terperangkap?','option','PFM000000055','a:4:{i:0;s:24:"Lebih besar dari 10 mN/m";i:1;s:27:"Antara 1 mN/m sampai 5 mN/m";i:2;s:22:"Kurang dari 10^-2 mN/m";i:3;s:17:"Tepat pada 1 mN/m";}','','Kurang dari 10^-2 mN/m','What is the interfacial tension (IFT) value categorized as ultralow that is effective for mobilizing trapped oil?','a:4:{i:0;s:20:"Greater than 10 mN/m";i:1;s:25:"Between 1 mN/m and 5 mN/m";i:2;s:20:"Less than 10^-2 mN/m";i:3;s:17:"Exactly at 1 mN/m";}','Less than 10^-2 mN/m','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000272','Faktor apa saja yang dipengaruhi secara langsung oleh peningkatan capillary number (Nc) dalam surfactant flooding?','multi','PFM000000055','a:4:{i:0;s:27:"Peningkatan recovery factor";i:1;s:29:"Peningkatan viskositas minyak";i:2;s:50:"Mobilisasi minyak yang terperangkap (residual oil)";i:3;s:26:"Penurunan laju alir fluida";}','','a:2:{i:0;s:27:"Peningkatan recovery factor";i:1;s:50:"Mobilisasi minyak yang terperangkap (residual oil)";}','Which factors are directly influenced by the increase of capillary number (Nc) in surfactant flooding?','a:4:{i:0;s:27:"Increase in recovery factor";i:1;s:25:"Increase in oil viscosity";i:2;s:36:"Mobilization of trapped residual oil";i:3;s:27:"Decrease in fluid flow rate";}','a:2:{i:0;s:27:"Increase in recovery factor";i:1;s:36:"Mobilization of trapped residual oil";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000273','Bagaimana hubungan antara capillary number (Nc) dan recovery factor dalam reservoir?','option','PFM000000055','a:4:{i:0;s:69:"Berbanding terbalik, semakin tinggi Nc semakin rendah recovery factor";i:1;s:35:"Tidak memiliki hubungan sama sekali";i:2;s:74:"Berbanding lurus, semakin tinggi Nc semakin tinggi potensi recovery factor";i:3;s:57:"Recovery factor hanya bergantung pada porositas, bukan Nc";}','','Berbanding lurus, semakin tinggi Nc semakin tinggi potensi recovery factor','What is the relationship between capillary number (Nc) and recovery factor in a reservoir?','a:4:{i:0;s:64:"Inversely proportional, higher Nc leads to lower recovery factor";i:1;s:31:"There is no relationship at all";i:2;s:74:"Directly proportional, higher Nc leads to higher potential recovery factor";i:3;s:48:"Recovery factor depends only on porosity, not Nc";}','Directly proportional, higher Nc leads to higher potential recovery factor','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000274','Apa mekanisme fisik utama surfaktan dalam mendesorpsi minyak dari permukaan batuan?','option','PFM000000055','a:4:{i:0;s:27:"Melarutkan batuan reservoir";i:1;s:57:"Menurunkan gaya adhesi antara minyak dan permukaan batuan";i:2;s:32:"Menambah ukuran pori-pori batuan";i:3;s:44:"Membekukan minyak agar lebih mudah terdorong";}','','Menurunkan gaya adhesi antara minyak dan permukaan batuan','What is the main physical mechanism of surfactants in desorbing oil from rock surfaces?','a:4:{i:0;s:25:"Dissolving reservoir rock";i:1;s:57:"Reducing the adhesive force between oil and rock surfaces";i:2;s:29:"Increasing the rock pore size";i:3;s:42:"Freezing the oil to make it easier to push";}','Reducing the adhesive force between oil and rock surfaces','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000275','Jenis surfaktan manakah yang paling sering digunakan dalam aplikasi EOR karena ketahanannya terhadap adsorpsi pada batuan reservoir yang bermuatan negatif?','option','PFM000000056','a:4:{i:0;s:17:"Surfaktan anionik";i:1;s:18:"Surfaktan kationik";i:2;s:18:"Surfaktan nonionik";i:3;s:17:"Surfaktan amfoter";}','','Surfaktan anionik','Which type of surfactant is most commonly used in EOR applications due to its resistance to adsorption on negatively charged reservoir rocks?','a:4:{i:0;s:19:"Anionic surfactants";i:1;s:20:"Cationic surfactants";i:2;s:20:"Nonionic surfactants";i:3;s:22:"Amphoteric surfactants";}','Anionic surfactants','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000276','Dalam klasifikasi perilaku fase Winsor, tipe manakah yang menunjukkan sistem mikroemulsi dengan tegangan antar muka (IFT) yang sangat rendah?','option','PFM000000056','a:4:{i:0;s:8:"Winsor I";i:1;s:9:"Winsor II";i:2;s:10:"Winsor III";i:3;s:9:"Winsor IV";}','','Winsor III','In the Winsor phase behavior classification, which type indicates a microemulsion system with ultra-low interfacial tension (IFT)?','a:4:{i:0;s:8:"Winsor I";i:1;s:9:"Winsor II";i:2;s:10:"Winsor III";i:3;s:9:"Winsor IV";}','Winsor III','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000277','Faktor apa saja yang mempengaruhi solubilization ratio dalam sistem surfaktan-minyak-air?','multi','PFM000000056','a:4:{i:0;s:19:"Salinitas reservoir";i:1;s:15:"Jenis surfaktan";i:2;s:22:"Viskositas air injeksi";i:3;s:20:"Temperatur reservoir";}','','a:3:{i:0;s:19:"Salinitas reservoir";i:1;s:15:"Jenis surfaktan";i:2;s:20:"Temperatur reservoir";}','What factors influence the solubilization ratio in a surfactant-oil-water system?','a:4:{i:0;s:18:"Reservoir salinity";i:1;s:15:"Surfactant type";i:2;s:25:"Injection water viscosity";i:3;s:21:"Reservoir temperature";}','a:3:{i:0;s:18:"Reservoir salinity";i:1;s:15:"Surfactant type";i:2;s:21:"Reservoir temperature";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000278','Apa yang terjadi jika salinitas sistem surfaktan berada di atas salinitas optimal dalam konteks perilaku fase?','option','PFM000000056','a:4:{i:0;s:44:"Sistem membentuk fase mikroemulsi Winsor III";i:1;s:50:"Sistem cenderung membentuk perilaku fase Winsor II";i:2;s:49:"Sistem cenderung membentuk perilaku fase Winsor I";i:3;s:50:"Tegangan antar muka mencapai titik minimum absolut";}','','Sistem cenderung membentuk perilaku fase Winsor II','What happens if the salinity of a surfactant system is above the optimal salinity in the context of phase behavior?','a:4:{i:0;s:49:"The system forms a Winsor III microemulsion phase";i:1;s:49:"The system tends to form Winsor II phase behavior";i:2;s:48:"The system tends to form Winsor I phase behavior";i:3;s:47:"Interfacial tension reaches an absolute minimum";}','The system tends to form Winsor II phase behavior','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000279','Mengapa surfaktan nonionik sering ditambahkan ke dalam formulasi surfaktan anionik dalam kondisi salinitas tinggi?','option','PFM000000056','a:4:{i:0;s:37:"Untuk meningkatkan viskositas larutan";i:1;s:49:"Untuk meningkatkan adsorpsi surfaktan pada batuan";i:2;s:64:"Untuk meningkatkan toleransi terhadap salinitas dan divalent ion";i:3;s:47:"Untuk mempercepat laju korosi peralatan injeksi";}','','Untuk meningkatkan toleransi terhadap salinitas dan divalent ion','Why are nonionic surfactants often added to anionic surfactant formulations in high salinity conditions?','a:4:{i:0;s:41:"To increase the viscosity of the solution";i:1;s:45:"To increase surfactant adsorption on the rock";i:2;s:51:"To increase tolerance to salinity and divalent ions";i:3;s:55:"To accelerate the corrosion rate of injection equipment";}','To increase tolerance to salinity and divalent ions','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000280','Apa fungsi utama penambahan agen alkali seperti NaOH atau Na2CO3 dalam proses Alkaline Flooding?','option','PFM000000057','a:4:{i:0;s:70:"Menurunkan Interfacial Tension (IFT) melalui pembentukan sabun in-situ";i:1;s:50:"Meningkatkan viskositas air injeksi secara drastis";i:2;s:44:"Menutup pori-pori batuan agar fluida terarah";i:3;s:65:"Mengurangi tekanan injeksi tanpa mempengaruhi tegangan antar muka";}','','Menurunkan Interfacial Tension (IFT) melalui pembentukan sabun in-situ','What is the primary function of adding alkaline agents such as NaOH or Na2CO3 in the Alkaline Flooding process?','a:4:{i:0;s:65:"Reducing Interfacial Tension (IFT) through in-situ soap formation";i:1;s:48:"Increasing injection water viscosity drastically";i:2;s:40:"Blocking rock pores to direct fluid flow";i:3;s:65:"Reducing injection pressure without affecting interfacial tension";}','Reducing Interfacial Tension (IFT) through in-situ soap formation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000281','Reaksi kimia antara alkali dengan asam organik (asam naphthenic) yang terkandung dalam minyak mentah disebut sebagai proses?','option','PFM000000057','a:4:{i:0;s:12:"Saponifikasi";i:1;s:11:"Hidrogenasi";i:2;s:12:"Polimerisasi";i:3;s:8:"Oksidasi";}','','Saponifikasi','The chemical reaction between an alkali and organic acids (naphthenic acids) contained in crude oil is called?','a:4:{i:0;s:14:"Saponification";i:1;s:13:"Hydrogenation";i:2;s:14:"Polymerization";i:3;s:9:"Oxidation";}','Saponification','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000282','Manakah dari mekanisme berikut yang terjadi akibat interaksi antara alkali dengan permukaan batuan (wettability alteration)?','multi','PFM000000057','a:4:{i:0;s:51:"Minyak menjadi kurang melekat pada permukaan batuan";i:1;s:30:"Batuan menjadi lebih water-wet";i:2;s:47:"Meningkatkan nilai permeabilitas absolut batuan";i:3;s:31:"Mengubah batuan menjadi oil-wet";}','','a:2:{i:0;s:51:"Minyak menjadi kurang melekat pada permukaan batuan";i:1;s:30:"Batuan menjadi lebih water-wet";}','Which of the following mechanisms occurs due to the interaction between alkali and rock surfaces (wettability alteration)?','a:4:{i:0;s:44:"Oil becomes less adhered to the rock surface";i:1;s:27:"Rock becomes more water-wet";i:2;s:37:"Increasing rock absolute permeability";i:3;s:24:"Turning the rock oil-wet";}','a:2:{i:0;s:44:"Oil becomes less adhered to the rock surface";i:1;s:27:"Rock becomes more water-wet";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000283','Apa dampak negatif utama yang harus dipertimbangkan terkait konsumsi alkali oleh mineral batuan reservoir?','option','PFM000000057','a:4:{i:0;s:66:"Hilangnya efektivitas alkali karena bereaksi dengan mineral batuan";i:1;s:36:"Peningkatan viskositas minyak mentah";i:2;s:42:"Terjadinya ekspansi batuan yang signifikan";i:3;s:40:"Penurunan pH air injeksi secara otomatis";}','','Hilangnya efektivitas alkali karena bereaksi dengan mineral batuan','What is the primary negative impact to be considered regarding alkali consumption by reservoir rock minerals?','a:4:{i:0;s:63:"Loss of alkali effectiveness due to reaction with rock minerals";i:1;s:31:"Increase in crude oil viscosity";i:2;s:26:"Significant rock expansion";i:3;s:40:"Automatic decrease in injection water pH";}','Loss of alkali effectiveness due to reaction with rock minerals','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000284','Alkali yang sering digunakan dalam proses Chemical EOR karena sifatnya yang efektif dalam membentuk surfaktan alami adalah?','option','PFM000000057','a:4:{i:0;s:25:"Natrium Hidroksida (NaOH)";i:1;s:23:"Kalsium Klorida (CaCl2)";i:2;s:24:"Magnesium Sulfat (MgSO4)";i:3;s:22:"Natrium Klorida (NaCl)";}','','Natrium Hidroksida (NaOH)','Which alkali is frequently used in Chemical EOR processes due to its effectiveness in forming natural surfactants?','a:4:{i:0;s:23:"Sodium Hydroxide (NaOH)";i:1;s:24:"Calcium Chloride (CaCl2)";i:2;s:25:"Magnesium Sulfate (MgSO4)";i:3;s:22:"Sodium Chloride (NaCl)";}','Sodium Hydroxide (NaOH)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000285','Apa fungsi utama dari penambahan komponen Alkaline dalam proses ASP flooding?','option','PFM000000058','a:4:{i:0;s:58:"Mengurangi tegangan antar muka (IFT) menjadi sangat rendah";i:1;s:51:"Mengurangi adsorpsi surfaktan pada permukaan batuan";i:2;s:38:"Meningkatkan viskositas fluida injeksi";i:3;s:43:"Mencegah terjadinya emulsi minyak dalam air";}','','Mengurangi adsorpsi surfaktan pada permukaan batuan','What is the primary function of adding the Alkaline component in the ASP flooding process?','a:4:{i:0;s:54:"Reducing Interfacial Tension (IFT) to ultra-low levels";i:1;s:52:"Reducing surfactant adsorption onto the rock surface";i:2;s:36:"Increasing injection fluid viscosity";i:3;s:32:"Preventing oil-in-water emulsion";}','Reducing surfactant adsorption onto the rock surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000286','Parameter apa saja yang sangat dipengaruhi oleh perubahan salinitas sistem dalam formulasi ASP?','multi','PFM000000058','a:4:{i:0;s:25:"Tegangan antar muka (IFT)";i:1;s:19:"Kelarutan surfaktan";i:2;s:16:"Porositas batuan";i:3;s:17:"Viskositas batuan";}','','a:2:{i:0;s:25:"Tegangan antar muka (IFT)";i:1;s:19:"Kelarutan surfaktan";}','Which parameters are significantly affected by changes in system salinity in ASP formulations?','a:4:{i:0;s:25:"Interfacial Tension (IFT)";i:1;s:21:"Surfactant solubility";i:2;s:13:"Rock porosity";i:3;s:14:"Rock viscosity";}','a:2:{i:0;s:25:"Interfacial Tension (IFT)";i:1;s:21:"Surfactant solubility";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000287','Apa peran utama polimer dalam formulasi ASP flooding pada reservoir?','option','PFM000000058','a:4:{i:0;s:26:"Menetralkan pH air formasi";i:1;s:41:"Mengurangi IFT hingga di bawah 10^-3 mN/m";i:2;s:65:"Mengontrol mobilitas fluida untuk memperbaiki efisiensi penyapuan";i:3;s:39:"Melarutkan mineral karbonat pada batuan";}','','Mengontrol mobilitas fluida untuk memperbaiki efisiensi penyapuan','What is the primary role of polymer in the ASP flooding formulation in reservoirs?','a:4:{i:0;s:31:"Neutralizing formation water pH";i:1;s:32:"Reducing IFT to below 10^-3 mN/m";i:2;s:54:"Controlling fluid mobility to improve sweep efficiency";i:3;s:41:"Dissolving carbonate minerals in the rock";}','Controlling fluid mobility to improve sweep efficiency','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000288','Fenomena hilangnya surfaktan ke dalam matriks batuan selama proses injeksi disebut dengan istilah?','option','PFM000000058','a:4:{i:0;s:21:"Retensi atau adsorpsi";i:1;s:16:"Inhibisi kapiler";i:2;s:16:"Degradasi termal";i:3;s:20:"Emulsifikasi spontan";}','','Retensi atau adsorpsi','The phenomenon of surfactant loss into the rock matrix during the injection process is called?','a:4:{i:0;s:23:"Retention or adsorption";i:1;s:20:"Capillary inhibition";i:2;s:19:"Thermal degradation";i:3;s:26:"Spontaneous emulsification";}','Retention or adsorption','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000289','Kondisi optimal salinitas dalam desain ASP biasanya dicapai ketika sistem membentuk tipe emulsi apa?','option','PFM000000058','a:4:{i:0;s:34:"Emulsi minyak dalam air (Winsor I)";i:1;s:35:"Emulsi air dalam minyak (Winsor II)";i:2;s:36:"Mikroemulsi bicontinuos (Winsor III)";i:3;s:31:"Emulsi fase tunggal (Winsor IV)";}','','Mikroemulsi bicontinuos (Winsor III)','The optimal salinity condition in ASP design is usually achieved when the system forms which type of emulsion?','a:4:{i:0;s:32:"Oil-in-water emulsion (Winsor I)";i:1;s:33:"Water-in-oil emulsion (Winsor II)";i:2;s:39:"Bicontinuous microemulsion (Winsor III)";i:3;s:33:"Single-phase emulsion (Winsor IV)";}','Bicontinuous microemulsion (Winsor III)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000290','Apa tujuan utama pelaksanaan proyek pilot Chemical EOR sebelum melangkah ke implementasi full field?','option','PFM000000059','a:4:{i:0;s:50:"Mengurangi biaya modal total proyek secara drastis";i:1;s:78:"Memvalidasi kinerja teknis dan efisiensi kimia di kondisi reservoir sebenarnya";i:2;s:59:"Menghilangkan kebutuhan akan studi laboratorium fundamental";i:3;s:57:"Meningkatkan permeabilitas absolut batuan secara permanen";}','','Memvalidasi kinerja teknis dan efisiensi kimia di kondisi reservoir sebenarnya','What is the primary objective of conducting a Chemical EOR pilot project before full field implementation?','a:4:{i:0;s:52:"Drastically reduce total project capital expenditure";i:1;s:88:"Validate technical performance and chemical efficiency under actual reservoir conditions";i:2;s:53:"Eliminate the need for fundamental laboratory studies";i:3;s:47:"Permanently increase absolute rock permeability";}','Validate technical performance and chemical efficiency under actual reservoir conditions','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000291','Manakah di antara berikut yang merupakan kendala teknis utama dalam implementasi injeksi kimia di lapangan?','multi','PFM000000059','a:4:{i:0;s:40:"Adsorpsi surfaktan pada permukaan batuan";i:1;s:58:"Terbentuknya kerak (scaling) akibat ketidakcocokan kimiawi";i:2;s:70:"Peningkatan tajam pada viskositas air formasi tanpa penambahan polimer";i:3;s:53:"Pembentukan emulsi yang sulit dipisahkan di permukaan";}','','a:3:{i:0;s:40:"Adsorpsi surfaktan pada permukaan batuan";i:1;s:58:"Terbentuknya kerak (scaling) akibat ketidakcocokan kimiawi";i:2;s:53:"Pembentukan emulsi yang sulit dipisahkan di permukaan";}','Which of the following are major technical challenges in field-scale chemical injection implementation?','a:4:{i:0;s:38:"Surfactant adsorption on rock surfaces";i:1;s:47:"Scale formation due to chemical incompatibility";i:2;s:68:"Sharp increase in formation water viscosity without polymer addition";i:3;s:68:"Formation of emulsions that are difficult to separate at the surface";}','a:3:{i:0;s:38:"Surfactant adsorption on rock surfaces";i:1;s:47:"Scale formation due to chemical incompatibility";i:2;s:68:"Formation of emulsions that are difficult to separate at the surface";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000292','Dalam sistem injeksi ASP (Alkaline-Surfactant-Polymer), apa peran utama dari komponen Alkaline?','option','PFM000000059','a:4:{i:0;s:39:"Meningkatkan viskositas larutan injeksi";i:1;s:48:"Mengurangi tegangan antar muka hingga nol mutlak";i:2;s:80:"Mengurangi adsorpsi surfaktan dan membentuk sabun in-situ dengan asam naphthenic";i:3;s:59:"Menurunkan permeabilitas batuan agar penyapuan lebih merata";}','','Mengurangi adsorpsi surfaktan dan membentuk sabun in-situ dengan asam naphthenic','In an ASP (Alkaline-Surfactant-Polymer) injection system, what is the primary role of the Alkaline component?','a:4:{i:0;s:48:"Increase the viscosity of the injection solution";i:1;s:43:"Reduce interfacial tension to absolute zero";i:2;s:73:"Reduce surfactant adsorption and form in-situ soaps with naphthenic acids";i:3;s:60:"Decrease rock permeability for more uniform sweep efficiency";}','Reduce surfactant adsorption and form in-situ soaps with naphthenic acids','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000293','Faktor apa yang paling menentukan keberhasilan perpindahan dari skala pilot ke skala full field pada proyek Chemical EOR?','option','PFM000000059','a:4:{i:0;s:54:"Penggantian seluruh pompa injeksi dengan model terbaru";i:1;s:77:"Ketersediaan pasokan bahan kimia dalam jumlah besar dengan kualitas konsisten";i:2;s:51:"Penghentian total produksi dari sumur-sumur sekitar";i:3;s:41:"Penggunaan air laut tanpa proses filtrasi";}','','Ketersediaan pasokan bahan kimia dalam jumlah besar dengan kualitas konsisten','What factor is most critical for the successful transition from pilot scale to full field scale in a Chemical EOR project?','a:4:{i:0;s:52:"Replacing all injection pumps with the latest models";i:1;s:67:"Availability of large-scale chemical supply with consistent quality";i:2;s:55:"Complete cessation of production from surrounding wells";i:3;s:52:"Utilization of seawater without filtration processes";}','Availability of large-scale chemical supply with consistent quality','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000294','Mengapa kontrol kualitas (quality control) terhadap konsentrasi kimia sangat penting dalam operasi Chemical EOR di lapangan?','option','PFM000000059','a:4:{i:0;s:44:"Untuk memastikan pH air formasi tetap rendah";i:1;s:80:"Untuk menjaga efektivitas penurunan IFT (Interfacial Tension) agar tetap optimal";i:2;s:64:"Agar tekanan injeksi selalu berada di atas tekanan rekah formasi";i:3;s:51:"Untuk mempercepat laju korosi pada pipa baja karbon";}','','Untuk menjaga efektivitas penurunan IFT (Interfacial Tension) agar tetap optimal','Why is quality control of chemical concentrations crucial during field Chemical EOR operations?','a:4:{i:0;s:40:"To ensure formation water pH remains low";i:1;s:69:"To maintain optimal IFT (Interfacial Tension) reduction effectiveness";i:2;s:67:"To keep injection pressure always above formation fracture pressure";i:3;s:55:"To accelerate corrosion rates on carbon steel pipelines";}','To maintain optimal IFT (Interfacial Tension) reduction effectiveness','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000295','Manakah komponen biaya yang dikategorikan sebagai biaya operasional (OPEX) utama dalam implementasi proyek Chemical EOR?','option','PFM000000060','a:4:{i:0;s:43:"Pembelian bahan kimia surfaktan dan polimer";i:1;s:60:"Pembangunan fasilitas pengolahan air (water treatment plant)";i:2;s:29:"Pengeboran sumur injeksi baru";i:3;s:31:"Pemasangan pipa transmisi utama";}','','Pembelian bahan kimia surfaktan dan polimer','Which cost component is classified as a major operational expenditure (OPEX) in Chemical EOR project implementation?','a:4:{i:0;s:44:"Purchase of surfactant and polymer chemicals";i:1;s:48:"Construction of water treatment plant facilities";i:2;s:31:"Drilling of new injection wells";i:3;s:43:"Installation of main transmission pipelines";}','Purchase of surfactant and polymer chemicals','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000296','Faktor apa saja yang secara signifikan mempengaruhi nilai Net Present Value (NPV) pada proyek CEOR?','multi','PFM000000060','a:4:{i:0;s:24:"Harga jual minyak mentah";i:1;s:28:"Laju kenaikan inflasi global";i:2;s:27:"Biaya perolehan bahan kimia";i:3;s:29:"Warna cat fasilitas permukaan";}','','a:2:{i:0;s:24:"Harga jual minyak mentah";i:1;s:27:"Biaya perolehan bahan kimia";}','What factors significantly influence the Net Present Value (NPV) of a CEOR project?','a:4:{i:0;s:23:"Crude oil selling price";i:1;s:21:"Global inflation rate";i:2;s:26:"Chemical acquisition costs";i:3;s:28:"Surface facility paint color";}','a:2:{i:0;s:23:"Crude oil selling price";i:1;s:26:"Chemical acquisition costs";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000297','Apa risiko teknis utama yang sering dihadapi dalam injeksi alkaline pada reservoir batuan karbonat?','option','PFM000000060','a:4:{i:0;s:47:"Pembentukan kerak (scaling) akibat reaksi kimia";i:1;s:44:"Peningkatan viskositas minyak secara spontan";i:2;s:51:"Penurunan porositas efektif akibat pelarutan batuan";i:3;s:55:"Peningkatan permeabilitas absolut yang tidak terkontrol";}','','Pembentukan kerak (scaling) akibat reaksi kimia','What is the primary technical risk often encountered during alkaline injection in carbonate reservoirs?','a:4:{i:0;s:41:"Scale formation due to chemical reactions";i:1;s:37:"Spontaneous increase in oil viscosity";i:2;s:54:"Decrease in effective porosity due to rock dissolution";i:3;s:43:"Uncontrolled absolute permeability increase";}','Scale formation due to chemical reactions','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000298','Bagaimana pengaruh peningkatan harga minyak terhadap batas ekonomi (economic limit) suatu proyek Chemical EOR?','option','PFM000000060','a:4:{i:0;s:71:"Memperpanjang usia ekonomis lapangan karena margin keuntungan meningkat";i:1;s:71:"Memperpendek usia ekonomis karena biaya operasional menjadi lebih mahal";i:2;s:49:"Tidak berpengaruh terhadap usia ekonomis lapangan";i:3;s:71:"Menyebabkan proyek segera dihentikan karena risiko lingkungan meningkat";}','','Memperpanjang usia ekonomis lapangan karena margin keuntungan meningkat','How does an increase in oil price affect the economic limit of a Chemical EOR project?','a:4:{i:0;s:70:"Extends the economic life of the field due to increased profit margins";i:1;s:72:"Shortens the economic life because operating costs become more expensive";i:2;s:47:"Has no effect on the economic life of the field";i:3;s:84:"Causes the project to be immediately terminated due to increased environmental risks";}','Extends the economic life of the field due to increased profit margins','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000299','Manakah pernyataan yang benar mengenai risiko lingkungan dalam proyek Chemical EOR?','option','PFM000000060','a:4:{i:0;s:57:"Adanya potensi kebocoran bahan kimia ke akuifer air tanah";i:1;s:65:"Bahan kimia EOR selalu bersifat biodegradable dan tidak berbahaya";i:2;s:71:"Risiko lingkungan hanya terbatas pada emisi gas rumah kaca di permukaan";i:3;s:57:"Injeksi kimia tidak memerlukan izin pengelolaan limbah B3";}','','Adanya potensi kebocoran bahan kimia ke akuifer air tanah','Which statement is correct regarding environmental risks in Chemical EOR projects?','a:4:{i:0;s:67:"There is a potential for chemical leakage into groundwater aquifers";i:1;s:51:"EOR chemicals are always biodegradable and harmless";i:2;s:72:"Environmental risks are limited only to surface greenhouse gas emissions";i:3;s:70:"Chemical injection does not require hazardous waste management permits";}','There is a potential for chemical leakage into groundwater aquifers','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000300','Apa mekanisme utama injeksi uap untuk meningkatkan perolehan minyak pada reservoir minyak berat?','option','PFM000000061','a:4:{i:0;s:54:"Penurunan viskositas minyak akibat kenaikan temperatur";i:1;s:47:"Peningkatan saturasi air residual di dalam pori";i:2;s:44:"Perubahan wettability batuan menjadi oil-wet";i:3;s:52:"Peningkatan tegangan antarmuka antara uap dan minyak";}','','Penurunan viskositas minyak akibat kenaikan temperatur','What is the primary recovery mechanism of steam injection in heavy oil reservoirs?','a:4:{i:0;s:54:"Reduction of oil viscosity due to temperature increase";i:1;s:50:"Increase of residual water saturation in the pores";i:2;s:37:"Change of rock wettability to oil-wet";i:3;s:53:"Increase of interfacial tension between steam and oil";}','Reduction of oil viscosity due to temperature increase','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000301','Manakah pernyataan yang benar mengenai metode Cyclic Steam Stimulation (CSS) atau huff and puff?','option','PFM000000061','a:4:{i:0;s:89:"Melibatkan tiga tahap yaitu injeksi, perendaman (soak), dan produksi pada sumur yang sama";i:1;s:98:"Dilakukan dengan injeksi uap secara kontinu melalui sumur injeksi yang berbeda dari sumur produksi";i:2;s:81:"Metode ini sangat efektif untuk reservoir dengan permeabilitas yang sangat rendah";i:3;s:53:"Meniadakan kebutuhan akan tekanan injeksi yang tinggi";}','','Melibatkan tiga tahap yaitu injeksi, perendaman (soak), dan produksi pada sumur yang sama','Which statement is correct regarding the Cyclic Steam Stimulation (CSS) or huff and puff method?','a:4:{i:0;s:71:"Involves three stages: injection, soak, and production in the same well";i:1;s:92:"Conducted by continuous steam injection through an injector well different from the producer";i:2;s:73:"This method is highly effective for reservoirs with very low permeability";i:3;s:48:"Eliminates the need for high injection pressures";}','Involves three stages: injection, soak, and production in the same well','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000302','Parameter apa saja yang digunakan untuk mengevaluasi efisiensi ekonomi dan teknis dari proyek injeksi uap?','multi','PFM000000061','a:4:{i:0;s:21:"Steam-Oil Ratio (SOR)";i:1;s:26:"Cumulative Steam-Oil Ratio";i:2;s:31:"Permeabilitas absolut reservoir";i:3;s:16:"Porositas batuan";}','','a:2:{i:0;s:21:"Steam-Oil Ratio (SOR)";i:1;s:26:"Cumulative Steam-Oil Ratio";}','Which parameters are used to evaluate the economic and technical efficiency of steam injection projects?','a:4:{i:0;s:21:"Steam-Oil Ratio (SOR)";i:1;s:26:"Cumulative Steam-Oil Ratio";i:2;s:31:"Absolute reservoir permeability";i:3;s:13:"Rock porosity";}','a:2:{i:0;s:21:"Steam-Oil Ratio (SOR)";i:1;s:26:"Cumulative Steam-Oil Ratio";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000303','Apa perbedaan utama antara metode Steamflood dibandingkan dengan Cyclic Steam Stimulation?','option','PFM000000061','a:4:{i:0;s:83:"Steamflood menggunakan pola sumur injeksi dan produksi yang terpisah secara kontinu";i:1;s:56:"Steamflood tidak menyebabkan perubahan viskositas minyak";i:2;s:105:"Cyclic Steam Stimulation memiliki efisiensi sapuan (sweep efficiency) yang lebih luas daripada Steamflood";i:3;s:83:"Steamflood hanya bisa dilakukan pada reservoir dangkal dengan tekanan sangat rendah";}','','Steamflood menggunakan pola sumur injeksi dan produksi yang terpisah secara kontinu','What is the main difference between Steamflood and Cyclic Steam Stimulation?','a:4:{i:0;s:77:"Steamflood uses a separate injection and production well pattern continuously";i:1;s:50:"Steamflood does not cause changes in oil viscosity";i:2;s:69:"Cyclic Steam Stimulation has a wider sweep efficiency than Steamflood";i:3;s:77:"Steamflood can only be performed in shallow reservoirs with very low pressure";}','Steamflood uses a separate injection and production well pattern continuously','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000304','Bagaimana pengaruh kenaikan temperatur terhadap perolehan minyak pada proses thermal EOR?','option','PFM000000061','a:4:{i:0;s:52:"Meningkatkan mobilitas minyak di dalam media berpori";i:1;s:50:"Menurunkan mobilitas minyak karena ekspansi termal";i:2;s:62:"Tidak memberikan pengaruh signifikan terhadap mobilitas fluida";i:3;s:54:"Meningkatkan tegangan permukaan yang menghambat aliran";}','','Meningkatkan mobilitas minyak di dalam media berpori','How does an increase in temperature affect oil recovery in thermal EOR processes?','a:4:{i:0;s:46:"Increases oil mobility within the porous media";i:1;s:47:"Decreases oil mobility due to thermal expansion";i:2;s:44:"Does not significantly affect fluid mobility";i:3;s:45:"Increases surface tension which inhibits flow";}','Increases oil mobility within the porous media','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000305','Apa mekanisme utama pendorong pergerakan minyak pada proses Steam Assisted Gravity Drainage (SAGD)?','option','PFM000000062','a:4:{i:0;s:9:"Gravitasi";i:1;s:21:"Tekanan injeksi pompa";i:2;s:21:"Ekspansi gas terlarut";i:3;s:15:"Tekanan kapiler";}','','Gravitasi','What is the primary driving mechanism for oil movement in the Steam Assisted Gravity Drainage (SAGD) process?','a:4:{i:0;s:7:"Gravity";i:1;s:23:"Pump injection pressure";i:2;s:22:"Solution gas expansion";i:3;s:18:"Capillary pressure";}','Gravity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000306','Pilih dua fenomena yang terjadi pada zona pembakaran (combustion front) dalam proses In-Situ Combustion.','multi','PFM000000062','a:4:{i:0;s:28:"Oksidasi bahan bakar (kokas)";i:1;s:29:"Peningkatan viskositas minyak";i:2;s:27:"Transfer panas ke reservoir";i:3;s:24:"Penurunan suhu reservoir";}','','a:2:{i:0;s:28:"Oksidasi bahan bakar (kokas)";i:1;s:27:"Transfer panas ke reservoir";}','Select two phenomena that occur at the combustion front in the In-Situ Combustion process.','a:4:{i:0;s:21:"Fuel (coke) oxidation";i:1;s:25:"Increase in oil viscosity";i:2;s:30:"Heat transfer to the reservoir";i:3;s:33:"Decrease in reservoir temperature";}','a:2:{i:0;s:21:"Fuel (coke) oxidation";i:1;s:30:"Heat transfer to the reservoir";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000307','Dalam In-Situ Combustion, manakah arah pergerakan zona pembakaran yang paling umum diterapkan di lapangan?','option','PFM000000062','a:4:{i:0;s:18:"Forward combustion";i:1;s:18:"Reverse combustion";i:2;s:18:"Lateral combustion";i:3;s:19:"Downward combustion";}','','Forward combustion','In In-Situ Combustion, which direction of combustion front movement is most commonly applied in the field?','a:4:{i:0;s:18:"Forward combustion";i:1;s:18:"Reverse combustion";i:2;s:18:"Lateral combustion";i:3;s:19:"Downward combustion";}','Forward combustion','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000308','Apa yang dimaksud dengan air requirement dalam desain proyek In-Situ Combustion?','option','PFM000000062','a:4:{i:0;s:79:"Jumlah volume udara yang dibutuhkan untuk membakar satu satuan volume reservoir";i:1;s:50:"Jumlah air yang dibutuhkan untuk pendinginan sumur";i:2;s:49:"Kebutuhan oksigen untuk memicu pembakaran spontan";i:3;s:52:"Laju alir udara maksimum sebelum terjadi penyumbatan";}','','Jumlah volume udara yang dibutuhkan untuk membakar satu satuan volume reservoir','What is meant by air requirement in the design of an In-Situ Combustion project?','a:4:{i:0;s:61:"The volume of air required to burn a unit volume of reservoir";i:1;s:45:"The amount of water required for well cooling";i:2;s:51:"The oxygen demand to trigger spontaneous combustion";i:3;s:48:"The maximum air flow rate before plugging occurs";}','The volume of air required to burn a unit volume of reservoir','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000309','Mengapa Reverse Combustion jarang diterapkan secara luas dalam skala lapangan dibandingkan Forward Combustion?','option','PFM000000062','a:4:{i:0;s:88:"Tingginya risiko penyumbatan oleh minyak berat yang teroksidasi di depan zona pembakaran";i:1;s:34:"Konsumsi udara yang terlalu rendah";i:2;s:44:"Ketidakmampuan menghasilkan panas yang cukup";i:3;s:54:"Biaya operasional yang lebih murah namun tidak efisien";}','','Tingginya risiko penyumbatan oleh minyak berat yang teroksidasi di depan zona pembakaran','Why is Reverse Combustion rarely applied on a field scale compared to Forward Combustion?','a:4:{i:0;s:73:"High risk of plugging by oxidized heavy oil ahead of the combustion front";i:1;s:26:"Air consumption is too low";i:2;s:37:"Inability to generate sufficient heat";i:3;s:43:"Operational costs are lower but inefficient";}','High risk of plugging by oxidized heavy oil ahead of the combustion front','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000310','Apa yang dimaksud dengan Minimum Miscibility Pressure (MMP) dalam proses injeksi gas?','option','PFM000000063','a:4:{i:0;s:89:"Tekanan terendah di mana gas yang diinjeksikan bercampur sempurna dengan minyak reservoir";i:1;s:77:"Tekanan maksimum yang diizinkan untuk mencegah kebocoran gas ke lapisan tutup";i:2;s:69:"Tekanan di mana air mulai terpisah dari minyak pada kondisi reservoir";i:3;s:89:"Tekanan kapiler minimum yang diperlukan untuk mengalirkan minyak melalui batuan reservoir";}','','Tekanan terendah di mana gas yang diinjeksikan bercampur sempurna dengan minyak reservoir','What is the Minimum Miscibility Pressure (MMP) in a gas injection process?','a:4:{i:0;s:91:"The lowest pressure at which the injected gas becomes fully miscible with the reservoir oil";i:1;s:69:"The maximum pressure allowed to prevent gas leakage into the cap rock";i:2;s:79:"The pressure at which water starts to separate from oil at reservoir conditions";i:3;s:78:"The minimum capillary pressure required to flow oil through the reservoir rock";}','The lowest pressure at which the injected gas becomes fully miscible with the reservoir oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000311','Manakah dari mekanisme berikut yang terjadi saat injeksi CO2 ke dalam reservoir minyak?','multi','PFM000000063','a:4:{i:0;s:37:"Pengembangan volume minyak (swelling)";i:1;s:27:"Penurunan viskositas minyak";i:2;s:52:"Peningkatan tegangan antarmuka (interfacial tension)";i:3;s:41:"Pembentukan endapan aspal yang berlebihan";}','','a:2:{i:0;s:37:"Pengembangan volume minyak (swelling)";i:1;s:27:"Penurunan viskositas minyak";}','Which of the following mechanisms occur during CO2 injection into an oil reservoir?','a:4:{i:0;s:12:"Oil swelling";i:1;s:26:"Reduction of oil viscosity";i:2;s:31:"Increase in interfacial tension";i:3;s:34:"Excessive asphaltene precipitation";}','a:2:{i:0;s:12:"Oil swelling";i:1;s:26:"Reduction of oil viscosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000312','Teknik Water-Alternating-Gas (WAG) pada injeksi gas bertujuan terutama untuk:','option','PFM000000063','a:4:{i:0;s:82:"Memperbaiki efisiensi penyapuan (sweep efficiency) dengan mengontrol mobilitas gas";i:1;s:51:"Meningkatkan suhu reservoir agar minyak lebih encer";i:2;s:65:"Menambah konsentrasi CO2 agar tekanan reservoir meningkat drastis";i:3;s:84:"Menurunkan biaya operasional dengan menggunakan air sebagai pengganti gas sepenuhnya";}','','Memperbaiki efisiensi penyapuan (sweep efficiency) dengan mengontrol mobilitas gas','The Water-Alternating-Gas (WAG) technique in gas injection is primarily aimed at:','a:4:{i:0;s:54:"Improving sweep efficiency by controlling gas mobility";i:1;s:60:"Increasing reservoir temperature so that oil becomes thinner";i:2;s:70:"Increasing CO2 concentration to raise reservoir pressure significantly";i:3;s:75:"Reducing operational costs by using water as a complete replacement for gas";}','Improving sweep efficiency by controlling gas mobility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000313','Apa perbedaan utama antara injeksi gas miscible dan immiscible?','option','PFM000000063','a:4:{i:0;s:116:"Pada kondisi miscible, gas dan minyak bercampur menjadi satu fase, sedangkan pada immiscible keduanya tetap terpisah";i:1;s:93:"Injeksi miscible hanya bisa dilakukan dengan CO2, sedangkan immiscible dengan gas hidrokarbon";i:2;s:86:"Injeksi miscible membutuhkan tekanan yang lebih rendah dibandingkan injeksi immiscible";i:3;s:89:"Injeksi immiscible menghasilkan faktor perolehan yang jauh lebih tinggi daripada miscible";}','','Pada kondisi miscible, gas dan minyak bercampur menjadi satu fase, sedangkan pada immiscible keduanya tetap terpisah','What is the primary difference between miscible and immiscible gas injection?','a:4:{i:0;s:101:"In miscible conditions, gas and oil mix into a single phase, while in immiscible they remain separate";i:1;s:83:"Miscible injection can only be done with CO2, while immiscible with hydrocarbon gas";i:2;s:68:"Miscible injection requires lower pressure than immiscible injection";i:3;s:71:"Immiscible injection yields a much higher recovery factor than miscible";}','In miscible conditions, gas and oil mix into a single phase, while in immiscible they remain separate','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000314','Sumber utama gas CO2 yang sering digunakan dalam proyek EOR skala besar adalah:','option','PFM000000063','a:4:{i:0;s:53:"Reservoir gas alam yang kaya CO2 (natural CO2 source)";i:1;s:54:"Pemisahan langsung dari atmosfer menggunakan kompresor";i:2;s:46:"Injeksi gas buang dari pembakaran mesin diesel";i:3;s:49:"Hasil samping dari proses pengeboran batuan dasar";}','','Reservoir gas alam yang kaya CO2 (natural CO2 source)','The primary source of CO2 gas often used in large-scale EOR projects is:','a:4:{i:0;s:31:"Natural CO2-rich gas reservoirs";i:1;s:55:"Direct separation from the atmosphere using compressors";i:2;s:54:"Injection of exhaust gas from diesel engine combustion";i:3;s:49:"By-products from basement rock drilling processes";}','Natural CO2-rich gas reservoirs','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000315','Apa yang dimaksud dengan kondisi miscibility kontak pertama (first-contact miscibility) dalam injeksi gas?','option','PFM000000064','a:4:{i:0;s:93:"Fluida injeksi dan minyak bercampur secara instan pada semua perbandingan saat terjadi kontak";i:1;s:89:"Percampuran terjadi melalui transfer massa komponen menengah setelah beberapa kali kontak";i:2;s:79:"Kondisi di mana tekanan reservoir harus berada di bawah tekanan titik gelembung";i:3;s:75:"Proses di mana gas hanya mendorong minyak tanpa terjadi perubahan komposisi";}','','Fluida injeksi dan minyak bercampur secara instan pada semua perbandingan saat terjadi kontak','What is meant by first-contact miscibility in gas injection?','a:4:{i:0;s:69:"Injection fluid and oil mix instantly at all proportions upon contact";i:1;s:86:"Mixing occurs through mass transfer of intermediate components after multiple contacts";i:2;s:74:"Condition where reservoir pressure must be below the bubble point pressure";i:3;s:67:"Process where gas only drives oil without any compositional changes";}','Injection fluid and oil mix instantly at all proportions upon contact','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000316','Mekanisme perpindahan massa apa yang mendasari proses condensing gas drive (second-contact miscibility)?','option','PFM000000064','a:4:{i:0;s:65:"Komponen menengah dari gas injeksi mengembun ke dalam fase minyak";i:1;s:67:"Komponen minyak yang lebih ringan menguap ke dalam fase gas injeksi";i:2;s:63:"Penurunan tegangan antar muka hingga mencapai nol secara instan";i:3;s:60:"Pembentukan emulsi antara gas dan air dalam pori-pori batuan";}','','Komponen menengah dari gas injeksi mengembun ke dalam fase minyak','What mass transfer mechanism underlies the condensing gas drive (second-contact miscibility) process?','a:4:{i:0;s:70:"Intermediate components from injection gas condense into the oil phase";i:1;s:60:"Lighter oil components vaporize into the injection gas phase";i:2;s:50:"Reduction of interfacial tension to zero instantly";i:3;s:61:"Formation of emulsion between gas and water within rock pores";}','Intermediate components from injection gas condense into the oil phase','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000317','Pilihlah faktor-faktor utama yang mempengaruhi keberhasilan injeksi gas tercampur (miscible gas injection) dalam screening kriteria.','multi','PFM000000064','a:4:{i:0;s:66:"Tekanan reservoir harus di atas Minimum Miscibility Pressure (MMP)";i:1;s:52:"Viskositas minyak yang sangat tinggi di atas 1000 cP";i:2;s:62:"Komposisi minyak yang memiliki cukup komponen menengah (C2-C6)";i:3;s:63:"Heterogenitas reservoir yang rendah untuk menghindari fingering";}','','a:3:{i:0;s:66:"Tekanan reservoir harus di atas Minimum Miscibility Pressure (MMP)";i:1;s:62:"Komposisi minyak yang memiliki cukup komponen menengah (C2-C6)";i:2;s:63:"Heterogenitas reservoir yang rendah untuk menghindari fingering";}','Select the key factors that influence the success of miscible gas injection in screening criteria.','a:4:{i:0;s:71:"Reservoir pressure must be above the Minimum Miscibility Pressure (MMP)";i:1;s:37:"Very high oil viscosity above 1000 cP";i:2;s:69:"Oil composition containing sufficient intermediate components (C2-C6)";i:3;s:46:"Low reservoir heterogeneity to avoid fingering";}','a:3:{i:0;s:71:"Reservoir pressure must be above the Minimum Miscibility Pressure (MMP)";i:1;s:69:"Oil composition containing sufficient intermediate components (C2-C6)";i:2;s:46:"Low reservoir heterogeneity to avoid fingering";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000318','Dalam mekanisme vaporizing gas drive, apa yang terjadi pada zona transisi?','option','PFM000000064','a:4:{i:0;s:86:"Komponen hidrokarbon ringan hingga menengah dari minyak teruapkan ke dalam gas injeksi";i:1;s:61:"Gas injeksi kehilangan komponen beratnya ke dalam air formasi";i:2;s:69:"Terjadi pemisahan gravitasi antara gas injeksi dan gas asli reservoir";i:3;s:69:"Tekanan kapiler meningkat tajam sehingga menghambat pergerakan minyak";}','','Komponen hidrokarbon ringan hingga menengah dari minyak teruapkan ke dalam gas injeksi','In the vaporizing gas drive mechanism, what happens in the transition zone?','a:4:{i:0;s:85:"Light to intermediate hydrocarbon components from oil vaporize into the injection gas";i:1;s:61:"Injection gas loses its heavy components into formation water";i:2;s:75:"Gravity segregation occurs between injection gas and original reservoir gas";i:3;s:60:"Capillary pressure increases sharply, hindering oil movement";}','Light to intermediate hydrocarbon components from oil vaporize into the injection gas','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000319','Berapakah nilai tegangan antar muka (interfacial tension) antara minyak dan gas pada kondisi miscible?','option','PFM000000064','a:4:{i:0;s:13:"Mendekati nol";i:1;s:21:"Sekitar 30-50 dyne/cm";i:2;s:28:"Sangat tinggi (> 70 dyne/cm)";i:3;s:31:"Tidak berubah dari kondisi awal";}','','Mendekati nol','What is the value of the interfacial tension between oil and gas under miscible conditions?','a:4:{i:0;s:16:"Approaching zero";i:1;s:20:"Around 30-50 dyne/cm";i:2;s:24:"Very high (> 70 dyne/cm)";i:3;s:33:"Unchanged from initial conditions";}','Approaching zero','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000320','Manakah kriteria screening utama yang paling menentukan keberhasilan penerapan Steam Flooding pada reservoir minyak berat?','option','PFM000000065','a:4:{i:0;s:66:"Viskositas minyak yang tinggi dan kedalaman reservoir yang dangkal";i:1;s:39:"Permeabilitas batuan yang sangat rendah";i:2;s:36:"Saturasi air yang tinggi di atas 60%";i:3;s:53:"Tekanan reservoir yang sangat tinggi di atas 5000 psi";}','','Viskositas minyak yang tinggi dan kedalaman reservoir yang dangkal','Which is the primary screening criterion that determines the success of Steam Flooding application in heavy oil reservoirs?','a:4:{i:0;s:46:"High oil viscosity and shallow reservoir depth";i:1;s:26:"Very low rock permeability";i:2;s:31:"High water saturation above 60%";i:3;s:43:"Very high reservoir pressure above 5000 psi";}','High oil viscosity and shallow reservoir depth','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000321','Faktor apa saja yang menjadi keunggulan utama dari metode Gas Injection (seperti CO2 atau Gas Miscible) dibandingkan dengan metode Thermal EOR?','multi','PFM000000065','a:4:{i:0;s:61:"Kemampuan untuk diaplikasikan pada reservoir yang lebih dalam";i:1;s:79:"Efisiensi penyapuan (sweep efficiency) yang lebih baik pada reservoir heterogen";i:2;s:71:"Biaya operasional yang sangat rendah karena ketersediaan fluida injeksi";i:3;s:83:"Kemampuan untuk mengurangi tegangan antarmuka (interfacial tension) hingga miscible";}','','a:2:{i:0;s:61:"Kemampuan untuk diaplikasikan pada reservoir yang lebih dalam";i:1;s:83:"Kemampuan untuk mengurangi tegangan antarmuka (interfacial tension) hingga miscible";}','What are the main advantages of Gas Injection methods (such as CO2 or Miscible Gas) compared to Thermal EOR methods?','a:4:{i:0;s:42:"Ability to be applied in deeper reservoirs";i:1;s:51:"Better sweep efficiency in heterogeneous reservoirs";i:2;s:62:"Very low operational costs due to injection fluid availability";i:3;s:52:"Ability to reduce interfacial tension to miscibility";}','a:2:{i:0;s:42:"Ability to be applied in deeper reservoirs";i:1;s:52:"Ability to reduce interfacial tension to miscibility";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000322','Metode Thermal EOR seperti Cyclic Steam Stimulation (CSS) biasanya dipilih karena alasan ekonomi berikut:','option','PFM000000065','a:4:{i:0;s:78:"Memerlukan biaya modal yang jauh lebih rendah dibandingkan injeksi gas kontinu";i:1;s:66:"Memiliki recovery factor yang lebih tinggi daripada Steam Flooding";i:2;s:78:"Dapat memberikan aliran balik minyak (oil backflow) yang cepat ke lubang sumur";i:3;s:49:"Tidak memerlukan peralatan penunjang di permukaan";}','','Dapat memberikan aliran balik minyak (oil backflow) yang cepat ke lubang sumur','Thermal EOR methods such as Cyclic Steam Stimulation (CSS) are typically chosen for the following economic reason:','a:4:{i:0;s:70:"Requires much lower capital costs compared to continuous gas injection";i:1;s:48:"Has a higher recovery factor than Steam Flooding";i:2;s:46:"Can provide rapid oil backflow to the wellbore";i:3;s:42:"Does not require surface support equipment";}','Can provide rapid oil backflow to the wellbore','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000323','Apa kendala utama dalam penerapan Gas EOR (seperti injeksi CO2) terkait dengan heterogenitas reservoir?','option','PFM000000065','a:4:{i:0;s:83:"Terjadinya fenomena fingering atau channeling gas karena viskositas gas yang rendah";i:1;s:59:"Terjadinya pengendapan asphaltene yang menghambat porositas";i:2;s:47:"Gas tidak mampu masuk ke pori-pori batuan mikro";i:3;s:56:"Pembentukan emulsi yang sangat kental di dalam reservoir";}','','Terjadinya fenomena fingering atau channeling gas karena viskositas gas yang rendah','What is the primary challenge in Gas EOR application (such as CO2 injection) related to reservoir heterogeneity?','a:4:{i:0;s:66:"Occurrence of gas fingering or channeling due to low gas viscosity";i:1;s:46:"Asphaltene precipitation that hinders porosity";i:2;s:46:"Gas inability to enter micro-pores of the rock";i:3;s:58:"Formation of highly viscous emulsions within the reservoir";}','Occurrence of gas fingering or channeling due to low gas viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000324','Dalam konteks perbandingan metode EOR, metode Thermal EOR umumnya dibatasi oleh:','option','PFM000000065','a:4:{i:0;s:62:"Kedalaman reservoir yang tidak boleh terlalu dalam (heat loss)";i:1;s:39:"Jenis batuan yang harus selalu karbonat";i:2;s:38:"Saturasi minyak awal yang harus rendah";i:3;s:42:"Tekanan reservoir yang harus sangat tinggi";}','','Kedalaman reservoir yang tidak boleh terlalu dalam (heat loss)','In the context of EOR method comparison, Thermal EOR methods are generally limited by:','a:4:{i:0;s:51:"Reservoir depth that cannot be too deep (heat loss)";i:1;s:39:"Rock type that must always be carbonate";i:2;s:39:"Initial oil saturation that must be low";i:3;s:41:"Reservoir pressure that must be very high";}','Reservoir depth that cannot be too deep (heat loss)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000325','Metode injeksi uap (steam flooding) paling efektif diterapkan pada reservoar dengan karakteristik viskositas minyak yang bagaimana?','option','PFM000000066','a:4:{i:0;s:39:"Viskositas minyak berat di atas 1000 cP";i:1;s:38:"Viskositas minyak ringan di bawah 5 cP";i:2;s:40:"Viskositas minyak sedang antara 10-50 cP";i:3;s:45:"Viskositas minyak sangat rendah di bawah 1 cP";}','','Viskositas minyak berat di atas 1000 cP','Steam flooding is most effectively applied in reservoirs with which oil viscosity characteristics?','a:4:{i:0;s:33:"Heavy oil viscosity above 1000 cP";i:1;s:30:"Light oil viscosity below 5 cP";i:2;s:37:"Medium oil viscosity between 10-50 cP";i:3;s:33:"Very low oil viscosity below 1 cP";}','Heavy oil viscosity above 1000 cP','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000326','Faktor utama yang membatasi penerapan metode injeksi uap pada reservoar yang sangat dalam adalah:','option','PFM000000066','a:4:{i:0;s:43:"Kandungan salinitas air formasi yang tinggi";i:1;s:43:"Kehilangan panas yang besar di dalam tubing";i:2;s:35:"Tekanan kapiler yang terlalu rendah";i:3;s:36:"Porositas batuan yang terlalu tinggi";}','','Kehilangan panas yang besar di dalam tubing','The main factor limiting the application of steam injection in very deep reservoirs is:','a:4:{i:0;s:29:"High formation water salinity";i:1;s:35:"Significant heat loss in the tubing";i:2;s:26:"Too low capillary pressure";i:3;s:22:"Too high rock porosity";}','Significant heat loss in the tubing','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000327','Manakah dari kondisi berikut yang membuat metode miscible gas injection (CO2) menjadi pilihan yang kurang tepat?','multi','PFM000000066','a:4:{i:0;s:37:"Reservoar dengan heterogenitas tinggi";i:1;s:48:"Reservoar dengan kedalaman kurang dari 2000 kaki";i:2;s:48:"Reservoar dengan saturasi air yang sangat rendah";i:3;s:43:"Reservoar dengan permeabilitas yang seragam";}','','a:2:{i:0;s:37:"Reservoar dengan heterogenitas tinggi";i:1;s:48:"Reservoar dengan kedalaman kurang dari 2000 kaki";}','Which of the following conditions make the miscible gas injection (CO2) method a less suitable choice?','a:4:{i:0;s:34:"Reservoirs with high heterogeneity";i:1;s:46:"Reservoirs with a depth of less than 2000 feet";i:2;s:41:"Reservoirs with very low water saturation";i:3;s:36:"Reservoirs with uniform permeability";}','a:2:{i:0;s:34:"Reservoirs with high heterogeneity";i:1;s:46:"Reservoirs with a depth of less than 2000 feet";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000328','Dalam pemilihan metode gas EOR, mengapa tekanan reservoar harus berada di atas tekanan misibilitas minimum (MMP)?','option','PFM000000066','a:4:{i:0;s:33:"Untuk meningkatkan viskositas gas";i:1;s:56:"Untuk memastikan tercapainya kontak misibel antar fluida";i:2;s:38:"Untuk mengurangi laju korosi pada pipa";i:3;s:45:"Untuk meningkatkan kelarutan air dalam minyak";}','','Untuk memastikan tercapainya kontak misibel antar fluida','In selecting gas EOR methods, why must the reservoir pressure be above the Minimum Miscibility Pressure (MMP)?','a:4:{i:0;s:25:"To increase gas viscosity";i:1;s:53:"To ensure miscible contact between fluids is achieved";i:2;s:34:"To reduce corrosion rates in pipes";i:3;s:35:"To increase water solubility in oil";}','To ensure miscible contact between fluids is achieved','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000329','Metode thermal EOR seperti Cyclic Steam Stimulation (CSS) umumnya memerlukan reservoar dengan syarat:','option','PFM000000066','a:4:{i:0;s:32:"Saturasi minyak sisa yang rendah";i:1;s:52:"Ketebalan formasi yang memadai untuk akumulasi panas";i:2;s:65:"Suhu formasi alami yang sangat tinggi di atas 200 derajat Celsius";i:3;s:45:"Kedalaman reservoar yang melebihi 15.000 kaki";}','','Ketebalan formasi yang memadai untuk akumulasi panas','Thermal EOR methods such as Cyclic Steam Stimulation (CSS) generally require reservoirs with the condition of:','a:4:{i:0;s:27:"Low residual oil saturation";i:1;s:50:"Adequate formation thickness for heat accumulation";i:2;s:65:"Very high natural formation temperature above 200 degrees Celsius";i:3;s:37:"Reservoir depth exceeding 15,000 feet";}','Adequate formation thickness for heat accumulation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000330','Parameter utama apa yang diuji dalam laboratorium menggunakan tes core flooding untuk mengevaluasi efisiensi perpindahan fluida EOR?','option','PFM000000067','a:4:{i:0;s:46:"Permeabilitas relatif dan saturasi sisa minyak";i:1;s:26:"Kelarutan gas dalam minyak";i:2;s:20:"Tekanan formasi awal";i:3;s:27:"Konduktivitas termal batuan";}','','Permeabilitas relatif dan saturasi sisa minyak','What is the primary parameter tested in the laboratory using core flooding tests to evaluate EOR displacement efficiency?','a:4:{i:0;s:49:"Relative permeability and residual oil saturation";i:1;s:21:"Gas solubility in oil";i:2;s:26:"Initial reservoir pressure";i:3;s:25:"Rock thermal conductivity";}','Relative permeability and residual oil saturation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000331','Manakah dari berikut ini yang merupakan tujuan utama dari pelaksanaan proyek pilot EOR sebelum skala komersial penuh?','multi','PFM000000067','a:4:{i:0;s:48:"Mengurangi ketidakpastian teknis dan operasional";i:1;s:36:"Memvalidasi model simulasi reservoir";i:2;s:31:"Menambah beban pajak perusahaan";i:3;s:41:"Menghentikan produksi sumur di sekitarnya";}','','a:2:{i:0;s:48:"Mengurangi ketidakpastian teknis dan operasional";i:1;s:36:"Memvalidasi model simulasi reservoir";}','Which of the following are the primary objectives of implementing an EOR pilot project before full-scale commercialization?','a:4:{i:0;s:48:"Reducing technical and operational uncertainties";i:1;s:38:"Validating reservoir simulation models";i:2;s:29:"Increasing company tax burden";i:3;s:40:"Stopping production of surrounding wells";}','a:2:{i:0;s:48:"Reducing technical and operational uncertainties";i:1;s:38:"Validating reservoir simulation models";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000332','Dalam tahap pengumpulan data (data gathering) untuk EOR, mengapa data sejarah produksi dan tekanan reservoir sangat krusial?','option','PFM000000067','a:4:{i:0;s:86:"Untuk mengkalibrasi model simulasi reservoir agar sesuai dengan kondisi lapangan nyata";i:1;s:50:"Untuk menentukan harga jual minyak di pasar global";i:2;s:55:"Untuk memperpanjang umur mekanis peralatan di permukaan";i:3;s:51:"Untuk menghilangkan kebutuhan akan tes laboratorium";}','','Untuk mengkalibrasi model simulasi reservoir agar sesuai dengan kondisi lapangan nyata','In the data gathering stage for EOR, why are historical production and reservoir pressure data crucial?','a:4:{i:0;s:73:"To calibrate reservoir simulation models to match actual field conditions";i:1;s:52:"To determine oil selling prices in the global market";i:2;s:50:"To extend the mechanical life of surface equipment";i:3;s:42:"To eliminate the need for laboratory tests";}','To calibrate reservoir simulation models to match actual field conditions','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000333','Apa fungsi utama dari pengujian rheologi dalam perencanaan proyek EOR, khususnya pada metode polymer flooding?','option','PFM000000067','a:4:{i:0;s:62:"Menentukan viskositas larutan polimer pada berbagai laju geser";i:1;s:38:"Mengukur kedalaman sumur secara akurat";i:2;s:35:"Menentukan porositas efektif batuan";i:3;s:37:"Menghitung densitas gas yang terlarut";}','','Menentukan viskositas larutan polimer pada berbagai laju geser','What is the main function of rheology testing in EOR project planning, specifically for polymer flooding methods?','a:4:{i:0;s:61:"Determining polymer solution viscosity at various shear rates";i:1;s:31:"Measuring well depth accurately";i:2;s:35:"Determining effective rock porosity";i:3;s:40:"Calculating the density of dissolved gas";}','Determining polymer solution viscosity at various shear rates','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000334','Setelah keberhasilan proyek pilot, langkah apa yang umumnya diambil sebelum mencapai skala komersial penuh?','option','PFM000000067','a:4:{i:0;s:45:"Evaluasi ekonomi dan optimasi desain lapangan";i:1;s:43:"Menutup seluruh fasilitas produksi yang ada";i:2;s:42:"Mengganti seluruh tenaga kerja di lapangan";i:3;s:48:"Menghentikan penggunaan teknologi EOR sepenuhnya";}','','Evaluasi ekonomi dan optimasi desain lapangan','After the success of a pilot project, what step is generally taken before reaching full commercial scale?','a:4:{i:0;s:49:"Economic evaluation and field design optimization";i:1;s:48:"Shutting down all existing production facilities";i:2;s:43:"Replacing the entire workforce in the field";i:3;s:42:"Ceasing the use of EOR technology entirely";}','Economic evaluation and field design optimization','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000335','Apa tujuan utama dilakukannya pilot test pada proyek Chemical Enhanced Oil Recovery sebelum implementasi skala lapangan penuh?','option','PFM000000068','a:4:{i:0;s:55:"Mengurangi ketidakpastian teknis dan risiko operasional";i:1;s:47:"Menghilangkan kebutuhan akan studi laboratorium";i:2;s:50:"Menggantikan simulasi reservoir secara keseluruhan";i:3;s:42:"Memastikan harga minyak dunia tetap stabil";}','','Mengurangi ketidakpastian teknis dan risiko operasional','What is the primary objective of conducting a pilot test in a Chemical Enhanced Oil Recovery project before full-field implementation?','a:4:{i:0;s:53:"To reduce technical uncertainty and operational risks";i:1;s:44:"To eliminate the need for laboratory studies";i:2;s:37:"To replace full reservoir simulations";i:3;s:41:"To ensure global oil prices remain stable";}','To reduce technical uncertainty and operational risks','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000336','Faktor apa saja yang menjadi pertimbangan utama dalam pemilihan pola injeksi pada pilot test? (Pilih dua)','multi','PFM000000068','a:4:{i:0;s:23:"Heterogenitas reservoir";i:1;s:11:"Spasi sumur";i:2;s:20:"Warna fluida injeksi";i:3;s:29:"Ketersediaan peralatan kantor";}','','a:2:{i:0;s:23:"Heterogenitas reservoir";i:1;s:11:"Spasi sumur";}','Which factors are the primary considerations in selecting an injection pattern for a pilot test? (Select two)','a:4:{i:0;s:23:"Reservoir heterogeneity";i:1;s:12:"Well spacing";i:2;s:21:"Injection fluid color";i:3;s:29:"Office equipment availability";}','a:2:{i:0;s:23:"Reservoir heterogeneity";i:1;s:12:"Well spacing";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000337','Parameter apa yang paling krusial untuk dimonitor selama fase injeksi pilot test guna memastikan efisiensi pendesakan?','option','PFM000000068','a:4:{i:0;s:32:"Laju injeksi dan tekanan injeksi";i:1;s:29:"Warna cat fasilitas permukaan";i:2;s:25:"Jumlah karyawan di lokasi";i:3;s:24:"Waktu istirahat operator";}','','Laju injeksi dan tekanan injeksi','Which parameter is most crucial to monitor during the pilot test injection phase to ensure displacement efficiency?','a:4:{i:0;s:37:"Injection rate and injection pressure";i:1;s:28:"Surface facility paint color";i:2;s:27:"Number of employees on site";i:3;s:19:"Operator break time";}','Injection rate and injection pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000338','Apa tantangan teknis utama dalam melakukan scale-up dari hasil pilot test ke skala lapangan penuh?','option','PFM000000068','a:4:{i:0;s:49:"Perbedaan heterogenitas dan kontinuitas reservoir";i:1;s:43:"Kurangnya minat investor terhadap teknologi";i:2;s:31:"Kesulitan dalam penamaan proyek";i:3;s:40:"Perubahan cuaca musiman di lokasi proyek";}','','Perbedaan heterogenitas dan kontinuitas reservoir','What is the main technical challenge in scaling up from pilot test results to full-field scale?','a:4:{i:0;s:53:"Differences in reservoir heterogeneity and continuity";i:1;s:43:"Lack of investor interest in the technology";i:2;s:32:"Difficulty in naming the project";i:3;s:44:"Seasonal weather changes at the project site";}','Differences in reservoir heterogeneity and continuity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000339','Kriteria sukses manakah yang menjadi indikator kinerja utama (Key Performance Indicator) dalam proyek pilot CEOR?','option','PFM000000068','a:4:{i:0;s:55:"Peningkatan perolehan minyak (incremental oil recovery)";i:1;s:27:"Penurunan biaya sewa kantor";i:2;s:39:"Peningkatan jumlah tamu yang berkunjung";i:3;s:32:"Pengurangan durasi rapat bulanan";}','','Peningkatan perolehan minyak (incremental oil recovery)','Which success criterion is a key performance indicator (KPI) in a CEOR pilot project?','a:4:{i:0;s:24:"Incremental oil recovery";i:1;s:32:"Reduction in office rental costs";i:2;s:30:"Increase in number of visitors";i:3;s:37:"Reduction in monthly meeting duration";}','Incremental oil recovery','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000340','Dalam konteks analisis ekonomi proyek EOR, manakah komponen yang termasuk ke dalam Capital Expenditure (CAPEX)?','multi','PFM000000069','a:4:{i:0;s:41:"Biaya pembangunan fasilitas injeksi kimia";i:1;s:48:"Biaya pembelian bahan kimia (surfactant/polymer)";i:2;s:35:"Biaya pengeboran sumur injeksi baru";i:3;s:31:"Biaya operasional listrik pompa";}','','a:2:{i:0;s:41:"Biaya pembangunan fasilitas injeksi kimia";i:1;s:35:"Biaya pengeboran sumur injeksi baru";}','In the context of EOR project economic analysis, which components are classified as Capital Expenditure (CAPEX)?','a:4:{i:0;s:48:"Cost of chemical injection facility construction";i:1;s:49:"Cost of purchasing chemicals (surfactant/polymer)";i:2;s:36:"Cost of drilling new injection wells";i:3;s:32:"Cost of electric pump operations";}','a:2:{i:0;s:48:"Cost of chemical injection facility construction";i:1;s:36:"Cost of drilling new injection wells";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000341','Apa yang dimaksud dengan incremental oil dalam evaluasi ekonomi proyek EOR?','option','PFM000000069','a:4:{i:0;s:42:"Total produksi minyak kumulatif dari sumur";i:1;s:74:"Tambahan produksi minyak yang dihasilkan hanya akibat penerapan metode EOR";i:2;s:63:"Volume minyak yang tersisa di reservoir setelah proyek berakhir";i:3;s:47:"Laju produksi minyak sebelum proyek EOR dimulai";}','','Tambahan produksi minyak yang dihasilkan hanya akibat penerapan metode EOR','What is meant by incremental oil in EOR project economic evaluation?','a:4:{i:0;s:45:"Total cumulative oil production from the well";i:1;s:80:"Additional oil production resulting solely from the implementation of EOR method";i:2;s:63:"Volume of oil remaining in the reservoir after the project ends";i:3;s:49:"Oil production rate before the EOR project begins";}','Additional oil production resulting solely from the implementation of EOR method','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000342','Indikator ekonomi yang digunakan untuk menentukan harga minyak minimum agar proyek EOR mencapai titik impas adalah:','option','PFM000000069','a:4:{i:0;s:29:"Internal Rate of Return (IRR)";i:1;s:23:"Net Present Value (NPV)";i:2;s:20:"Break-even Oil Price";i:3;s:11:"Payout Time";}','','Break-even Oil Price','The economic indicator used to determine the minimum oil price required for an EOR project to reach the break-even point is:','a:4:{i:0;s:29:"Internal Rate of Return (IRR)";i:1;s:23:"Net Present Value (NPV)";i:2;s:20:"Break-even Oil Price";i:3;s:11:"Payout Time";}','Break-even Oil Price','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000343','Parameter utama yang paling sensitif terhadap ketidakpastian dalam proyek EOR adalah:','option','PFM000000069','a:4:{i:0;s:32:"Price deck (asumsi harga minyak)";i:1;s:28:"Jumlah karyawan administrasi";i:2;s:21:"Biaya asuransi kantor";i:3;s:23:"Biaya sewa gedung pusat";}','','Price deck (asumsi harga minyak)','The primary parameter that is most sensitive to uncertainty in EOR projects is:','a:4:{i:0;s:34:"Price deck (oil price assumptions)";i:1;s:30:"Number of administrative staff";i:2;s:22:"Office insurance costs";i:3;s:23:"Headquarters rent costs";}','Price deck (oil price assumptions)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000344','Apa fungsi dari Net Present Value (NPV) dalam penilaian proyek EOR?','option','PFM000000069','a:4:{i:0;s:49:"Mengukur rasio antara biaya operasional dan modal";i:1;s:80:"Menghitung nilai waktu dari uang untuk menentukan profitabilitas proyek saat ini";i:2;s:47:"Menentukan durasi waktu pengembalian modal awal";i:3;s:56:"Menghitung persentase tingkat bunga pengembalian tahunan";}','','Menghitung nilai waktu dari uang untuk menentukan profitabilitas proyek saat ini','What is the function of Net Present Value (NPV) in EOR project appraisal?','a:4:{i:0;s:55:"Measuring the ratio between operating costs and capital";i:1;s:87:"Calculating the time value of money to determine project profitability in today''s terms";i:2;s:52:"Determining the duration of initial capital recovery";i:3;s:48:"Calculating the annual percentage rate of return";}','Calculating the time value of money to determine project profitability in today''s terms','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000345','Manakah dari berikut ini yang merupakan risiko teknis utama dalam injeksi polimer yang dapat menghambat laju alir (injectivity) ke dalam formasi?','option','PFM000000070','a:4:{i:0;s:45:"Penurunan viskositas akibat degradasi mekanis";i:1;s:32:"Peningkatan permeabilitas batuan";i:2;s:33:"Perubahan densitas fluida injeksi";i:3;s:32:"Peningkatan saturasi minyak sisa";}','','Penurunan viskositas akibat degradasi mekanis','Which of the following is a primary technical risk in polymer injection that can hinder injectivity into the formation?','a:4:{i:0;s:49:"Viscosity reduction due to mechanical degradation";i:1;s:29:"Increase in rock permeability";i:2;s:33:"Change in injection fluid density";i:3;s:35:"Increase in residual oil saturation";}','Viscosity reduction due to mechanical degradation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000346','Faktor-faktor apa saja yang menjadi risiko pasar yang signifikan dalam ekonomi proyek CEOR?','multi','PFM000000070','a:4:{i:0;s:36:"Fluktuasi harga minyak mentah global";i:1;s:34:"Biaya pengadaan bahan kimia khusus";i:2;s:30:"Kedalaman total sumur pemboran";i:3;s:34:"Tingkat porositas batuan reservoir";}','','a:2:{i:0;s:36:"Fluktuasi harga minyak mentah global";i:1;s:34:"Biaya pengadaan bahan kimia khusus";}','What factors represent significant market risks in the economics of CEOR projects?','a:4:{i:0;s:35:"Global crude oil price fluctuations";i:1;s:40:"Cost of specialized chemical procurement";i:2;s:31:"Total depth of the drilled well";i:3;s:29:"Rock reservoir porosity level";}','a:2:{i:0;s:35:"Global crude oil price fluctuations";i:1;s:40:"Cost of specialized chemical procurement";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000347','Tindakan pencegahan utama dalam HSE (Health, Safety, and Environment) saat menangani bahan kimia EOR di lapangan adalah:','option','PFM000000070','a:4:{i:0;s:49:"Menggunakan alat pelindung diri (APD) sesuai MSDS";i:1;s:47:"Membuang residu kimia langsung ke air permukaan";i:2;s:49:"Menyimpan bahan kimia di area terbuka tanpa label";i:3;s:39:"Mengabaikan prosedur pencampuran fluida";}','','Menggunakan alat pelindung diri (APD) sesuai MSDS','The primary HSE (Health, Safety, and Environment) precaution when handling EOR chemicals in the field is:','a:4:{i:0;s:59:"Using personal protective equipment (PPE) according to MSDS";i:1;s:58:"Disposing of chemical residues directly into surface water";i:2;s:46:"Storing chemicals in open areas without labels";i:3;s:32:"Ignoring fluid mixing procedures";}','Using personal protective equipment (PPE) according to MSDS','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000348','Apa dampak utama dari pembentukan scaling (kerak) di dekat lubang bor (near-wellbore) selama proses injeksi kimia?','option','PFM000000070','a:4:{i:0;s:52:"Penurunan indeks produktivitas dan kerusakan formasi";i:1;s:36:"Peningkatan viskositas minyak mentah";i:2;s:48:"Perbaikan efisiensi penyapuan (sweep efficiency)";i:3;s:44:"Peningkatan tekanan reservoir secara drastis";}','','Penurunan indeks produktivitas dan kerusakan formasi','What is the primary impact of scale formation in the near-wellbore area during chemical injection processes?','a:4:{i:0;s:52:"Reduction in productivity index and formation damage";i:1;s:31:"Increase in crude oil viscosity";i:2;s:31:"Improvement of sweep efficiency";i:3;s:38:"Drastic increase in reservoir pressure";}','Reduction in productivity index and formation damage','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000349','Mengapa kepatuhan terhadap regulasi lingkungan sangat penting dalam implementasi proyek CEOR?','option','PFM000000070','a:4:{i:0;s:53:"Mencegah kontaminasi air tanah akibat kebocoran kimia";i:1;s:43:"Meningkatkan permeabilitas batuan reservoir";i:2;s:39:"Mempercepat laju produksi minyak harian";i:3;s:37:"Mengurangi biaya operasional pemboran";}','','Mencegah kontaminasi air tanah akibat kebocoran kimia','Why is environmental regulatory compliance critical in the implementation of CEOR projects?','a:4:{i:0;s:56:"To prevent groundwater contamination from chemical leaks";i:1;s:39:"To increase reservoir rock permeability";i:2;s:40:"To accelerate daily oil production rates";i:3;s:36:"To reduce drilling operational costs";}','To prevent groundwater contamination from chemical leaks','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000350','Dalam proyek polymer flooding, manakah faktor utama yang paling signifikan meningkatkan efisiensi penyapuan (sweep efficiency)?','option','PFM000000071','a:4:{i:0;s:37:"Peningkatan viskositas fluida injeksi";i:1;s:25:"Penurunan densitas minyak";i:2;s:27:"Peningkatan tekanan kapiler";i:3;s:36:"Pengurangan saturasi air irreducible";}','','Peningkatan viskositas fluida injeksi','In a polymer flooding project, which factor is most significant in improving sweep efficiency?','a:4:{i:0;s:37:"Increase in injection fluid viscosity";i:1;s:23:"Decrease in oil density";i:2;s:30:"Increase in capillary pressure";i:3;s:41:"Reduction of irreducible water saturation";}','Increase in injection fluid viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000351','Apa saja tantangan teknis utama dalam implementasi injeksi surfaktan pada reservoir karbonat?','multi','PFM000000071','a:4:{i:0;s:30:"Adsorpsi surfaktan pada batuan";i:1;s:39:"Presipitasi surfaktan oleh ion divalent";i:2;s:36:"Peningkatan viskositas minyak mentah";i:3;s:26:"Penurunan porositas batuan";}','','a:2:{i:0;s:30:"Adsorpsi surfaktan pada batuan";i:1;s:39:"Presipitasi surfaktan oleh ion divalent";}','What are the main technical challenges in implementing surfactant injection in carbonate reservoirs?','a:4:{i:0;s:29:"Surfactant adsorption on rock";i:1;s:41:"Surfactant precipitation by divalent ions";i:2;s:31:"Increase in crude oil viscosity";i:3;s:25:"Decrease in rock porosity";}','a:2:{i:0;s:29:"Surfactant adsorption on rock";i:1;s:41:"Surfactant precipitation by divalent ions";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000352','Pada proyek CO2-EOR, mekanisme utama apa yang berperan dalam meningkatkan perolehan minyak pada kondisi miscible?','option','PFM000000071','a:4:{i:0;s:45:"Ekstraksi komponen ringan minyak dan swelling";i:1;s:34:"Peningkatan viskositas air formasi";i:2;s:31:"Pembentukan emulsi oil-in-water";i:3;s:38:"Penyumbatan pori oleh endapan aspalten";}','','Ekstraksi komponen ringan minyak dan swelling','In CO2-EOR projects, what is the primary mechanism contributing to increased oil recovery under miscible conditions?','a:4:{i:0;s:47:"Extraction of light oil components and swelling";i:1;s:37:"Increase in formation water viscosity";i:2;s:34:"Formation of oil-in-water emulsion";i:3;s:38:"Pore plugging by asphaltene deposition";}','Extraction of light oil components and swelling','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000353','Manakah parameter ekonomi yang paling krusial dalam menentukan kelayakan (feasibility) proyek CEOR skala lapangan?','option','PFM000000071','a:4:{i:0;s:27:"Incremental recovery factor";i:1;s:31:"Permeabilitas absolut reservoir";i:2;s:24:"Tekanan injeksi maksimum";i:3;s:27:"Komposisi mineralogi batuan";}','','Incremental recovery factor','Which economic parameter is most crucial in determining the feasibility of a field-scale CEOR project?','a:4:{i:0;s:27:"Incremental recovery factor";i:1;s:31:"Absolute reservoir permeability";i:2;s:26:"Maximum injection pressure";i:3;s:30:"Rock mineralogical composition";}','Incremental recovery factor','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000354','Dalam studi kasus CEOR, apa dampak negatif dari fenomena channeling atau fingering terhadap efisiensi injeksi?','option','PFM000000071','a:4:{i:0;s:40:"Penurunan efisiensi penyapuan volumetrik";i:1;s:44:"Peningkatan tekanan reservoir secara drastis";i:2;s:38:"Peningkatan nilai saturasi minyak sisa";i:3;s:44:"Perubahan wettability batuan menjadi oil-wet";}','','Penurunan efisiensi penyapuan volumetrik','In CEOR case studies, what is the negative impact of channeling or fingering phenomena on injection efficiency?','a:4:{i:0;s:39:"Decrease in volumetric sweep efficiency";i:1;s:38:"Drastic increase in reservoir pressure";i:2;s:41:"Increase in residual oil saturation value";i:3;s:37:"Change in rock wettability to oil-wet";}','Decrease in volumetric sweep efficiency','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000355','Manakah di antara mekanisme berikut yang diyakini sebagai pendorong utama peningkatan perolehan minyak pada teknik Low Salinity Waterflooding?','option','PFM000000072','a:4:{i:0;s:52:"Perubahan wettability batuan menjadi lebih water-wet";i:1;s:49:"Peningkatan viskositas air injeksi secara drastis";i:2;s:40:"Pengurangan volume pori batuan reservoir";i:3;s:54:"Penghilangan total saturasi minyak residu di pori-pori";}','','Perubahan wettability batuan menjadi lebih water-wet','Which of the following mechanisms is believed to be the primary driver for oil recovery enhancement in Low Salinity Waterflooding techniques?','a:4:{i:0;s:55:"Alteration of rock wettability to become more water-wet";i:1;s:49:"Significant increase in injection water viscosity";i:2;s:34:"Reduction of reservoir pore volume";i:3;s:53:"Total elimination of residual oil saturation in pores";}','Alteration of rock wettability to become more water-wet','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000356','Dalam konteks CO2-EOR dan CCS, apa fungsi utama dari penyimpanan CO2 di formasi geologi setelah proses pendorongan minyak selesai?','option','PFM000000072','a:4:{i:0;s:35:"Meningkatkan tekanan kapiler batuan";i:1;s:57:"Mitigasi emisi gas rumah kaca dengan penyimpanan permanen";i:2;s:50:"Mengurangi biaya operasional pengeboran sumur baru";i:3;s:43:"Menggantikan kebutuhan akan injeksi polymer";}','','Mitigasi emisi gas rumah kaca dengan penyimpanan permanen','In the context of CO2-EOR and CCS, what is the primary function of CO2 storage in geological formations after the oil displacement process is completed?','a:4:{i:0;s:34:"Increasing rock capillary pressure";i:1;s:64:"Mitigation of greenhouse gas emissions through permanent storage";i:2;s:48:"Reducing operational costs of drilling new wells";i:3;s:40:"Replacing the need for polymer injection";}','Mitigation of greenhouse gas emissions through permanent storage','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000357','Pilihlah teknologi yang termasuk dalam digitalisasi untuk optimasi proyek EOR.','multi','PFM000000072','a:4:{i:0;s:45:"Machine Learning untuk prediksi kurva decline";i:1;s:60:"Digital Twin untuk monitoring kinerja sumur secara real-time";i:2;s:35:"Penggunaan pompa manual tradisional";i:3;s:49:"Analisis data seismik 4D berbasis cloud computing";}','','a:3:{i:0;s:45:"Machine Learning untuk prediksi kurva decline";i:1;s:60:"Digital Twin untuk monitoring kinerja sumur secara real-time";i:2;s:49:"Analisis data seismik 4D berbasis cloud computing";}','Select the technologies that are part of digitalization for EOR project optimization.','a:4:{i:0;s:45:"Machine Learning for decline curve prediction";i:1;s:54:"Digital Twin for real-time well performance monitoring";i:2;s:31:"Use of traditional manual pumps";i:3;s:36:"Cloud-based 4D seismic data analysis";}','a:3:{i:0;s:45:"Machine Learning for decline curve prediction";i:1;s:54:"Digital Twin for real-time well performance monitoring";i:2;s:36:"Cloud-based 4D seismic data analysis";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000358','Apa tantangan utama dalam implementasi proyek EOR di lapangan tua (mature fields) terkait dengan kebijakan energi?','option','PFM000000072','a:4:{i:0;s:42:"Kurangnya ketersediaan air tawar di lokasi";i:1;s:61:"Ketidakpastian harga minyak dan regulasi terkait jejak karbon";i:2;s:43:"Ketiadaan teknologi injeksi gas di industri";i:3;s:57:"Kurangnya minat perusahaan untuk menggunakan digitalisasi";}','','Ketidakpastian harga minyak dan regulasi terkait jejak karbon','What is the primary challenge in implementing EOR projects in mature fields regarding energy policy?','a:4:{i:0;s:40:"Lack of fresh water availability on site";i:1;s:58:"Uncertainty in oil prices and carbon footprint regulations";i:2;s:51:"Absence of gas injection technology in the industry";i:3;s:48:"Lack of company interest in using digitalization";}','Uncertainty in oil prices and carbon footprint regulations','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO soal(id, question, type, mid, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('QST00000000009000000359','Mengapa karakterisasi reservoir yang akurat sangat krusial dalam perencanaan proyek EOR?','option','PFM000000072','a:4:{i:0;s:42:"Untuk menghindari pajak karbon yang tinggi";i:1;s:66:"Untuk memastikan efisiensi sweep dan penempatan sumur yang optimal";i:2;s:44:"Untuk mengurangi jumlah personel di lapangan";i:3;s:53:"Untuk menghilangkan kebutuhan akan pemodelan simulasi";}','','Untuk memastikan efisiensi sweep dan penempatan sumur yang optimal','Why is accurate reservoir characterization crucial in EOR project planning?','a:4:{i:0;s:26:"To avoid high carbon taxes";i:1;s:53:"To ensure sweep efficiency and optimal well placement";i:2;s:46:"To reduce the number of personnel in the field";i:3;s:45:"To eliminate the need for simulation modeling";}','To ensure sweep efficiency and optimal well placement','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000000','Apakah definisi utama dari ilmu petrofisika dalam konteks industri migas?','option','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:78:"Studi mengenai sifat fisik dan kimia batuan serta interaksi fluida di dalamnya";i:1;s:61:"Studi mengenai pergerakan lempeng tektonik di bawah permukaan";i:2;s:59:"Ilmu yang mempelajari desain struktur anjungan lepas pantai";i:3;s:59:"Ilmu yang fokus pada manajemen pemasaran produk minyak bumi";}','','Studi mengenai sifat fisik dan kimia batuan serta interaksi fluida di dalamnya','What is the primary definition of petrophysics in the context of the oil and gas industry?','a:4:{i:0;s:79:"The study of physical and chemical rock properties and their fluid interactions";i:1;s:55:"The study of tectonic plate movements in the subsurface";i:2;s:53:"The science of designing offshore platform structures";i:3;s:62:"The science focusing on petroleum product marketing management";}','The study of physical and chemical rock properties and their fluid interactions','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000001','Manakah parameter berikut yang termasuk dalam parameter utama batuan reservoar?','multi','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:9:"Porositas";i:1;s:13:"Permeabilitas";i:2;s:12:"Saturasi air";i:3;s:22:"Sudut kemiringan sumur";}','','a:3:{i:0;s:9:"Porositas";i:1;s:13:"Permeabilitas";i:2;s:12:"Saturasi air";}','Which of the following parameters are included as the primary reservoir rock parameters?','a:4:{i:0;s:8:"Porosity";i:1;s:12:"Permeability";i:2;s:16:"Water saturation";i:3;s:26:"Wellbore inclination angle";}','a:3:{i:0;s:8:"Porosity";i:1;s:12:"Permeability";i:2;s:16:"Water saturation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000002','Apa fungsi utama dari analisis data core dalam evaluasi petrofisika?','option','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:55:"Memberikan sampel fisik batuan untuk kalibrasi data log";i:1;s:53:"Mengukur tekanan aliran fluida di dalam pipa produksi";i:2;s:51:"Menentukan lokasi pengeboran sumur baru di lapangan";i:3;s:46:"Menghitung volume cadangan minyak secara makro";}','','Memberikan sampel fisik batuan untuk kalibrasi data log','What is the primary function of core data analysis in petrophysical evaluation?','a:4:{i:0;s:57:"To provide physical rock samples for calibrating log data";i:1;s:55:"To measure fluid flow pressure inside production tubing";i:2;s:48:"To determine new drilling locations in the field";i:3;s:49:"To calculate oil reserve volumes on a macro scale";}','To provide physical rock samples for calibrating log data','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000003','Log wireline manakah yang paling umum digunakan untuk mengestimasi porositas batuan?','option','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:28:"Log Densitas dan Log Neutron";i:1;s:13:"Log Gamma Ray";i:2;s:25:"Log Spontaneous Potential";i:3;s:16:"Log Resistivitas";}','','Log Densitas dan Log Neutron','Which wireline log is most commonly used to estimate rock porosity?','a:4:{i:0;s:27:"Density Log and Neutron Log";i:1;s:13:"Gamma Ray Log";i:2;s:25:"Spontaneous Potential Log";i:3;s:15:"Resistivity Log";}','Density Log and Neutron Log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000004','Apakah yang dimaksud dengan permeabilitas dalam batuan reservoar?','option','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:40:"Kemampuan batuan untuk meloloskan fluida";i:1;s:51:"Persentase volume pori terhadap total volume batuan";i:2;s:39:"Fraksi volume pori yang terisi oleh air";i:3;s:44:"Ketahanan batuan terhadap tekanan overburden";}','','Kemampuan batuan untuk meloloskan fluida','What is meant by permeability in reservoir rocks?','a:4:{i:0;s:39:"The ability of rock to allow fluid flow";i:1;s:59:"The percentage of pore volume relative to total rock volume";i:2;s:45:"The fraction of pore volume occupied by water";i:3;s:45:"The resistance of rock to overburden pressure";}','The ability of rock to allow fluid flow','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000005','Data apa yang dapat diperoleh langsung dari pengukuran log resistivitas?','option','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:24:"Estimasi saturasi fluida";i:1;s:24:"Estimasi porositas total";i:2;s:36:"Identifikasi litologi batuan lempung";i:3;s:34:"Penentuan sudut kemiringan formasi";}','','Estimasi saturasi fluida','What data can be obtained directly from resistivity log measurements?','a:4:{i:0;s:27:"Fluid saturation estimation";i:1;s:25:"Total porosity estimation";i:2;s:33:"Identification of shale lithology";i:3;s:36:"Determination of formation dip angle";}','Fluid saturation estimation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000006','Mengapa Gamma Ray log digunakan sebagai indikator litologi?','option','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:60:"Karena mampu mendeteksi radioaktivitas alami mineral lempung";i:1;s:39:"Karena mengukur hambatan listrik batuan";i:2;s:41:"Karena mengukur kecepatan gelombang suara";i:3;s:50:"Karena mendeteksi keberadaan minyak di pori batuan";}','','Karena mampu mendeteksi radioaktivitas alami mineral lempung','Why is the Gamma Ray log used as a lithology indicator?','a:4:{i:0;s:64:"Because it can detect the natural radioactivity of clay minerals";i:1;s:46:"Because it measures rock electrical resistance";i:2;s:39:"Because it measures sound wave velocity";i:3;s:52:"Because it detects the presence of oil in rock pores";}','Because it can detect the natural radioactivity of clay minerals','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000007','Dalam konteks petrofisika, apa yang dimaksud dengan porositas efektif?','option','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:69:"Pori-pori yang saling berhubungan sehingga memungkinkan aliran fluida";i:1;s:68:"Total volume pori di dalam batuan tanpa memperhitungkan konektivitas";i:2;s:45:"Volume air yang terjebak di dalam pori batuan";i:3;s:40:"Pori-pori yang terisi oleh mineral semen";}','','Pori-pori yang saling berhubungan sehingga memungkinkan aliran fluida','In the context of petrophysics, what is meant by effective porosity?','a:4:{i:0;s:42:"Interconnected pores that allow fluid flow";i:1;s:62:"Total pore volume in the rock without considering connectivity";i:2;s:41:"Volume of water trapped inside rock pores";i:3;s:32:"Pores filled with mineral cement";}','Interconnected pores that allow fluid flow','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000008','Manakah dari berikut ini yang merupakan perbedaan antara data log dan data core?','multi','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:53:"Log bersifat kontinu, sedangkan core bersifat diskret";i:1;s:64:"Log diukur secara in-situ, sedangkan core diukur di laboratorium";i:2;s:47:"Data log selalu lebih akurat daripada data core";i:3;s:37:"Data core tidak membutuhkan kalibrasi";}','','a:2:{i:0;s:53:"Log bersifat kontinu, sedangkan core bersifat diskret";i:1;s:64:"Log diukur secara in-situ, sedangkan core diukur di laboratorium";}','Which of the following are differences between log data and core data?','a:4:{i:0;s:45:"Logs are continuous, while cores are discrete";i:1;s:69:"Logs are measured in-situ, while cores are measured in the laboratory";i:2;s:47:"Log data is always more accurate than core data";i:3;s:38:"Core data does not require calibration";}','a:2:{i:0;s:45:"Logs are continuous, while cores are discrete";i:1;s:69:"Logs are measured in-situ, while cores are measured in the laboratory";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000009','Apa pengaruh utama dari peningkatan nilai saturasi air pada reservoar?','option','PFS000000001','Ujian Pelajaran','a:4:{i:0;s:45:"Mengurangi potensi perolehan minyak (net pay)";i:1;s:41:"Meningkatkan permeabilitas absolut batuan";i:2;s:47:"Meningkatkan porositas batuan secara signifikan";i:3;s:50:"Tidak memberikan pengaruh terhadap cadangan minyak";}','','Mengurangi potensi perolehan minyak (net pay)','What is the primary effect of increasing water saturation values in a reservoir?','a:4:{i:0;s:40:"Reduces potential oil recovery (net pay)";i:1;s:36:"Increases absolute rock permeability";i:2;s:37:"Significantly increases rock porosity";i:3;s:29:"Has no effect on oil reserves";}','Reduces potential oil recovery (net pay)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000010','Manakah dari berikut ini yang merupakan karakteristik utama dari batuan reservoar klastik?','option','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:57:"Terbentuk dari akumulasi fragmen mineral atau batuan lain";i:1;s:48:"Terbentuk terutama dari proses presipitasi kimia";i:2;s:44:"Memiliki porositas primer yang sangat rendah";i:3;s:33:"Sering menunjukkan struktur karst";}','','Terbentuk dari akumulasi fragmen mineral atau batuan lain','Which of the following is the main characteristic of clastic reservoir rocks?','a:4:{i:0;s:63:"Formed from the accumulation of mineral or other rock fragments";i:1;s:54:"Formed primarily from chemical precipitation processes";i:2;s:35:"Possesses very low primary porosity";i:3;s:31:"Often exhibits karst structures";}','Formed from the accumulation of mineral or other rock fragments','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000011','Komponen utama yang menyusun batuan karbonat adalah?','multi','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:6:"Kalsit";i:1;s:7:"Dolomit";i:2;s:6:"Kuarsa";i:3;s:8:"Feldspar";}','','a:2:{i:0;s:6:"Kalsit";i:1;s:7:"Dolomit";}','The main components that make up carbonate rocks are?','a:4:{i:0;s:7:"Calcite";i:1;s:8:"Dolomite";i:2;s:6:"Quartz";i:3;s:8:"Feldspar";}','a:2:{i:0;s:7:"Calcite";i:1;s:8:"Dolomite";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000012','Apa yang dimaksud dengan sortasi (sorting) dalam konteks tekstur batuan klastik?','option','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:48:"Derajat keseragaman ukuran butir penyusun batuan";i:1;s:36:"Bentuk kebulatan dari fragmen batuan";i:2;s:32:"Kekompakan butiran dalam matriks";i:3;s:31:"Jumlah ruang pori antar butiran";}','','Derajat keseragaman ukuran butir penyusun batuan','What is meant by sorting in the context of clastic rock texture?','a:4:{i:0;s:50:"The degree of uniformity of grain size in the rock";i:1;s:41:"The degree of roundness of rock fragments";i:2;s:43:"The compactness of grains within the matrix";i:3;s:39:"The amount of pore space between grains";}','The degree of uniformity of grain size in the rock','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000013','Batuan reservoar yang mengalami konsolidasi rendah dan memiliki butiran lepas disebut?','option','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:19:"Unconsolidated sand";i:1;s:5:"Shale";i:2;s:9:"Limestone";i:3;s:14:"Tight gas sand";}','','Unconsolidated sand','A reservoir rock that has undergone low consolidation and has loose grains is called?','a:4:{i:0;s:19:"Unconsolidated sand";i:1;s:5:"Shale";i:2;s:9:"Limestone";i:3;s:14:"Tight gas sand";}','Unconsolidated sand','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000014','Manakah faktor yang paling mempengaruhi porositas sekunder pada batuan karbonat?','option','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:35:"Proses pelarutan dan rekristalisasi";i:1;s:20:"Ukuran butir klastik";i:2;s:29:"Kecepatan pengendapan sedimen";i:3;s:35:"Kandungan tanah liat (clay content)";}','','Proses pelarutan dan rekristalisasi','Which factor most influences secondary porosity in carbonate rocks?','a:4:{i:0;s:43:"Dissolution and recrystallization processes";i:1;s:18:"Clastic grain size";i:2;s:24:"Sediment deposition rate";i:3;s:12:"Clay content";}','Dissolution and recrystallization processes','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000015','Lingkungan pengendapan mana yang biasanya menghasilkan reservoar batu pasir (sandstone) dengan sortasi yang baik?','option','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:39:"Lingkungan pantai (Aeolian atau pantai)";i:1;s:48:"Lingkungan sungai (fluvial) dengan arus turbulen";i:2;s:35:"Lingkungan laut dalam (deep marine)";i:3;s:22:"Lingkungan rawa gambut";}','','Lingkungan pantai (Aeolian atau pantai)','Which depositional environment typically produces sandstone reservoirs with good sorting?','a:4:{i:0;s:39:"Coastal environments (Aeolian or beach)";i:1;s:40:"Fluvial environments with turbulent flow";i:2;s:24:"Deep marine environments";i:3;s:23:"Peat swamp environments";}','Coastal environments (Aeolian or beach)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000016','Dalam kerangka batuan (rock framework), apa fungsi utama dari semen?','option','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:58:"Merekatkan butiran batuan sehingga meningkatkan kekompakan";i:1;s:32:"Menambah porositas primer batuan";i:2;s:34:"Meningkatkan permeabilitas absolut";i:3;s:41:"Mengurangi densitas batuan secara drastis";}','','Merekatkan butiran batuan sehingga meningkatkan kekompakan','In a rock framework, what is the primary function of cement?','a:4:{i:0;s:52:"Bonding rock grains together to increase compactness";i:1;s:32:"Increasing primary rock porosity";i:2;s:32:"Increasing absolute permeability";i:3;s:33:"Drastically reducing rock density";}','Bonding rock grains together to increase compactness','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000017','Mengapa batuan karbonat sering kali memiliki heterogenitas yang lebih tinggi dibandingkan batuan klastik?','option','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:64:"Karena pengaruh proses diagenesa pasca-pengendapan yang kompleks";i:1;s:63:"Karena batuan karbonat selalu terbentuk di lingkungan air dalam";i:2;s:60:"Karena batuan karbonat hanya terdiri dari satu jenis mineral";i:3;s:48:"Karena batuan karbonat tidak memiliki ruang pori";}','','Karena pengaruh proses diagenesa pasca-pengendapan yang kompleks','Why do carbonate rocks often have higher heterogeneity compared to clastic rocks?','a:4:{i:0;s:70:"Due to the influence of complex post-depositional diagenetic processes";i:1;s:62:"Because carbonate rocks always form in deep-water environments";i:2;s:59:"Because carbonate rocks consist of only one type of mineral";i:3;s:46:"Because carbonate rocks do not have pore space";}','Due to the influence of complex post-depositional diagenetic processes','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000018','Istilah ''matriks'' dalam batuan klastik merujuk pada?','option','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:74:"Material berukuran halus yang mengisi ruang antar butiran yang lebih besar";i:1;s:30:"Butiran kuarsa berukuran besar";i:2;s:27:"Semen kimiawi yang mengeras";i:3;s:36:"Fosil yang terperangkap dalam batuan";}','','Material berukuran halus yang mengisi ruang antar butiran yang lebih besar','The term ''matrix'' in clastic rocks refers to?','a:4:{i:0;s:61:"Fine-grained material filling the space between larger grains";i:1;s:19:"Large quartz grains";i:2;s:24:"Hardened chemical cement";i:3;s:31:"Fossils trapped within the rock";}','Fine-grained material filling the space between larger grains','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000019','Manakah pernyataan yang benar mengenai tekstur batuan reservoar?','multi','PFS000000002','Ujian Pelajaran','a:4:{i:0;s:48:"Tekstur mempengaruhi porositas dan permeabilitas";i:1;s:56:"Kebulatan butir (roundness) mempengaruhi packing butiran";i:2;s:70:"Batuan dengan sortasi buruk selalu memiliki permeabilitas lebih tinggi";i:3;s:60:"Ukuran butir tidak mempengaruhi kapasitas penyimpanan fluida";}','','a:2:{i:0;s:48:"Tekstur mempengaruhi porositas dan permeabilitas";i:1;s:56:"Kebulatan butir (roundness) mempengaruhi packing butiran";}','Which statements are true regarding reservoir rock texture?','a:4:{i:0;s:44:"Texture influences porosity and permeability";i:1;s:40:"Grain roundness influences grain packing";i:2;s:51:"Poorly sorted rocks always have higher permeability";i:3;s:49:"Grain size does not affect fluid storage capacity";}','a:2:{i:0;s:44:"Texture influences porosity and permeability";i:1;s:40:"Grain roundness influences grain packing";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000020','Jenis batuan manakah yang paling umum berfungsi sebagai batuan induk (source rock) karena kandungan material organik yang tinggi?','option','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:10:"Batu pasir";i:1;s:19:"Batu serpih (shale)";i:2;s:22:"Batu gamping kristalin";i:3;s:11:"Konglomerat";}','','Batu serpih (shale)','Which rock type most commonly acts as a source rock due to its high organic material content?','a:4:{i:0;s:9:"Sandstone";i:1;s:5:"Shale";i:2;s:21:"Crystalline limestone";i:3;s:12:"Conglomerate";}','Shale','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000021','Faktor apa saja yang memicu proses migrasi primer hidrokarbon dari batuan induk ke batuan reservoar?','multi','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:50:"Peningkatan tekanan akibat pembebanan (compaction)";i:1;s:37:"Peningkatan suhu (thermal maturation)";i:2;s:20:"Gaya gravitasi murni";i:3;s:27:"Perbedaan viskositas fluida";}','','a:2:{i:0;s:50:"Peningkatan tekanan akibat pembebanan (compaction)";i:1;s:37:"Peningkatan suhu (thermal maturation)";}','What factors trigger the primary migration of hydrocarbons from the source rock to the reservoir rock?','a:4:{i:0;s:36:"Increased pressure due to compaction";i:1;s:42:"Increased temperature (thermal maturation)";i:2;s:24:"Pure gravitational force";i:3;s:27:"Fluid viscosity differences";}','a:2:{i:0;s:36:"Increased pressure due to compaction";i:1;s:42:"Increased temperature (thermal maturation)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000022','Apa fungsi utama dari batuan penutup (seal rock) dalam suatu sistem jebakan hidrokarbon?','option','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:35:"Menambah porositas batuan reservoar";i:1;s:56:"Menghambat migrasi hidrokarbon lebih lanjut ke permukaan";i:2;s:33:"Meningkatkan permeabilitas batuan";i:3;s:46:"Menyediakan material organik untuk hidrokarbon";}','','Menghambat migrasi hidrokarbon lebih lanjut ke permukaan','What is the primary function of a seal rock in a hydrocarbon trap system?','a:4:{i:0;s:32:"Increase reservoir rock porosity";i:1;s:52:"Prevent further hydrocarbon migration to the surface";i:2;s:26:"Increase rock permeability";i:3;s:41:"Provide organic material for hydrocarbons";}','Prevent further hydrocarbon migration to the surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000023','Jebakan hidrokarbon yang terbentuk akibat adanya pergeseran lapisan batuan yang memutus kesinambungan reservoar disebut?','option','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:16:"Jebakan antiklin";i:1;s:26:"Jebakan sesar (fault trap)";i:2;s:19:"Jebakan stratigrafi";i:3;s:12:"Jebakan reef";}','','Jebakan sesar (fault trap)','Hydrocarbon traps formed by the displacement of rock layers that break the continuity of the reservoir are called?','a:4:{i:0;s:14:"Anticline trap";i:1;s:10:"Fault trap";i:2;s:18:"Stratigraphic trap";i:3;s:9:"Reef trap";}','Fault trap','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000024','Dalam akumulasi hidrokarbon pada reservoar yang mengandung air, di manakah posisi minyak biasanya berada?','option','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:32:"Di bagian paling bawah reservoar";i:1;s:34:"Tepat di bawah gas dan di atas air";i:2;s:27:"Tercampur merata dengan air";i:3;s:31:"Di bagian paling atas reservoar";}','','Tepat di bawah gas dan di atas air','In hydrocarbon accumulation within a reservoir containing water, where is the oil usually located?','a:4:{i:0;s:35:"At the very bottom of the reservoir";i:1;s:38:"Just below the gas and above the water";i:2;s:23:"Evenly mixed with water";i:3;s:32:"At the very top of the reservoir";}','Just below the gas and above the water','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000025','Manakah dari berikut ini yang merupakan contoh jebakan stratigrafi?','option','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:31:"Ketidakselarasan (unconformity)";i:1;s:16:"Lipatan antiklin";i:2;s:12:"Sesar normal";i:3;s:10:"Sesar naik";}','','Ketidakselarasan (unconformity)','Which of the following is an example of a stratigraphic trap?','a:4:{i:0;s:12:"Unconformity";i:1;s:14:"Anticline fold";i:2;s:12:"Normal fault";i:3;s:13:"Reverse fault";}','Unconformity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000026','Proses migrasi hidrokarbon yang terjadi melalui lapisan batuan berpori setelah keluar dari batuan induk disebut?','option','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:14:"Migrasi primer";i:1;s:16:"Migrasi sekunder";i:2;s:15:"Migrasi tersier";i:3;s:15:"Migrasi lateral";}','','Migrasi sekunder','The process of hydrocarbon migration that occurs through porous rock layers after leaving the source rock is called?','a:4:{i:0;s:17:"Primary migration";i:1;s:19:"Secondary migration";i:2;s:18:"Tertiary migration";i:3;s:17:"Lateral migration";}','Secondary migration','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000027','Apa syarat mutlak agar suatu batuan dapat menjadi reservoar yang baik?','multi','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:29:"Memiliki porositas yang cukup";i:1;s:33:"Memiliki permeabilitas yang cukup";i:2;s:28:"Tidak memiliki kandungan air";i:3;s:29:"Terletak di atas batuan induk";}','','a:2:{i:0;s:29:"Memiliki porositas yang cukup";i:1;s:33:"Memiliki permeabilitas yang cukup";}','What are the absolute requirements for a rock to become a good reservoir?','a:4:{i:0;s:26:"Having sufficient porosity";i:1;s:30:"Having sufficient permeability";i:2;s:23:"Having no water content";i:3;s:29:"Located above the source rock";}','a:2:{i:0;s:26:"Having sufficient porosity";i:1;s:30:"Having sufficient permeability";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000028','Gaya apa yang paling dominan menggerakkan migrasi sekunder hidrokarbon di dalam reservoar?','option','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:21:"Gaya apung (buoyancy)";i:1;s:12:"Gaya kapiler";i:2;s:14:"Gaya molekuler";i:3;s:20:"Gaya elektromagnetik";}','','Gaya apung (buoyancy)','What force is most dominant in driving the secondary migration of hydrocarbons within the reservoir?','a:4:{i:0;s:14:"Buoyancy force";i:1;s:15:"Capillary force";i:2;s:15:"Molecular force";i:3;s:21:"Electromagnetic force";}','Buoyancy force','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000029','Batuan sumber (source rock) yang matang harus mengalami pemanasan dalam jendela suhu tertentu untuk mengubah kerogen menjadi minyak. Jendela minyak (oil window) umumnya berada pada kisaran suhu?','option','PFS000000003','Ujian Pelajaran','a:4:{i:0;s:21:"20-40 derajat Celcius";i:1;s:22:"60-120 derajat Celcius";i:2;s:23:"200-300 derajat Celcius";i:3;s:27:"Di atas 500 derajat Celcius";}','','60-120 derajat Celcius','Mature source rocks must undergo heating within a specific temperature window to convert kerogen into oil. The oil window generally occurs at what temperature range?','a:4:{i:0;s:21:"20-40 degrees Celsius";i:1;s:22:"60-120 degrees Celsius";i:2;s:23:"200-300 degrees Celsius";i:3;s:25:"Above 500 degrees Celsius";}','60-120 degrees Celsius','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000030','Apa perbedaan utama antara porositas total dan porositas efektif pada batuan reservoar?','option','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:106:"Porositas total mencakup semua pori, sedangkan porositas efektif hanya mencakup pori yang saling terhubung";i:1;s:89:"Porositas total hanya mencakup pori yang terhubung, sedangkan efektif mencakup semua pori";i:2;s:75:"Porositas total diukur di laboratorium, sedangkan efektif diukur dengan log";i:3;s:35:"Tidak ada perbedaan antara keduanya";}','','Porositas total mencakup semua pori, sedangkan porositas efektif hanya mencakup pori yang saling terhubung','What is the main difference between total porosity and effective porosity in reservoir rocks?','a:4:{i:0;s:94:"Total porosity includes all pores, while effective porosity only includes interconnected pores";i:1;s:80:"Total porosity only includes connected pores, while effective includes all pores";i:2;s:74:"Total porosity is measured in the lab, while effective is measured by logs";i:3;s:35:"There is no difference between them";}','Total porosity includes all pores, while effective porosity only includes interconnected pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000031','Faktor apa saja yang secara signifikan dapat menurunkan nilai porositas batuan sedimen selama proses diagenesa?','multi','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:8:"Kompaksi";i:1;s:9:"Sementasi";i:2;s:17:"Pelarutan mineral";i:3;s:30:"Penyortiran butiran yang buruk";}','','a:2:{i:0;s:8:"Kompaksi";i:1;s:9:"Sementasi";}','Which factors can significantly decrease the porosity value of sedimentary rocks during diagenesis?','a:4:{i:0;s:10:"Compaction";i:1;s:11:"Cementation";i:2;s:19:"Mineral dissolution";i:3;s:18:"Poor grain sorting";}','a:2:{i:0;s:10:"Compaction";i:1;s:11:"Cementation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000032','Bagaimana pengaruh kemasan butir (grain packing) yang lebih rapat terhadap porositas batuan pasir yang tidak tersementasi?','option','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:24:"Porositas akan meningkat";i:1;s:22:"Porositas akan menurun";i:2;s:23:"Porositas tetap konstan";i:3;s:31:"Porositas menjadi tidak terukur";}','','Porositas akan menurun','How does tighter grain packing affect the porosity of unconsolidated sandstone?','a:4:{i:0;s:22:"Porosity will increase";i:1;s:22:"Porosity will decrease";i:2;s:25:"Porosity remains constant";i:3;s:29:"Porosity becomes immeasurable";}','Porosity will decrease','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000033','Metode log sumur manakah yang paling umum digunakan untuk mengestimasi porositas berdasarkan densitas elektron batuan?','option','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:13:"Log Gamma Ray";i:1;s:26:"Log Densitas (Density Log)";i:2;s:25:"Log Spontaneous Potential";i:3;s:14:"Log Temperatur";}','','Log Densitas (Density Log)','Which well logging method is most commonly used to estimate porosity based on the electron density of the rock?','a:4:{i:0;s:13:"Gamma Ray Log";i:1;s:11:"Density Log";i:2;s:25:"Spontaneous Potential Log";i:3;s:15:"Temperature Log";}','Density Log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000034','Proses geologi apakah yang dapat meningkatkan porositas sekunder pada batuan karbonat?','option','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:16:"Kompaksi mekanik";i:1;s:16:"Sementasi kalsit";i:2;s:41:"Pelarutan (dissolution) oleh air meteorik";i:3;s:32:"Rekristalisasi yang sangat padat";}','','Pelarutan (dissolution) oleh air meteorik','Which geological process can increase secondary porosity in carbonate rocks?','a:4:{i:0;s:21:"Mechanical compaction";i:1;s:19:"Calcite cementation";i:2;s:29:"Dissolution by meteoric water";i:3;s:30:"High-density recrystallization";}','Dissolution by meteoric water','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000035','Jika sebuah sampel core memiliki volume total 100 cc dan volume butiran padat sebesar 75 cc, berapakah porositas sampel tersebut?','option','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:3:"20%";i:1;s:3:"25%";i:2;s:3:"33%";i:3;s:3:"75%";}','','25%','If a core sample has a total volume of 100 cc and a solid grain volume of 75 cc, what is the porosity of the sample?','a:4:{i:0;s:3:"20%";i:1;s:3:"25%";i:2;s:3:"33%";i:3;s:3:"75%";}','25%','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000036','Pilih dua alat log yang sering dikombinasikan untuk mengidentifikasi efek porositas sekunder (seperti vuggy porosity) pada batuan karbonat?','multi','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:12:"Log Densitas";i:1;s:11:"Log Neutron";i:2;s:13:"Log Gamma Ray";i:3;s:6:"Log SP";}','','a:2:{i:0;s:12:"Log Densitas";i:1;s:11:"Log Neutron";}','Select two log tools often combined to identify secondary porosity effects (such as vuggy porosity) in carbonate rocks?','a:4:{i:0;s:11:"Density Log";i:1;s:11:"Neutron Log";i:2;s:13:"Gamma Ray Log";i:3;s:6:"SP Log";}','a:2:{i:0;s:11:"Density Log";i:1;s:11:"Neutron Log";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000037','Bagaimana pengaruh sortasi (pemilahan) butiran terhadap porositas batuan sedimen?','option','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:49:"Sortasi buruk menghasilkan porositas lebih tinggi";i:1;s:48:"Sortasi baik menghasilkan porositas lebih tinggi";i:2;s:44:"Sortasi tidak berpengaruh terhadap porositas";i:3;s:54:"Semakin seragam ukuran butir, porositas semakin rendah";}','','Sortasi baik menghasilkan porositas lebih tinggi','How does grain sorting influence the porosity of sedimentary rocks?','a:4:{i:0;s:39:"Poor sorting results in higher porosity";i:1;s:39:"Good sorting results in higher porosity";i:2;s:33:"Sorting has no effect on porosity";i:3;s:55:"The more uniform the grain size, the lower the porosity";}','Good sorting results in higher porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000038','Apa fungsi utama dari pengukuran porositas menggunakan sampel core di laboratorium?','option','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:36:"Menggantikan fungsi log secara total";i:1;s:51:"Sebagai data kalibrasi untuk interpretasi log sumur";i:2;s:41:"Hanya untuk mengetahui berat jenis batuan";i:3;s:42:"Mengukur tekanan reservoir secara langsung";}','','Sebagai data kalibrasi untuk interpretasi log sumur','What is the primary function of porosity measurement using core samples in the laboratory?','a:4:{i:0;s:33:"To replace log functions entirely";i:1;s:47:"As calibration data for well log interpretation";i:2;s:30:"Only to determine rock density";i:3;s:38:"To measure reservoir pressure directly";}','As calibration data for well log interpretation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000039','Manakah pernyataan yang benar mengenai porositas primer?','option','PFS000000004','Ujian Pelajaran','a:4:{i:0;s:53:"Porositas yang terbentuk setelah batuan terlitifikasi";i:1;s:68:"Porositas yang terbentuk bersamaan dengan proses pengendapan sedimen";i:2;s:47:"Porositas yang disebabkan oleh pelarutan batuan";i:3;s:47:"Porositas yang terbentuk akibat proses tektonik";}','','Porositas yang terbentuk bersamaan dengan proses pengendapan sedimen','Which statement is correct regarding primary porosity?','a:4:{i:0;s:40:"Porosity formed after rock lithification";i:1;s:54:"Porosity formed during the sediment deposition process";i:2;s:35:"Porosity caused by rock dissolution";i:3;s:41:"Porosity formed due to tectonic processes";}','Porosity formed during the sediment deposition process','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000040','Apa syarat utama agar Hukum Darcy dapat diaplikasikan dalam aliran fluida di batuan berpori?','option','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:62:"Aliran tunak (steady state), laminer, dan fluida inkompresibel";i:1;s:48:"Aliran tidak tunak (unsteady state) dan turbulen";i:2;s:42:"Fluida kompresibel dengan aliran multifasa";i:3;s:56:"Aliran pada kondisi reservoir dengan saturasi air tinggi";}','','Aliran tunak (steady state), laminer, dan fluida inkompresibel','What is the main requirement for Darcy''s Law to be applied in fluid flow through porous media?','a:4:{i:0;s:52:"Steady state, laminar, and incompressible fluid flow";i:1;s:33:"Unsteady state and turbulent flow";i:2;s:39:"Compressible fluid with multiphase flow";i:3;s:51:"Reservoir condition flow with high water saturation";}','Steady state, laminar, and incompressible fluid flow','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000041','Faktor apa saja yang paling signifikan mempengaruhi permeabilitas batuan sedimen?','multi','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:30:"Ukuran butir dan sortasi butir";i:1;s:12:"Saturasi gas";i:2;s:18:"Tekanan overburden";i:3;s:17:"Viskositas fluida";}','','a:2:{i:0;s:30:"Ukuran butir dan sortasi butir";i:1;s:18:"Tekanan overburden";}','Which factors most significantly affect the permeability of sedimentary rocks?','a:4:{i:0;s:22:"Grain size and sorting";i:1;s:14:"Gas saturation";i:2;s:19:"Overburden pressure";i:3;s:15:"Fluid viscosity";}','a:2:{i:0;s:22:"Grain size and sorting";i:1;s:19:"Overburden pressure";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000042','Manakah pernyataan yang benar mengenai permeabilitas efektif?','option','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:77:"Permeabilitas suatu fluida jika terdapat lebih dari satu fluida yang mengalir";i:1;s:59:"Permeabilitas batuan yang hanya mengandung satu fasa fluida";i:2;s:63:"Rasio antara permeabilitas efektif dengan permeabilitas absolut";i:3;s:58:"Nilai permeabilitas yang diukur pada kondisi tekanan vakum";}','','Permeabilitas suatu fluida jika terdapat lebih dari satu fluida yang mengalir','Which statement is correct regarding effective permeability?','a:4:{i:0;s:63:"The permeability of a fluid when more than one fluid is flowing";i:1;s:56:"The permeability of rock containing only one fluid phase";i:2;s:60:"The ratio of effective permeability to absolute permeability";i:3;s:61:"The permeability value measured at vacuum pressure conditions";}','The permeability of a fluid when more than one fluid is flowing','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000043','Apa yang dimaksud dengan permeabilitas relatif?','option','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:69:"Rasio permeabilitas efektif suatu fasa terhadap permeabilitas absolut";i:1;s:54:"Hasil perkalian permeabilitas efektif dengan porositas";i:2;s:77:"Nilai permeabilitas yang diukur secara tegak lurus terhadap bidang perlapisan";i:3;s:57:"Permeabilitas total batuan pada kondisi saturasi air 100%";}','','Rasio permeabilitas efektif suatu fasa terhadap permeabilitas absolut','What is meant by relative permeability?','a:4:{i:0;s:79:"The ratio of the effective permeability of a phase to the absolute permeability";i:1;s:50:"The product of effective permeability and porosity";i:2;s:66:"The permeability value measured perpendicular to the bedding plane";i:3;s:52:"The total rock permeability at 100% water saturation";}','The ratio of the effective permeability of a phase to the absolute permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000044','Permeabilitas absolut didefinisikan sebagai permeabilitas batuan ketika...','option','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:45:"Batuan hanya dijenuhkan oleh satu fasa fluida";i:1;s:46:"Batuan dijenuhkan oleh campuran minyak dan air";i:2;s:49:"Batuan dalam kondisi kering sempurna tanpa fluida";i:3;s:37:"Batuan memiliki porositas sebesar nol";}','','Batuan hanya dijenuhkan oleh satu fasa fluida','Absolute permeability is defined as the rock permeability when...','a:4:{i:0;s:47:"The rock is saturated with only one fluid phase";i:1;s:53:"The rock is saturated with a mixture of oil and water";i:2;s:54:"The rock is in a perfectly dry condition with no fluid";i:3;s:26:"The rock has zero porosity";}','The rock is saturated with only one fluid phase','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000045','Bagaimana pengaruh clay (lempung) terhadap permeabilitas batuan?','option','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:70:"Dapat menurunkan permeabilitas secara signifikan karena menyumbat pori";i:1;s:55:"Meningkatkan permeabilitas karena sifatnya yang reaktif";i:2;s:46:"Tidak memiliki pengaruh terhadap permeabilitas";i:3;s:57:"Hanya mempengaruhi porositas tanpa mengubah permeabilitas";}','','Dapat menurunkan permeabilitas secara signifikan karena menyumbat pori','How does clay affect rock permeability?','a:4:{i:0;s:60:"It can significantly decrease permeability by plugging pores";i:1;s:52:"It increases permeability due to its reactive nature";i:2;s:32:"It has no effect on permeability";i:3;s:54:"It only affects porosity without altering permeability";}','It can significantly decrease permeability by plugging pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000046','Alat manakah yang umum digunakan di laboratorium untuk mengukur permeabilitas sampel batuan core?','option','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:11:"Permeameter";i:1;s:11:"Porosimeter";i:2;s:12:"Viskosimeter";i:3;s:10:"Pycnometer";}','','Permeameter','Which instrument is commonly used in the laboratory to measure permeability of core samples?','a:4:{i:0;s:11:"Permeameter";i:1;s:11:"Porosimeter";i:2;s:12:"Viscosimeter";i:3;s:10:"Pycnometer";}','Permeameter','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000047','Mengapa permeabilitas bisa bersifat anisotropik di reservoir?','option','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:67:"Karena adanya struktur perlapisan atau orientasi butir yang dominan";i:1;s:48:"Karena distribusi saturasi air yang tidak merata";i:2;s:53:"Karena pengaruh kedalaman reservoir yang sangat dalam";i:3;s:47:"Karena perbedaan jenis fluida yang mengisi pori";}','','Karena adanya struktur perlapisan atau orientasi butir yang dominan','Why can permeability be anisotropic in a reservoir?','a:4:{i:0;s:71:"Due to the presence of bedding structures or dominant grain orientation";i:1;s:46:"Due to uneven distribution of water saturation";i:2;s:46:"Due to the effect of very deep reservoir depth";i:3;s:58:"Due to differences in the type of fluids filling the pores";}','Due to the presence of bedding structures or dominant grain orientation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000048','Dalam Hukum Darcy, manakah parameter yang berbanding terbalik dengan laju alir (Q)?','multi','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:17:"Viskositas fluida";i:1;s:23:"Panjang lintasan aliran";i:2;s:14:"Luas penampang";i:3;s:7:"Tekanan";}','','a:2:{i:0;s:17:"Viskositas fluida";i:1;s:23:"Panjang lintasan aliran";}','In Darcy''s Law, which parameters are inversely proportional to the flow rate (Q)?','a:4:{i:0;s:15:"Fluid viscosity";i:1;s:16:"Flow path length";i:2;s:20:"Cross-sectional area";i:3;s:8:"Pressure";}','a:2:{i:0;s:15:"Fluid viscosity";i:1;s:16:"Flow path length";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000049','Apa yang dimaksud dengan Klinkenberg effect dalam pengukuran permeabilitas?','option','PFS000000005','Ujian Pelajaran','a:4:{i:0;s:62:"Koreksi permeabilitas akibat slippage gas pada pori-pori kecil";i:1;s:58:"Koreksi akibat tekanan kapiler tinggi pada batuan karbonat";i:2;s:59:"Fenomena penurunan permeabilitas akibat pengendapan mineral";i:3;s:45:"Koreksi akibat adanya distorsi pada alat ukur";}','','Koreksi permeabilitas akibat slippage gas pada pori-pori kecil','What is the Klinkenberg effect in permeability measurement?','a:4:{i:0;s:58:"Permeability correction due to gas slippage in small pores";i:1;s:60:"Correction due to high capillary pressure in carbonate rocks";i:2;s:62:"Phenomenon of permeability reduction due to mineral deposition";i:3;s:53:"Correction due to distortion in measuring instruments";}','Permeability correction due to gas slippage in small pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000050','Berapakah definisi dari saturasi air (Sw) dalam suatu sistem pori batuan reservoir?','option','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:60:"Rasio volume pori yang terisi air terhadap total volume pori";i:1;s:44:"Rasio volume air terhadap volume bulk batuan";i:2;s:53:"Persentase air yang dapat bergerak di dalam reservoir";i:3;s:61:"Volume air yang terikat secara kimiawi pada permukaan butiran";}','','Rasio volume pori yang terisi air terhadap total volume pori','What is the definition of water saturation (Sw) in a reservoir rock pore system?','a:4:{i:0;s:59:"Ratio of pore volume occupied by water to total pore volume";i:1;s:41:"Ratio of water volume to bulk rock volume";i:2;s:43:"Percentage of mobile water in the reservoir";i:3;s:50:"Volume of water chemically bound to grain surfaces";}','Ratio of pore volume occupied by water to total pore volume','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000051','Manakah pernyataan yang paling tepat mengenai hubungan antara porositas dan permeabilitas pada batuan klastik?','option','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:79:"Permeabilitas cenderung meningkat seiring dengan bertambahnya porositas efektif";i:1;s:82:"Permeabilitas selalu berbanding lurus dengan porositas tanpa pengaruh ukuran butir";i:2;s:53:"Porositas tinggi selalu menjamin permeabilitas tinggi";i:3;s:56:"Permeabilitas tidak memiliki korelasi dengan ukuran pori";}','','Permeabilitas cenderung meningkat seiring dengan bertambahnya porositas efektif','Which statement best describes the relationship between porosity and permeability in clastic rocks?','a:4:{i:0;s:65:"Permeability tends to increase with increasing effective porosity";i:1;s:81:"Permeability is always directly proportional to porosity regardless of grain size";i:2;s:49:"High porosity always guarantees high permeability";i:3;s:46:"Permeability has no correlation with pore size";}','Permeability tends to increase with increasing effective porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000052','Apa yang dimaksud dengan Net Pay dalam perhitungan cadangan hidrokarbon?','multi','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:72:"Bagian dari reservoir yang mampu memproduksi hidrokarbon secara ekonomis";i:1;s:58:"Ketebalan total formasi dari puncak hingga dasar reservoir";i:2;s:55:"Ketebalan batuan dengan porositas di atas batas minimum";i:3;s:60:"Ketebalan batuan dengan saturasi air di bawah batas maksimum";}','','a:3:{i:0;s:72:"Bagian dari reservoir yang mampu memproduksi hidrokarbon secara ekonomis";i:1;s:55:"Ketebalan batuan dengan porositas di atas batas minimum";i:2;s:60:"Ketebalan batuan dengan saturasi air di bawah batas maksimum";}','What is meant by Net Pay in hydrocarbon reserve calculations?','a:4:{i:0;s:75:"The portion of the reservoir capable of producing hydrocarbons economically";i:1;s:67:"Total formation thickness from the top to the base of the reservoir";i:2;s:51:"Rock thickness with porosity above a minimum cutoff";i:3;s:59:"Rock thickness with water saturation below a maximum cutoff";}','a:3:{i:0;s:75:"The portion of the reservoir capable of producing hydrocarbons economically";i:1;s:51:"Rock thickness with porosity above a minimum cutoff";i:2;s:59:"Rock thickness with water saturation below a maximum cutoff";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000053','Faktor apa yang paling signifikan mempengaruhi kompresibilitas batuan (rock compressibility)?','option','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:47:"Porositas batuan dan tekanan efektif overburden";i:1;s:34:"Warna batuan dan komposisi mineral";i:2;s:37:"Laju alir fluida saat pengujian sumur";i:3;s:38:"Suhu reservoir pada kedalaman tertentu";}','','Porositas batuan dan tekanan efektif overburden','What factor most significantly influences rock compressibility?','a:4:{i:0;s:47:"Rock porosity and effective overburden pressure";i:1;s:34:"Rock color and mineral composition";i:2;s:35:"Fluid flow rate during well testing";i:3;s:38:"Reservoir temperature at a given depth";}','Rock porosity and effective overburden pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000054','Dalam kondisi reservoir, berapakah jumlah total saturasi fluida dalam pori batuan?','option','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:15:"1.0 (atau 100%)";i:1;s:14:"0.5 (atau 50%)";i:2;s:30:"Sesuai dengan porositas batuan";i:3;s:33:"Tergantung pada viskositas minyak";}','','1.0 (atau 100%)','Under reservoir conditions, what is the total sum of fluid saturations in the rock pores?','a:4:{i:0;s:13:"1.0 (or 100%)";i:1;s:12:"0.5 (or 50%)";i:2;s:22:"Equal to rock porosity";i:3;s:24:"Depends on oil viscosity";}','1.0 (or 100%)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000055','Mengapa permeabilitas absolut berbeda dengan permeabilitas efektif?','option','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:82:"Permeabilitas efektif dipengaruhi oleh keberadaan fluida lain (saturasi multipasa)";i:1;s:45:"Permeabilitas absolut hanya berlaku untuk gas";i:2;s:50:"Permeabilitas efektif hanya diukur di laboratorium";i:3;s:58:"Permeabilitas absolut tidak dipengaruhi oleh struktur pori";}','','Permeabilitas efektif dipengaruhi oleh keberadaan fluida lain (saturasi multipasa)','Why is absolute permeability different from effective permeability?','a:4:{i:0;s:92:"Effective permeability is influenced by the presence of other fluids (multiphase saturation)";i:1;s:41:"Absolute permeability applies only to gas";i:2;s:57:"Effective permeability is only measured in the laboratory";i:3;s:57:"Absolute permeability is not influenced by pore structure";}','Effective permeability is influenced by the presence of other fluids (multiphase saturation)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000056','Apa dampak peningkatan tekanan reservoir terhadap kompresibilitas batuan?','option','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:59:"Batuan cenderung mengalami pemampatan (penurunan porositas)";i:1;s:53:"Batuan mengalami pengembangan (peningkatan porositas)";i:2;s:41:"Tidak ada perubahan pada porositas batuan";i:3;s:58:"Permeabilitas akan meningkat secara drastis secara drastis";}','','Batuan cenderung mengalami pemampatan (penurunan porositas)','What is the impact of increasing reservoir pressure on rock compressibility?','a:4:{i:0;s:55:"Rock tends to undergo compaction (decrease in porosity)";i:1;s:47:"Rock undergoes expansion (increase in porosity)";i:2;s:26:"No change in rock porosity";i:3;s:38:"Permeability will increase drastically";}','Rock tends to undergo compaction (decrease in porosity)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000057','Manakah parameter yang digunakan untuk membedakan antara Net Sand dan Net Pay?','option','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:66:"Cut-off properti petrofisika (porositas, saturasi air, dan Vshale)";i:1;s:21:"Hanya kedalaman sumur";i:2;s:26:"Hanya permeabilitas mutlak";i:3;s:23:"Jumlah lubang perforasi";}','','Cut-off properti petrofisika (porositas, saturasi air, dan Vshale)','Which parameters are used to distinguish between Net Sand and Net Pay?','a:4:{i:0;s:72:"Petrophysical property cut-offs (porosity, water saturation, and Vshale)";i:1;s:15:"Only well depth";i:2;s:26:"Only absolute permeability";i:3;s:27:"Number of perforation holes";}','Petrophysical property cut-offs (porosity, water saturation, and Vshale)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000058','Jika sebuah batuan memiliki saturasi air (Sw) sebesar 20%, berapakah saturasi hidrokarbonnya?','option','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:3:"80%";i:1;s:3:"20%";i:2;s:4:"100%";i:3;s:3:"40%";}','','80%','If a rock has a water saturation (Sw) of 20%, what is its hydrocarbon saturation?','a:4:{i:0;s:3:"80%";i:1;s:3:"20%";i:2;s:4:"100%";i:3;s:3:"40%";}','80%','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000059','Bagaimana pengaruh ukuran butiran terhadap permeabilitas pada batuan pasir yang terpilah baik (well-sorted)?','option','PFS000000006','Ujian Pelajaran','a:4:{i:0;s:82:"Ukuran butiran yang lebih besar umumnya memberikan permeabilitas yang lebih tinggi";i:1;s:55:"Ukuran butiran tidak berpengaruh terhadap permeabilitas";i:2;s:64:"Ukuran butiran kecil selalu memberikan permeabilitas lebih besar";i:3;s:54:"Permeabilitas hanya bergantung pada tekanan overburden";}','','Ukuran butiran yang lebih besar umumnya memberikan permeabilitas yang lebih tinggi','How does grain size influence permeability in well-sorted sandstone?','a:4:{i:0;s:56:"Larger grain size generally provides higher permeability";i:1;s:40:"Grain size has no effect on permeability";i:2;s:54:"Smaller grain size always provides higher permeability";i:3;s:48:"Permeability depends only on overburden pressure";}','Larger grain size generally provides higher permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000060','Pada diagram fase hidrokarbon, titik manakah yang mewakili kondisi di mana fase cair dan fase gas memiliki sifat yang identik?','option','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:12:"Titik kritis";i:1;s:20:"Titik cricondentherm";i:2;s:18:"Titik cricondenbar";i:3;s:18:"Titik bubble point";}','','Titik kritis','On a hydrocarbon phase diagram, which point represents the condition where liquid and gas phases have identical properties?','a:4:{i:0;s:14:"Critical point";i:1;s:20:"Cricondentherm point";i:2;s:18:"Cricondenbar point";i:3;s:12:"Bubble point";}','Critical point','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000061','Jenis reservoir fluida yang komposisinya didominasi oleh fraksi berat (C7+) dan mengalami penurunan tekanan signifikan di bawah bubble point adalah:','option','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:9:"Black oil";i:1;s:12:"Volatile oil";i:2;s:13:"Gas kondensat";i:3;s:7:"Dry gas";}','','Black oil','The type of reservoir fluid dominated by heavy fractions (C7+) that experiences significant pressure drop below the bubble point is:','a:4:{i:0;s:9:"Black oil";i:1;s:12:"Volatile oil";i:2;s:14:"Gas condensate";i:3;s:7:"Dry gas";}','Black oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000062','Manakah pernyataan berikut yang benar mengenai karakteristik reservoir gas kondensat?','multi','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:48:"Terjadi kondensasi retrograde di dalam reservoir";i:1;s:62:"Suhu reservoir berada di antara suhu kritis dan cricondentherm";i:2;s:41:"Hanya memproduksi gas kering di permukaan";i:3;s:31:"Memiliki GOR yang sangat rendah";}','','a:2:{i:0;s:48:"Terjadi kondensasi retrograde di dalam reservoir";i:1;s:62:"Suhu reservoir berada di antara suhu kritis dan cricondentherm";}','Which of the following statements are true regarding the characteristics of a gas condensate reservoir?','a:4:{i:0;s:51:"Retrograde condensation occurs within the reservoir";i:1;s:72:"Reservoir temperature is between critical temperature and cricondentherm";i:2;s:36:"Produces only dry gas at the surface";i:3;s:18:"Has a very low GOR";}','a:2:{i:0;s:51:"Retrograde condensation occurs within the reservoir";i:1;s:72:"Reservoir temperature is between critical temperature and cricondentherm";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000063','Apa yang dimaksud dengan cricondentherm dalam diagram fase hidrokarbon?','option','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:42:"Suhu maksimum di mana dua fase dapat eksis";i:1;s:45:"Tekanan maksimum di mana dua fase dapat eksis";i:2;s:32:"Suhu di mana gas mulai mengembun";i:3;s:49:"Tekanan di mana gelembung gas pertama kali muncul";}','','Suhu maksimum di mana dua fase dapat eksis','What is meant by cricondentherm in a hydrocarbon phase diagram?','a:4:{i:0;s:51:"Maximum temperature at which two phases can coexist";i:1;s:48:"Maximum pressure at which two phases can coexist";i:2;s:40:"Temperature where gas starts to condense";i:3;s:43:"Pressure where the first gas bubble appears";}','Maximum temperature at which two phases can coexist','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000064','Reservoir yang fluida-nya tetap dalam fase gas meskipun tekanan turun secara isotermal di bawah tekanan dew point dikenal sebagai:','option','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:7:"Dry gas";i:1;s:7:"Wet gas";i:2;s:12:"Volatile oil";i:3;s:9:"Black oil";}','','Dry gas','A reservoir whose fluid remains in the gas phase even if the pressure drops isothermally below the dew point is known as:','a:4:{i:0;s:7:"Dry gas";i:1;s:7:"Wet gas";i:2;s:12:"Volatile oil";i:3;s:9:"Black oil";}','Dry gas','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000065','Apa perbedaan utama antara Black Oil dan Volatile Oil dalam hal rasio gas-minyak (GOR)?','option','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:43:"Volatile oil memiliki GOR yang lebih tinggi";i:1;s:40:"Black oil memiliki GOR yang lebih tinggi";i:2;s:31:"Keduanya memiliki GOR yang sama";i:3;s:39:"Volatile oil memiliki GOR mendekati nol";}','','Volatile oil memiliki GOR yang lebih tinggi','What is the main difference between Black Oil and Volatile Oil in terms of gas-oil ratio (GOR)?','a:4:{i:0;s:29:"Volatile oil has a higher GOR";i:1;s:26:"Black oil has a higher GOR";i:2;s:22:"Both have the same GOR";i:3;s:32:"Volatile oil has a GOR near zero";}','Volatile oil has a higher GOR','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000066','Dalam diagram fase, garis yang memisahkan area dua fase (cair dan gas) dari area fase tunggal cair disebut sebagai:','option','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:17:"Bubble point line";i:1;s:14:"Dew point line";i:2;s:17:"Critical isotherm";i:3;s:17:"Cricondenbar line";}','','Bubble point line','In a phase diagram, the line separating the two-phase area (liquid and gas) from the single-phase liquid area is called:','a:4:{i:0;s:17:"Bubble point line";i:1;s:14:"Dew point line";i:2;s:17:"Critical isotherm";i:3;s:17:"Cricondenbar line";}','Bubble point line','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000067','Faktor apa saja yang memengaruhi perubahan fase fluida reservoir?','multi','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:7:"Tekanan";i:1;s:4:"Suhu";i:2;s:20:"Permeabilitas batuan";i:3;s:22:"Komposisi kimia fluida";}','','a:3:{i:0;s:7:"Tekanan";i:1;s:4:"Suhu";i:2;s:22:"Komposisi kimia fluida";}','What factors influence the phase changes of reservoir fluids?','a:4:{i:0;s:8:"Pressure";i:1;s:11:"Temperature";i:2;s:17:"Rock permeability";i:3;s:33:"Chemical composition of the fluid";}','a:3:{i:0;s:8:"Pressure";i:1;s:11:"Temperature";i:2;s:33:"Chemical composition of the fluid";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000068','Fenomena di mana cairan terbentuk dari fasa gas akibat penurunan tekanan di reservoir disebut:','option','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:23:"Retrograde condensation";i:1;s:18:"Flash vaporization";i:2;s:23:"Bubble point depression";i:3;s:20:"Critical fluctuation";}','','Retrograde condensation','The phenomenon where liquid forms from a gas phase due to pressure decrease in the reservoir is called:','a:4:{i:0;s:23:"Retrograde condensation";i:1;s:18:"Flash vaporization";i:2;s:23:"Bubble point depression";i:3;s:20:"Critical fluctuation";}','Retrograde condensation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000069','Karakteristik utama dari ''Wet Gas'' adalah:','option','PFS000000007','Ujian Pelajaran','a:4:{i:0;s:40:"Menghasilkan kondensat cair di permukaan";i:1;s:25:"Hanya berupa metana murni";i:2;s:25:"Hanya berupa minyak berat";i:3;s:26:"Tidak memiliki titik embun";}','','Menghasilkan kondensat cair di permukaan','The main characteristic of ''Wet Gas'' is:','a:4:{i:0;s:41:"Produces liquid condensate at the surface";i:1;s:29:"Consists only of pure methane";i:2;s:26:"Consists only of heavy oil";i:3;s:16:"Has no dew point";}','Produces liquid condensate at the surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000070','Apa yang dimaksud dengan faktor volume formasi minyak (Bo)?','option','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:96:"Perbandingan volume minyak di reservoir terhadap volume minyak di permukaan pada kondisi standar";i:1;s:72:"Perbandingan volume gas di reservoir terhadap volume minyak di permukaan";i:2;s:64:"Densitas minyak di reservoir dibagi densitas minyak di permukaan";i:3;s:45:"Kompresibilitas minyak pada tekanan reservoir";}','','Perbandingan volume minyak di reservoir terhadap volume minyak di permukaan pada kondisi standar','What is defined as the oil formation volume factor (Bo)?','a:4:{i:0;s:88:"Ratio of oil volume at reservoir conditions to oil volume at standard surface conditions";i:1;s:57:"Ratio of gas volume at reservoir to oil volume at surface";i:2;s:58:"Oil density at reservoir divided by oil density at surface";i:3;s:41:"Oil compressibility at reservoir pressure";}','Ratio of oil volume at reservoir conditions to oil volume at standard surface conditions','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000071','Faktor apa saja yang mempengaruhi nilai kompresibilitas isotermal minyak (Co)?','multi','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:17:"Tekanan reservoir";i:1;s:20:"Temperatur reservoir";i:2;s:20:"Permeabilitas batuan";i:3;s:17:"Saturasi air awal";}','','a:2:{i:0;s:17:"Tekanan reservoir";i:1;s:20:"Temperatur reservoir";}','Which factors influence the isothermal oil compressibility (Co)?','a:4:{i:0;s:18:"Reservoir pressure";i:1;s:21:"Reservoir temperature";i:2;s:17:"Rock permeability";i:3;s:24:"Initial water saturation";}','a:2:{i:0;s:18:"Reservoir pressure";i:1;s:21:"Reservoir temperature";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000072','Bagaimana hubungan antara nilai Gas-Oil Ratio (GOR) dengan tekanan di atas bubble point pada minyak undersaturated?','option','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:23:"Nilai GOR tetap konstan";i:1;s:27:"Nilai GOR meningkat drastis";i:2;s:43:"Nilai GOR menurun seiring penurunan tekanan";i:3;s:13:"Nilai GOR nol";}','','Nilai GOR tetap konstan','How does the Gas-Oil Ratio (GOR) relate to pressure above the bubble point in undersaturated oil?','a:4:{i:0;s:20:"GOR remains constant";i:1;s:25:"GOR increases drastically";i:2;s:31:"GOR decreases as pressure drops";i:3;s:11:"GOR is zero";}','GOR remains constant','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000073','Dalam uji laboratorium PVT, kondisi apa yang harus dipertahankan untuk merepresentasikan reservoir yang sebenarnya?','option','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:24:"Isotermal (suhu konstan)";i:1;s:26:"Isobarik (tekanan konstan)";i:2;s:9:"Adiabatik";i:3;s:13:"Kondisi vakum";}','','Isotermal (suhu konstan)','In PVT laboratory tests, what condition must be maintained to represent the actual reservoir?','a:4:{i:0;s:33:"Isothermal (constant temperature)";i:1;s:28:"Isobaric (constant pressure)";i:2;s:9:"Adiabatic";i:3;s:16:"Vacuum condition";}','Isothermal (constant temperature)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000074','Pilih parameter fisik fluida yang diukur langsung dari analisis PVT di laboratorium.','multi','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:26:"Faktor volume formasi (Bo)";i:1;s:21:"Permeabilitas relatif";i:2;s:20:"Tekanan bubble point";i:3;s:15:"Densitas fluida";}','','a:3:{i:0;s:26:"Faktor volume formasi (Bo)";i:1;s:20:"Tekanan bubble point";i:2;s:15:"Densitas fluida";}','Select the fluid physical parameters measured directly from laboratory PVT analysis.','a:4:{i:0;s:28:"Formation volume factor (Bo)";i:1;s:21:"Relative permeability";i:2;s:21:"Bubble point pressure";i:3;s:13:"Fluid density";}','a:3:{i:0;s:28:"Formation volume factor (Bo)";i:1;s:21:"Bubble point pressure";i:2;s:13:"Fluid density";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000075','Apa yang terjadi pada faktor volume formasi gas (Bg) ketika tekanan reservoir menurun?','option','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:18:"Nilai Bg meningkat";i:1;s:16:"Nilai Bg menurun";i:2;s:14:"Nilai Bg tetap";i:3;s:20:"Nilai Bg menjadi nol";}','','Nilai Bg meningkat','What happens to the gas formation volume factor (Bg) when reservoir pressure decreases?','a:4:{i:0;s:18:"Bg value increases";i:1;s:18:"Bg value decreases";i:2;s:25:"Bg value remains constant";i:3;s:21:"Bg value becomes zero";}','Bg value increases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000076','Manakah pernyataan yang benar mengenai faktor volume formasi air (Bw)?','option','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:29:"Nilainya selalu mendekati 1.0";i:1;s:35:"Nilainya selalu lebih besar dari Bo";i:2;s:35:"Nilainya sangat bergantung pada GOR";i:3;s:31:"Nilainya tidak dipengaruhi suhu";}','','Nilainya selalu mendekati 1.0','Which statement is correct regarding the water formation volume factor (Bw)?','a:4:{i:0;s:32:"Its value is always close to 1.0";i:1;s:35:"Its value is always greater than Bo";i:2;s:31:"Its value highly depends on GOR";i:3;s:40:"Its value is not affected by temperature";}','Its value is always close to 1.0','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000077','Apa dampak peningkatan suhu reservoir terhadap densitas minyak?','option','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:16:"Densitas menurun";i:1;s:18:"Densitas meningkat";i:2;s:22:"Densitas tidak berubah";i:3;s:30:"Densitas menjadi tak terhingga";}','','Densitas menurun','What is the effect of increasing reservoir temperature on oil density?','a:4:{i:0;s:17:"Density decreases";i:1;s:17:"Density increases";i:2;s:25:"Density remains unchanged";i:3;s:24:"Density becomes infinite";}','Density decreases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000078','Parameter apa yang digunakan untuk mengukur perubahan volume fluida terhadap perubahan tekanan?','option','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:15:"Kompresibilitas";i:1;s:10:"Viskositas";i:2;s:19:"Tegangan antar muka";i:3;s:8:"Densitas";}','','Kompresibilitas','What parameter is used to measure the change in fluid volume with respect to change in pressure?','a:4:{i:0;s:15:"Compressibility";i:1;s:9:"Viscosity";i:2;s:19:"Interfacial tension";i:3;s:7:"Density";}','Compressibility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000079','Pada kondisi reservoir di bawah bubble point, apa yang terjadi pada gas dalam minyak?','option','PFS000000008','Ujian Pelajaran','a:4:{i:0;s:35:"Gas terbebaskan dari larutan minyak";i:1;s:40:"Gas semakin banyak terlarut dalam minyak";i:2;s:34:"Gas tidak mengalami perubahan fase";i:3;s:25:"Gas berubah menjadi padat";}','','Gas terbebaskan dari larutan minyak','Under reservoir conditions below the bubble point, what happens to the gas in the oil?','a:4:{i:0;s:38:"Gas is liberated from the oil solution";i:1;s:31:"More gas dissolves into the oil";i:2;s:33:"Gas does not undergo phase change";i:3;s:20:"Gas turns into solid";}','Gas is liberated from the oil solution','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000080','Parameter utama yang paling dominan mempengaruhi nilai resistivitas air formasi (Rw) pada kondisi suhu tertentu adalah?','option','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:9:"Salinitas";i:1;s:18:"Tekanan overburden";i:2;s:16:"Porositas batuan";i:3;s:17:"Viskositas minyak";}','','Salinitas','What is the primary parameter that most dominantly influences the formation water resistivity (Rw) at a given temperature?','a:4:{i:0;s:8:"Salinity";i:1;s:19:"Overburden pressure";i:2;s:13:"Rock porosity";i:3;s:13:"Oil viscosity";}','Salinity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000081','Bagaimana pengaruh peningkatan suhu formasi mempengaruhi nilai resistivitas air (Rw)?','option','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:12:"Rw meningkat";i:1;s:10:"Rw menurun";i:2;s:16:"Rw tetap konstan";i:3;s:14:"Rw menjadi nol";}','','Rw menurun','How does an increase in formation temperature affect the water resistivity (Rw) value?','a:4:{i:0;s:12:"Rw increases";i:1;s:12:"Rw decreases";i:2;s:19:"Rw remains constant";i:3;s:15:"Rw becomes zero";}','Rw decreases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000082','Faktor apa saja yang menyebabkan resistivitas batuan (Rt) menjadi lebih rendah dibandingkan seharusnya pada zona yang mengandung hidrokarbon?','multi','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:33:"Kehadiran mineral lempung (shale)";i:1;s:33:"Peningkatan salinitas air formasi";i:2;s:27:"Adanya air konat dalam pori";i:3;s:28:"Peningkatan porositas primer";}','','a:2:{i:0;s:33:"Kehadiran mineral lempung (shale)";i:1;s:33:"Peningkatan salinitas air formasi";}','What factors cause the rock resistivity (Rt) to be lower than expected in hydrocarbon-bearing zones?','a:4:{i:0;s:33:"Presence of clay minerals (shale)";i:1;s:36:"Increase in formation water salinity";i:2;s:34:"Presence of connate water in pores";i:3;s:28:"Increase in primary porosity";}','a:2:{i:0;s:33:"Presence of clay minerals (shale)";i:1;s:36:"Increase in formation water salinity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000083','Dalam persamaan Archie, apa yang direpresentasikan oleh faktor formasi (F)?','option','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:25:"Hubungan antara Ro dan Rw";i:1;s:25:"Hubungan antara Rt dan Rw";i:2;s:34:"Hubungan antara salinitas dan suhu";i:3;s:35:"Hubungan antara saturasi air dan Rw";}','','Hubungan antara Ro dan Rw','In the Archie equation, what does the formation factor (F) represent?','a:4:{i:0;s:30:"Relationship between Ro and Rw";i:1;s:30:"Relationship between Rt and Rw";i:2;s:45:"Relationship between salinity and temperature";i:3;s:44:"Relationship between water saturation and Rw";}','Relationship between Ro and Rw','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000084','Apa yang dimaksud dengan Ro dalam konteks petrofisika?','option','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:39:"Resistivitas batuan saat jenuh air 100%";i:1;s:42:"Resistivitas batuan saat jenuh hidrokarbon";i:2;s:24:"Resistivitas air formasi";i:3;s:24:"Resistivitas zona invasi";}','','Resistivitas batuan saat jenuh air 100%','What is meant by Ro in the context of petrophysics?','a:4:{i:0;s:44:"Resistivity of rock at 100% water saturation";i:1;s:45:"Resistivity of rock at hydrocarbon saturation";i:2;s:27:"Formation water resistivity";i:3;s:31:"Resistivity of the invaded zone";}','Resistivity of rock at 100% water saturation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000085','Kehadiran shale (mineral lempung) pada batuan reservoir akan menyebabkan nilai resistivitas yang terukur (Rt) menjadi:','option','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:41:"Lebih rendah dari resistivitas sebenarnya";i:1;s:41:"Lebih tinggi dari resistivitas sebenarnya";i:2;s:17:"Tidak terpengaruh";i:3;s:14:"Sama dengan Ro";}','','Lebih rendah dari resistivitas sebenarnya','The presence of shale (clay minerals) in a reservoir rock will cause the measured resistivity (Rt) value to be:','a:4:{i:0;s:27:"Lower than true resistivity";i:1;s:28:"Higher than true resistivity";i:2;s:10:"Unaffected";i:3;s:11:"Equal to Ro";}','Lower than true resistivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000086','Jika salinitas air formasi meningkat, maka resistivitas air (Rw) akan:','option','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:7:"Menurun";i:1;s:9:"Meningkat";i:2;s:13:"Tidak berubah";i:3;s:26:"Menjadi konduktor sempurna";}','','Menurun','If the formation water salinity increases, the water resistivity (Rw) will:','a:4:{i:0;s:8:"Decrease";i:1;s:8:"Increase";i:2;s:16:"Remain unchanged";i:3;s:26:"Become a perfect conductor";}','Decrease','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000087','Parameter manakah yang merupakan komponen utama dalam Hukum Archie untuk menghitung saturasi air (Sw)?','multi','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:29:"Resistivitas air formasi (Rw)";i:1;s:35:"Resistivitas batuan sebenarnya (Rt)";i:2;s:16:"Porositas batuan";i:3;s:17:"Tekanan reservoir";}','','a:3:{i:0;s:29:"Resistivitas air formasi (Rw)";i:1;s:35:"Resistivitas batuan sebenarnya (Rt)";i:2;s:16:"Porositas batuan";}','Which parameters are the main components in Archie''s Law for calculating water saturation (Sw)?','a:4:{i:0;s:32:"Formation water resistivity (Rw)";i:1;s:26:"True rock resistivity (Rt)";i:2;s:13:"Rock porosity";i:3;s:18:"Reservoir pressure";}','a:3:{i:0;s:32:"Formation water resistivity (Rw)";i:1;s:26:"True rock resistivity (Rt)";i:2;s:13:"Rock porosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000088','Mengapa mineral lempung (clay) bersifat konduktif secara elektrik?','option','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:54:"Karena adanya pertukaran kation pada permukaan lempung";i:1;s:34:"Karena sifatnya yang tidak berpori";i:2;s:41:"Karena kandungan minyak yang terperangkap";i:3;s:41:"Karena struktur kristalnya yang kedap air";}','','Karena adanya pertukaran kation pada permukaan lempung','Why are clay minerals electrically conductive?','a:4:{i:0;s:42:"Due to cation exchange on the clay surface";i:1;s:30:"Due to their non-porous nature";i:2;s:26:"Due to trapped oil content";i:3;s:48:"Due to their water-impermeable crystal structure";}','Due to cation exchange on the clay surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000089','Pada kondisi reservoir yang bersih (clean sand), nilai resistivitas (Rt) berbanding terbalik dengan:','option','PFS000000009','Ujian Pelajaran','a:4:{i:0;s:17:"Saturasi air (Sw)";i:1;s:9:"Porositas";i:2;s:13:"Salinitas air";i:3;s:9:"Kedalaman";}','','Saturasi air (Sw)','In a clean sand reservoir condition, the resistivity (Rt) value is inversely proportional to:','a:4:{i:0;s:21:"Water saturation (Sw)";i:1;s:8:"Porosity";i:2;s:14:"Water salinity";i:3;s:5:"Depth";}','Water saturation (Sw)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000090','Log manakah yang diklasifikasikan sebagai log nuklir untuk mengukur porositas formasi?','option','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:11:"Density Log";i:1;s:15:"Resistivity Log";i:2;s:9:"Sonic Log";i:3;s:6:"SP Log";}','','Density Log','Which log is classified as a nuclear log to measure formation porosity?','a:4:{i:0;s:11:"Density Log";i:1;s:15:"Resistivity Log";i:2;s:9:"Sonic Log";i:3;s:6:"SP Log";}','Density Log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000091','Prinsip utama yang diukur oleh log resistivitas untuk menentukan saturasi fluida adalah?','option','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:28:"Konduktivitas listrik batuan";i:1;s:25:"Kecepatan gelombang suara";i:2;s:17:"Densitas elektron";i:3;s:20:"Radioaktivitas alami";}','','Konduktivitas listrik batuan','What is the main principle measured by the resistivity log to determine fluid saturation?','a:4:{i:0;s:31:"Electrical conductivity of rock";i:1;s:20:"Speed of sound waves";i:2;s:16:"Electron density";i:3;s:21:"Natural radioactivity";}','Electrical conductivity of rock','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000092','Data apa saja yang umumnya diperoleh dari log Gamma Ray?','multi','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:35:"Tingkat radioaktivitas alami batuan";i:1;s:27:"Identifikasi jenis litologi";i:2;s:23:"Kadar porositas efektif";i:3;s:18:"Kadar saturasi air";}','','a:2:{i:0;s:35:"Tingkat radioaktivitas alami batuan";i:1;s:27:"Identifikasi jenis litologi";}','What data are generally obtained from the Gamma Ray log?','a:4:{i:0;s:36:"Natural radioactivity level of rocks";i:1;s:29:"Lithology type identification";i:2;s:24:"Effective porosity level";i:3;s:22:"Water saturation level";}','a:2:{i:0;s:36:"Natural radioactivity level of rocks";i:1;s:29:"Lithology type identification";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000093','Parameter utama yang diukur oleh Sonic Log untuk analisis petrofisika adalah?','option','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:21:"Interval transit time";i:1;s:19:"Resistivitas batuan";i:2;s:13:"Densitas bulk";i:3;s:17:"Potensial spontan";}','','Interval transit time','What is the main parameter measured by the Sonic Log for petrophysical analysis?','a:4:{i:0;s:21:"Interval transit time";i:1;s:16:"Rock resistivity";i:2;s:12:"Bulk density";i:3;s:21:"Spontaneous potential";}','Interval transit time','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000094','Apa fungsi utama dari depth control pada operasi wireline logging?','option','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:55:"Memastikan kedalaman alat akurat terhadap kedalaman bor";i:1;s:27:"Menentukan porositas batuan";i:2;s:26:"Mengukur tekanan reservoir";i:3;s:27:"Mendeteksi zona hidrokarbon";}','','Memastikan kedalaman alat akurat terhadap kedalaman bor','What is the main function of depth control in wireline logging operations?','a:4:{i:0;s:55:"Ensuring tool depth accuracy relative to drilling depth";i:1;s:25:"Determining rock porosity";i:2;s:28:"Measuring reservoir pressure";i:3;s:27:"Detecting hydrocarbon zones";}','Ensuring tool depth accuracy relative to drilling depth','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000095','Jenis log manakah yang termasuk dalam kategori log elektrik?','multi','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:13:"Induction Log";i:1;s:9:"Laterolog";i:2;s:11:"Neutron Log";i:3;s:13:"Gamma Ray Log";}','','a:2:{i:0;s:13:"Induction Log";i:1;s:9:"Laterolog";}','Which log types are categorized as electrical logs?','a:4:{i:0;s:13:"Induction Log";i:1;s:9:"Laterolog";i:2;s:11:"Neutron Log";i:3;s:13:"Gamma Ray Log";}','a:2:{i:0;s:13:"Induction Log";i:1;s:9:"Laterolog";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000096','Log densitas mengukur sifat fisik batuan berdasarkan interaksi radiasi gamma dengan?','option','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:22:"Elektron dalam formasi";i:1;s:15:"Butiran mineral";i:2;s:12:"Saturasi air";i:3;s:20:"Permeabilitas batuan";}','','Elektron dalam formasi','The density log measures rock physical properties based on gamma radiation interaction with?','a:4:{i:0;s:26:"Electrons in the formation";i:1;s:14:"Mineral grains";i:2;s:16:"Water saturation";i:3;s:17:"Rock permeability";}','Electrons in the formation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000097','Apa yang dimaksud dengan resolusi vertikal pada alat wireline logging?','option','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:63:"Ketebalan minimum lapisan batuan yang dapat dibedakan oleh alat";i:1;s:50:"Kedalaman maksimum alat dapat mencapai dasar sumur";i:2;s:35:"Kecepatan alat saat ditarik ke atas";i:3;s:30:"Akurasi pembacaan resistivitas";}','','Ketebalan minimum lapisan batuan yang dapat dibedakan oleh alat','What is meant by vertical resolution in a wireline logging tool?','a:4:{i:0;s:56:"Minimum rock layer thickness distinguishable by the tool";i:1;s:44:"Maximum depth the tool can reach in the well";i:2;s:32:"Speed of the tool during logging";i:3;s:31:"Accuracy of resistivity reading";}','Minimum rock layer thickness distinguishable by the tool','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000098','Log yang paling sensitif terhadap kandungan serpih (shale) dalam formasi adalah?','option','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:13:"Gamma Ray Log";i:1;s:11:"Density Log";i:2;s:9:"Sonic Log";i:3;s:15:"Resistivity Log";}','','Gamma Ray Log','Which log is the most sensitive to shale content in the formation?','a:4:{i:0;s:13:"Gamma Ray Log";i:1;s:11:"Density Log";i:2;s:9:"Sonic Log";i:3;s:15:"Resistivity Log";}','Gamma Ray Log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000099','Untuk mengukur porositas dengan menggunakan log neutron, interaksi apa yang terjadi?','option','PFS000000010','Ujian Pelajaran','a:4:{i:0;s:35:"Hamburan neutron oleh atom hidrogen";i:1;s:28:"Absorpsi foton oleh elektron";i:2;s:26:"Refraksi gelombang akustik";i:3;s:20:"Induksi arus listrik";}','','Hamburan neutron oleh atom hidrogen','To measure porosity using a neutron log, what interaction occurs?','a:4:{i:0;s:36:"Neutron scattering by hydrogen atoms";i:1;s:30:"Photon absorption by electrons";i:2;s:24:"Acoustic wave refraction";i:3;s:28:"Electrical current induction";}','Neutron scattering by hydrogen atoms','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000100','Apa fungsi utama dari kurva Spontaneous Potential (SP) dalam evaluasi formasi?','option','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:51:"Membedakan batuan permeabel dari batuan impermeabel";i:1;s:52:"Mengukur kadar salinitas air formasi secara langsung";i:2;s:35:"Menentukan porositas efektif batuan";i:3;s:49:"Mendeteksi keberadaan hidrokarbon secara langsung";}','','Membedakan batuan permeabel dari batuan impermeabel','What is the primary function of the Spontaneous Potential (SP) curve in formation evaluation?','a:4:{i:0;s:54:"Differentiating permeable rocks from impermeable rocks";i:1;s:43:"Measuring formation water salinity directly";i:2;s:35:"Determining effective rock porosity";i:3;s:47:"Directly detecting the presence of hydrocarbons";}','Differentiating permeable rocks from impermeable rocks','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000101','Faktor apa saja yang memengaruhi defleksi log SP dalam sebuah formasi?','multi','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:49:"Perbedaan salinitas antara lumpur dan air formasi";i:1;s:20:"Permeabilitas batuan";i:2;s:24:"Ketebalan lapisan batuan";i:3;s:32:"Tekanan hidrostatik kolom lumpur";}','','a:3:{i:0;s:49:"Perbedaan salinitas antara lumpur dan air formasi";i:1;s:20:"Permeabilitas batuan";i:2;s:24:"Ketebalan lapisan batuan";}','What factors influence SP log deflection in a formation?','a:4:{i:0;s:54:"Difference in salinity between mud and formation water";i:1;s:17:"Rock permeability";i:2;s:13:"Bed thickness";i:3;s:38:"Hydrostatic pressure of the mud column";}','a:3:{i:0;s:54:"Difference in salinity between mud and formation water";i:1;s:17:"Rock permeability";i:2;s:13:"Bed thickness";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000102','Pada zona yang terinvasi (invaded zone) oleh mud filtrate yang bersifat fresh, bagaimana respon resistivitas yang terukur?','option','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:32:"Resistivitas cenderung meningkat";i:1;s:30:"Resistivitas cenderung menurun";i:2;s:38:"Resistivitas tidak berubah sama sekali";i:3;s:24:"Resistivitas menjadi nol";}','','Resistivitas cenderung meningkat','In a zone invaded by fresh mud filtrate, how does the measured resistivity respond?','a:4:{i:0;s:29:"Resistivity tends to increase";i:1;s:29:"Resistivity tends to decrease";i:2;s:34:"Resistivity does not change at all";i:3;s:24:"Resistivity becomes zero";}','Resistivity tends to increase','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000103','Alat log yang digunakan untuk mengukur resistivitas zona dalam (deep investigation) agar meminimalkan efek invasi adalah?','option','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:19:"Induction Log (ILD)";i:1;s:21:"Laterolog Micro (LL8)";i:2;s:14:"Microlaterolog";i:3;s:13:"Proximity Log";}','','Induction Log (ILD)','Which logging tool is used to measure deep investigation resistivity to minimize invasion effects?','a:4:{i:0;s:19:"Induction Log (ILD)";i:1;s:21:"Laterolog Micro (LL8)";i:2;s:14:"Microlaterolog";i:3;s:13:"Proximity Log";}','Induction Log (ILD)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000104','Apa keuntungan utama dari penggunaan Array Induction Tool (AIT) dibandingkan Induction Log konvensional?','option','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:70:"Memberikan resolusi vertikal yang lebih baik dan pembacaan multi-depth";i:1;s:53:"Hanya bisa digunakan di sumur dengan lumpur oil-based";i:2;s:31:"Tidak memerlukan kalibrasi alat";i:3;s:59:"Dapat mengukur porositas secara langsung tanpa alat neutron";}','','Memberikan resolusi vertikal yang lebih baik dan pembacaan multi-depth','What is the main advantage of using the Array Induction Tool (AIT) compared to conventional Induction Logs?','a:4:{i:0;s:60:"Provides better vertical resolution and multi-depth readings";i:1;s:39:"Can only be used in oil-based mud wells";i:2;s:33:"Does not require tool calibration";i:3;s:51:"Can measure porosity directly without neutron tools";}','Provides better vertical resolution and multi-depth readings','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000105','Fenomena apa yang terjadi ketika mud filtrate masuk ke dalam formasi permeabel dan mendorong fluida asli menjauh?','option','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:6:"Invasi";i:1;s:6:"Difusi";i:2;s:8:"Ekspansi";i:3;s:11:"Presipitasi";}','','Invasi','What phenomenon occurs when mud filtrate enters a permeable formation and pushes the original fluids away?','a:4:{i:0;s:8:"Invasion";i:1;s:9:"Diffusion";i:2;s:9:"Expansion";i:3;s:13:"Precipitation";}','Invasion','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000106','Jika formasi mengandung hidrokarbon, bagaimana karakteristik pembacaan resistivitas dalam (Rt) dibandingkan dengan resistivitas zona terinvasi (Rxo)?','option','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:27:"Rt lebih besar daripada Rxo";i:1;s:27:"Rt lebih kecil daripada Rxo";i:2;s:18:"Rt sama dengan Rxo";i:3;s:34:"Tidak ada hubungan antara keduanya";}','','Rt lebih besar daripada Rxo','If the formation contains hydrocarbons, how does the deep resistivity (Rt) reading compare to the flushed zone resistivity (Rxo)?','a:4:{i:0;s:22:"Rt is greater than Rxo";i:1;s:19:"Rt is less than Rxo";i:2;s:18:"Rt is equal to Rxo";i:3;s:37:"There is no relationship between them";}','Rt is greater than Rxo','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000107','Laterolog (LL) lebih efektif digunakan pada kondisi sumur seperti apa?','option','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:28:"Lumpur konduktif (mud salin)";i:1;s:36:"Lumpur non-konduktif (oil-based mud)";i:2;s:28:"Formasi dengan porositas nol";i:3;s:19:"Formasi batuan beku";}','','Lumpur konduktif (mud salin)','In what well conditions is the Laterolog (LL) more effective?','a:4:{i:0;s:27:"Conductive mud (saline mud)";i:1;s:34:"Non-conductive mud (oil-based mud)";i:2;s:23:"Zero porosity formation";i:3;s:22:"Igneous rock formation";}','Conductive mud (saline mud)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000108','Apa yang dimaksud dengan zona ''flushed'' dalam konteks invasi?','option','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:90:"Bagian terdekat dari lubang bor di mana hampir semua fluida formasi asli telah tergantikan";i:1;s:51:"Zona yang tidak terpengaruh oleh lumpur sama sekali";i:2;s:44:"Zona di mana mud cake terbentuk paling tebal";i:3;s:55:"Bagian formasi yang memiliki resistivitas paling tinggi";}','','Bagian terdekat dari lubang bor di mana hampir semua fluida formasi asli telah tergantikan','What is meant by the ''flushed'' zone in the context of invasion?','a:4:{i:0;s:95:"The part closest to the borehole where almost all original formation fluids have been displaced";i:1;s:33:"A zone not affected by mud at all";i:2;s:35:"The zone where mud cake is thickest";i:3;s:54:"The part of the formation with the highest resistivity";}','The part closest to the borehole where almost all original formation fluids have been displaced','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000109','Mengapa kurva resistivitas dangkal (shallow resistivity) sangat penting dalam interpretasi petrofisika?','multi','PFS000000011','Ujian Pelajaran','a:4:{i:0;s:47:"Untuk menghitung saturasi air di zona terinvasi";i:1;s:48:"Untuk mengevaluasi kedalaman invasi mud filtrate";i:2;s:39:"Untuk menentukan porositas total batuan";i:3;s:65:"Sebagai perbandingan untuk koreksi invasi pada resistivitas dalam";}','','a:3:{i:0;s:47:"Untuk menghitung saturasi air di zona terinvasi";i:1;s:48:"Untuk mengevaluasi kedalaman invasi mud filtrate";i:2;s:65:"Sebagai perbandingan untuk koreksi invasi pada resistivitas dalam";}','Why is the shallow resistivity curve very important in petrophysical interpretation?','a:4:{i:0;s:49:"To calculate water saturation in the invaded zone";i:1;s:46:"To evaluate the depth of mud filtrate invasion";i:2;s:32:"To determine total rock porosity";i:3;s:59:"As a comparison for invasion correction on deep resistivity";}','a:3:{i:0;s:49:"To calculate water saturation in the invaded zone";i:1;s:46:"To evaluate the depth of mud filtrate invasion";i:2;s:59:"As a comparison for invasion correction on deep resistivity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000110','Log neutron mengukur porositas batuan dengan cara mendeteksi konsentrasi atom apa di dalam formasi?','option','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:8:"Hidrogen";i:1;s:6:"Karbon";i:2;s:7:"Silikon";i:3;s:7:"Kalsium";}','','Hidrogen','The neutron log measures rock porosity by detecting the concentration of which atom in the formation?','a:4:{i:0;s:8:"Hydrogen";i:1;s:6:"Carbon";i:2;s:7:"Silicon";i:3;s:7:"Calcium";}','Hydrogen','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000111','Manakah pernyataan yang benar mengenai prinsip dasar log densitas?','option','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:53:"Mengukur atenuasi sinar gamma akibat hamburan Compton";i:1;s:37:"Mengukur waktu tempuh gelombang suara";i:2;s:34:"Mengukur penyerapan neutron termal";i:3;s:37:"Mengukur resistivitas listrik formasi";}','','Mengukur atenuasi sinar gamma akibat hamburan Compton','Which statement is correct regarding the basic principle of the density log?','a:4:{i:0;s:56:"Measures gamma ray attenuation due to Compton scattering";i:1;s:34:"Measures acoustic wave travel time";i:2;s:35:"Measures thermal neutron absorption";i:3;s:41:"Measures formation electrical resistivity";}','Measures gamma ray attenuation due to Compton scattering','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000112','Log sonic (akustik) mengukur parameter apa untuk menentukan porositas?','option','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:31:"Interval transit time (delta t)";i:1;s:13:"Densitas bulk";i:2;s:15:"Indeks hidrogen";i:3;s:20:"Radioaktivitas alami";}','','Interval transit time (delta t)','What parameter does the sonic (acoustic) log measure to determine porosity?','a:4:{i:0;s:31:"Interval transit time (delta t)";i:1;s:12:"Bulk density";i:2;s:14:"Hydrogen index";i:3;s:21:"Natural radioactivity";}','Interval transit time (delta t)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000113','Faktor apa saja yang dapat menyebabkan pembacaan log neutron menjadi terlalu tinggi (overestimate)?','multi','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:33:"Kehadiran mineral lempung (shale)";i:1;s:24:"Adanya gas dalam formasi";i:2;s:41:"Lubang sumur yang terlalu besar (washout)";i:3;s:33:"Salinitas air formasi yang tinggi";}','','a:2:{i:0;s:33:"Kehadiran mineral lempung (shale)";i:1;s:41:"Lubang sumur yang terlalu besar (washout)";}','Which factors can cause neutron log readings to be overestimated?','a:4:{i:0;s:33:"Presence of clay minerals (shale)";i:1;s:32:"Presence of gas in the formation";i:2;s:29:"Over-sized borehole (washout)";i:3;s:29:"High formation water salinity";}','a:2:{i:0;s:33:"Presence of clay minerals (shale)";i:1;s:29:"Over-sized borehole (washout)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000114','Persamaan Wyllie Time-Average digunakan untuk menghitung porositas berdasarkan data dari log apa?','option','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:9:"Log sonic";i:1;s:12:"Log densitas";i:2;s:11:"Log neutron";i:3;s:11:"Log kaliper";}','','Log sonic','The Wyllie Time-Average equation is used to calculate porosity based on data from which log?','a:4:{i:0;s:9:"Sonic log";i:1;s:11:"Density log";i:2;s:11:"Neutron log";i:3;s:11:"Caliper log";}','Sonic log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000115','Pada formasi batupasir yang mengandung gas, apa dampak yang terlihat pada plot silang (crossplot) densitas-neutron?','option','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:55:"Separasi ''gas effect'' (neutron rendah, densitas rendah)";i:1;s:55:"Separasi ''gas effect'' (neutron rendah, densitas tinggi)";i:2;s:36:"Neutron dan densitas tetap berhimpit";i:3;s:43:"Peningkatan porositas densitas yang ekstrem";}','','Separasi ''gas effect'' (neutron rendah, densitas rendah)','In a gas-bearing sandstone formation, what effect is visible on the density-neutron crossplot?','a:4:{i:0;s:50:"''Gas effect'' separation (low neutron, low density)";i:1;s:51:"''Gas effect'' separation (low neutron, high density)";i:2;s:37:"Neutron and density remain coincident";i:3;s:36:"Extreme increase in density porosity";}','''Gas effect'' separation (low neutron, low density)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000116','Apa yang dimaksud dengan ''Secondary Porosity Index'' (SPI) dalam evaluasi log sonic?','option','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:88:"Selisih antara porositas total (dari densitas/neutron) dan porositas primer (dari sonic)";i:1;s:63:"Porositas yang diukur hanya pada lubang sumur yang tidak stabil";i:2;s:42:"Porositas yang dihitung dari log gamma ray";i:3;s:42:"Porositas batuan akibat tekanan overburden";}','','Selisih antara porositas total (dari densitas/neutron) dan porositas primer (dari sonic)','What is meant by ''Secondary Porosity Index'' (SPI) in sonic log evaluation?','a:4:{i:0;s:94:"The difference between total porosity (from density/neutron) and primary porosity (from sonic)";i:1;s:44:"Porosity measured only in unstable boreholes";i:2;s:39:"Porosity calculated from gamma ray logs";i:3;s:40:"Rock porosity due to overburden pressure";}','The difference between total porosity (from density/neutron) and primary porosity (from sonic)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000117','Manakah pernyataan yang benar mengenai pengaruh litologi terhadap log densitas?','option','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:61:"Log densitas sangat sensitif terhadap densitas matriks batuan";i:1;s:49:"Log densitas tidak terpengaruh oleh jenis mineral";i:2;s:42:"Log densitas hanya dipengaruhi oleh fluida";i:3;s:74:"Log densitas selalu memberikan porositas yang benar tanpa koreksi litologi";}','','Log densitas sangat sensitif terhadap densitas matriks batuan','Which statement is correct regarding the effect of lithology on the density log?','a:4:{i:0;s:56:"The density log is very sensitive to rock matrix density";i:1;s:45:"The density log is unaffected by mineral type";i:2;s:42:"The density log is only affected by fluids";i:3;s:77:"The density log always provides correct porosity without lithology correction";}','The density log is very sensitive to rock matrix density','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000118','Sumber radioaktif yang umumnya digunakan pada alat log densitas adalah?','option','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:10:"Cesium-137";i:1;s:13:"Americium-241";i:2;s:9:"Cobalt-60";i:3;s:11:"Uranium-238";}','','Cesium-137','The radioactive source commonly used in density logging tools is?','a:4:{i:0;s:10:"Cesium-137";i:1;s:13:"Americium-241";i:2;s:9:"Cobalt-60";i:3;s:11:"Uranium-238";}','Cesium-137','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000119','Mengapa penggunaan log densitas dan log neutron secara bersamaan sangat krusial dalam evaluasi formasi?','multi','PFS000000012','Ujian Pelajaran','a:4:{i:0;s:33:"Untuk menentukan litologi formasi";i:1;s:27:"Untuk mendeteksi adanya gas";i:2;s:44:"Untuk mengukur permeabilitas secara langsung";i:3;s:39:"Untuk mengidentifikasi jenis clay shale";}','','a:2:{i:0;s:33:"Untuk menentukan litologi formasi";i:1;s:27:"Untuk mendeteksi adanya gas";}','Why is the combined use of density and neutron logs crucial in formation evaluation?','a:4:{i:0;s:32:"To determine formation lithology";i:1;s:29:"To detect the presence of gas";i:2;s:32:"To measure permeability directly";i:3;s:28:"To identify shale clay types";}','a:2:{i:0;s:32:"To determine formation lithology";i:1;s:29:"To detect the presence of gas";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000120','Parameter utama yang digunakan untuk menghitung volume shale (Vsh) menggunakan log Gamma Ray adalah...','option','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:22:"Indeks Gamma Ray (IGR)";i:1;s:12:"Saturasi air";i:2;s:23:"Permeabilitas intrinsik";i:3;s:18:"Porositas sekunder";}','','Indeks Gamma Ray (IGR)','The main parameter used to calculate shale volume (Vsh) using Gamma Ray logs is...','a:4:{i:0;s:21:"Gamma Ray Index (IGR)";i:1;s:16:"Water saturation";i:2;s:22:"Intrinsic permeability";i:3;s:18:"Secondary porosity";}','Gamma Ray Index (IGR)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000121','Faktor apa saja yang harus dipertimbangkan saat melakukan koreksi shale pada perhitungan porositas efektif?','multi','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:18:"Volume shale (Vsh)";i:1;s:21:"Jenis mineral lempung";i:2;s:24:"Saturasi minyak residual";i:3;s:30:"Kekompakan batuan (compaction)";}','','a:2:{i:0;s:18:"Volume shale (Vsh)";i:1;s:21:"Jenis mineral lempung";}','What factors must be considered when applying shale corrections to effective porosity calculations?','a:4:{i:0;s:18:"Shale volume (Vsh)";i:1;s:17:"Clay mineral type";i:2;s:23:"Residual oil saturation";i:3;s:15:"Rock compaction";}','a:2:{i:0;s:18:"Shale volume (Vsh)";i:1;s:17:"Clay mineral type";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000122','Pada kondisi bersih (clean sand), berapakah nilai IGR yang ideal?','option','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:1:"0";i:1;s:3:"0.5";i:2;s:1:"1";i:3;s:1:"2";}','','0','In clean sand conditions, what is the ideal IGR value?','a:4:{i:0;s:1:"0";i:1;s:3:"0.5";i:2;s:1:"1";i:3;s:1:"2";}','0','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000123','Apa dampak keberadaan shale terhadap porositas total yang terukur oleh alat logging?','option','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:64:"Menyebabkan porositas terbaca lebih besar dari porositas efektif";i:1;s:23:"Tidak memberikan dampak";i:2;s:35:"Menghilangkan efek porositas primer";i:3;s:26:"Meningkatkan permeabilitas";}','','Menyebabkan porositas terbaca lebih besar dari porositas efektif','What is the impact of shale presence on the total porosity measured by logging tools?','a:4:{i:0;s:57:"Causes porosity to be read higher than effective porosity";i:1;s:13:"Has no impact";i:2;s:35:"Eliminates primary porosity effects";i:3;s:22:"Increases permeability";}','Causes porosity to be read higher than effective porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000124','Rumus linear sederhana untuk menghitung Vsh adalah Vsh = (GRlog - GRclean) / (GRshale - GRclean). Apa batasan utama rumus ini?','option','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:65:"Sering memberikan nilai Vsh yang terlalu optimis (terlalu rendah)";i:1;s:31:"Tidak memerlukan nilai GR clean";i:2;s:35:"Hanya berlaku untuk batuan karbonat";i:3;s:28:"Memerlukan data tekanan pori";}','','Sering memberikan nilai Vsh yang terlalu optimis (terlalu rendah)','The simple linear formula for calculating Vsh is Vsh = (GRlog - GRclean) / (GRshale - GRclean). What is the main limitation of this formula?','a:4:{i:0;s:53:"Often provides overly optimistic (too low) Vsh values";i:1;s:32:"Does not require GR clean values";i:2;s:31:"Only applies to carbonate rocks";i:3;s:27:"Requires pore pressure data";}','Often provides overly optimistic (too low) Vsh values','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000125','Manakah pernyataan yang benar mengenai porositas efektif?','option','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:88:"Bagian dari porositas total yang saling terhubung dan tidak terikat oleh mineral lempung";i:1;s:30:"Total volume pori dalam batuan";i:2;s:45:"Porositas yang dihitung sebelum koreksi shale";i:3;s:43:"Porositas yang hanya diukur di laboratorium";}','','Bagian dari porositas total yang saling terhubung dan tidak terikat oleh mineral lempung','Which statement is correct regarding effective porosity?','a:4:{i:0;s:80:"The part of total porosity that is interconnected and not bound by clay minerals";i:1;s:29:"The total pore volume in rock";i:2;s:43:"Porosity calculated before shale correction";i:3;s:40:"Porosity measured only in the laboratory";}','The part of total porosity that is interconnected and not bound by clay minerals','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000126','Kapan penggunaan koreksi shale non-linear (seperti rumus Steiber atau Clavier) lebih disarankan?','multi','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:37:"Pada formasi muda atau unconsolidated";i:1;s:61:"Ketika data GR menunjukkan adanya variasi shale yang kompleks";i:2;s:39:"Pada formasi karbonat yang sangat murni";i:3;s:43:"Ketika nilai GR log konstan sepanjang sumur";}','','a:2:{i:0;s:37:"Pada formasi muda atau unconsolidated";i:1;s:61:"Ketika data GR menunjukkan adanya variasi shale yang kompleks";}','When is the use of non-linear shale corrections (such as Steiber or Clavier formulas) more recommended?','a:4:{i:0;s:37:"In young or unconsolidated formations";i:1;s:43:"When GR data shows complex shale variations";i:2;s:33:"In very pure carbonate formations";i:3;s:51:"When GR log values are constant throughout the well";}','a:2:{i:0;s:37:"In young or unconsolidated formations";i:1;s:43:"When GR data shows complex shale variations";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000127','Log SP (Spontaneous Potential) dapat digunakan untuk menentukan volume shale dengan cara membandingkan defleksi SP pada zona formasi dengan...','option','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:41:"Defleksi SP pada zona shale (SSP dan PSP)";i:1;s:19:"Resistivitas batuan";i:2;s:13:"Densitas bulk";i:3;s:22:"Nilai neutron porosity";}','','Defleksi SP pada zona shale (SSP dan PSP)','The SP log can be used to determine shale volume by comparing the SP deflection in the formation zone with...','a:4:{i:0;s:45:"SP deflection in the shale zone (SSP and PSP)";i:1;s:16:"Rock resistivity";i:2;s:12:"Bulk density";i:3;s:22:"Neutron porosity value";}','SP deflection in the shale zone (SSP and PSP)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000128','Apa pengaruh air terikat lempung (bound water) pada perhitungan porositas dari log densitas?','option','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:62:"Menyebabkan nilai porositas yang terhitung menjadi lebih besar";i:1;s:33:"Menurunkan nilai densitas matriks";i:2;s:24:"Tidak mempengaruhi hasil";i:3;s:29:"Membuat porositas menjadi nol";}','','Menyebabkan nilai porositas yang terhitung menjadi lebih besar','What is the effect of clay-bound water on porosity calculations from density logs?','a:4:{i:0;s:49:"Causes the calculated porosity value to be higher";i:1;s:31:"Lowers the matrix density value";i:2;s:27:"Does not affect the results";i:3;s:19:"Makes porosity zero";}','Causes the calculated porosity value to be higher','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000129','Untuk menghitung porositas efektif dari porositas total, parameter apa yang biasanya dikurangkan?','option','PFS000000013','Ujian Pelajaran','a:4:{i:0;s:62:"Produk dari volume shale (Vsh) dan porositas shale (phi_shale)";i:1;s:27:"Nilai permeabilitas absolut";i:2;s:17:"Saturasi air sisa";i:3;s:15:"Tekanan kapiler";}','','Produk dari volume shale (Vsh) dan porositas shale (phi_shale)','To calculate effective porosity from total porosity, what parameter is usually subtracted?','a:4:{i:0;s:64:"The product of shale volume (Vsh) and shale porosity (phi_shale)";i:1;s:27:"Absolute permeability value";i:2;s:25:"Residual water saturation";i:3;s:18:"Capillary pressure";}','The product of shale volume (Vsh) and shale porosity (phi_shale)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000130','Dalam persamaan Archie, berapakah nilai eksponen sementasi (m) yang umum digunakan untuk batuan pasir (sandstone) yang terkonsolidasi?','option','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:3:"1.0";i:1;s:3:"1.5";i:2;s:3:"2.0";i:3;s:3:"3.0";}','','2.0','In the Archie equation, what is the typical cementation exponent (m) value used for consolidated sandstone?','a:4:{i:0;s:3:"1.0";i:1;s:3:"1.5";i:2;s:3:"2.0";i:3;s:3:"3.0";}','2.0','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000131','Faktor formasi (F) didefinisikan sebagai rasio antara resistivitas batuan yang jenuh air 100% (Ro) terhadap apa?','option','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:27:"Resistivitas filtrat lumpur";i:1;s:24:"Resistivitas air formasi";i:2;s:25:"Resistivitas batuan total";i:3;s:27:"Resistivitas zona terinvasi";}','','Resistivitas air formasi','Formation factor (F) is defined as the ratio between the resistivity of a 100% water-saturated rock (Ro) and what?','a:4:{i:0;s:24:"Mud filtrate resistivity";i:1;s:27:"Formation water resistivity";i:2;s:22:"Total rock resistivity";i:3;s:24:"Invaded zone resistivity";}','Formation water resistivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000132','Parameter apa saja yang secara langsung mempengaruhi besarnya faktor formasi (F) dalam model Archie?','multi','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:9:"Porositas";i:1;s:22:"Eksponen sementasi (m)";i:2;s:17:"Saturasi air (Sw)";i:3;s:22:"Faktor tortuositas (a)";}','','a:3:{i:0;s:9:"Porositas";i:1;s:22:"Eksponen sementasi (m)";i:2;s:22:"Faktor tortuositas (a)";}','Which parameters directly affect the formation factor (F) in the Archie model?','a:4:{i:0;s:8:"Porosity";i:1;s:24:"Cementation exponent (m)";i:2;s:21:"Water saturation (Sw)";i:3;s:21:"Tortuosity factor (a)";}','a:3:{i:0;s:8:"Porosity";i:1;s:24:"Cementation exponent (m)";i:2;s:21:"Tortuosity factor (a)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000133','Jika resistivitas air formasi (Rw) meningkat, maka untuk nilai porositas yang tetap, bagaimanakah pengaruhnya terhadap resistivitas batuan (Ro)?','option','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:17:"Ro akan meningkat";i:1;s:15:"Ro akan menurun";i:2;s:16:"Ro tidak berubah";i:3;s:28:"Ro menjadi tidak terdefinisi";}','','Ro akan meningkat','If the formation water resistivity (Rw) increases, what is the effect on the rock resistivity (Ro) assuming constant porosity?','a:4:{i:0;s:16:"Ro will increase";i:1;s:16:"Ro will decrease";i:2;s:24:"Ro will remain unchanged";i:3;s:20:"Ro becomes undefined";}','Ro will increase','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000134','Apa yang dimaksud dengan indeks resistivitas (I) dalam hubungan Archie?','option','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:20:"Rasio Rt terhadap Ro";i:1;s:20:"Rasio Rw terhadap Rt";i:2;s:20:"Rasio Rt terhadap Rw";i:3;s:27:"Rasio Sw terhadap porositas";}','','Rasio Rt terhadap Ro','What is meant by the resistivity index (I) in the Archie relationship?','a:4:{i:0;s:17:"Ratio of Rt to Ro";i:1;s:17:"Ratio of Rw to Rt";i:2;s:17:"Ratio of Rt to Rw";i:3;s:23:"Ratio of Sw to porosity";}','Ratio of Rt to Ro','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000135','Dalam persamaan Archie, eksponen saturasi (n) umumnya diasumsikan bernilai berapa untuk kebanyakan reservoir?','option','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:3:"1.0";i:1;s:3:"2.0";i:2;s:3:"3.0";i:3;s:3:"0.5";}','','2.0','In the Archie equation, the saturation exponent (n) is generally assumed to be what value for most reservoirs?','a:4:{i:0;s:3:"1.0";i:1;s:3:"2.0";i:2;s:3:"3.0";i:3;s:3:"0.5";}','2.0','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000136','Batasan utama penggunaan persamaan Archie adalah?','option','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:58:"Hanya berlaku untuk batuan dengan kandungan lempung tinggi";i:1;s:67:"Hanya berlaku untuk formasi yang tidak mengandung mineral konduktif";i:2;s:36:"Hanya berlaku pada kedalaman dangkal";i:3;s:45:"Hanya berlaku jika hidrokarbon dalam fase gas";}','','Hanya berlaku untuk formasi yang tidak mengandung mineral konduktif','What is the main limitation of using the Archie equation?','a:4:{i:0;s:38:"Only valid for high clay content rocks";i:1;s:53:"Only valid for formations without conductive minerals";i:2;s:28:"Only valid at shallow depths";i:3;s:47:"Only valid if hydrocarbons are in the gas phase";}','Only valid for formations without conductive minerals','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000137','Jika nilai indeks resistivitas (I) adalah 4, dan eksponen saturasi (n) adalah 2, berapakah saturasi air (Sw) batuan tersebut?','option','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:4:"0.25";i:1;s:4:"0.50";i:2;s:4:"0.75";i:3;s:4:"0.10";}','','0.50','If the resistivity index (I) is 4, and the saturation exponent (n) is 2, what is the water saturation (Sw) of the rock?','a:4:{i:0;s:4:"0.25";i:1;s:4:"0.50";i:2;s:4:"0.75";i:3;s:4:"0.10";}','0.50','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000138','Parameter ''a'' dalam persamaan Archie (F = a / phi^m) merepresentasikan apa?','option','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:18:"Eksponen sementasi";i:1;s:21:"Koefisien tortuositas";i:2;s:12:"Saturasi air";i:3;s:20:"Resistivitas formasi";}','','Koefisien tortuositas','What does the parameter ''a'' in the Archie equation (F = a / phi^m) represent?','a:4:{i:0;s:20:"Cementation exponent";i:1;s:22:"Tortuosity coefficient";i:2;s:16:"Water saturation";i:3;s:21:"Formation resistivity";}','Tortuosity coefficient','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000139','Manakah pernyataan yang benar mengenai hubungan resistivitas batuan (Rt) dengan saturasi air (Sw) menurut Archie?','option','PFS000000014','Ujian Pelajaran','a:4:{i:0;s:29:"Rt berbanding lurus dengan Sw";i:1;s:34:"Rt berbanding terbalik dengan Sw^n";i:2;s:28:"Rt tidak dipengaruhi oleh Sw";i:3;s:31:"Rt berbanding lurus dengan Sw^2";}','','Rt berbanding terbalik dengan Sw^n','Which statement is correct regarding the relationship between rock resistivity (Rt) and water saturation (Sw) according to Archie?','a:4:{i:0;s:33:"Rt is directly proportional to Sw";i:1;s:36:"Rt is inversely proportional to Sw^n";i:2;s:26:"Rt is not influenced by Sw";i:3;s:35:"Rt is directly proportional to Sw^2";}','Rt is inversely proportional to Sw^n','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000140','Apakah perbedaan utama antara net reservoir dan net pay dalam evaluasi formasi?','option','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:128:"Net reservoir mencakup seluruh zona berpori, sedangkan net pay mencakup zona berpori yang memiliki saturasi hidrokarbon ekonomis";i:1;s:85:"Net pay mencakup seluruh zona permeabel, sedangkan net reservoir hanya zona produktif";i:2;s:35:"Tidak ada perbedaan antara keduanya";i:3;s:63:"Net reservoir hanya mencakup batuan dengan permeabilitas tinggi";}','','Net reservoir mencakup seluruh zona berpori, sedangkan net pay mencakup zona berpori yang memiliki saturasi hidrokarbon ekonomis','What is the main difference between net reservoir and net pay in formation evaluation?','a:4:{i:0;s:113:"Net reservoir includes all porous zones, while net pay includes porous zones with economic hydrocarbon saturation";i:1;s:88:"Net pay includes all permeable zones, while net reservoir only includes productive zones";i:2;s:35:"There is no difference between them";i:3;s:51:"Net reservoir only includes high permeability rocks";}','Net reservoir includes all porous zones, while net pay includes porous zones with economic hydrocarbon saturation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000141','Dalam penentuan cut-off, parameter apa saja yang biasanya digunakan untuk mendefinisikan net reservoir?','multi','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:17:"Porositas minimum";i:1;s:21:"Saturasi air maksimum";i:2;s:21:"Volume shale maksimum";i:3;s:15:"Tekanan formasi";}','','a:2:{i:0;s:17:"Porositas minimum";i:1;s:21:"Volume shale maksimum";}','In determining cut-offs, which parameters are typically used to define net reservoir?','a:4:{i:0;s:16:"Minimum porosity";i:1;s:24:"Maximum water saturation";i:2;s:20:"Maximum shale volume";i:3;s:18:"Formation pressure";}','a:2:{i:0;s:16:"Minimum porosity";i:1;s:20:"Maximum shale volume";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000142','Apa tujuan utama dari korelasi log antar sumur dalam sebuah lapangan?','option','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:46:"Untuk memahami kesinambungan lateral reservoir";i:1;s:43:"Untuk menghitung cadangan secara volumetrik";i:2;s:49:"Untuk menentukan jenis fluida di dalam lubang bor";i:3;s:32:"Untuk mengkalibrasi alat logging";}','','Untuk memahami kesinambungan lateral reservoir','What is the primary purpose of log correlation between wells in a field?','a:4:{i:0;s:53:"To understand the lateral continuity of the reservoir";i:1;s:36:"To calculate reserves volumetrically";i:2;s:40:"To determine fluid types in the borehole";i:3;s:26:"To calibrate logging tools";}','To understand the lateral continuity of the reservoir','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000143','Log apa yang paling umum digunakan sebagai penanda (marker) utama dalam korelasi log untuk menentukan zonasi?','option','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:13:"Log Gamma Ray";i:1;s:12:"Log Densitas";i:2;s:11:"Log Neutron";i:3;s:16:"Log Resistivitas";}','','Log Gamma Ray','Which log is most commonly used as a primary marker in log correlation to determine zonation?','a:4:{i:0;s:13:"Gamma Ray log";i:1;s:11:"Density log";i:2;s:11:"Neutron log";i:3;s:15:"Resistivity log";}','Gamma Ray log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000144','Mengapa penentuan cut-off saturasi air (Sw) sangat krusial dalam perhitungan net pay?','option','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:57:"Karena Sw menentukan batas ekonomis akumulasi hidrokarbon";i:1;s:50:"Karena Sw selalu berbanding lurus dengan porositas";i:2;s:48:"Karena Sw tidak berpengaruh pada volume cadangan";i:3;s:52:"Karena Sw digunakan untuk mengkalibrasi log densitas";}','','Karena Sw menentukan batas ekonomis akumulasi hidrokarbon','Why is the determination of water saturation (Sw) cut-off crucial in net pay calculations?','a:4:{i:0;s:68:"Because Sw determines the economic limit of hydrocarbon accumulation";i:1;s:54:"Because Sw is always directly proportional to porosity";i:2;s:42:"Because Sw has no effect on reserve volume";i:3;s:47:"Because Sw is used to calibrate the density log";}','Because Sw determines the economic limit of hydrocarbon accumulation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000145','Apa dampak menetapkan nilai cut-off volume shale (Vsh) yang terlalu rendah?','option','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:20:"Overestimasi net pay";i:1;s:21:"Underestimasi net pay";i:2;s:29:"Tidak ada dampak pada net pay";i:3;s:27:"Peningkatan porositas total";}','','Underestimasi net pay','What is the impact of setting a shale volume (Vsh) cut-off value that is too low?','a:4:{i:0;s:25:"Overestimation of net pay";i:1;s:26:"Underestimation of net pay";i:2;s:20:"No impact on net pay";i:3;s:26:"Increase in total porosity";}','Underestimation of net pay','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000146','Dalam penyajian hasil evaluasi petrofisika (composite log), data apa yang harus ditampilkan bersamaan?','multi','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:14:"Kurva log asli";i:1;s:39:"Hasil interpretasi (porositas, Sw, Vsh)";i:2;s:38:"Zona net pay yang telah diidentifikasi";i:3;s:17:"Harga jual minyak";}','','a:3:{i:0;s:14:"Kurva log asli";i:1;s:39:"Hasil interpretasi (porositas, Sw, Vsh)";i:2;s:38:"Zona net pay yang telah diidentifikasi";}','In the presentation of petrophysical evaluation results (composite log), what data should be displayed together?','a:4:{i:0;s:19:"Original log curves";i:1;s:42:"Interpretation results (porosity, Sw, Vsh)";i:2;s:24:"Identified net pay zones";i:3;s:17:"Oil selling price";}','a:3:{i:0;s:19:"Original log curves";i:1;s:42:"Interpretation results (porosity, Sw, Vsh)";i:2;s:24:"Identified net pay zones";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000147','Apa yang dimaksud dengan korelasi stratigrafi dalam konteks zonasi log?','option','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:91:"Menghubungkan interval yang memiliki umur geologi atau karakteristik deposisional yang sama";i:1;s:56:"Menghubungkan sumur berdasarkan kedalaman yang sama saja";i:2;s:62:"Menghubungkan sumur berdasarkan tingkat resistivitas tertinggi";i:3;s:48:"Menghubungkan zona berdasarkan tekanan reservoir";}','','Menghubungkan interval yang memiliki umur geologi atau karakteristik deposisional yang sama','What is meant by stratigraphic correlation in the context of log zonation?','a:4:{i:0;s:86:"Connecting intervals that have the same geological age or depositional characteristics";i:1;s:45:"Connecting wells based on the same depth only";i:2;s:56:"Connecting wells based on the highest resistivity levels";i:3;s:44:"Connecting zones based on reservoir pressure";}','Connecting intervals that have the same geological age or depositional characteristics','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000148','Jika sebuah lapisan memiliki porositas 10% dan batas cut-off porositas perusahaan adalah 12%, maka lapisan tersebut dikategorikan sebagai apa?','option','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:13:"Non-reservoir";i:1;s:13:"Net reservoir";i:2;s:7:"Net pay";i:3;s:22:"High-quality reservoir";}','','Non-reservoir','If a layer has a porosity of 10% and the company''s porosity cut-off is 12%, how is that layer categorized?','a:4:{i:0;s:13:"Non-reservoir";i:1;s:13:"Net reservoir";i:2;s:7:"Net pay";i:3;s:22:"High-quality reservoir";}','Non-reservoir','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000149','Apa fungsi utama dari pembuatan zonasi formasi sebelum melakukan perhitungan volumetrik?','option','PFS000000015','Ujian Pelajaran','a:4:{i:0;s:70:"Untuk mengelompokkan reservoir dengan properti petrofisika yang serupa";i:1;s:35:"Untuk mempercepat proses pengeboran";i:2;s:34:"Untuk meningkatkan tekanan formasi";i:3;s:29:"Untuk mengurangi saturasi air";}','','Untuk mengelompokkan reservoir dengan properti petrofisika yang serupa','What is the main function of creating formation zonation before performing volumetric calculations?','a:4:{i:0;s:57:"To group reservoirs with similar petrophysical properties";i:1;s:34:"To accelerate the drilling process";i:2;s:30:"To increase formation pressure";i:3;s:26:"To reduce water saturation";}','To group reservoirs with similar petrophysical properties','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000150','Parameter utama apa yang mendefinisikan perbedaan tekanan antara dua fluida yang tidak bercampur dalam ruang pori?','option','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:15:"Tekanan kapiler";i:1;s:15:"Tekanan formasi";i:2;s:18:"Tekanan overburden";i:3;s:19:"Tekanan hidrostatik";}','','Tekanan kapiler','What is the main parameter that defines the pressure difference between two immiscible fluids in a pore space?','a:4:{i:0;s:18:"Capillary pressure";i:1;s:18:"Formation pressure";i:2;s:19:"Overburden pressure";i:3;s:20:"Hydrostatic pressure";}','Capillary pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000151','Faktor apa saja yang memengaruhi besarnya tekanan kapiler dalam medium berpori?','multi','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:18:"Tegangan antarmuka";i:1;s:12:"Sudut kontak";i:2;s:21:"Permeabilitas absolut";i:3;s:14:"Jari-jari pori";}','','a:3:{i:0;s:18:"Tegangan antarmuka";i:1;s:12:"Sudut kontak";i:2;s:14:"Jari-jari pori";}','What factors influence the magnitude of capillary pressure in a porous medium?','a:4:{i:0;s:19:"Interfacial tension";i:1;s:13:"Contact angle";i:2;s:21:"Absolute permeability";i:3;s:11:"Pore radius";}','a:3:{i:0;s:19:"Interfacial tension";i:1;s:13:"Contact angle";i:2;s:11:"Pore radius";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000152','Dalam sistem batuan oil-wet, manakah pernyataan yang benar mengenai sudut kontak (theta)?','option','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:35:"Sudut kontak kurang dari 90 derajat";i:1;s:34:"Sudut kontak sama dengan 0 derajat";i:2;s:40:"Sudut kontak lebih besar dari 90 derajat";i:3;s:43:"Sudut kontak tidak mempengaruhi wettability";}','','Sudut kontak lebih besar dari 90 derajat','In an oil-wet rock system, which statement regarding the contact angle (theta) is correct?','a:4:{i:0;s:37:"Contact angle is less than 90 degrees";i:1;s:35:"Contact angle is equal to 0 degrees";i:2;s:40:"Contact angle is greater than 90 degrees";i:3;s:41:"Contact angle does not affect wettability";}','Contact angle is greater than 90 degrees','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000153','Apa yang terjadi pada ketinggian di atas Free Water Level (FWL) jika jari-jari pori batuan semakin kecil?','option','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:30:"Ketinggian akan semakin rendah";i:1;s:30:"Ketinggian akan semakin tinggi";i:2;s:24:"Ketinggian tidak berubah";i:3;s:27:"Tekanan kapiler menjadi nol";}','','Ketinggian akan semakin tinggi','What happens to the height above the Free Water Level (FWL) if the pore radius of the rock becomes smaller?','a:4:{i:0;s:20:"Height will be lower";i:1;s:21:"Height will be higher";i:2;s:24:"Height remains unchanged";i:3;s:31:"Capillary pressure becomes zero";}','Height will be higher','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000154','Manakah pernyataan yang paling tepat mendefinisikan Free Water Level (FWL)?','option','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:45:"Level di mana tekanan kapiler sama dengan nol";i:1;s:46:"Level di mana saturasi air mencapai 100 persen";i:2;s:56:"Level di mana minyak dan air memiliki densitas yang sama";i:3;s:56:"Level di mana tekanan hidrostatik minyak sama dengan nol";}','','Level di mana tekanan kapiler sama dengan nol','Which statement best defines the Free Water Level (FWL)?','a:4:{i:0;s:46:"The level where capillary pressure equals zero";i:1;s:52:"The level where water saturation reaches 100 percent";i:2;s:51:"The level where oil and water have the same density";i:3;s:52:"The level where oil hydrostatic pressure equals zero";}','The level where capillary pressure equals zero','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000155','Bagaimana hubungan antara tegangan antarmuka (IFT) dengan tekanan kapiler?','option','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:16:"Berbanding lurus";i:1;s:19:"Berbanding terbalik";i:2;s:18:"Tidak ada hubungan";i:3;s:20:"Eksponensial negatif";}','','Berbanding lurus','What is the relationship between interfacial tension (IFT) and capillary pressure?','a:4:{i:0;s:21:"Directly proportional";i:1;s:22:"Inversely proportional";i:2;s:15:"No relationship";i:3;s:20:"Negative exponential";}','Directly proportional','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000156','Fenomena dimana fluida membasahi permukaan batuan lebih dominan dibandingkan fluida lainnya disebut sebagai?','option','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:11:"Wettability";i:1;s:13:"Permeabilitas";i:2;s:9:"Porositas";i:3;s:16:"Transmisibilitas";}','','Wettability','The phenomenon where a fluid wets the rock surface more dominantly than the other fluid is called?','a:4:{i:0;s:11:"Wettability";i:1;s:12:"Permeability";i:2;s:8:"Porosity";i:3;s:16:"Transmissibility";}','Wettability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000157','Manakah dari berikut ini yang merupakan satuan umum untuk tekanan kapiler?','option','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:3:"psi";i:1;s:5:"Darcy";i:2;s:7:"Dyne/cm";i:3;s:6:"Persen";}','','psi','Which of the following is a common unit for capillary pressure?','a:4:{i:0;s:3:"psi";i:1;s:5:"Darcy";i:2;s:7:"Dyne/cm";i:3;s:7:"Percent";}','psi','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000158','Dalam zona transisi di atas FWL, apa yang terjadi pada saturasi air terhadap ketinggian?','option','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:52:"Saturasi air menurun seiring bertambahnya ketinggian";i:1;s:54:"Saturasi air meningkat seiring bertambahnya ketinggian";i:2;s:26:"Saturasi air tetap konstan";i:3;s:33:"Saturasi air menjadi nol seketika";}','','Saturasi air menurun seiring bertambahnya ketinggian','In the transition zone above the FWL, what happens to water saturation with respect to height?','a:4:{i:0;s:49:"Water saturation decreases with increasing height";i:1;s:49:"Water saturation increases with increasing height";i:2;s:33:"Water saturation remains constant";i:3;s:39:"Water saturation becomes zero instantly";}','Water saturation decreases with increasing height','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000159','Apa yang dimaksud dengan ''Spontaneous Imbibition'' dalam konteks wettability?','option','PFS000000016','Ujian Pelajaran','a:4:{i:0;s:56:"Proses masuknya fase pembasah ke dalam pori secara alami";i:1;s:46:"Proses pengeluaran minyak dengan injeksi kimia";i:2;s:58:"Pengukuran permeabilitas relatif pada kondisi steady state";i:3;s:36:"Proses penguapan fluida di reservoir";}','','Proses masuknya fase pembasah ke dalam pori secara alami','What is meant by ''Spontaneous Imbibition'' in the context of wettability?','a:4:{i:0;s:57:"The process of the wetting phase entering pores naturally";i:1;s:52:"The process of oil recovery using chemical injection";i:2;s:66:"Measurement of relative permeability under steady-state conditions";i:3;s:49:"The process of fluid evaporation in the reservoir";}','The process of the wetting phase entering pores naturally','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000160','Metode pengukuran tekanan kapiler yang menggunakan tekanan gas untuk menekan merkuri ke dalam pori-pori sampel batuan kering adalah?','option','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:17:"Mercury Injection";i:1;s:12:"Porous Plate";i:2;s:10:"Centrifuge";i:3;s:23:"Semi-permeable Membrane";}','','Mercury Injection','Which capillary pressure measurement method uses gas pressure to force mercury into the pores of a dry rock sample?','a:4:{i:0;s:17:"Mercury Injection";i:1;s:12:"Porous Plate";i:2;s:10:"Centrifuge";i:3;s:23:"Semi-permeable Membrane";}','Mercury Injection','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000161','Apa fungsi utama dari Leverett J-function dalam analisis petrofisika?','option','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:25:"Mengoreksi data porositas";i:1;s:63:"Menormalisasi data tekanan kapiler untuk berbagai permeabilitas";i:2;s:28:"Menghitung saturasi air sisa";i:3;s:38:"Menentukan viskositas fluida reservoir";}','','Menormalisasi data tekanan kapiler untuk berbagai permeabilitas','What is the primary function of the Leverett J-function in petrophysical analysis?','a:4:{i:0;s:24:"Correcting porosity data";i:1;s:64:"Normalizing capillary pressure data for different permeabilities";i:2;s:40:"Calculating irreducible water saturation";i:3;s:37:"Determining reservoir fluid viscosity";}','Normalizing capillary pressure data for different permeabilities','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000162','Pilih dua metode yang umumnya dianggap sebagai metode kesetimbangan (equilibrium method) dalam pengukuran tekanan kapiler:','multi','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:12:"Porous Plate";i:1;s:10:"Centrifuge";i:2;s:17:"Mercury Injection";i:3;s:16:"Log Resistivitas";}','','a:2:{i:0;s:12:"Porous Plate";i:1;s:10:"Centrifuge";}','Select two methods that are generally considered as equilibrium methods in capillary pressure measurement:','a:4:{i:0;s:12:"Porous Plate";i:1;s:10:"Centrifuge";i:2;s:17:"Mercury Injection";i:3;s:15:"Resistivity Log";}','a:2:{i:0;s:12:"Porous Plate";i:1;s:10:"Centrifuge";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000163','Saturasi air sisa (Swc) pada kurva tekanan kapiler tercapai ketika:','option','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:34:"Tekanan kapiler mencapai nilai nol";i:1;s:71:"Saturasi air tidak lagi berkurang meskipun tekanan kapiler ditingkatkan";i:2;s:45:"Permeabilitas absolut mencapai nilai maksimum";i:3;s:49:"Tekanan kapiler setara dengan tekanan hidrostatik";}','','Saturasi air tidak lagi berkurang meskipun tekanan kapiler ditingkatkan','Irreducible water saturation (Swc) on a capillary pressure curve is reached when:','a:4:{i:0;s:31:"Capillary pressure reaches zero";i:1;s:76:"Water saturation no longer decreases even if capillary pressure is increased";i:2;s:47:"Absolute permeability reaches its maximum value";i:3;s:51:"Capillary pressure is equal to hydrostatic pressure";}','Water saturation no longer decreases even if capillary pressure is increased','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000164','Parameter utama yang mempengaruhi besarnya apa saja yang diperlukan untuk menghitung Leverett J-function?','multi','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:15:"Tekanan kapiler";i:1;s:13:"Permeabilitas";i:2;s:9:"Porositas";i:3;s:14:"Viskositas air";}','','a:3:{i:0;s:15:"Tekanan kapiler";i:1;s:13:"Permeabilitas";i:2;s:9:"Porositas";}','Which parameters are required to calculate the Leverett J-function?','a:4:{i:0;s:18:"Capillary pressure";i:1;s:12:"Permeability";i:2;s:8:"Porosity";i:3;s:15:"Water viscosity";}','a:3:{i:0;s:18:"Capillary pressure";i:1;s:12:"Permeability";i:2;s:8:"Porosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000165','Dalam metode centrifuge, gaya apa yang digunakan untuk melawan gaya kapiler guna mengusir fluida dari sampel batuan?','option','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:14:"Gaya gravitasi";i:1;s:16:"Gaya sentrifugal";i:2;s:11:"Gaya viskos";i:3;s:20:"Gaya elektromagnetik";}','','Gaya sentrifugal','In the centrifuge method, what force is used to overcome capillary forces to displace fluids from the rock sample?','a:4:{i:0;s:13:"Gravity force";i:1;s:17:"Centrifugal force";i:2;s:13:"Viscous force";i:3;s:21:"Electromagnetic force";}','Centrifugal force','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000166','Mengapa Mercury Injection tidak disarankan untuk sampel batuan yang mengandung lempung ekspansif (swelling clays)?','option','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:49:"Merkuri akan bereaksi secara kimia dengan lempung";i:1;s:56:"Tekanan tinggi dapat merusak struktur pori yang sensitif";i:2;s:40:"Merkuri tidak bisa masuk ke pori lempung";i:3;s:37:"Merkuri terlalu mahal untuk digunakan";}','','Tekanan tinggi dapat merusak struktur pori yang sensitif','Why is Mercury Injection not recommended for rock samples containing swelling clays?','a:4:{i:0;s:43:"Mercury will react chemically with the clay";i:1;s:50:"High pressure can damage sensitive pore structures";i:2;s:31:"Mercury cannot enter clay pores";i:3;s:31:"Mercury is too expensive to use";}','High pressure can damage sensitive pore structures','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000167','Pada kurva tekanan kapiler, ''Entry Pressure'' didefinisikan sebagai:','option','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:56:"Tekanan minimum untuk memulai injeksi fluida non-wetting";i:1;s:38:"Tekanan saat saturasi air mencapai 50%";i:2;s:51:"Tekanan saat permeabilitas relatif mencapai nilai 1";i:3;s:41:"Tekanan saat batuan benar-benar jenuh air";}','','Tekanan minimum untuk memulai injeksi fluida non-wetting','On a capillary pressure curve, ''Entry Pressure'' is defined as:','a:4:{i:0;s:53:"Minimum pressure to start non-wetting fluid injection";i:1;s:42:"Pressure when water saturation reaches 50%";i:2;s:45:"Pressure when relative permeability reaches 1";i:3;s:47:"Pressure when the rock is fully water saturated";}','Minimum pressure to start non-wetting fluid injection','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000168','Manakah pernyataan yang benar mengenai Swc dan ukuran pori?','option','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:44:"Semakin kecil ukuran pori, semakin kecil Swc";i:1;s:44:"Semakin besar ukuran pori, semakin besar Swc";i:2;s:44:"Semakin kecil ukuran pori, semakin besar Swc";i:3;s:38:"Swc tidak dipengaruhi oleh ukuran pori";}','','Semakin kecil ukuran pori, semakin besar Swc','Which statement is correct regarding Swc and pore size?','a:4:{i:0;s:46:"The smaller the pore size, the smaller the Swc";i:1;s:44:"The larger the pore size, the larger the Swc";i:2;s:45:"The smaller the pore size, the larger the Swc";i:3;s:32:"Swc is not affected by pore size";}','The smaller the pore size, the larger the Swc','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000169','Metode Porous Plate memiliki keunggulan utama dibandingkan metode lainnya, yaitu:','option','PFS000000017','Ujian Pelajaran','a:4:{i:0;s:34:"Waktu pengukuran yang sangat cepat";i:1;s:60:"Dapat mensimulasikan kondisi tekanan reservoir secara akurat";i:2;s:35:"Tidak memerlukan peralatan tambahan";i:3;s:54:"Dapat digunakan untuk semua jenis batuan tanpa batasan";}','','Dapat mensimulasikan kondisi tekanan reservoir secara akurat','The Porous Plate method has a major advantage over other methods, which is:','a:4:{i:0;s:26:"Very fast measurement time";i:1;s:53:"Can accurately simulate reservoir pressure conditions";i:2;s:37:"Does not require additional equipment";i:3;s:50:"Can be used for all rock types without limitations";}','Can accurately simulate reservoir pressure conditions','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000170','Apa yang dimaksud dengan saturasi air konat (Swc) pada kurva permeabilitas relatif?','option','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:57:"Saturasi air minimum di mana fase air tidak lagi mengalir";i:1;s:46:"Saturasi air maksimum saat minyak terperangkap";i:2;s:66:"Titik di mana permeabilitas relatif minyak mencapai nilai maksimum";i:3;s:49:"Saturasi air di mana tekanan kapiler bernilai nol";}','','Saturasi air minimum di mana fase air tidak lagi mengalir','What is meant by irreducible water saturation (Swc) on a relative permeability curve?','a:4:{i:0;s:62:"Minimum water saturation where the water phase no longer flows";i:1;s:44:"Maximum water saturation when oil is trapped";i:2;s:63:"Point where relative oil permeability reaches its maximum value";i:3;s:49:"Water saturation where capillary pressure is zero";}','Minimum water saturation where the water phase no longer flows','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000171','Manakah pernyataan yang benar mengenai hubungan antara tekanan kapiler dan permeabilitas relatif?','multi','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:60:"Tekanan kapiler mempengaruhi distribusi fluida di dalam pori";i:1;s:56:"Permeabilitas relatif adalah fungsi dari saturasi fluida";i:2;s:55:"Tekanan kapiler hanya bergantung pada viskositas fluida";i:3;s:63:"Permeabilitas relatif tidak dipengaruhi oleh wettability batuan";}','','a:2:{i:0;s:60:"Tekanan kapiler mempengaruhi distribusi fluida di dalam pori";i:1;s:56:"Permeabilitas relatif adalah fungsi dari saturasi fluida";}','Which statements are correct regarding the relationship between capillary pressure and relative permeability?','a:4:{i:0;s:61:"Capillary pressure influences fluid distribution within pores";i:1;s:55:"Relative permeability is a function of fluid saturation";i:2;s:50:"Capillary pressure depends only on fluid viscosity";i:3;s:57:"Relative permeability is not affected by rock wettability";}','a:2:{i:0;s:61:"Capillary pressure influences fluid distribution within pores";i:1;s:55:"Relative permeability is a function of fluid saturation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000172','Pada sistem aliran dua-fase minyak-air, apa yang terjadi pada permeabilitas relatif minyak (Kro) saat saturasi air meningkat?','option','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:32:"Nilai Kro menurun secara drastis";i:1;s:33:"Nilai Kro meningkat secara linear";i:2;s:23:"Nilai Kro tetap konstan";i:3;s:39:"Nilai Kro menjadi lebih besar dari satu";}','','Nilai Kro menurun secara drastis','In a two-phase oil-water flow system, what happens to the oil relative permeability (Kro) as water saturation increases?','a:4:{i:0;s:31:"Kro values decrease drastically";i:1;s:28:"Kro values increase linearly";i:2;s:26:"Kro values remain constant";i:3;s:34:"Kro values become greater than one";}','Kro values decrease drastically','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000173','Apa yang dimaksud dengan Sor (Residual Oil Saturation) dalam konteks permeabilitas relatif?','option','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:58:"Saturasi minyak yang tersisa setelah proses pendesakan air";i:1;s:39:"Saturasi minyak awal sebelum pendesakan";i:2;s:55:"Saturasi di mana permeabilitas relatif air bernilai nol";i:3;s:48:"Saturasi minyak pada kondisi tekanan kapiler nol";}','','Saturasi minyak yang tersisa setelah proses pendesakan air','What is meant by Sor (Residual Oil Saturation) in the context of relative permeability?','a:4:{i:0;s:59:"Oil saturation remaining after a water displacement process";i:1;s:42:"Initial oil saturation before displacement";i:2;s:52:"Saturation where water relative permeability is zero";i:3;s:51:"Oil saturation at zero capillary pressure condition";}','Oil saturation remaining after a water displacement process','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000174','Faktor apa saja yang mempengaruhi bentuk kurva permeabilitas relatif?','multi','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:18:"Wettability batuan";i:1;s:22:"Distribusi ukuran pori";i:2;s:19:"Viskositas air saja";i:3;s:41:"Sejarah saturasi (drainage vs imbibition)";}','','a:3:{i:0;s:18:"Wettability batuan";i:1;s:22:"Distribusi ukuran pori";i:2;s:41:"Sejarah saturasi (drainage vs imbibition)";}','What factors influence the shape of the relative permeability curve?','a:4:{i:0;s:16:"Rock wettability";i:1;s:22:"Pore size distribution";i:2;s:20:"Water viscosity only";i:3;s:43:"Saturation history (drainage vs imbibition)";}','a:3:{i:0;s:16:"Rock wettability";i:1;s:22:"Pore size distribution";i:2;s:43:"Saturation history (drainage vs imbibition)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000175','Dalam aliran tiga-fase (minyak, air, gas), permeabilitas relatif fase non-wetting biasanya ditentukan oleh?','option','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:25:"Saturasi fase itu sendiri";i:1;s:34:"Saturasi ketiga fase yang terlibat";i:2;s:23:"Viskositas fase wetting";i:3;s:20:"Tekanan formasi saja";}','','Saturasi fase itu sendiri','In three-phase flow (oil, water, gas), the relative permeability of a non-wetting phase is typically determined by?','a:4:{i:0;s:34:"The saturation of the phase itself";i:1;s:43:"The saturation of all three phases involved";i:2;s:30:"Viscosity of the wetting phase";i:3;s:23:"Formation pressure only";}','The saturation of the phase itself','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000176','Apa dampak utama dari kondisi ''oil-wet'' terhadap kurva permeabilitas relatif air?','option','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:50:"Air mulai mengalir pada saturasi yang lebih rendah";i:1;s:61:"Air lebih sulit untuk mengalir dibandingkan kondisi water-wet";i:2;s:41:"Kro akan selalu lebih tinggi daripada Krw";i:3;s:34:"Tidak ada perubahan pada kurva Krw";}','','Air lebih sulit untuk mengalir dibandingkan kondisi water-wet','What is the primary impact of an ''oil-wet'' condition on the water relative permeability curve?','a:4:{i:0;s:40:"Water starts to flow at lower saturation";i:1;s:56:"Water is harder to flow compared to water-wet conditions";i:2;s:34:"Kro will always be higher than Krw";i:3;s:35:"There is no change in the Krw curve";}','Water is harder to flow compared to water-wet conditions','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000177','Mengapa kurva permeabilitas relatif drainase dan imbibisi sering kali berbeda?','option','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:42:"Karena adanya fenomena histeresis saturasi";i:1;s:41:"Karena perubahan viskositas selama proses";i:2;s:40:"Karena tekanan kapiler tidak berpengaruh";i:3;s:36:"Karena laju alir yang selalu konstan";}','','Karena adanya fenomena histeresis saturasi','Why do drainage and imbibition relative permeability curves often differ?','a:4:{i:0;s:38:"Due to saturation hysteresis phenomena";i:1;s:43:"Due to viscosity changes during the process";i:2;s:40:"Because capillary pressure has no effect";i:3;s:38:"Because flow rates are always constant";}','Due to saturation hysteresis phenomena','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000178','Pada titik crossover di kurva Krw dan Kro, kondisi apa yang biasanya terjadi?','option','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:64:"Saturasi air biasanya lebih besar dari 50% jika batuan water-wet";i:1;s:44:"Permeabilitas relatif keduanya bernilai satu";i:2;s:39:"Tekanan kapiler mencapai nilai maksimum";i:3;s:33:"Aliran minyak berhenti sepenuhnya";}','','Saturasi air biasanya lebih besar dari 50% jika batuan water-wet','At the crossover point on Krw and Kro curves, what condition typically occurs?','a:4:{i:0;s:69:"Water saturation is usually greater than 50% if the rock is water-wet";i:1;s:45:"Both relative permeabilities are equal to one";i:2;s:44:"Capillary pressure reaches its maximum value";i:3;s:25:"Oil flow stops completely";}','Water saturation is usually greater than 50% if the rock is water-wet','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000179','Apa yang dimaksud dengan ''End-point relative permeability''?','option','PFS000000018','Ujian Pelajaran','a:4:{i:0;s:43:"Nilai Kr pada saturasi batas (Swc atau Sor)";i:1;s:48:"Nilai rata-rata Kr pada seluruh rentang saturasi";i:2;s:33:"Nilai Kr saat tekanan kapiler nol";i:3;s:37:"Titik potong antara kurva Krw dan Kro";}','','Nilai Kr pada saturasi batas (Swc atau Sor)','What is meant by ''End-point relative permeability''?','a:4:{i:0;s:48:"The Kr value at boundary saturation (Swc or Sor)";i:1;s:55:"The average Kr value across the entire saturation range";i:2;s:44:"The Kr value when capillary pressure is zero";i:3;s:49:"The intersection point between Krw and Kro curves";}','The Kr value at boundary saturation (Swc or Sor)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000180','Parameter utama yang merepresentasikan fraksi dari total volume batuan yang dapat ditempati oleh fluida adalah:','option','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:9:"Porositas";i:1;s:13:"Permeabilitas";i:2;s:12:"Saturasi air";i:3;s:12:"Net to Gross";}','','Porositas','The primary parameter representing the fraction of total rock volume that can be occupied by fluids is:','a:4:{i:0;s:8:"Porosity";i:1;s:12:"Permeability";i:2;s:16:"Water saturation";i:3;s:12:"Net to Gross";}','Porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000181','Manakah dari berikut ini yang diperlukan untuk menghitung Bulk Volume (BV) suatu reservoir?','multi','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:9:"Luas area";i:1;s:19:"Ketebalan reservoir";i:2;s:13:"Permeabilitas";i:3;s:17:"Viskositas fluida";}','','a:2:{i:0;s:9:"Luas area";i:1;s:19:"Ketebalan reservoir";}','Which of the following are required to calculate the Bulk Volume (BV) of a reservoir?','a:4:{i:0;s:12:"Surface area";i:1;s:19:"Reservoir thickness";i:2;s:12:"Permeability";i:3;s:15:"Fluid viscosity";}','a:2:{i:0;s:12:"Surface area";i:1;s:19:"Reservoir thickness";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000182','Rasio antara ketebalan formasi bersih (net) terhadap ketebalan total (gross) dikenal sebagai:','option','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:18:"Net to Gross ratio";i:1;s:14:"Porosity ratio";i:2;s:15:"Recovery factor";i:3;s:23:"Formation Volume Factor";}','','Net to Gross ratio','The ratio between the net formation thickness and the total gross thickness is known as:','a:4:{i:0;s:18:"Net to Gross ratio";i:1;s:14:"Porosity ratio";i:2;s:15:"Recovery factor";i:3;s:23:"Formation Volume Factor";}','Net to Gross ratio','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000183','Faktor volume formasi (Bo) didefinisikan sebagai rasio volume minyak di kondisi reservoir terhadap volume minyak di kondisi:','option','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:13:"Standar (STP)";i:1;s:17:"Tekanan geostatik";i:2;s:15:"Titik gelembung";i:3;s:13:"Kondisi jenuh";}','','Standar (STP)','Formation volume factor (Bo) is defined as the ratio of oil volume at reservoir conditions to oil volume at:','a:4:{i:0;s:25:"Standard conditions (STP)";i:1;s:18:"Geostatic pressure";i:2;s:12:"Bubble point";i:3;s:20:"Saturated conditions";}','Standard conditions (STP)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000184','Rumus dasar untuk menghitung Original Oil In Place (OOIP) secara volumetrik adalah:','option','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:38:"(BV * NTG * Porositas * (1 - Sw)) / Bo";i:1;s:31:"(BV * NTG * Permeabilitas) / Bo";i:2;s:14:"(BV * Sw) / Bo";i:3;s:26:"(BV * Porositas * Sw) / Bo";}','','(BV * NTG * Porositas * (1 - Sw)) / Bo','The basic formula to calculate the Original Oil In Place (OOIP) volumetrically is:','a:4:{i:0;s:37:"(BV * NTG * Porosity * (1 - Sw)) / Bo";i:1;s:30:"(BV * NTG * Permeability) / Bo";i:2;s:14:"(BV * Sw) / Bo";i:3;s:25:"(BV * Porosity * Sw) / Bo";}','(BV * NTG * Porosity * (1 - Sw)) / Bo','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000185','Jika 1 acre-feet setara dengan 43,560 cubic feet, berapakah perkiraan konversi ke satuan metrik barrel (1 m3 = 6.29 bbl)?','option','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:9:"7,758 bbl";i:1;s:9:"1,000 bbl";i:2;s:9:"5,615 bbl";i:3;s:6:"42 bbl";}','','7,758 bbl','If 1 acre-feet is equivalent to 43,560 cubic feet, what is the approximate conversion to barrels (1 m3 = 6.29 bbl)?','a:4:{i:0;s:9:"7,758 bbl";i:1;s:9:"1,000 bbl";i:2;s:9:"5,615 bbl";i:3;s:6:"42 bbl";}','7,758 bbl','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000186','Saturasi air (Sw) dalam perhitungan cadangan berfungsi untuk:','option','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:51:"Menentukan volume ruang pori yang diisi hidrokarbon";i:1;s:28:"Menghitung tekanan reservoir";i:2;s:28:"Menentukan viskositas minyak";i:3;s:26:"Menghitung densitas batuan";}','','Menentukan volume ruang pori yang diisi hidrokarbon','Water saturation (Sw) in reserves calculation serves to:','a:4:{i:0;s:52:"Determine pore space volume filled with hydrocarbons";i:1;s:28:"Calculate reservoir pressure";i:2;s:23:"Determine oil viscosity";i:3;s:22:"Calculate rock density";}','Determine pore space volume filled with hydrocarbons','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000187','Apa yang dimaksud dengan Net Pay dalam evaluasi petrofisika?','multi','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:53:"Bagian reservoir yang mengandung hidrokarbon ekonomis";i:1;s:52:"Bagian batuan yang memiliki porositas di atas cutoff";i:2;s:41:"Bagian reservoir dengan permeabilitas nol";i:3;s:36:"Bagian reservoir yang jenuh air 100%";}','','a:2:{i:0;s:53:"Bagian reservoir yang mengandung hidrokarbon ekonomis";i:1;s:52:"Bagian batuan yang memiliki porositas di atas cutoff";}','What is meant by Net Pay in petrophysical evaluation?','a:4:{i:0;s:58:"The part of the reservoir containing economic hydrocarbons";i:1;s:43:"The rock section with porosity above cutoff";i:2;s:48:"The part of the reservoir with zero permeability";i:3;s:46:"The part of the reservoir 100% water saturated";}','a:2:{i:0;s:58:"The part of the reservoir containing economic hydrocarbons";i:1;s:43:"The rock section with porosity above cutoff";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000188','Dalam perhitungan cadangan gas, faktor volume formasi gas (Bg) biasanya meningkat seiring dengan:','option','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:17:"Penurunan tekanan";i:1;s:16:"Peningkatan suhu";i:2;s:24:"Peningkatan saturasi air";i:3;s:19:"Penurunan porositas";}','','Penurunan tekanan','In gas reserves calculation, the gas formation volume factor (Bg) usually increases with:','a:4:{i:0;s:17:"Pressure decrease";i:1;s:20:"Temperature increase";i:2;s:25:"Water saturation increase";i:3;s:17:"Porosity decrease";}','Pressure decrease','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000189','Satuan standar yang digunakan untuk Bulk Volume (BV) dalam perhitungan cadangan di industri perminyakan adalah:','option','PFS000000019','Ujian Pelajaran','a:4:{i:0;s:9:"Acre-feet";i:1;s:7:"Darcies";i:2;s:10:"Centipoise";i:3;s:3:"PSI";}','','Acre-feet','The standard unit used for Bulk Volume (BV) in reserves calculation in the petroleum industry is:','a:4:{i:0;s:9:"Acre-feet";i:1;s:7:"Darcies";i:2;s:10:"Centipoise";i:3;s:3:"PSI";}','Acre-feet','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000190','Apa tujuan utama dari integrasi data log sumur dengan data inti (core) dalam evaluasi petrofisika?','option','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:78:"Melakukan kalibrasi parameter log terhadap data laboratorium yang lebih akurat";i:1;s:42:"Mengabaikan data log karena kurang presisi";i:2;s:37:"Meningkatkan biaya operasional proyek";i:3;s:49:"Menghilangkan kebutuhan akan interpretasi geologi";}','','Melakukan kalibrasi parameter log terhadap data laboratorium yang lebih akurat','What is the primary purpose of integrating well log data with core data in petrophysical evaluation?','a:4:{i:0;s:64:"Calibrating log parameters against more accurate laboratory data";i:1;s:42:"Ignoring log data due to lack of precision";i:2;s:36:"Increasing project operational costs";i:3;s:50:"Eliminating the need for geological interpretation";}','Calibrating log parameters against more accurate laboratory data','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000191','Manakah dari berikut ini yang merupakan indikator kualitas (QC) pada log Gamma Ray sebelum dilakukan interpretasi?','multi','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:43:"Adanya pergeseran baseline (baseline shift)";i:1;s:50:"Skala log yang konsisten dengan interval kedalaman";i:2;s:44:"Kecepatan logging yang tidak stabil (spikes)";i:3;s:51:"Respon yang merepresentasikan litologi secara logis";}','','a:3:{i:0;s:43:"Adanya pergeseran baseline (baseline shift)";i:1;s:44:"Kecepatan logging yang tidak stabil (spikes)";i:2;s:51:"Respon yang merepresentasikan litologi secara logis";}','Which of the following are quality control (QC) indicators for Gamma Ray logs before interpretation?','a:4:{i:0;s:26:"Presence of baseline shift";i:1;s:41:"Log scale consistency with depth interval";i:2;s:31:"Unstable logging speed (spikes)";i:3;s:41:"Response representing lithology logically";}','a:3:{i:0;s:26:"Presence of baseline shift";i:1;s:31:"Unstable logging speed (spikes)";i:2;s:41:"Response representing lithology logically";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000192','Dalam crossplot Neutron-Density, jika titik data terletak di antara garis sandstone dan limestone, apa interpretasi yang paling mungkin?','option','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:51:"Litologi merupakan campuran sandstone dan limestone";i:1;s:34:"Lubang bor mengalami washout parah";i:2;s:45:"Formasi mengandung gas dengan saturasi tinggi";i:3;s:37:"Terjadi kerusakan alat saat perekaman";}','','Litologi merupakan campuran sandstone dan limestone','In a Neutron-Density crossplot, if the data points lie between the sandstone and limestone lines, what is the most likely interpretation?','a:4:{i:0;s:53:"The lithology is a mixture of sandstone and limestone";i:1;s:31:"The borehole has severe washout";i:2;s:47:"The formation contains gas with high saturation";i:3;s:36:"Tool failure occurred during logging";}','The lithology is a mixture of sandstone and limestone','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000193','Apa manfaat utama dari penggunaan M-N plot dalam evaluasi petrofisika?','option','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:64:"Identifikasi litologi kompleks dengan menggunakan tiga porositas";i:1;s:38:"Estimasi permeabilitas secara langsung";i:2;s:38:"Menentukan viskositas fluida reservoir";i:3;s:42:"Menghitung tekanan kapiler secara otomatis";}','','Identifikasi litologi kompleks dengan menggunakan tiga porositas','What is the main benefit of using an M-N plot in petrophysical evaluation?','a:4:{i:0;s:61:"Identification of complex lithology using three porosity logs";i:1;s:30:"Direct permeability estimation";i:2;s:37:"Determining reservoir fluid viscosity";i:3;s:43:"Automatic calculation of capillary pressure";}','Identification of complex lithology using three porosity logs','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000194','Bagaimana pengaruh efek ''gas effect'' pada crossplot Neutron-Density?','option','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:62:"Menyebabkan nilai porositas neutron rendah dan densitas tinggi";i:1;s:47:"Tidak memberikan perubahan pada nilai pembacaan";i:2;s:45:"Membuat nilai porositas neutron sangat tinggi";i:3;s:52:"Menyebabkan pembacaan densitas menjadi sangat rendah";}','','Menyebabkan nilai porositas neutron rendah dan densitas tinggi','How does the ''gas effect'' influence a Neutron-Density crossplot?','a:4:{i:0;s:51:"Causes low neutron porosity and high density values";i:1;s:34:"Does not change the reading values";i:2;s:39:"Makes neutron porosity values very high";i:3;s:42:"Causes density readings to become very low";}','Causes low neutron porosity and high density values','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000195','Faktor apa saja yang harus diperiksa saat melakukan Quality Control (QC) data core terhadap data log?','multi','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:46:"Kedalaman (depth shifting) antara log dan core";i:1;s:30:"Pemulihan core (core recovery)";i:2;s:34:"Orientasi core terhadap arah utara";i:3;s:37:"Tekanan formasi saat pengambilan core";}','','a:2:{i:0;s:46:"Kedalaman (depth shifting) antara log dan core";i:1;s:30:"Pemulihan core (core recovery)";}','Which factors should be checked when performing Quality Control (QC) of core data against log data?','a:4:{i:0;s:35:"Depth shifting between log and core";i:1;s:13:"Core recovery";i:2;s:34:"Core orientation relative to north";i:3;s:32:"Formation pressure during coring";}','a:2:{i:0;s:35:"Depth shifting between log and core";i:1;s:13:"Core recovery";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000196','Pada penyajian petrophysical summary, kurva apa yang paling umum digunakan untuk menentukan zona reservoir netto?','option','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:37:"Volume lempung (Vshale) dan Porositas";i:1;s:26:"Kurva kecepatan sonik saja";i:2;s:30:"Hanya kurva resistivitas dalam";i:3;s:22:"Kurva temperatur sumur";}','','Volume lempung (Vshale) dan Porositas','In a petrophysical summary presentation, which curves are most commonly used to determine net reservoir zones?','a:4:{i:0;s:34:"Shale volume (Vshale) and Porosity";i:1;s:25:"Sonic velocity curve only";i:2;s:27:"Deep resistivity curve only";i:3;s:22:"Well temperature curve";}','Shale volume (Vshale) and Porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000197','Mengapa integrasi data geologi penting dalam interpretasi petrofisika?','option','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:71:"Untuk memastikan model petrofisika sesuai dengan lingkungan pengendapan";i:1;s:49:"Untuk mempercepat waktu komputasi perangkat lunak";i:2;s:44:"Hanya untuk keperluan dokumentasi perusahaan";i:3;s:40:"Agar tidak perlu melakukan logging ulang";}','','Untuk memastikan model petrofisika sesuai dengan lingkungan pengendapan','Why is geological data integration important in petrophysical interpretation?','a:4:{i:0;s:74:"To ensure the petrophysical model aligns with the depositional environment";i:1;s:37:"To speed up software computation time";i:2;s:41:"Only for corporate documentation purposes";i:3;s:19:"To avoid re-logging";}','To ensure the petrophysical model aligns with the depositional environment','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000198','Dalam konteks QC log resistivitas, kondisi apa yang menunjukkan adanya invasi filtrat lumpur yang signifikan?','option','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:48:"Separasi antara log shallow dan deep resistivity";i:1;s:48:"Kurva resistivitas yang tumpang tindih (overlay)";i:2;s:52:"Nilai resistivitas yang sangat tinggi di zona serpih";i:3;s:56:"Tidak adanya perbedaan antara log mikrolat dan lateralog";}','','Separasi antara log shallow dan deep resistivity','In the context of resistivity log QC, what condition indicates significant mud filtrate invasion?','a:4:{i:0;s:52:"Separation between shallow and deep resistivity logs";i:1;s:30:"Overlapping resistivity curves";i:2;s:46:"Very high resistivity values in the shale zone";i:3;s:50:"No difference between microlaterolog and laterolog";}','Separation between shallow and deep resistivity logs','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000199','Crossplot antara resistivitas dan porositas (Pickett Plot) digunakan untuk menentukan apa?','option','PFS000000020','Ujian Pelajaran','a:4:{i:0;s:49:"Saturasi air (Sw) dan parameter formasi (m, n, a)";i:1;s:21:"Permeabilitas absolut";i:2;s:17:"Tekanan reservoir";i:3;s:36:"Kecepatan perambatan gelombang suara";}','','Saturasi air (Sw) dan parameter formasi (m, n, a)','The crossplot between resistivity and porosity (Pickett Plot) is used to determine what?','a:4:{i:0;s:56:"Water saturation (Sw) and formation parameters (m, n, a)";i:1;s:21:"Absolute permeability";i:2;s:18:"Reservoir pressure";i:3;s:31:"Sound wave propagation velocity";}','Water saturation (Sw) and formation parameters (m, n, a)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000200','Jika sebuah formasi memiliki resistivitas air formasi (Rw) sebesar 0.05 ohm-m pada suhu reservoir dan resistivitas batuan (Rt) sebesar 5 ohm-m dengan faktor formasi (F) sebesar 20, berapa nilai saturasi air (Sw) menggunakan persamaan Archie (n=2)?','option','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:4:"0.40";i:1;s:4:"0.45";i:2;s:4:"0.50";i:3;s:4:"0.60";}','','0.45','If a formation has a formation water resistivity (Rw) of 0.05 ohm-m at reservoir temperature and a true rock resistivity (Rt) of 5 ohm-m with a formation factor (F) of 20, what is the water saturation (Sw) value using the Archie equation (n=2)?','a:4:{i:0;s:4:"0.40";i:1;s:4:"0.45";i:2;s:4:"0.50";i:3;s:4:"0.60";}','0.45','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000201','Dalam studi kasus log sumur, manakah parameter yang paling berpengaruh secara langsung dalam perhitungan volume hidrokarbon awal di tempat (OOIP)?','multi','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:17:"Porositas efektif";i:1;s:12:"Saturasi air";i:2;s:7:"Net pay";i:3;s:21:"Permeabilitas absolut";}','','a:3:{i:0;s:17:"Porositas efektif";i:1;s:12:"Saturasi air";i:2;s:7:"Net pay";}','In a well log case study, which parameters directly influence the calculation of the original oil in place (OOIP)?','a:4:{i:0;s:18:"Effective porosity";i:1;s:16:"Water saturation";i:2;s:7:"Net pay";i:3;s:21:"Absolute permeability";}','a:3:{i:0;s:18:"Effective porosity";i:1;s:16:"Water saturation";i:2;s:7:"Net pay";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000202','Pada zona sandstone bersih (clean sand), respon log Gamma Ray (GR) yang rendah mengindikasikan apa?','option','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:36:"Kandungan serpih (shale) yang tinggi";i:1;s:36:"Kandungan serpih (shale) yang rendah";i:2;s:28:"Porositas yang sangat rendah";i:3;s:14:"Keberadaan gas";}','','Kandungan serpih (shale) yang rendah','In a clean sand zone, what does a low Gamma Ray (GR) log response indicate?','a:4:{i:0;s:18:"High shale content";i:1;s:17:"Low shale content";i:2;s:17:"Very low porosity";i:3;s:15:"Presence of gas";}','Low shale content','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000203','Sebuah reservoir memiliki porositas 20% dan ketebalan net pay 10 meter. Jika luas area adalah 1 km persegi dan saturasi air 30%, berapa estimasi volume minyak dalam meter kubik?','option','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:9:"1,400,000";i:1;s:9:"1,800,000";i:2;s:9:"2,000,000";i:3;s:9:"2,400,000";}','','1,400,000','A reservoir has 20% porosity and 10 meters of net pay. If the area is 1 square kilometer and water saturation is 30%, what is the estimated oil volume in cubic meters?','a:4:{i:0;s:9:"1,400,000";i:1;s:9:"1,800,000";i:2;s:9:"2,000,000";i:3;s:9:"2,400,000";}','1,400,000','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000204','Manakah di antara berikut ini yang merupakan hubungan empiris utama dalam menentukan porositas dari log densitas?','option','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:56:"Phi = (rho_matrix - rho_bulk) / (rho_matrix - rho_fluid)";i:1;s:56:"Phi = (rho_bulk - rho_matrix) / (rho_matrix - rho_fluid)";i:2;s:56:"Phi = (rho_matrix - rho_fluid) / (rho_bulk - rho_matrix)";i:3;s:54:"Phi = (rho_bulk - rho_fluid) / (rho_matrix - rho_bulk)";}','','Phi = (rho_matrix - rho_bulk) / (rho_matrix - rho_fluid)','Which of the following is the primary empirical relationship for determining porosity from the density log?','a:4:{i:0;s:56:"Phi = (rho_matrix - rho_bulk) / (rho_matrix - rho_fluid)";i:1;s:56:"Phi = (rho_bulk - rho_matrix) / (rho_matrix - rho_fluid)";i:2;s:56:"Phi = (rho_matrix - rho_fluid) / (rho_bulk - rho_matrix)";i:3;s:54:"Phi = (rho_bulk - rho_fluid) / (rho_matrix - rho_bulk)";}','Phi = (rho_matrix - rho_bulk) / (rho_matrix - rho_fluid)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000205','Apa dampak utama dari keberadaan lempung (shale) pada interpretasi resistivitas sumur?','option','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:33:"Meningkatkan resistivitas terbaca";i:1;s:31:"Menurunkan resistivitas terbaca";i:2;s:35:"Tidak berpengaruh pada resistivitas";i:3;s:42:"Membuat resistivitas menjadi tak terhingga";}','','Menurunkan resistivitas terbaca','What is the primary impact of clay (shale) presence on well resistivity interpretation?','a:4:{i:0;s:30:"Increases apparent resistivity";i:1;s:30:"Decreases apparent resistivity";i:2;s:24:"No effect on resistivity";i:3;s:26:"Makes resistivity infinite";}','Decreases apparent resistivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000206','Dalam konteks evaluasi formasi, apa yang dimaksud dengan Vsh (Volume Shale)?','option','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:38:"Volume hidrokarbon di dalam ruang pori";i:1;s:46:"Fraksi volume batuan serpih di dalam reservoir";i:2;s:40:"Kecepatan gelombang suara melalui serpih";i:3;s:36:"Kapasitas serpih untuk menyimpan air";}','','Fraksi volume batuan serpih di dalam reservoir','In the context of formation evaluation, what is Vsh (Shale Volume)?','a:4:{i:0;s:36:"Hydrocarbon volume in the pore space";i:1;s:50:"Volume fraction of shale rock within the reservoir";i:2;s:37:"Velocity of sound waves through shale";i:3;s:32:"Capacity of shale to store water";}','Volume fraction of shale rock within the reservoir','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000207','Jika log neutron dan log densitas saling berhimpit (crossover) pada formasi sandstone, apa interpretasi petrofisikanya?','option','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:15:"Adanya zona air";i:1;s:10:"Adanya gas";i:2;s:26:"Formasi yang sangat kompak";i:3;s:15:"Adanya batubara";}','','Adanya gas','If neutron and density logs crossover in a sandstone formation, what is the petrophysical interpretation?','a:4:{i:0;s:22:"Presence of water zone";i:1;s:15:"Presence of gas";i:2;s:22:"Very compact formation";i:3;s:16:"Presence of coal";}','Presence of gas','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000208','Manakah parameter yang diperlukan untuk menghitung faktor formasi (F) menggunakan rumus Archie?','multi','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:9:"Porositas";i:1;s:12:"Saturasi air";i:2;s:11:"Tortuositas";i:3;s:14:"Semenatasi (m)";}','','a:2:{i:0;s:9:"Porositas";i:1;s:14:"Semenatasi (m)";}','Which parameters are needed to calculate the formation factor (F) using the Archie formula?','a:4:{i:0;s:8:"Porosity";i:1;s:16:"Water saturation";i:2;s:10:"Tortuosity";i:3;s:24:"Cementation exponent (m)";}','a:2:{i:0;s:8:"Porosity";i:1;s:24:"Cementation exponent (m)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000209','Dalam perhitungan volumetrik, apa fungsi utama dari pemotongan (cutoff) porositas?','option','PFS000000021','Ujian Pelajaran','a:4:{i:0;s:36:"Untuk menentukan batas atas cadangan";i:1;s:70:"Untuk mengeliminasi batuan yang tidak berkontribusi pada aliran fluida";i:2;s:32:"Untuk menghitung tekanan kapiler";i:3;s:45:"Untuk memperbaiki akurasi pembacaan Gamma Ray";}','','Untuk mengeliminasi batuan yang tidak berkontribusi pada aliran fluida','In volumetric calculations, what is the main function of porosity cutoffs?','a:4:{i:0;s:40:"To determine the upper limit of reserves";i:1;s:56:"To eliminate rock that does not contribute to fluid flow";i:2;s:31:"To calculate capillary pressure";i:3;s:37:"To improve Gamma Ray reading accuracy";}','To eliminate rock that does not contribute to fluid flow','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000210','Apa mekanisme pendorong utama yang menyebabkan minyak mengalir ke lubang sumur selama tahap primary recovery?','option','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:22:"Energi alami reservoir";i:1;s:11:"Injeksi air";i:2;s:15:"Injeksi gas CO2";i:3;s:15:"Injeksi polimer";}','','Energi alami reservoir','What is the primary driving mechanism that causes oil to flow into the wellbore during the primary recovery stage?','a:4:{i:0;s:24:"Natural reservoir energy";i:1;s:15:"Water injection";i:2;s:17:"CO2 gas injection";i:3;s:17:"Polymer injection";}','Natural reservoir energy','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000211','Manakah dari berikut ini yang termasuk dalam metode secondary recovery untuk mempertahankan tekanan reservoir?','multi','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:13:"Waterflooding";i:1;s:36:"Gas injection (pressure maintenance)";i:2;s:17:"Injeksi surfaktan";i:3;s:16:"Thermal recovery";}','','a:2:{i:0;s:13:"Waterflooding";i:1;s:36:"Gas injection (pressure maintenance)";}','Which of the following are included in secondary recovery methods to maintain reservoir pressure?','a:4:{i:0;s:13:"Waterflooding";i:1;s:36:"Gas injection (pressure maintenance)";i:2;s:20:"Surfactant injection";i:3;s:16:"Thermal recovery";}','a:2:{i:0;s:13:"Waterflooding";i:1;s:36:"Gas injection (pressure maintenance)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000212','Apa tujuan utama dari penerapan Enhanced Oil Recovery (EOR) setelah tahap secondary recovery berakhir?','option','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:28:"Mengurangi biaya operasional";i:1;s:76:"Meningkatkan perolehan minyak dengan mengubah sifat fisik fluida atau batuan";i:2;s:26:"Mengganti pompa sucker rod";i:3;s:40:"Menutup sumur yang sudah tidak produktif";}','','Meningkatkan perolehan minyak dengan mengubah sifat fisik fluida atau batuan','What is the main purpose of applying Enhanced Oil Recovery (EOR) after the secondary recovery stage ends?','a:4:{i:0;s:24:"Reduce operational costs";i:1;s:72:"Increase oil recovery by altering physical properties of fluids or rocks";i:2;s:24:"Replace sucker rod pumps";i:3;s:26:"Shut in unproductive wells";}','Increase oil recovery by altering physical properties of fluids or rocks','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000213','Faktor perolehan (Recovery Factor) didefinisikan sebagai rasio antara:','option','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:58:"Minyak yang diproduksi dengan original oil in place (OOIP)";i:1;s:45:"Tekanan reservoir dengan tekanan bubble point";i:2;s:37:"Laju alir minyak dengan laju alir air";i:3;s:36:"Porositas batuan dengan saturasi air";}','','Minyak yang diproduksi dengan original oil in place (OOIP)','The Recovery Factor is defined as the ratio between:','a:4:{i:0;s:45:"Produced oil and original oil in place (OOIP)";i:1;s:44:"Reservoir pressure and bubble point pressure";i:2;s:33:"Oil flow rate and water flow rate";i:3;s:34:"Rock porosity and water saturation";}','Produced oil and original oil in place (OOIP)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000214','Apa yang dimaksud dengan residual oil saturation (Sor) dalam konteks EOR?','option','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:70:"Saturasi minyak yang tertinggal di reservoir setelah proses pendesakan";i:1;s:37:"Saturasi minyak awal sebelum produksi";i:2;s:52:"Saturasi minyak yang bisa diproduksi secara ekonomis";i:3;s:31:"Saturasi minyak di zona gas cap";}','','Saturasi minyak yang tertinggal di reservoir setelah proses pendesakan','What is meant by residual oil saturation (Sor) in the context of EOR?','a:4:{i:0;s:60:"Oil saturation remaining in the reservoir after displacement";i:1;s:40:"Initial oil saturation before production";i:2;s:48:"Oil saturation that can be economically produced";i:3;s:34:"Oil saturation in the gas cap zone";}','Oil saturation remaining in the reservoir after displacement','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000215','Manakah komponen utama yang mempengaruhi efisiensi penyapuan (sweep efficiency) dalam suatu reservoir?','option','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:41:"Heterogenitas batuan dan mobilitas fluida";i:1;s:15:"Kedalaman sumur";i:2;s:15:"Diameter casing";i:3;s:21:"Jumlah kru pengeboran";}','','Heterogenitas batuan dan mobilitas fluida','Which main components affect sweep efficiency in a reservoir?','a:4:{i:0;s:37:"Rock heterogeneity and fluid mobility";i:1;s:10:"Well depth";i:2;s:15:"Casing diameter";i:3;s:23:"Number of drilling crew";}','Rock heterogeneity and fluid mobility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000216','Metode EOR yang bekerja terutama dengan cara menurunkan tegangan antar muka (interfacial tension) antara minyak dan air adalah:','option','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:17:"Injeksi surfaktan";i:1;s:11:"Injeksi uap";i:2;s:15:"Injeksi polimer";i:3;s:17:"Injeksi air panas";}','','Injeksi surfaktan','The EOR method that works primarily by lowering the interfacial tension between oil and water is:','a:4:{i:0;s:20:"Surfactant injection";i:1;s:15:"Steam injection";i:2;s:17:"Polymer injection";i:3;s:19:"Hot water injection";}','Surfactant injection','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000217','Dalam konteks tahapan produksi, manakah pernyataan yang benar mengenai urutan umum pengembangan lapangan?','option','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:32:"Primary -> Secondary -> Tertiary";i:1;s:32:"Tertiary -> Primary -> Secondary";i:2;s:32:"Secondary -> Primary -> Tertiary";i:3;s:32:"Primary -> Tertiary -> Secondary";}','','Primary -> Secondary -> Tertiary','In the context of production stages, which statement is correct regarding the general sequence of field development?','a:4:{i:0;s:32:"Primary -> Secondary -> Tertiary";i:1;s:32:"Tertiary -> Primary -> Secondary";i:2;s:32:"Secondary -> Primary -> Tertiary";i:3;s:32:"Primary -> Tertiary -> Secondary";}','Primary -> Secondary -> Tertiary','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000218','Apa fungsi utama dari penambahan polimer dalam waterflooding?','option','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:63:"Meningkatkan viskositas air injeksi untuk memperbaiki mobilitas";i:1;s:28:"Menurunkan viskositas minyak";i:2;s:29:"Membunuh bakteri di reservoir";i:3;s:34:"Membersihkan kerak di lubang sumur";}','','Meningkatkan viskositas air injeksi untuk memperbaiki mobilitas','What is the primary function of adding polymers in waterflooding?','a:4:{i:0;s:54:"Increase injection water viscosity to improve mobility";i:1;s:22:"Decrease oil viscosity";i:2;s:30:"Kill bacteria in the reservoir";i:3;s:27:"Clean scale in the wellbore";}','Increase injection water viscosity to improve mobility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000219','Faktor perolehan akhir suatu lapangan minyak dipengaruhi oleh:','multi','PFS000000022','Ujian Pelajaran','a:4:{i:0;s:32:"Efisiensi pendesakan mikroskopis";i:1;s:31:"Efisiensi penyapuan makroskopis";i:2;s:22:"Biaya sewa alat kantor";i:3;s:12:"Warna minyak";}','','a:2:{i:0;s:32:"Efisiensi pendesakan mikroskopis";i:1;s:31:"Efisiensi penyapuan makroskopis";}','The final recovery factor of an oil field is influenced by:','a:4:{i:0;s:35:"Microscopic displacement efficiency";i:1;s:28:"Macroscopic sweep efficiency";i:2;s:29:"Office equipment rental costs";i:3;s:9:"Oil color";}','a:2:{i:0;s:35:"Microscopic displacement efficiency";i:1;s:28:"Macroscopic sweep efficiency";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000220','Mekanisme pendorong utama pada reservoir yang mengandalkan ekspansi gas terlarut dalam minyak disebut sebagai','option','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:15:"Depletion drive";i:1;s:11:"Water drive";i:2;s:13:"Gas cap drive";i:3;s:16:"Gravity drainage";}','','Depletion drive','The primary drive mechanism in a reservoir relying on the expansion of gas dissolved in oil is called','a:4:{i:0;s:15:"Depletion drive";i:1;s:11:"Water drive";i:2;s:13:"Gas cap drive";i:3;s:16:"Gravity drainage";}','Depletion drive','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000221','Faktor apa saja yang menentukan besarnya residual oil saturation (Sor) di dalam pori batuan setelah proses pendorongan?','multi','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:21:"Kekuatan gaya kapiler";i:1;s:36:"Sifat kebasahan batuan (wettability)";i:2;s:16:"Kecepatan aliran";i:3;s:17:"Viskositas fluida";}','','a:3:{i:0;s:21:"Kekuatan gaya kapiler";i:1;s:36:"Sifat kebasahan batuan (wettability)";i:2;s:17:"Viskositas fluida";}','What factors determine the magnitude of residual oil saturation (Sor) within rock pores after a displacement process?','a:4:{i:0;s:24:"Capillary force strength";i:1;s:16:"Rock wettability";i:2;s:13:"Flow velocity";i:3;s:15:"Fluid viscosity";}','a:3:{i:0;s:24:"Capillary force strength";i:1;s:16:"Rock wettability";i:2;s:15:"Fluid viscosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000222','Pada mekanisme water drive, efisiensi penyapuan (sweep efficiency) sangat dipengaruhi oleh','option','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:39:"Mobilitas relatif antara air dan minyak";i:1;s:22:"Tekanan awal reservoir";i:2;s:19:"Kedalaman reservoir";i:3;s:25:"Kadar sulfur dalam minyak";}','','Mobilitas relatif antara air dan minyak','In a water drive mechanism, sweep efficiency is strongly influenced by','a:4:{i:0;s:39:"Relative mobility between water and oil";i:1;s:26:"Initial reservoir pressure";i:2;s:15:"Reservoir depth";i:3;s:21:"Sulfur content in oil";}','Relative mobility between water and oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000223','Mekanisme pendorong yang memanfaatkan perbedaan densitas antara minyak dan gas untuk mendesak minyak ke sumur produksi disebut','option','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:16:"Gravity drainage";i:1;s:15:"Depletion drive";i:2;s:11:"Water drive";i:3;s:13:"Gas cap drive";}','','Gravity drainage','The drive mechanism that utilizes density differences between oil and gas to push oil toward production wells is called','a:4:{i:0;s:16:"Gravity drainage";i:1;s:15:"Depletion drive";i:2;s:11:"Water drive";i:3;s:13:"Gas cap drive";}','Gravity drainage','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000224','Apa dampak utama dari penurunan tekanan reservoir di bawah bubble point pada mekanisme depletion drive?','option','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:67:"Terbentuknya gas bebas yang menurunkan permeabilitas relatif minyak";i:1;s:44:"Peningkatan viskositas minyak secara drastis";i:2;s:38:"Peningkatan saturasi air secara instan";i:3;s:24:"Hilangnya gaya gravitasi";}','','Terbentuknya gas bebas yang menurunkan permeabilitas relatif minyak','What is the primary impact of reservoir pressure dropping below the bubble point in a depletion drive mechanism?','a:4:{i:0;s:61:"Formation of free gas which reduces oil relative permeability";i:1;s:33:"Drastic increase in oil viscosity";i:2;s:42:"Instantaneous increase in water saturation";i:3;s:21:"Loss of gravity force";}','Formation of free gas which reduces oil relative permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000225','Saturasi minyak residual (Sor) secara teknis didefinisikan sebagai','option','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:69:"Fraksi minyak yang terperangkap dalam pori setelah proses pendorongan";i:1;s:41:"Minyak awal di reservoir sebelum produksi";i:2;s:51:"Jumlah minyak yang dapat diproduksi secara ekonomis";i:3;s:39:"Minyak yang mengalir bebas ke permukaan";}','','Fraksi minyak yang terperangkap dalam pori setelah proses pendorongan','Residual oil saturation (Sor) is technically defined as','a:4:{i:0;s:61:"Fraction of oil trapped in pores after a displacement process";i:1;s:46:"Initial oil in the reservoir before production";i:2;s:47:"Amount of oil that can be produced economically";i:3;s:36:"Oil that flows freely to the surface";}','Fraction of oil trapped in pores after a displacement process','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000226','Manakah pernyataan yang benar mengenai mekanisme gas cap drive?','option','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:47:"Gas cap yang ekspansif mendesak minyak ke bawah";i:1;s:31:"Minyak mendesak gas cap ke atas";i:2;s:38:"Hanya mengandalkan tekanan air formasi";i:3;s:45:"Tidak ada gas yang terlibat dalam pendorongan";}','','Gas cap yang ekspansif mendesak minyak ke bawah','Which statement is correct regarding the gas cap drive mechanism?','a:4:{i:0;s:40:"An expansive gas cap pushes oil downward";i:1;s:29:"Oil pushes the gas cap upward";i:2;s:39:"Only relies on formation water pressure";i:3;s:38:"No gas is involved in the displacement";}','An expansive gas cap pushes oil downward','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000227','Pilih dua faktor yang dapat memperkecil nilai Sor dalam reservoir','multi','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:35:"Penurunan tegangan antar muka (IFT)";i:1;s:29:"Peningkatan viskositas minyak";i:2;s:46:"Perubahan wettability batuan menjadi water-wet";i:3;s:27:"Peningkatan tekanan kapiler";}','','a:2:{i:0;s:35:"Penurunan tegangan antar muka (IFT)";i:1;s:46:"Perubahan wettability batuan menjadi water-wet";}','Select two factors that can reduce the Sor value in a reservoir','a:4:{i:0;s:38:"Reduction in interfacial tension (IFT)";i:1;s:25:"Increase in oil viscosity";i:2;s:38:"Changing rock wettability to water-wet";i:3;s:30:"Increase in capillary pressure";}','a:2:{i:0;s:38:"Reduction in interfacial tension (IFT)";i:1;s:38:"Changing rock wettability to water-wet";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000228','Efisiensi recovery pada reservoir dengan mekanisme water drive sangat bergantung pada','option','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:20:"Konektivitas aquifer";i:1;s:20:"Jumlah sumur injeksi";i:2;s:24:"Kadar porositas sekunder";i:3;s:27:"Tekanan kapiler batuan saja";}','','Konektivitas aquifer','Recovery efficiency in a water drive reservoir is highly dependent on','a:4:{i:0;s:20:"Aquifer connectivity";i:1;s:25:"Number of injection wells";i:2;s:26:"Secondary porosity content";i:3;s:36:"Capillary pressure of the rock alone";}','Aquifer connectivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000229','Mengapa gravity drainage seringkali menjadi mekanisme yang paling efisien dalam pemulihan minyak?','option','PFS000000023','Ujian Pelajaran','a:4:{i:0;s:67:"Karena memanfaatkan gaya alamiah yang konstan untuk drainase minyak";i:1;s:50:"Karena tekanan reservoir meningkat secara otomatis";i:2;s:54:"Karena air secara otomatis menggantikan seluruh minyak";i:3;s:38:"Karena tidak memerlukan sumur produksi";}','','Karena memanfaatkan gaya alamiah yang konstan untuk drainase minyak','Why is gravity drainage often the most efficient mechanism in oil recovery?','a:4:{i:0;s:61:"Because it utilizes a constant natural force for oil drainage";i:1;s:50:"Because reservoir pressure increases automatically";i:2;s:44:"Because water automatically replaces all oil";i:3;s:44:"Because it does not require production wells";}','Because it utilizes a constant natural force for oil drainage','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000230','Metode EOR mana yang paling efektif untuk reservoir minyak berat dengan viskositas tinggi guna menurunkan viskositas minyak secara drastis?','option','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:15:"Injeksi Polymer";i:1;s:20:"Injeksi Gas Miscible";i:2;s:16:"Thermal Recovery";i:3;s:15:"Injeksi Mikroba";}','','Thermal Recovery','Which EOR method is most effective for heavy oil reservoirs with high viscosity to drastically reduce oil viscosity?','a:4:{i:0;s:17:"Polymer Injection";i:1;s:22:"Miscible Gas Injection";i:2;s:16:"Thermal Recovery";i:3;s:19:"Microbial Injection";}','Thermal Recovery','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000231','Faktor utama yang membatasi penerapan injeksi gas miscible pada reservoir adalah sebagai berikut','multi','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:42:"Tekanan reservoir minimum yang disyaratkan";i:1;s:19:"Kedalaman reservoir";i:2;s:16:"Komposisi minyak";i:3;s:14:"Viskositas air";}','','a:2:{i:0;s:42:"Tekanan reservoir minimum yang disyaratkan";i:1;s:16:"Komposisi minyak";}','The main factors that limit the application of miscible gas injection in a reservoir are','a:4:{i:0;s:37:"Required minimum miscibility pressure";i:1;s:15:"Reservoir depth";i:2;s:15:"Oil composition";i:3;s:15:"Water viscosity";}','a:2:{i:0;s:37:"Required minimum miscibility pressure";i:1;s:15:"Oil composition";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000232','Manakah dari berikut ini yang merupakan mekanisme utama injeksi polymer dalam meningkatkan perolehan minyak?','option','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:35:"Menurunkan tegangan antarmuka (IFT)";i:1;s:35:"Meningkatkan viskositas air injeksi";i:2;s:25:"Mengubah kebasahan batuan";i:3;s:28:"Meningkatkan tekanan injeksi";}','','Meningkatkan viskositas air injeksi','Which of the following is the primary mechanism of polymer flooding in improving oil recovery?','a:4:{i:0;s:34:"Reducing Interfacial Tension (IFT)";i:1;s:36:"Increasing injection water viscosity";i:2;s:25:"Altering rock wettability";i:3;s:29:"Increasing injection pressure";}','Increasing injection water viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000233','Kriteria screening untuk injeksi thermal biasanya memerlukan nilai permeabilitas yang tinggi, yakni sekitar di atas','option','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:5:"10 mD";i:1;s:5:"50 mD";i:2;s:6:"200 mD";i:3;s:7:"1000 mD";}','','200 mD','Screening criteria for thermal injection usually require a high permeability value, which is around above','a:4:{i:0;s:5:"10 mD";i:1;s:5:"50 mD";i:2;s:6:"200 mD";i:3;s:7:"1000 mD";}','200 mD','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000234','Injeksi surfaktan dalam CEOR berfungsi terutama untuk','option','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:35:"Menurunkan tegangan antarmuka (IFT)";i:1;s:30:"Meningkatkan viskositas minyak";i:2;s:17:"Membekukan minyak";i:3;s:27:"Menurunkan porositas batuan";}','','Menurunkan tegangan antarmuka (IFT)','Surfactant injection in CEOR primarily functions to','a:4:{i:0;s:32:"Reduce Interfacial Tension (IFT)";i:1;s:22:"Increase oil viscosity";i:2;s:14:"Freeze the oil";i:3;s:22:"Decrease rock porosity";}','Reduce Interfacial Tension (IFT)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000235','Metode microbial EOR (MEOR) memanfaatkan aktivitas mikroba untuk memproduksi produk sampingan berupa','multi','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:16:"Gas (CO2/Metana)";i:1;s:18:"Asam dan surfaktan";i:2;s:7:"Polimer";i:3;s:11:"Logam berat";}','','a:3:{i:0;s:16:"Gas (CO2/Metana)";i:1;s:18:"Asam dan surfaktan";i:2;s:7:"Polimer";}','Microbial EOR (MEOR) methods utilize microbial activity to produce by-products in the form of','a:4:{i:0;s:17:"Gas (CO2/Methane)";i:1;s:21:"Acids and surfactants";i:2;s:8:"Polymers";i:3;s:12:"Heavy metals";}','a:3:{i:0;s:17:"Gas (CO2/Methane)";i:1;s:21:"Acids and surfactants";i:2;s:8:"Polymers";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000236','Batas maksimum viskositas minyak untuk penerapan injeksi polymer yang umum adalah sekitar','option','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:5:"10 cP";i:1;s:6:"150 cP";i:2;s:6:"500 cP";i:3;s:7:"1000 cP";}','','150 cP','The typical maximum oil viscosity limit for polymer injection application is around','a:4:{i:0;s:5:"10 cP";i:1;s:6:"150 cP";i:2;s:6:"500 cP";i:3;s:7:"1000 cP";}','150 cP','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000237','Injeksi gas miscible sangat bergantung pada parameter reservoir berikut ini','option','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:65:"Tekanan reservoir harus di atas tekanan misibilitas minimum (MMP)";i:1;s:48:"Suhu reservoir harus di bawah 20 derajat Celcius";i:2;s:27:"Porositas harus di bawah 5%";i:3;s:34:"Permeabilitas harus di bawah 10 mD";}','','Tekanan reservoir harus di atas tekanan misibilitas minimum (MMP)','Miscible gas injection is highly dependent on the following reservoir parameter','a:4:{i:0;s:71:"Reservoir pressure must be above the Minimum Miscibility Pressure (MMP)";i:1;s:54:"Reservoir temperature must be below 20 degrees Celsius";i:2;s:25:"Porosity must be below 5%";i:3;s:32:"Permeability must be below 10 mD";}','Reservoir pressure must be above the Minimum Miscibility Pressure (MMP)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000238','Mengapa injeksi thermal (seperti Steam Flooding) tidak disarankan untuk reservoir yang sangat dalam?','option','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:50:"Karena kehilangan panas yang besar di dalam tubing";i:1;s:29:"Karena tekanan terlalu rendah";i:2;s:38:"Karena minyak akan berubah menjadi gas";i:3;s:26:"Karena batuan akan mencair";}','','Karena kehilangan panas yang besar di dalam tubing','Why is thermal injection (such as Steam Flooding) not recommended for very deep reservoirs?','a:4:{i:0;s:42:"Because of massive heat loss in the tubing";i:1;s:31:"Because the pressure is too low";i:2;s:34:"Because the oil will turn into gas";i:3;s:26:"Because the rock will melt";}','Because of massive heat loss in the tubing','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000239','Kriteria utama untuk suksesnya penerapan chemical flooding adalah','option','PFS000000024','Ujian Pelajaran','a:4:{i:0;s:76:"Suhu reservoir yang tidak terlalu tinggi agar bahan kimia tidak terdegradasi";i:1;s:40:"Salinitas air formasi yang sangat tinggi";i:2;s:32:"Keberadaan gas bebas yang banyak";i:3;s:33:"Kedalaman reservoir harus dangkal";}','','Suhu reservoir yang tidak terlalu tinggi agar bahan kimia tidak terdegradasi','The key criterion for a successful chemical flooding application is','a:4:{i:0;s:69:"Reservoir temperature is not too high to prevent chemical degradation";i:1;s:34:"Very high formation water salinity";i:2;s:32:"Presence of significant free gas";i:3;s:31:"Reservoir depth must be shallow";}','Reservoir temperature is not too high to prevent chemical degradation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000240','Apa fungsi utama penambahan polimer ke dalam fluida injeksi pada proses Polymer Flooding?','option','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:35:"Meningkatkan viskositas air injeksi";i:1;s:33:"Mengurangi tekanan kapiler batuan";i:2;s:49:"Meningkatkan wettability batuan menjadi water-wet";i:3;s:46:"Menurunkan saturasi minyak residu di pori-pori";}','','Meningkatkan viskositas air injeksi','What is the primary function of adding polymers to the injection fluid in the Polymer Flooding process?','a:4:{i:0;s:34:"Increase injection water viscosity";i:1;s:30:"Reduce rock capillary pressure";i:2;s:36:"Change rock wettability to water-wet";i:3;s:38:"Lower residual oil saturation in pores";}','Increase injection water viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000241','Pilih faktor-faktor yang dipengaruhi langsung oleh penurunan mobility ratio (M) dalam proses Polymer Flooding.','multi','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:28:"Peningkatan sweep efficiency";i:1;s:27:"Penurunan saturasi air awal";i:2;s:40:"Perbaikan distribusi aliran di reservoir";i:3;s:40:"Peningkatan permeabilitas absolut batuan";}','','a:2:{i:0;s:28:"Peningkatan sweep efficiency";i:1;s:40:"Perbaikan distribusi aliran di reservoir";}','Select factors that are directly influenced by the reduction of mobility ratio (M) in the Polymer Flooding process.','a:4:{i:0;s:31:"Improvement in sweep efficiency";i:1;s:36:"Decrease in initial water saturation";i:2;s:49:"Improvement in flow distribution in the reservoir";i:3;s:38:"Increase in absolute rock permeability";}','a:2:{i:0;s:31:"Improvement in sweep efficiency";i:1;s:49:"Improvement in flow distribution in the reservoir";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000242','Bagaimana pengaruh peningkatan viskositas air terhadap nilai mobility ratio (M)?','option','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:20:"Meningkatkan nilai M";i:1;s:18:"Menurunkan nilai M";i:2;s:31:"Membuat nilai M menjadi konstan";i:3;s:26:"Tidak mempengaruhi nilai M";}','','Menurunkan nilai M','How does the increase in water viscosity affect the mobility ratio (M) value?','a:4:{i:0;s:17:"Increases M value";i:1;s:17:"Decreases M value";i:2;s:22:"Makes M value constant";i:3;s:23:"Does not affect M value";}','Decreases M value','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000243','Apa yang dimaksud dengan mobility ratio (M) dalam konteks EOR?','option','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:75:"Perbandingan mobilitas fluida pendesak dengan mobilitas fluida yang didesak";i:1;s:52:"Perbandingan viskositas minyak dengan viskositas air";i:2;s:51:"Perbandingan permeabilitas relatif dengan porositas";i:3;s:55:"Perbandingan kecepatan injeksi dengan tekanan reservoir";}','','Perbandingan mobilitas fluida pendesak dengan mobilitas fluida yang didesak','What is meant by mobility ratio (M) in the context of EOR?','a:4:{i:0;s:62:"Ratio of displacing fluid mobility to displaced fluid mobility";i:1;s:41:"Ratio of oil viscosity to water viscosity";i:2;s:42:"Ratio of relative permeability to porosity";i:3;s:45:"Ratio of injection rate to reservoir pressure";}','Ratio of displacing fluid mobility to displaced fluid mobility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000244','Mengapa mobility ratio yang tidak menguntungkan (M > 1) menyebabkan penurunan sweep efficiency?','option','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:34:"Terjadi fenomena viscous fingering";i:1;s:38:"Tekanan injeksi menjadi terlalu rendah";i:2;s:46:"Polimer teradsorpsi terlalu banyak pada batuan";i:3;s:47:"Viskositas air menjadi lebih tinggi dari minyak";}','','Terjadi fenomena viscous fingering','Why does an unfavorable mobility ratio (M > 1) lead to a decrease in sweep efficiency?','a:4:{i:0;s:35:"Viscous fingering phenomenon occurs";i:1;s:34:"Injection pressure becomes too low";i:2;s:38:"Polymer adsorbs too much onto the rock";i:3;s:39:"Water viscosity becomes higher than oil";}','Viscous fingering phenomenon occurs','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000245','Dalam desain Polymer Flooding, apa target utama dari kontrol mobilitas?','option','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:61:"Mencapai mobility ratio yang lebih rendah atau mendekati satu";i:1;s:57:"Meningkatkan saturasi minyak residu agar mudah diproduksi";i:2;s:59:"Menghentikan aliran air di zona dengan permeabilitas tinggi";i:3;s:43:"Mempercepat waktu tembus (breakthrough) air";}','','Mencapai mobility ratio yang lebih rendah atau mendekati satu','In Polymer Flooding design, what is the main target of mobility control?','a:4:{i:0;s:51:"Achieve a mobility ratio lower than or close to one";i:1;s:54:"Increase residual oil saturation for easier production";i:2;s:42:"Stop water flow in high permeability zones";i:3;s:34:"Accelerate water breakthrough time";}','Achieve a mobility ratio lower than or close to one','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000246','Manakah pernyataan yang tepat mengenai hubungan antara viskositas polimer dan sweep efficiency?','option','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:64:"Semakin tinggi viskositas polimer, semakin baik sweep efficiency";i:1;s:65:"Semakin tinggi viskositas polimer, semakin buruk sweep efficiency";i:2;s:57:"Sweep efficiency tidak bergantung pada viskositas polimer";i:3;s:55:"Viskositas polimer hanya mempengaruhi biaya operasional";}','','Semakin tinggi viskositas polimer, semakin baik sweep efficiency','Which statement is correct regarding the relationship between polymer viscosity and sweep efficiency?','a:4:{i:0;s:57:"Higher polymer viscosity leads to better sweep efficiency";i:1;s:56:"Higher polymer viscosity leads to worse sweep efficiency";i:2;s:53:"Sweep efficiency does not depend on polymer viscosity";i:3;s:48:"Polymer viscosity only affects operational costs";}','Higher polymer viscosity leads to better sweep efficiency','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000247','Komponen apa saja yang menentukan besarnya mobilitas fluida (lambda) dalam hukum Darcy?','multi','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:21:"Permeabilitas efektif";i:1;s:17:"Viskositas fluida";i:2;s:16:"Porositas batuan";i:3;s:15:"Tekanan kapiler";}','','a:2:{i:0;s:21:"Permeabilitas efektif";i:1;s:17:"Viskositas fluida";}','Which components determine the magnitude of fluid mobility (lambda) in Darcy''s Law?','a:4:{i:0;s:22:"Effective permeability";i:1;s:15:"Fluid viscosity";i:2;s:13:"Rock porosity";i:3;s:18:"Capillary pressure";}','a:2:{i:0;s:22:"Effective permeability";i:1;s:15:"Fluid viscosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000248','Apa yang terjadi pada profil injeksi air di reservoir heterogen jika polimer ditambahkan?','option','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:55:"Aliran lebih merata ke zona dengan permeabilitas rendah";i:1;s:57:"Air hanya mengalir ke zona dengan permeabilitas tertinggi";i:2;s:33:"Kecepatan injeksi menurun drastis";i:3;s:38:"Saturasi air di zona permeabel menurun";}','','Aliran lebih merata ke zona dengan permeabilitas rendah','What happens to the water injection profile in a heterogeneous reservoir if polymers are added?','a:4:{i:0;s:55:"Flow becomes more uniform into lower permeability zones";i:1;s:52:"Water only flows into the highest permeability zones";i:2;s:36:"Injection rate decreases drastically";i:3;s:45:"Water saturation in permeable zones decreases";}','Flow becomes more uniform into lower permeability zones','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000249','Manakah dari berikut ini yang merupakan tujuan utama perbaikan volumetric sweep efficiency?','option','PFS000000025','Ujian Pelajaran','a:4:{i:0;s:72:"Menjangkau minyak di zona yang sebelumnya tidak tersapu oleh air injeksi";i:1;s:47:"Mengubah sifat kimia minyak mentah di reservoir";i:2;s:47:"Menghilangkan efek gravitasi di dalam reservoir";i:3;s:40:"Mengurangi biaya penanganan air produksi";}','','Menjangkau minyak di zona yang sebelumnya tidak tersapu oleh air injeksi','Which of the following is a primary objective of improving volumetric sweep efficiency?','a:4:{i:0;s:61:"Contacting oil in zones previously unswept by injection water";i:1;s:62:"Changing the chemical properties of crude oil in the reservoir";i:2;s:50:"Eliminating gravitational effects in the reservoir";i:3;s:38:"Reducing produced water handling costs";}','Contacting oil in zones previously unswept by injection water','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000250','Apa perbedaan utama antara polimer sintetik HPAM dan biopolimer Xanthan dalam konteks injeksi polimer?','option','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:64:"HPAM bersifat pseudoplastik sedangkan Xanthan bersifat Newtonian";i:1;s:63:"HPAM lebih tahan terhadap salinitas tinggi dibandingkan Xanthan";i:2;s:103:"Struktur molekul HPAM berbentuk rantai linier fleksibel sedangkan Xanthan memiliki struktur heliks kaku";i:3;s:70:"Xanthan mengalami degradasi mekanik yang lebih parah dibandingkan HPAM";}','','Struktur molekul HPAM berbentuk rantai linier fleksibel sedangkan Xanthan memiliki struktur heliks kaku','What is the main difference between synthetic HPAM polymers and Xanthan biopolymers in the context of polymer injection?','a:4:{i:0;s:48:"HPAM is pseudoplastic while Xanthan is Newtonian";i:1;s:59:"HPAM is more resistant to high salinity compared to Xanthan";i:2;s:95:"HPAM molecular structure is a flexible linear chain while Xanthan has a rigid helical structure";i:3;s:62:"Xanthan undergoes more severe mechanical degradation than HPAM";}','HPAM molecular structure is a flexible linear chain while Xanthan has a rigid helical structure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000251','Sifat rheologi polimer HPAM sangat dipengaruhi oleh salinitas. Apa yang terjadi pada viskositas larutan HPAM saat salinitas air formasi meningkat?','option','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:28:"Viskositas meningkat drastis";i:1;s:65:"Viskositas menurun karena efek pelipatan rantai polimer (coiling)";i:2;s:45:"Viskositas tetap stabil tanpa dipengaruhi ion";i:3;s:54:"Viskositas meningkat karena pemanjangan rantai polimer";}','','Viskositas menurun karena efek pelipatan rantai polimer (coiling)','The rheological properties of HPAM polymers are highly influenced by salinity. What happens to the viscosity of HPAM solutions when formation water salinity increases?','a:4:{i:0;s:31:"Viscosity increases drastically";i:1;s:59:"Viscosity decreases due to the polymer chain coiling effect";i:2;s:43:"Viscosity remains stable regardless of ions";i:3;s:51:"Viscosity increases due to polymer chain elongation";}','Viscosity decreases due to the polymer chain coiling effect','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000252','Manakah faktor-faktor berikut yang dapat menyebabkan degradasi mekanik pada polimer saat melewati media berpori?','multi','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:52:"Laju alir yang sangat tinggi melalui pori-pori kecil";i:1;s:58:"Tekanan injeksi yang melebihi batas kekuatan tarik polimer";i:2;s:40:"Kadar salinitas yang rendah dalam fluida";i:3;s:47:"Suhu reservoir yang di bawah 50 derajat Celsius";}','','a:2:{i:0;s:52:"Laju alir yang sangat tinggi melalui pori-pori kecil";i:1;s:58:"Tekanan injeksi yang melebihi batas kekuatan tarik polimer";}','Which of the following factors can cause mechanical degradation of polymers when passing through porous media?','a:4:{i:0;s:40:"Very high flow rates through small pores";i:1;s:63:"Injection pressure exceeding the polymer tensile strength limit";i:2;s:32:"Low salinity levels in the fluid";i:3;s:47:"Reservoir temperatures below 50 degrees Celsius";}','a:2:{i:0;s:40:"Very high flow rates through small pores";i:1;s:63:"Injection pressure exceeding the polymer tensile strength limit";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000253','Mengapa Xanthan Gum dianggap lebih unggul dibandingkan HPAM dalam kondisi reservoir dengan salinitas yang tinggi?','option','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:55:"Karena Xanthan memiliki berat molekul yang lebih rendah";i:1;s:68:"Karena struktur heliks Xanthan melindunginya dari efek screening ion";i:2;s:41:"Karena Xanthan lebih murah secara ekonomi";i:3;s:49:"Karena Xanthan mudah terdegradasi secara biologis";}','','Karena struktur heliks Xanthan melindunginya dari efek screening ion','Why is Xanthan Gum considered superior to HPAM in reservoir conditions with high salinity?','a:4:{i:0;s:44:"Because Xanthan has a lower molecular weight";i:1;s:74:"Because Xanthan''s helical structure protects it from ion screening effects";i:2;s:47:"Because Xanthan is more economically affordable";i:3;s:39:"Because Xanthan is easily biodegradable";}','Because Xanthan''s helical structure protects it from ion screening effects','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000254','Dalam uji laboratorium, fenomena apa yang terjadi jika laju geser (shear rate) pada larutan polimer ditingkatkan?','option','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:34:"Viskositas meningkat secara linier";i:1;s:64:"Larutan polimer menunjukkan sifat shear-thinning (pseudoplastik)";i:2;s:61:"Larutan polimer menunjukkan sifat dilatant (shear-thickening)";i:3;s:30:"Tidak ada perubahan viskositas";}','','Larutan polimer menunjukkan sifat shear-thinning (pseudoplastik)','In laboratory tests, what phenomenon occurs if the shear rate of a polymer solution is increased?','a:4:{i:0;s:28:"Viscosity increases linearly";i:1;s:71:"The polymer solution exhibits shear-thinning (pseudoplastic) properties";i:2;s:68:"The polymer solution exhibits dilatant (shear-thickening) properties";i:3;s:31:"There is no change in viscosity";}','The polymer solution exhibits shear-thinning (pseudoplastic) properties','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000255','Apa dampak negatif dari degradasi termal pada polimer HPAM di reservoir dengan suhu tinggi?','option','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:44:"Peningkatan viskositas yang tidak terkendali";i:1;s:62:"Pemutusan rantai polimer yang menyebabkan penurunan viskositas";i:2;s:45:"Pembentukan endapan padat yang menyumbat pori";i:3;s:50:"Peningkatan kemampuan polimer untuk menyapu minyak";}','','Pemutusan rantai polimer yang menyebabkan penurunan viskositas','What is the negative impact of thermal degradation on HPAM polymers in high-temperature reservoirs?','a:4:{i:0;s:31:"Uncontrolled viscosity increase";i:1;s:48:"Polymer chain scission leading to viscosity loss";i:2;s:43:"Formation of solid deposits that plug pores";i:3;s:36:"Improved polymer sweeping efficiency";}','Polymer chain scission leading to viscosity loss','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000256','Manakah pernyataan yang benar mengenai sifat rheologi polimer Xanthan?','multi','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:55:"Viskositasnya tidak sensitif terhadap konsentrasi garam";i:1;s:52:"Menunjukkan viskositas tinggi pada laju geser rendah";i:2;s:64:"Sangat mudah terdegradasi oleh bakteri jika tidak diberi biosida";i:3;s:46:"Bersifat Newtonian murni pada semua laju geser";}','','a:3:{i:0;s:55:"Viskositasnya tidak sensitif terhadap konsentrasi garam";i:1;s:52:"Menunjukkan viskositas tinggi pada laju geser rendah";i:2;s:64:"Sangat mudah terdegradasi oleh bakteri jika tidak diberi biosida";}','Which statements are correct regarding the rheological properties of Xanthan polymers?','a:4:{i:0;s:50:"Its viscosity is insensitive to salt concentration";i:1;s:39:"Shows high viscosity at low shear rates";i:2;s:72:"Highly susceptible to bacterial degradation if not treated with biocides";i:3;s:38:"Is purely Newtonian at all shear rates";}','a:3:{i:0;s:50:"Its viscosity is insensitive to salt concentration";i:1;s:39:"Shows high viscosity at low shear rates";i:2;s:72:"Highly susceptible to bacterial degradation if not treated with biocides";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000257','Bagaimana pengaruh penambahan polimer terhadap mobilitas fluida di dalam reservoir?','option','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:47:"Meningkatkan mobilitas untuk mempercepat aliran";i:1;s:59:"Menurunkan mobilitas dengan meningkatkan viskositas larutan";i:2;s:47:"Mengurangi permeabilitas batuan secara permanen";i:3;s:43:"Tidak mengubah mobilitas fluida sama sekali";}','','Menurunkan mobilitas dengan meningkatkan viskositas larutan','How does the addition of polymers affect fluid mobility within the reservoir?','a:4:{i:0;s:37:"Increases mobility to accelerate flow";i:1;s:51:"Decreases mobility by increasing solution viscosity";i:2;s:37:"Permanently reduces rock permeability";i:3;s:37:"Does not change fluid mobility at all";}','Decreases mobility by increasing solution viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000258','Faktor apa yang paling menentukan ketahanan polimer HPAM terhadap degradasi hidrolisis dalam lingkungan reservoir?','option','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:43:"Derajat hidrolisis dan temperatur reservoir";i:1;s:34:"Tingkat kekasaran permukaan batuan";i:2;s:23:"Jumlah injeksi air laut";i:3;s:41:"Kecepatan adsorpsi pada permukaan mineral";}','','Derajat hidrolisis dan temperatur reservoir','What factor most determines the resistance of HPAM polymers to hydrolysis degradation in the reservoir environment?','a:4:{i:0;s:46:"Degree of hydrolysis and reservoir temperature";i:1;s:29:"Surface roughness of the rock";i:2;s:28:"Amount of seawater injection";i:3;s:35:"Adsorption rate on mineral surfaces";}','Degree of hydrolysis and reservoir temperature','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000259','Dalam konteks aplikasi EOR, apa yang dimaksud dengan ''adsorpsi polimer''?','option','PFS000000026','Ujian Pelajaran','a:4:{i:0;s:56:"Penempelan molekul polimer pada permukaan butiran batuan";i:1;s:37:"Larutnya polimer ke dalam fase minyak";i:2;s:38:"Proses penguapan polimer di dalam pori";i:3;s:34:"Pencampuran polimer dengan gas CO2";}','','Penempelan molekul polimer pada permukaan butiran batuan','In the context of EOR applications, what is meant by ''polymer adsorption''?','a:4:{i:0;s:57:"Attachment of polymer molecules to the rock grain surface";i:1;s:41:"Dissolution of polymer into the oil phase";i:2;s:47:"Process of polymer evaporation within the pores";i:3;s:31:"Mixing of polymers with CO2 gas";}','Attachment of polymer molecules to the rock grain surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000260','Apa parameter utama yang menentukan mobilitas fluida injeksi dalam desain polymer flooding?','option','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:43:"Viskositas polimer dan permeabilitas batuan";i:1;s:37:"Tekanan injeksi dan porositas efektif";i:2;s:43:"Temperatur formasi dan saturasi minyak sisa";i:3;s:43:"Salinitas air formasi dan kelarutan polimer";}','','Viskositas polimer dan permeabilitas batuan','What is the primary parameter determining injection fluid mobility in polymer flooding design?','a:4:{i:0;s:39:"Polymer viscosity and rock permeability";i:1;s:41:"Injection pressure and effective porosity";i:2;s:49:"Formation temperature and residual oil saturation";i:3;s:47:"Formation water salinity and polymer solubility";}','Polymer viscosity and rock permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000261','Faktor apa saja yang harus dipertimbangkan dalam menentukan ukuran slug (slug size) polimer?','multi','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:38:"Efisiensi penyapuan (sweep efficiency)";i:1;s:17:"Biaya bahan kimia";i:2;s:23:"Heterogenitas reservoir";i:3;s:24:"Kecepatan injeksi fluida";}','','a:3:{i:0;s:38:"Efisiensi penyapuan (sweep efficiency)";i:1;s:17:"Biaya bahan kimia";i:2;s:23:"Heterogenitas reservoir";}','What factors must be considered when determining the polymer slug size?','a:4:{i:0;s:16:"Sweep efficiency";i:1;s:14:"Chemical costs";i:2;s:23:"Reservoir heterogeneity";i:3;s:20:"Fluid injection rate";}','a:3:{i:0;s:16:"Sweep efficiency";i:1;s:14:"Chemical costs";i:2;s:23:"Reservoir heterogeneity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000262','Bagaimana pengaruh peningkatan konsentrasi polimer terhadap injektivitas di dalam reservoir?','option','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:48:"Injektivitas menurun karena viskositas meningkat";i:1;s:48:"Injektivitas meningkat karena viskositas menurun";i:2;s:40:"Tidak ada pengaruh terhadap injektivitas";i:3;s:55:"Injektivitas meningkat secara linier dengan konsentrasi";}','','Injektivitas menurun karena viskositas meningkat','How does increasing polymer concentration affect injectivity within the reservoir?','a:4:{i:0;s:48:"Injectivity decreases due to increased viscosity";i:1;s:48:"Injectivity increases due to decreased viscosity";i:2;s:24:"No effect on injectivity";i:3;s:49:"Injectivity increases linearly with concentration";}','Injectivity decreases due to increased viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000263','Apa yang dimaksud dengan ''adsorpsi polimer'' dalam konteks desain CEOR?','option','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:56:"Kehilangan polimer akibat menempel pada permukaan batuan";i:1;s:48:"Peningkatan konsentrasi polimer karena penguapan";i:2;s:36:"Pengenceran polimer oleh air formasi";i:3;s:41:"Reaksi kimia polimer dengan minyak mentah";}','','Kehilangan polimer akibat menempel pada permukaan batuan','What is meant by ''polymer adsorption'' in the context of CEOR design?','a:4:{i:0;s:47:"Polymer loss due to attachment to rock surfaces";i:1;s:49:"Polymer concentration increase due to evaporation";i:2;s:35:"Polymer dilution by formation water";i:3;s:43:"Chemical reaction of polymer with crude oil";}','Polymer loss due to attachment to rock surfaces','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000264','Dalam studi kasus implementasi lapangan, apa tantangan utama penggunaan polimer HPAM pada reservoir dengan salinitas tinggi?','option','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:50:"Degradasi viskositas akibat sensitivitas salinitas";i:1;s:30:"Polimer menjadi terlalu kental";i:2;s:30:"Polimer mengalami kristalisasi";i:3;s:44:"Kebutuhan tekanan injeksi yang sangat rendah";}','','Degradasi viskositas akibat sensitivitas salinitas','In field implementation case studies, what is the main challenge of using HPAM polymers in high-salinity reservoirs?','a:4:{i:0;s:49:"Viscosity degradation due to salinity sensitivity";i:1;s:27:"Polymer becomes too viscous";i:2;s:33:"Polymer undergoes crystallization";i:3;s:43:"Requirement for very low injection pressure";}','Viscosity degradation due to salinity sensitivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000265','Apa tujuan utama penambahan ''tracer'' dalam uji injeksi polimer?','option','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:39:"Melacak jalur aliran (flow path) fluida";i:1;s:30:"Meningkatkan viskositas fluida";i:2;s:27:"Mengurangi adsorpsi polimer";i:3;s:24:"Mengukur tekanan kapiler";}','','Melacak jalur aliran (flow path) fluida','What is the primary purpose of adding a ''tracer'' in polymer injection tests?','a:4:{i:0;s:25:"To track fluid flow paths";i:1;s:27:"To increase fluid viscosity";i:2;s:28:"To reduce polymer adsorption";i:3;s:29:"To measure capillary pressure";}','To track fluid flow paths','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000266','Fenomena apa yang menyebabkan hambatan aliran (resistance factor) meningkat selama injeksi polimer?','option','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:52:"Penyumbatan pori (pore plugging) dan viscoelasticity";i:1;s:29:"Penurunan tegangan antar muka";i:2;s:25:"Peningkatan kelarutan gas";i:3;s:24:"Pengurangan saturasi air";}','','Penyumbatan pori (pore plugging) dan viscoelasticity','What phenomenon causes the resistance factor to increase during polymer injection?','a:4:{i:0;s:33:"Pore plugging and viscoelasticity";i:1;s:32:"Reduction in interfacial tension";i:2;s:26:"Increase in gas solubility";i:3;s:29:"Reduction in water saturation";}','Pore plugging and viscoelasticity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000267','Manakah pernyataan yang benar mengenai desain slug polimer?','multi','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:56:"Konsentrasi polimer disesuaikan dengan viskositas minyak";i:1;s:63:"Ukuran slug biasanya berkisar antara 0.5 hingga 1.0 pore volume";i:2;s:52:"Suhu reservoir tidak mempengaruhi stabilitas polimer";i:3;s:53:"Kompatibilitas polimer dengan air formasi harus diuji";}','','a:3:{i:0;s:56:"Konsentrasi polimer disesuaikan dengan viskositas minyak";i:1;s:63:"Ukuran slug biasanya berkisar antara 0.5 hingga 1.0 pore volume";i:2;s:53:"Kompatibilitas polimer dengan air formasi harus diuji";}','Which statements are true regarding polymer slug design?','a:4:{i:0;s:50:"Polymer concentration is adjusted to oil viscosity";i:1;s:45:"Slug size is typically 0.5 to 1.0 pore volume";i:2;s:55:"Reservoir temperature does not affect polymer stability";i:3;s:57:"Polymer compatibility with formation water must be tested";}','a:3:{i:0;s:50:"Polymer concentration is adjusted to oil viscosity";i:1;s:45:"Slug size is typically 0.5 to 1.0 pore volume";i:2;s:57:"Polymer compatibility with formation water must be tested";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000268','Mengapa ''shear degradation'' menjadi perhatian serius dalam desain fasilitas permukaan injeksi polimer?','option','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:60:"Karena dapat menurunkan berat molekul polimer dan viskositas";i:1;s:43:"Karena menyebabkan korosi pada pipa injeksi";i:2;s:43:"Karena meningkatkan biaya operasional pompa";i:3;s:44:"Karena menyebabkan pemisahan fase minyak-air";}','','Karena dapat menurunkan berat molekul polimer dan viskositas','Why is ''shear degradation'' a serious concern in the design of polymer injection surface facilities?','a:4:{i:0;s:60:"Because it can reduce polymer molecular weight and viscosity";i:1;s:46:"Because it causes corrosion in injection pipes";i:2;s:41:"Because it increases pump operating costs";i:3;s:44:"Because it causes oil-water phase separation";}','Because it can reduce polymer molecular weight and viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000269','Apa dampak utama dari keberhasilan desain mobilitas rasio dalam polymer flooding?','option','PFS000000027','Ujian Pelajaran','a:4:{i:0;s:46:"Peningkatan perolehan minyak (recovery factor)";i:1;s:28:"Peningkatan biaya pengeboran";i:2;s:40:"Penurunan tekanan injeksi secara drastis";i:3;s:42:"Eliminasi total dari air sisa di reservoir";}','','Peningkatan perolehan minyak (recovery factor)','What is the primary impact of a successful mobility ratio design in polymer flooding?','a:4:{i:0;s:40:"Increased oil recovery (recovery factor)";i:1;s:24:"Increased drilling costs";i:2;s:39:"Drastic reduction in injection pressure";i:3;s:52:"Total elimination of residual water in the reservoir";}','Increased oil recovery (recovery factor)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000270','Apa fungsi utama penambahan surfaktan dalam proses Chemical Enhanced Oil Recovery (CEOR)?','option','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:58:"Menurunkan tegangan antar muka (IFT) antara minyak dan air";i:1;s:50:"Meningkatkan viskositas air injeksi secara drastis";i:2;s:43:"Mengubah wettability batuan menjadi oil-wet";i:3;s:41:"Meningkatkan permeabilitas absolut batuan";}','','Menurunkan tegangan antar muka (IFT) antara minyak dan air','What is the primary function of adding surfactants in the Chemical Enhanced Oil Recovery (CEOR) process?','a:4:{i:0;s:60:"Lowering the interfacial tension (IFT) between oil and water";i:1;s:56:"Dramatically increasing the viscosity of injection water";i:2;s:36:"Changing rock wettability to oil-wet";i:3;s:48:"Increasing the absolute permeability of the rock";}','Lowering the interfacial tension (IFT) between oil and water','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000271','Faktor apa saja yang menentukan besarnya Capillary Number (Nc)?','multi','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:20:"Kecepatan aliran (v)";i:1;s:22:"Viskositas fluida (μ)";i:2;s:25:"Tegangan antar muka (IFT)";i:3;s:16:"Porositas batuan";}','','a:3:{i:0;s:20:"Kecepatan aliran (v)";i:1;s:22:"Viskositas fluida (μ)";i:2;s:25:"Tegangan antar muka (IFT)";}','What factors determine the magnitude of the Capillary Number (Nc)?','a:4:{i:0;s:17:"Flow velocity (v)";i:1;s:20:"Fluid viscosity (μ)";i:2;s:25:"Interfacial tension (IFT)";i:3;s:13:"Rock porosity";}','a:3:{i:0;s:17:"Flow velocity (v)";i:1;s:20:"Fluid viscosity (μ)";i:2;s:25:"Interfacial tension (IFT)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000272','Bagaimana hubungan antara Capillary Number dan saturasi minyak residual (Sor)?','option','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:49:"Semakin besar Capillary Number, semakin kecil Sor";i:1;s:49:"Semakin besar Capillary Number, semakin besar Sor";i:2;s:23:"Hubungan linear positif";i:3;s:34:"Tidak ada hubungan antara keduanya";}','','Semakin besar Capillary Number, semakin kecil Sor','What is the relationship between the Capillary Number and residual oil saturation (Sor)?','a:4:{i:0;s:50:"The larger the Capillary Number, the lower the Sor";i:1;s:51:"The larger the Capillary Number, the higher the Sor";i:2;s:28:"Positive linear relationship";i:3;s:31:"No relationship between the two";}','The larger the Capillary Number, the lower the Sor','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000273','Pada kondisi reservoir normal, gaya apa yang paling dominan menahan minyak di dalam pori-pori batuan?','option','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:12:"Gaya kapiler";i:1;s:14:"Gaya gravitasi";i:2;s:12:"Gaya inersia";i:3;s:11:"Gaya viskos";}','','Gaya kapiler','Under normal reservoir conditions, which force is most dominant in trapping oil within the rock pores?','a:4:{i:0;s:15:"Capillary force";i:1;s:13:"Gravity force";i:2;s:14:"Inertial force";i:3;s:13:"Viscous force";}','Capillary force','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000274','Berapa besaran penurunan IFT yang diperlukan agar minyak residual dapat termobilisasi secara signifikan?','option','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:32:"Penurunan hingga orde 10^-3 mN/m";i:1;s:32:"Penurunan hingga orde 10^-1 mN/m";i:2;s:25:"Tidak perlu penurunan IFT";i:3;s:31:"Peningkatan IFT hingga 100 mN/m";}','','Penurunan hingga orde 10^-3 mN/m','What magnitude of IFT reduction is required to significantly mobilize residual oil?','a:4:{i:0;s:36:"Reduction to the order of 10^-3 mN/m";i:1;s:36:"Reduction to the order of 10^-1 mN/m";i:2;s:23:"No IFT reduction needed";i:3;s:27:"Increase in IFT to 100 mN/m";}','Reduction to the order of 10^-3 mN/m','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000275','Apa yang terjadi pada tetesan minyak residual ketika Capillary Number ditingkatkan melampaui batas kritis?','option','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:60:"Tetesan minyak terdeformasi dan dapat bergerak melewati pori";i:1;s:53:"Tetesan minyak pecah menjadi mikro-emulsi yang stabil";i:2;s:43:"Tetesan minyak akan terperangkap lebih kuat";i:3;s:51:"Tetesan minyak akan berikatan dengan mineral batuan";}','','Tetesan minyak terdeformasi dan dapat bergerak melewati pori','What happens to residual oil droplets when the Capillary Number is increased beyond the critical limit?','a:4:{i:0;s:46:"Oil droplets deform and can move through pores";i:1;s:46:"Oil droplets break into stable micro-emulsions";i:2;s:41:"Oil droplets become more strongly trapped";i:3;s:36:"Oil droplets bond with rock minerals";}','Oil droplets deform and can move through pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000276','Manakah pernyataan yang benar mengenai mekanisme ''roll-up'' pada surfaktan?','option','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:51:"Surfaktan menggantikan minyak dari permukaan batuan";i:1;s:51:"Surfaktan meningkatkan gaya adhesi minyak ke batuan";i:2;s:33:"Surfaktan menghentikan aliran air";i:3;s:45:"Surfaktan meningkatkan tegangan permukaan air";}','','Surfaktan menggantikan minyak dari permukaan batuan','Which statement is correct regarding the ''roll-up'' mechanism of surfactants?','a:4:{i:0;s:46:"Surfactant displaces oil from the rock surface";i:1;s:41:"Surfactant increases oil adhesion to rock";i:2;s:27:"Surfactant stops water flow";i:3;s:42:"Surfactant increases water surface tension";}','Surfactant displaces oil from the rock surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000277','Pilih parameter yang memengaruhi keberhasilan mobilisasi minyak dalam Chemical EOR:','multi','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:21:"Salinitas air formasi";i:1;s:30:"Adsorpsi surfaktan pada batuan";i:2;s:20:"Temperatur reservoir";i:3;s:15:"Densitas batuan";}','','a:3:{i:0;s:21:"Salinitas air formasi";i:1;s:30:"Adsorpsi surfaktan pada batuan";i:2;s:20:"Temperatur reservoir";}','Select the parameters that affect the success of oil mobilization in Chemical EOR:','a:4:{i:0;s:24:"Formation water salinity";i:1;s:29:"Surfactant adsorption on rock";i:2;s:21:"Reservoir temperature";i:3;s:12:"Rock density";}','a:3:{i:0;s:24:"Formation water salinity";i:1;s:29:"Surfactant adsorption on rock";i:2;s:21:"Reservoir temperature";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000278','Apakah keuntungan dari tercapainya kondisi ''ultra-low IFT'' dalam aplikasi surfaktan?','option','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:38:"Mengurangi gaya kapiler penahan minyak";i:1;s:30:"Meningkatkan viskositas minyak";i:2;s:33:"Mempercepat pengendapan surfaktan";i:3;s:40:"Menghilangkan kebutuhan akan injeksi air";}','','Mengurangi gaya kapiler penahan minyak','What is the advantage of achieving ''ultra-low IFT'' conditions in surfactant applications?','a:4:{i:0;s:42:"Reducing capillary forces trapping the oil";i:1;s:24:"Increasing oil viscosity";i:2;s:37:"Accelerating surfactant precipitation";i:3;s:40:"Eliminating the need for water injection";}','Reducing capillary forces trapping the oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000279','Dalam konteks mobilisasi minyak, apa peran dari ''mikro-emulsi''?','option','PFS000000028','Ujian Pelajaran','a:4:{i:0;s:60:"Memungkinkan minyak terlarut dalam fase air untuk diproduksi";i:1;s:31:"Meningkatkan tegangan permukaan";i:2;s:26:"Menyumbat pori-pori batuan";i:3;s:37:"Meningkatkan saturasi minyak residual";}','','Memungkinkan minyak terlarut dalam fase air untuk diproduksi','In the context of oil mobilization, what is the role of ''micro-emulsion''?','a:4:{i:0;s:64:"Enabling oil to be dissolved in the aqueous phase for production";i:1;s:26:"Increasing surface tension";i:2;s:19:"Plugging rock pores";i:3;s:34:"Increasing residual oil saturation";}','Enabling oil to be dissolved in the aqueous phase for production','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000280','Proses kimia utama yang terjadi ketika agen alkali bereaksi dengan asam naftenat dalam minyak mentah untuk membentuk surfaktan in-situ adalah','option','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:12:"Saponifikasi";i:1;s:12:"Emulsifikasi";i:2;s:8:"Adsorpsi";i:3;s:11:"Presipitasi";}','','Saponifikasi','The primary chemical process that occurs when alkaline agents react with naphthenic acids in crude oil to form in-situ surfactants is','a:4:{i:0;s:14:"Saponification";i:1;s:14:"Emulsification";i:2;s:10:"Adsorption";i:3;s:13:"Precipitation";}','Saponification','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000281','Apa fungsi utama penambahan alkali dalam sistem ASP (Alkaline-Surfactant-Polymer) terkait dengan interaksi batuan?','option','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:51:"Mengurangi adsorpsi surfaktan pada permukaan batuan";i:1;s:35:"Meningkatkan viskositas air injeksi";i:2;s:43:"Mengubah wettability batuan menjadi oil-wet";i:3;s:28:"Meningkatkan tekanan kapiler";}','','Mengurangi adsorpsi surfaktan pada permukaan batuan','What is the primary function of adding alkali in an ASP (Alkaline-Surfactant-Polymer) system regarding rock interaction?','a:4:{i:0;s:47:"Reducing surfactant adsorption on rock surfaces";i:1;s:36:"Increasing injection water viscosity";i:2;s:36:"Changing rock wettability to oil-wet";i:3;s:29:"Increasing capillary pressure";}','Reducing surfactant adsorption on rock surfaces','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000282','Sinergi antara alkali dan surfaktan dalam proses EOR bertujuan untuk mencapai kondisi apa?','multi','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:44:"Tegangan antar muka (IFT) yang sangat rendah";i:1;s:37:"Kelarutan surfaktan yang lebih tinggi";i:2;s:30:"Pembentukan emulsi yang stabil";i:3;s:30:"Pengurangan konsumsi surfaktan";}','','a:2:{i:0;s:44:"Tegangan antar muka (IFT) yang sangat rendah";i:1;s:30:"Pengurangan konsumsi surfaktan";}','The synergy between alkali and surfactant in an EOR process aims to achieve which conditions?','a:4:{i:0;s:35:"Ultra-low interfacial tension (IFT)";i:1;s:28:"Higher surfactant solubility";i:2;s:29:"Formation of stable emulsions";i:3;s:35:"Reduction of surfactant consumption";}','a:2:{i:0;s:35:"Ultra-low interfacial tension (IFT)";i:1;s:35:"Reduction of surfactant consumption";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000283','Manakah dari berikut ini yang merupakan kelemahan potensial dari penggunaan alkali dalam flooding?','option','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:35:"Pembentukan kerak (scale) anorganik";i:1;s:29:"Peningkatan viskositas minyak";i:2;s:24:"Penurunan pH air formasi";i:3;s:30:"Peningkatan adsorpsi surfaktan";}','','Pembentukan kerak (scale) anorganik','Which of the following is a potential disadvantage of using alkali in flooding?','a:4:{i:0;s:25:"Inorganic scale formation";i:1;s:23:"Increased oil viscosity";i:2;s:30:"Decrease in formation water pH";i:3;s:31:"Increased surfactant adsorption";}','Inorganic scale formation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000284','Pada kondisi reservoir apa alkaline flooding paling efektif digunakan?','option','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:43:"Minyak dengan kandungan asam organik tinggi";i:1;s:45:"Reservoir dengan salinitas yang sangat rendah";i:2;s:31:"Reservoir batuan karbonat murni";i:3;s:49:"Minyak dengan viskositas sangat tinggi (>1000 cP)";}','','Minyak dengan kandungan asam organik tinggi','Under what reservoir conditions is alkaline flooding most effectively applied?','a:4:{i:0;s:40:"Crude oil with high organic acid content";i:1;s:32:"Reservoir with very low salinity";i:2;s:29:"Pure carbonate rock reservoir";i:3;s:39:"Oil with very high viscosity (>1000 cP)";}','Crude oil with high organic acid content','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000285','Bagaimana mekanisme alkali mengurangi adsorpsi surfaktan pada batuan?','option','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:53:"Membuat muatan permukaan batuan menjadi lebih negatif";i:1;s:42:"Meningkatkan kelarutan surfaktan dalam air";i:2;s:29:"Mengurangi viskositas larutan";i:3;s:31:"Meningkatkan tegangan permukaan";}','','Membuat muatan permukaan batuan menjadi lebih negatif','How does the alkaline mechanism reduce surfactant adsorption on rocks?','a:4:{i:0;s:47:"By making the rock surface charge more negative";i:1;s:44:"By increasing surfactant solubility in water";i:2;s:30:"By reducing solution viscosity";i:3;s:29:"By increasing surface tension";}','By making the rock surface charge more negative','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000286','Dalam sistem ASP, peran polimer adalah untuk','option','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:27:"Mengontrol mobilitas fluida";i:1;s:30:"Mengurangi tegangan antar muka";i:2;s:25:"Menetralkan asam naftenat";i:3;s:26:"Mencegah pembentukan scale";}','','Mengontrol mobilitas fluida','In an ASP system, the role of the polymer is to','a:4:{i:0;s:22:"Control fluid mobility";i:1;s:26:"Reduce interfacial tension";i:2;s:27:"Neutralize naphthenic acids";i:3;s:23:"Prevent scale formation";}','Control fluid mobility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000287','Mengapa alkali dapat membantu mengubah kebasahan (wettability) batuan?','option','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:68:"Melalui interaksi kimia dengan komponen minyak pada permukaan batuan";i:1;s:35:"Dengan meningkatkan tekanan injeksi";i:2;s:44:"Melalui proses pelarutan batuan secara total";i:3;s:32:"Dengan menurunkan suhu reservoir";}','','Melalui interaksi kimia dengan komponen minyak pada permukaan batuan','Why can alkali help change the wettability of the rock?','a:4:{i:0;s:68:"Through chemical interaction with oil components on the rock surface";i:1;s:32:"By increasing injection pressure";i:2;s:38:"Through total rock dissolution process";i:3;s:33:"By lowering reservoir temperature";}','Through chemical interaction with oil components on the rock surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000288','Apa dampak negatif jika konsentrasi alkali terlalu tinggi dalam proses flooding?','option','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:49:"Potensi pengendapan mineral dan kerusakan formasi";i:1;s:39:"Peningkatan drastis tegangan antar muka";i:2;s:41:"Surfaktan tidak dapat bekerja sama sekali";i:3;s:48:"Polimer kehilangan viskositasnya secara permanen";}','','Potensi pengendapan mineral dan kerusakan formasi','What is the negative impact if the alkaline concentration is too high in the flooding process?','a:4:{i:0;s:56:"Potential for mineral precipitation and formation damage";i:1;s:39:"Drastic increase in interfacial tension";i:2;s:33:"Surfactant cannot function at all";i:3;s:39:"Polymer permanently loses its viscosity";}','Potential for mineral precipitation and formation damage','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000289','Sebutkan parameter yang mempengaruhi efektivitas reaksi saponifikasi in-situ','multi','PFS000000029','Ujian Pelajaran','a:4:{i:0;s:41:"Kandungan asam dalam minyak (Acid Number)";i:1;s:38:"Ketersediaan ion kalsium dan magnesium";i:2;s:18:"pH larutan injeksi";i:3;s:16:"Porositas batuan";}','','a:3:{i:0;s:41:"Kandungan asam dalam minyak (Acid Number)";i:1;s:38:"Ketersediaan ion kalsium dan magnesium";i:2;s:18:"pH larutan injeksi";}','Mention the parameters that affect the effectiveness of in-situ saponification reactions','a:4:{i:0;s:33:"Acid content in oil (Acid Number)";i:1;s:42:"Availability of calcium and magnesium ions";i:2;s:21:"Injection solution pH";i:3;s:13:"Rock porosity";}','a:3:{i:0;s:33:"Acid content in oil (Acid Number)";i:1;s:42:"Availability of calcium and magnesium ions";i:2;s:21:"Injection solution pH";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000290','Apa fungsi utama penambahan alkaline dalam proses ASP flooding pada studi kasus lapangan mature?','option','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:44:"Menurunkan tegangan antarmuka secara drastis";i:1;s:41:"Mengurangi adsorpsi surfaktan pada batuan";i:2;s:35:"Meningkatkan viskositas air injeksi";i:3;s:38:"Memperbesar porositas batuan reservoir";}','','Mengurangi adsorpsi surfaktan pada batuan','What is the primary function of adding alkaline in the ASP flooding process for mature field case studies?','a:4:{i:0;s:38:"Drastically reduce interfacial tension";i:1;s:40:"Reduce surfactant adsorption on the rock";i:2;s:34:"Increase injection water viscosity";i:3;s:32:"Increase reservoir rock porosity";}','Reduce surfactant adsorption on the rock','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000291','Faktor apa saja yang menjadi tantangan utama implementasi Chemical EOR di lapangan dengan salinitas tinggi?','multi','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:17:"Presipitasi kimia";i:1;s:26:"Degradasi termal surfaktan";i:2;s:33:"Peningkatan permeabilitas absolut";i:3;s:29:"Ketidakstabilan fase campuran";}','','a:2:{i:0;s:17:"Presipitasi kimia";i:1;s:29:"Ketidakstabilan fase campuran";}','What are the main challenges in implementing Chemical EOR in high salinity fields?','a:4:{i:0;s:22:"Chemical precipitation";i:1;s:30:"Thermal surfactant degradation";i:2;s:30:"Absolute permeability increase";i:3;s:17:"Phase instability";}','a:2:{i:0;s:22:"Chemical precipitation";i:1;s:17:"Phase instability";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000292','Dalam pertimbangan ekonomi CEOR, apa dampak kenaikan harga minyak dunia terhadap Net Present Value (NPV) proyek?','option','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:44:"Menurunkan NPV karena biaya operasional naik";i:1;s:37:"Tidak berpengaruh pada ekonomi proyek";i:2;s:63:"Meningkatkan NPV karena margin keuntungan per barel lebih besar";i:3;s:53:"Meningkatkan biaya investasi awal secara proporsional";}','','Meningkatkan NPV karena margin keuntungan per barel lebih besar','In CEOR economic considerations, what is the impact of rising global oil prices on the project''s Net Present Value (NPV)?','a:4:{i:0;s:45:"Decreases NPV due to rising operational costs";i:1;s:34:"Has no effect on project economics";i:2;s:52:"Increases NPV due to higher profit margin per barrel";i:3;s:49:"Increases initial investment costs proportionally";}','Increases NPV due to higher profit margin per barrel','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000293','Mengapa adsorpsi surfaktan pada mineral lempung merupakan tantangan kritis dalam desain injeksi kimia?','option','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:54:"Karena dapat menyebabkan penyumbatan pori secara fisik";i:1;s:71:"Karena akan menghilangkan surfaktan dari fase fluida dan menambah biaya";i:2;s:44:"Karena meningkatkan viskositas larutan kimia";i:3;s:46:"Karena mempercepat laju korosi peralatan sumur";}','','Karena akan menghilangkan surfaktan dari fase fluida dan menambah biaya','Why is surfactant adsorption on clay minerals a critical challenge in chemical injection design?','a:4:{i:0;s:43:"Because it can cause physical pore plugging";i:1;s:70:"Because it removes surfactant from the fluid phase and increases costs";i:2;s:48:"Because it increases chemical solution viscosity";i:3;s:53:"Because it accelerates well equipment corrosion rates";}','Because it removes surfactant from the fluid phase and increases costs','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000294','Manakah dari berikut ini yang merupakan indikator keberhasilan teknis dalam proyek surfaktan flooding?','option','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:40:"Penurunan saturasi minyak residual (Sor)";i:1;s:36:"Peningkatan viskositas minyak mentah";i:2;s:30:"Penurunan densitas air injeksi";i:3;s:49:"Peningkatan tekanan injeksi di atas tekanan rekah";}','','Penurunan saturasi minyak residual (Sor)','Which of the following is a technical success indicator in a surfactant flooding project?','a:4:{i:0;s:42:"Reduction in residual oil saturation (Sor)";i:1;s:31:"Increase in crude oil viscosity";i:2;s:35:"Decrease in injection water density";i:3;s:56:"Increase in injection pressure above fracturing pressure";}','Reduction in residual oil saturation (Sor)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000295','Bagaimana pengaruh heterogenitas reservoir terhadap efisiensi perolehan minyak pada aplikasi CEOR?','option','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:48:"Meningkatkan efisiensi sapuan (sweep efficiency)";i:1;s:56:"Menyebabkan channeling yang mengurangi efektivitas kimia";i:2;s:32:"Tidak memiliki dampak signifikan";i:3;s:39:"Membantu distribusi kimia secara merata";}','','Menyebabkan channeling yang mengurangi efektivitas kimia','How does reservoir heterogeneity affect oil recovery efficiency in CEOR applications?','a:4:{i:0;s:26:"Increases sweep efficiency";i:1;s:53:"Causes channeling that reduces chemical effectiveness";i:2;s:25:"Has no significant impact";i:3;s:33:"Helps distribute chemicals evenly";}','Causes channeling that reduces chemical effectiveness','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000296','Pada studi kasus ASP, apa yang terjadi jika konsentrasi alkaline terlalu tinggi?','option','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:37:"Terjadi perbaikan efisiensi penyapuan";i:1;s:53:"Terjadi pembentukan kerak (scale) yang menyumbat pori";i:2;s:29:"Surfaktan menjadi lebih aktif";i:3;s:43:"Adsorpsi surfaktan justru meningkat drastis";}','','Terjadi pembentukan kerak (scale) yang menyumbat pori','In ASP case studies, what happens if the alkaline concentration is too high?','a:4:{i:0;s:32:"Improved sweep efficiency occurs";i:1;s:39:"Scale formation occurs that plugs pores";i:2;s:30:"Surfactant becomes more active";i:3;s:43:"Surfactant adsorption increases drastically";}','Scale formation occurs that plugs pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000297','Apa tujuan utama penambahan polimer dalam formulasi ASP (Alkaline-Surfactant-Polymer)?','option','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:29:"Mengurangi tegangan antarmuka";i:1;s:35:"Mengontrol mobilitas fluida injeksi";i:2;s:31:"Mengurangi nilai pH air formasi";i:3;s:32:"Meningkatkan kelarutan surfaktan";}','','Mengontrol mobilitas fluida injeksi','What is the main purpose of adding polymer in an ASP (Alkaline-Surfactant-Polymer) formulation?','a:4:{i:0;s:26:"Reduce interfacial tension";i:1;s:32:"Control injection fluid mobility";i:2;s:25:"Reduce formation water pH";i:3;s:30:"Increase surfactant solubility";}','Control injection fluid mobility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000298','Apa parameter ekonomi yang paling sensitif terhadap ketidakpastian volume perolehan minyak (incremental oil) pada proyek CEOR?','multi','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:29:"Internal Rate of Return (IRR)";i:1;s:16:"Pajak perusahaan";i:2;s:23:"Net Present Value (NPV)";i:3;s:24:"Biaya pemeliharaan rutin";}','','a:2:{i:0;s:29:"Internal Rate of Return (IRR)";i:1;s:23:"Net Present Value (NPV)";}','Which economic parameters are most sensitive to the uncertainty of incremental oil volume in CEOR projects?','a:4:{i:0;s:29:"Internal Rate of Return (IRR)";i:1;s:13:"Corporate tax";i:2;s:23:"Net Present Value (NPV)";i:3;s:25:"Routine maintenance costs";}','a:2:{i:0;s:29:"Internal Rate of Return (IRR)";i:1;s:23:"Net Present Value (NPV)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000299','Mengapa pemilihan jenis surfaktan harus disesuaikan dengan suhu reservoir?','option','PFS000000030','Ujian Pelajaran','a:4:{i:0;s:58:"Suhu mempengaruhi stabilitas kimia dan aktivitas surfaktan";i:1;s:37:"Suhu mengubah nilai porositas absolut";i:2;s:33:"Suhu menentukan harga jual minyak";i:3;s:55:"Suhu tidak memiliki kaitan dengan efektivitas surfaktan";}','','Suhu mempengaruhi stabilitas kimia dan aktivitas surfaktan','Why must the type of surfactant be matched to the reservoir temperature?','a:4:{i:0;s:62:"Temperature affects chemical stability and surfactant activity";i:1;s:44:"Temperature changes absolute porosity values";i:2;s:40:"Temperature determines oil selling price";i:3;s:55:"Temperature has no relation to surfactant effectiveness";}','Temperature affects chemical stability and surfactant activity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000300','Apa mekanisme utama dalam metode thermal recovery yang menyebabkan peningkatan mobilitas minyak berat di dalam reservoir?','option','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:54:"Penurunan viskositas minyak akibat kenaikan temperatur";i:1;s:27:"Peningkatan tekanan kapiler";i:2;s:28:"Perubahan wettability batuan";i:3;s:30:"Injeksi gas CO2 untuk swelling";}','','Penurunan viskositas minyak akibat kenaikan temperatur','What is the primary mechanism in thermal recovery methods that causes an increase in heavy oil mobility within the reservoir?','a:4:{i:0;s:51:"Oil viscosity reduction due to temperature increase";i:1;s:27:"Capillary pressure increase";i:2;s:27:"Rock wettability alteration";i:3;s:30:"CO2 gas injection for swelling";}','Oil viscosity reduction due to temperature increase','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000301','Metode Cyclic Steam Stimulation (CSS) umumnya melibatkan tahapan berulang, yaitu:','multi','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:23:"Injeksi uap (injection)";i:1;s:22:"Masa perendaman (soak)";i:2;s:21:"Produksi (production)";i:3;s:17:"Injeksi surfaktan";}','','a:3:{i:0;s:23:"Injeksi uap (injection)";i:1;s:22:"Masa perendaman (soak)";i:2;s:21:"Produksi (production)";}','The Cyclic Steam Stimulation (CSS) method generally involves repeated stages, namely:','a:4:{i:0;s:15:"Steam injection";i:1;s:14:"Soaking period";i:2;s:10:"Production";i:3;s:20:"Surfactant injection";}','a:3:{i:0;s:15:"Steam injection";i:1;s:14:"Soaking period";i:2;s:10:"Production";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000302','Pada metode Steam Assisted Gravity Drainage (SAGD), bagaimana posisi sumur injeksi dan sumur produksi?','option','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:36:"Sumur injeksi di atas sumur produksi";i:1;s:37:"Sumur injeksi di bawah sumur produksi";i:2;s:37:"Sumur injeksi sejajar secara vertikal";i:3;s:54:"Sumur injeksi dan produksi berada pada sumur yang sama";}','','Sumur injeksi di atas sumur produksi','In the Steam Assisted Gravity Drainage (SAGD) method, what is the position of the injection well and production well?','a:4:{i:0;s:36:"Injection well above production well";i:1;s:36:"Injection well below production well";i:2;s:34:"Injection well parallel vertically";i:3;s:55:"Injection and production wells are in the same wellbore";}','Injection well above production well','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000303','Parameter utama yang paling signifikan dalam keberhasilan metode steamflood adalah:','option','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:28:"Kualitas uap (steam quality)";i:1;s:19:"Tekanan hidrostatik";i:2;s:16:"Porositas batuan";i:3;s:29:"Kecepatan alir fluida injeksi";}','','Kualitas uap (steam quality)','What is the most significant parameter for the success of the steamflood method?','a:4:{i:0;s:13:"Steam quality";i:1;s:20:"Hydrostatic pressure";i:2;s:13:"Rock porosity";i:3;s:29:"Injection fluid flow velocity";}','Steam quality','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000304','Apa keunggulan utama dari SAGD dibandingkan dengan Cyclic Steam Stimulation (CSS)?','option','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:44:"Laju produksi yang lebih konstan dan kontinu";i:1;s:39:"Biaya operasional yang jauh lebih murah";i:2;s:33:"Tidak memerlukan sumur horisontal";i:3;s:43:"Dapat diterapkan pada semua jenis reservoir";}','','Laju produksi yang lebih konstan dan kontinu','What is the main advantage of SAGD compared to Cyclic Steam Stimulation (CSS)?','a:4:{i:0;s:44:"More constant and continuous production rate";i:1;s:37:"Significantly lower operational costs";i:2;s:33:"Does not require horizontal wells";i:3;s:41:"Can be applied to all types of reservoirs";}','More constant and continuous production rate','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000305','Faktor apa yang membatasi kedalaman reservoir untuk penerapan thermal recovery?','option','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:44:"Heat loss (kehilangan panas) di dalam tubing";i:1;s:16:"Ketersediaan air";i:2;s:22:"Tingginya saturasi gas";i:3;s:34:"Tekanan formasi yang sangat rendah";}','','Heat loss (kehilangan panas) di dalam tubing','What factor limits the reservoir depth for the application of thermal recovery?','a:4:{i:0;s:23:"Heat loss in the tubing";i:1;s:18:"Water availability";i:2;s:19:"High gas saturation";i:3;s:27:"Very low formation pressure";}','Heat loss in the tubing','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000306','Mengapa viskositas minyak berat sangat sensitif terhadap perubahan suhu?','option','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:60:"Karena struktur molekul minyak berat yang kompleks dan besar";i:1;s:39:"Karena adanya kandungan air yang tinggi";i:2;s:31:"Karena pengaruh tekanan formasi";i:3;s:26:"Karena adanya gas terlarut";}','','Karena struktur molekul minyak berat yang kompleks dan besar','Why is heavy oil viscosity highly sensitive to temperature changes?','a:4:{i:0;s:62:"Because of the complex and large heavy oil molecular structure";i:1;s:29:"Because of high water content";i:2;s:39:"Because of formation pressure influence";i:3;s:24:"Because of dissolved gas";}','Because of the complex and large heavy oil molecular structure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000307','Dalam metode steamflood, zona apa yang terbentuk di sekitar sumur injeksi akibat perpindahan panas?','option','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:21:"Steam zone (zona uap)";i:1;s:21:"Water bank (zona air)";i:2;s:22:"Oil bank (zona minyak)";i:3;s:7:"Gas cap";}','','Steam zone (zona uap)','In the steamflood method, what zone is formed around the injection well due to heat transfer?','a:4:{i:0;s:10:"Steam zone";i:1;s:10:"Water bank";i:2;s:8:"Oil bank";i:3;s:7:"Gas cap";}','Steam zone','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000308','Pilih dua kondisi reservoir yang mendukung penerapan SAGD:','multi','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:34:"Ketebalan formasi yang cukup besar";i:1;s:20:"Permeabilitas tinggi";i:2;s:13:"Porositas nol";i:3;s:34:"Tekanan formasi yang sangat tinggi";}','','a:2:{i:0;s:34:"Ketebalan formasi yang cukup besar";i:1;s:20:"Permeabilitas tinggi";}','Select two reservoir conditions that support the application of SAGD:','a:4:{i:0;s:31:"Significant formation thickness";i:1;s:17:"High permeability";i:2;s:13:"Zero porosity";i:3;s:28:"Very high formation pressure";}','a:2:{i:0;s:31:"Significant formation thickness";i:1;s:17:"High permeability";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000309','Istilah untuk periode di mana sumur ditutup setelah injeksi uap pada CSS agar panas berdifusi ke formasi adalah:','option','PFS000000031','Ujian Pelajaran','a:4:{i:0;s:11:"Soak period";i:1;s:16:"Injection period";i:2;s:17:"Production period";i:3;s:18:"Steam breakthrough";}','','Soak period','The term for the period when the well is shut in after steam injection in CSS to allow heat to diffuse into the formation is:','a:4:{i:0;s:11:"Soak period";i:1;s:16:"Injection period";i:2;s:17:"Production period";i:3;s:18:"Steam breakthrough";}','Soak period','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000310','Mekanisme utama yang menyebabkan tercapainya kondisi miscible pada injeksi CO2 adalah?','option','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:55:"Ekstraksi komponen hidrokarbon ringan ke dalam fase CO2";i:1;s:44:"Peningkatan viskositas minyak secara drastis";i:2;s:37:"Penurunan saturasi air secara mekanis";i:3;s:52:"Peningkatan tegangan antarmuka antara gas dan minyak";}','','Ekstraksi komponen hidrokarbon ringan ke dalam fase CO2','The primary mechanism that leads to achieving miscible conditions in CO2 injection is?','a:4:{i:0;s:61:"Extraction of light hydrocarbon components into the CO2 phase";i:1;s:33:"Drastic increase in oil viscosity";i:2;s:40:"Mechanical reduction of water saturation";i:3;s:51:"Increase in interfacial tension between gas and oil";}','Extraction of light hydrocarbon components into the CO2 phase','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000311','Faktor-faktor yang mempengaruhi tekanan minimum miscibility (MMP) adalah?','multi','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:20:"Temperatur reservoir";i:1;s:26:"Komposisi minyak reservoir";i:2;s:14:"Viskositas air";i:3;s:20:"Permeabilitas batuan";}','','a:2:{i:0;s:20:"Temperatur reservoir";i:1;s:26:"Komposisi minyak reservoir";}','Which factors influence the Minimum Miscibility Pressure (MMP)?','a:4:{i:0;s:21:"Reservoir temperature";i:1;s:25:"Reservoir oil composition";i:2;s:15:"Water viscosity";i:3;s:17:"Rock permeability";}','a:2:{i:0;s:21:"Reservoir temperature";i:1;s:25:"Reservoir oil composition";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000312','Pada injeksi gas hidrokarbon, mekanisme ''vaporizing gas drive'' terjadi ketika?','option','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:68:"Gas kaya (rich gas) menginjeksikan komponen menengah ke dalam minyak";i:1;s:62:"Gas kering (lean gas) menguapkan komponen menengah dari minyak";i:2;s:41:"Suhu reservoir berada di bawah titik beku";i:3;s:42:"Tekanan injeksi jauh di bawah bubble point";}','','Gas kering (lean gas) menguapkan komponen menengah dari minyak','In hydrocarbon gas injection, the ''vaporizing gas drive'' mechanism occurs when?','a:4:{i:0;s:53:"Rich gas injects intermediate components into the oil";i:1;s:55:"Lean gas vaporizes intermediate components from the oil";i:2;s:45:"Reservoir temperature is below freezing point";i:3;s:44:"Injection pressure is far below bubble point";}','Lean gas vaporizes intermediate components from the oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000313','Apa dampak utama dari injeksi gas secara immiscible ke dalam reservoir minyak?','option','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:53:"Pendorongan minyak melalui ekspansi gas dan gravitasi";i:1;s:37:"Penyatuan total antara gas dan minyak";i:2;s:45:"Penghilangan tegangan antarmuka secara instan";i:3;s:42:"Peningkatan saturasi air secara signifikan";}','','Pendorongan minyak melalui ekspansi gas dan gravitasi','What is the primary impact of immiscible gas injection into an oil reservoir?','a:4:{i:0;s:59:"Oil displacement through gas expansion and gravity drainage";i:1;s:34:"Total blending between gas and oil";i:2;s:48:"Instantaneous elimination of interfacial tension";i:3;s:40:"Significant increase in water saturation";}','Oil displacement through gas expansion and gravity drainage','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000314','Apa yang dimaksud dengan ''Multiple Contact Miscibility'' pada proses CO2 flooding?','option','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:75:"Miscibility yang dicapai melalui kontak berulang antara fase gas dan minyak";i:1;s:53:"Miscibility yang terjadi seketika pada kontak pertama";i:2;s:52:"Pencampuran yang hanya terjadi di zona sumur injeksi";i:3;s:39:"Hilangnya miscibility akibat adanya air";}','','Miscibility yang dicapai melalui kontak berulang antara fase gas dan minyak','What is meant by ''Multiple Contact Miscibility'' in the CO2 flooding process?','a:4:{i:0;s:72:"Miscibility achieved through repeated contact between gas and oil phases";i:1;s:56:"Miscibility that occurs instantaneously on first contact";i:2;s:50:"Mixing that only occurs in the injection well zone";i:3;s:48:"Loss of miscibility due to the presence of water";}','Miscibility achieved through repeated contact between gas and oil phases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000315','Manakah pernyataan yang benar mengenai injeksi gas hidrokarbon kaya (enriched gas)?','option','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:58:"Mengandung komponen intermediate (C2-C6) yang cukup tinggi";i:1;s:35:"Hanya terdiri dari gas metana murni";i:2;s:35:"Selalu tidak miscible dengan minyak";i:3;s:43:"Tidak terpengaruh oleh temperatur reservoir";}','','Mengandung komponen intermediate (C2-C6) yang cukup tinggi','Which statement is correct regarding enriched hydrocarbon gas injection?','a:4:{i:0;s:55:"Contains high levels of intermediate components (C2-C6)";i:1;s:33:"Consists only of pure methane gas";i:2;s:29:"Is always immiscible with oil";i:3;s:40:"Is not affected by reservoir temperature";}','Contains high levels of intermediate components (C2-C6)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000316','Dalam konteks CO2 flooding, apa fungsi utama dari sifat ''swelling'' minyak?','option','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:55:"Meningkatkan volume minyak dan menurunkan viskositasnya";i:1;s:37:"Memperbesar tegangan permukaan minyak";i:2;s:38:"Mengurangi mobilitas gas di dalam pori";i:3;s:37:"Mempercepat pembentukan scale di pipa";}','','Meningkatkan volume minyak dan menurunkan viskositasnya','In the context of CO2 flooding, what is the primary function of the oil ''swelling'' property?','a:4:{i:0;s:46:"Increases oil volume and reduces its viscosity";i:1;s:29:"Increases oil surface tension";i:2;s:33:"Reduces gas mobility within pores";i:3;s:36:"Accelerates scale formation in pipes";}','Increases oil volume and reduces its viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000317','Mengapa injeksi CO2 immiscible masih bisa meningkatkan perolehan minyak?','multi','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:29:"Pengurangan viskositas minyak";i:1;s:41:"Pengembangan volume minyak (oil swelling)";i:2;s:49:"Peningkatan permeabilitas absolut secara permanen";i:3;s:41:"Pembentukan emulsi air-minyak yang stabil";}','','a:2:{i:0;s:29:"Pengurangan viskositas minyak";i:1;s:41:"Pengembangan volume minyak (oil swelling)";}','Why can immiscible CO2 injection still increase oil recovery?','a:4:{i:0;s:26:"Reduction of oil viscosity";i:1;s:35:"Oil volume expansion (oil swelling)";i:2;s:43:"Permanent increase in absolute permeability";i:3;s:39:"Formation of stable water-oil emulsions";}','a:2:{i:0;s:26:"Reduction of oil viscosity";i:1;s:35:"Oil volume expansion (oil swelling)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000318','Apa kelemahan utama dari injeksi gas (termasuk CO2) dalam hal efisiensi penyapuan?','option','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:53:"Mobility ratio yang buruk (gas mudah menyalip minyak)";i:1;s:45:"Gas terlalu berat untuk bergerak di reservoir";i:2;s:46:"Terlalu banyak bereaksi dengan batuan karbonat";i:3;s:48:"Mengakibatkan korosi pada seluruh formasi batuan";}','','Mobility ratio yang buruk (gas mudah menyalip minyak)','What is the main drawback of gas injection (including CO2) in terms of sweep efficiency?','a:4:{i:0;s:45:"Poor mobility ratio (gas easily bypasses oil)";i:1;s:41:"Gas is too heavy to move in the reservoir";i:2;s:36:"Reacts too much with carbonate rocks";i:3;s:45:"Causes corrosion in the entire rock formation";}','Poor mobility ratio (gas easily bypasses oil)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000319','Proses miscibility di mana gas menyerap komponen hidrokarbon ke dalam fase gas disebut?','option','PFS000000032','Ujian Pelajaran','a:4:{i:0;s:16:"Vaporizing drive";i:1;s:16:"Condensing drive";i:2;s:16:"Gravity drainage";i:3;s:21:"Water-alternating-gas";}','','Vaporizing drive','The miscibility process where gas absorbs hydrocarbon components into the gas phase is called?','a:4:{i:0;s:16:"Vaporizing drive";i:1;s:16:"Condensing drive";i:2;s:16:"Gravity drainage";i:3;s:21:"Water-alternating-gas";}','Vaporizing drive','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000320','Metode Thermal EOR manakah yang paling efektif untuk reservoir minyak berat dengan viskositas tinggi guna menurunkan viskositas secara drastis melalui pemanasan?','option','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:14:"Steam flooding";i:1;s:21:"CO2 miscible flooding";i:2;s:16:"Polymer flooding";i:3;s:19:"Surfactant flooding";}','','Steam flooding','Which Thermal EOR method is most effective for heavy oil reservoirs with high viscosity to drastically reduce viscosity through heating?','a:4:{i:0;s:14:"Steam flooding";i:1;s:21:"CO2 miscible flooding";i:2;s:16:"Polymer flooding";i:3;s:19:"Surfactant flooding";}','Steam flooding','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000321','Pilihlah karakteristik reservoir yang umumnya menjadi syarat utama untuk implementasi Gas Miscible Flooding (CO2).','multi','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:47:"Kedalaman reservoir yang cukup (tekanan tinggi)";i:1;s:39:"Minyak ringan dengan API gravity tinggi";i:2;s:29:"Permeabilitas rendah (< 1 mD)";i:3;s:58:"Temperatur reservoir sangat tinggi (> 200 derajat Celsius)";}','','a:2:{i:0;s:47:"Kedalaman reservoir yang cukup (tekanan tinggi)";i:1;s:39:"Minyak ringan dengan API gravity tinggi";}','Select the reservoir characteristics that are generally the main requirements for the implementation of Gas Miscible Flooding (CO2).','a:4:{i:0;s:42:"Sufficient reservoir depth (high pressure)";i:1;s:31:"Light oil with high API gravity";i:2;s:25:"Low permeability (< 1 mD)";i:3;s:55:"Very high reservoir temperature (> 200 degrees Celsius)";}','a:2:{i:0;s:42:"Sufficient reservoir depth (high pressure)";i:1;s:31:"Light oil with high API gravity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000322','Apa dampak utama dari injeksi uap (steam injection) terhadap sifat fisik fluida di dalam reservoir?','option','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:37:"Meningkatkan tegangan antarmuka (IFT)";i:1;s:28:"Menurunkan viskositas minyak";i:2;s:37:"Meningkatkan saturasi air irreducible";i:3;s:36:"Mengubah wettability menjadi oil-wet";}','','Menurunkan viskositas minyak','What is the primary impact of steam injection on the physical properties of fluids within the reservoir?','a:4:{i:0;s:35:"Increases interfacial tension (IFT)";i:1;s:23:"Decreases oil viscosity";i:2;s:38:"Increases irreducible water saturation";i:3;s:30:"Changes wettability to oil-wet";}','Decreases oil viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000323','Metode EOR mana yang lebih disukai jika reservoir memiliki heterogenitas tinggi dan membutuhkan kontrol mobilitas?','option','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:14:"Steam flooding";i:1;s:16:"Polymer flooding";i:2;s:18:"In-situ combustion";i:3;s:22:"Miscible gas injection";}','','Polymer flooding','Which EOR method is preferred if the reservoir has high heterogeneity and requires mobility control?','a:4:{i:0;s:14:"Steam flooding";i:1;s:16:"Polymer flooding";i:2;s:18:"In-situ combustion";i:3;s:22:"Miscible gas injection";}','Polymer flooding','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000324','Pada kondisi reservoir apa metode In-Situ Combustion (ISC) sering dianggap sebagai alternatif thermal EOR yang potensial?','option','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:36:"Reservoir dalam dengan minyak ringan";i:1;s:37:"Reservoir dangkal dengan minyak berat";i:2;s:44:"Reservoir dengan permeabilitas sangat rendah";i:3;s:43:"Reservoir dengan saturasi air sangat tinggi";}','','Reservoir dangkal dengan minyak berat','Under what reservoir conditions is In-Situ Combustion (ISC) often considered as a potential thermal EOR alternative?','a:4:{i:0;s:30:"Deep reservoirs with light oil";i:1;s:33:"Shallow reservoirs with heavy oil";i:2;s:37:"Reservoirs with very low permeability";i:3;s:42:"Reservoirs with very high water saturation";}','Shallow reservoirs with heavy oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000325','Faktor utama yang membatasi efisiensi dari Gas Miscible Flooding adalah:','option','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:38:"Gravity override (segregasi gravitasi)";i:1;s:22:"Ketersediaan air tawar";i:2;s:30:"Tingginya konsumsi bahan kimia";i:3;s:35:"Sensitivitas formasi terhadap panas";}','','Gravity override (segregasi gravitasi)','The main factor limiting the efficiency of Gas Miscible Flooding is:','a:4:{i:0;s:16:"Gravity override";i:1;s:24:"Fresh water availability";i:2;s:25:"High chemical consumption";i:3;s:29:"Formation sensitivity to heat";}','Gravity override','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000326','Manakah dari berikut ini yang merupakan keuntungan menggunakan Gas EOR dibandingkan Thermal EOR?','multi','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:48:"Dapat diterapkan pada reservoir yang lebih dalam";i:1;s:43:"Tidak memerlukan panas tinggi untuk operasi";i:2;s:41:"Dapat menurunkan IFT hingga mendekati nol";i:3;s:60:"Lebih efektif untuk minyak dengan viskositas di atas 1000 cP";}','','a:3:{i:0;s:48:"Dapat diterapkan pada reservoir yang lebih dalam";i:1;s:43:"Tidak memerlukan panas tinggi untuk operasi";i:2;s:41:"Dapat menurunkan IFT hingga mendekati nol";}','Which of the following are advantages of using Gas EOR compared to Thermal EOR?','a:4:{i:0;s:35:"Can be applied in deeper reservoirs";i:1;s:41:"Does not require high heat for operations";i:2;s:27:"Can reduce IFT to near zero";i:3;s:51:"More effective for oil with viscosity above 1000 cP";}','a:3:{i:0;s:35:"Can be applied in deeper reservoirs";i:1;s:41:"Does not require high heat for operations";i:2;s:27:"Can reduce IFT to near zero";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000327','Apa peran utama surfaktan dalam Chemical EOR untuk meningkatkan recovery factor?','option','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:35:"Meningkatkan viskositas air injeksi";i:1;s:46:"Menurunkan tegangan antarmuka (IFT) minyak-air";i:2;s:26:"Menambah tekanan reservoir";i:3;s:27:"Meningkatkan suhu reservoir";}','','Menurunkan tegangan antarmuka (IFT) minyak-air','What is the main role of surfactants in Chemical EOR to improve recovery factor?','a:4:{i:0;s:36:"Increasing injection water viscosity";i:1;s:44:"Reducing oil-water interfacial tension (IFT)";i:2;s:29:"Increasing reservoir pressure";i:3;s:32:"Increasing reservoir temperature";}','Reducing oil-water interfacial tension (IFT)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000328','Metode thermal mana yang melibatkan pembakaran sebagian minyak di dalam reservoir?','option','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:38:"Steam Assisted Gravity Drainage (SAGD)";i:1;s:24:"Cyclic Steam Stimulation";i:2;s:18:"In-situ combustion";i:3;s:18:"Hot water flooding";}','','In-situ combustion','Which thermal method involves burning a portion of the oil inside the reservoir?','a:4:{i:0;s:38:"Steam Assisted Gravity Drainage (SAGD)";i:1;s:24:"Cyclic Steam Stimulation";i:2;s:18:"In-situ combustion";i:3;s:18:"Hot water flooding";}','In-situ combustion','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000329','Pemilihan metode EOR harus mempertimbangkan aspek teknis dan ekonomi. Faktor ekonomi utama dalam proyek Gas EOR adalah:','option','PFS000000033','Ujian Pelajaran','a:4:{i:0;s:55:"Biaya penyediaan gas injeksi dan infrastruktur kompresi";i:1;s:31:"Biaya pemanasan air untuk steam";i:2;s:45:"Harga polimer sintetis di pasar internasional";i:3;s:28:"Pajak emisi karbon per barel";}','','Biaya penyediaan gas injeksi dan infrastruktur kompresi','EOR method selection must consider technical and economic aspects. The main economic factor in Gas EOR projects is:','a:4:{i:0;s:63:"Cost of supply for injection gas and compression infrastructure";i:1;s:31:"Cost of heating water for steam";i:2;s:55:"Price of synthetic polymers in the international market";i:3;s:30:"Carbon emission tax per barrel";}','Cost of supply for injection gas and compression infrastructure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000330','Data reservoir apa yang paling krusial untuk menentukan kesesuaian lapangan terhadap metode Chemical EOR (CEOR)?','option','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:46:"Temperatur reservoir dan salinitas air formasi";i:1;s:22:"Warna batuan reservoir";i:2;s:26:"Jumlah sumur injeksi aktif";i:3;s:25:"Lokasi geografis lapangan";}','','Temperatur reservoir dan salinitas air formasi','Which reservoir data is most crucial for determining the suitability of a field for Chemical EOR (CEOR) methods?','a:4:{i:0;s:50:"Reservoir temperature and formation water salinity";i:1;s:20:"Reservoir rock color";i:2;s:32:"Number of active injection wells";i:3;s:34:"Geographical location of the field";}','Reservoir temperature and formation water salinity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000331','Manakah dari berikut ini yang merupakan tujuan utama dari kajian laboratorium (core flooding) dalam proyek CEOR?','multi','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:38:"Menentukan efisiensi pendesakan minyak";i:1;s:43:"Menentukan adsorpsi bahan kimia pada batuan";i:2;s:43:"Mengukur tekanan kapiler di permukaan tanah";i:3;s:30:"Memprediksi harga minyak dunia";}','','a:2:{i:0;s:38:"Menentukan efisiensi pendesakan minyak";i:1;s:43:"Menentukan adsorpsi bahan kimia pada batuan";}','Which of the following are the primary objectives of laboratory (core flooding) studies in a CEOR project?','a:4:{i:0;s:39:"Determining oil displacement efficiency";i:1;s:39:"Determining chemical adsorption on rock";i:2;s:36:"Measuring surface capillary pressure";i:3;s:28:"Predicting global oil prices";}','a:2:{i:0;s:39:"Determining oil displacement efficiency";i:1;s:39:"Determining chemical adsorption on rock";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000332','Apa fungsi utama dari pemodelan simulasi reservoir sebelum implementasi proyek CEOR skala penuh?','option','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:56:"Memprediksi kinerja injeksi dan memitigasi risiko teknis";i:1;s:50:"Menggantikan kebutuhan akan pengujian laboratorium";i:2;s:44:"Menentukan lokasi pengeboran eksplorasi baru";i:3;s:44:"Menghitung biaya pembersihan lingkungan saja";}','','Memprediksi kinerja injeksi dan memitigasi risiko teknis','What is the primary function of reservoir simulation modeling before full-scale CEOR project implementation?','a:4:{i:0;s:63:"Predicting injection performance and mitigating technical risks";i:1;s:41:"Replacing the need for laboratory testing";i:2;s:50:"Determining locations for new exploration drilling";i:3;s:44:"Calculating environmental cleanup costs only";}','Predicting injection performance and mitigating technical risks','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000333','Apa tujuan utama dari pelaksanaan proyek percontohan (pilot project) sebelum skala penuh?','option','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:59:"Validasi efektivitas metode di skala lapangan yang terbatas";i:1;s:35:"Meningkatkan harga saham perusahaan";i:2;s:39:"Mengurangi pajak produksi secara instan";i:3;s:41:"Menguji peralatan pengeboran konvensional";}','','Validasi efektivitas metode di skala lapangan yang terbatas','What is the primary objective of implementing a pilot project before full-scale deployment?','a:4:{i:0;s:56:"Validating method effectiveness at a limited field scale";i:1;s:31:"Increasing company stock prices";i:2;s:35:"Reducing production taxes instantly";i:3;s:39:"Testing conventional drilling equipment";}','Validating method effectiveness at a limited field scale','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000334','Parameter laboratorium apa yang diukur untuk mengevaluasi kemampuan bahan kimia dalam menurunkan Interfacial Tension (IFT)?','option','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:25:"Spinning drop tensiometer";i:1;s:15:"Porosimeter gas";i:2;s:17:"Permeameter udara";i:3;s:23:"Viskosimeter Brookfield";}','','Spinning drop tensiometer','What laboratory parameter is measured to evaluate the ability of chemicals to reduce Interfacial Tension (IFT)?','a:4:{i:0;s:25:"Spinning drop tensiometer";i:1;s:15:"Gas porosimeter";i:2;s:15:"Air permeameter";i:3;s:21:"Brookfield viscometer";}','Spinning drop tensiometer','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000335','Dalam perencanaan CEOR, mengapa pemahaman mengenai heterogenitas reservoir sangat penting?','option','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:58:"Mempengaruhi pola penyapuan (sweep efficiency) bahan kimia";i:1;s:40:"Tidak berpengaruh terhadap hasil injeksi";i:2;s:45:"Hanya relevan untuk pengeboran sumur vertikal";i:3;s:34:"Hanya relevan untuk metode thermal";}','','Mempengaruhi pola penyapuan (sweep efficiency) bahan kimia','In CEOR planning, why is understanding reservoir heterogeneity very important?','a:4:{i:0;s:44:"It affects the sweep efficiency of chemicals";i:1;s:37:"It has no effect on injection results";i:2;s:46:"It is only relevant for vertical well drilling";i:3;s:39:"It is only relevant for thermal methods";}','It affects the sweep efficiency of chemicals','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000336','Faktor apa saja yang harus dipertimbangkan dalam transisi dari pilot ke skala lapangan penuh?','multi','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:47:"Integritas fasilitas surface dan logistik kimia";i:1;s:50:"Ketersediaan volume bahan kimia dalam jumlah besar";i:2;s:63:"Biaya operasional dibandingkan dengan tambahan perolehan minyak";i:3;s:22:"Warna fluida reservoir";}','','a:3:{i:0;s:47:"Integritas fasilitas surface dan logistik kimia";i:1;s:50:"Ketersediaan volume bahan kimia dalam jumlah besar";i:2;s:63:"Biaya operasional dibandingkan dengan tambahan perolehan minyak";}','What factors must be considered in the transition from pilot to full-scale field operations?','a:4:{i:0;s:49:"Surface facility integrity and chemical logistics";i:1;s:38:"Availability of large chemical volumes";i:2;s:52:"Operating costs compared to incremental oil recovery";i:3;s:21:"Reservoir fluid color";}','a:3:{i:0;s:49:"Surface facility integrity and chemical logistics";i:1;s:38:"Availability of large chemical volumes";i:2;s:52:"Operating costs compared to incremental oil recovery";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000337','Apa dampak negatif yang mungkin terjadi jika kompatibilitas kimiawi tidak diuji terhadap air formasi?','option','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:63:"Terjadinya presipitasi (pengendapan) yang menyumbat pori batuan";i:1;s:48:"Meningkatkan permeabilitas batuan secara drastis";i:2;s:34:"Memperbaiki kualitas minyak mentah";i:3;s:41:"Menurunkan viskositas minyak secara alami";}','','Terjadinya presipitasi (pengendapan) yang menyumbat pori batuan','What negative impact might occur if chemical compatibility is not tested against formation water?','a:4:{i:0;s:35:"Precipitation that plugs rock pores";i:1;s:37:"Drastic increase in rock permeability";i:2;s:32:"Improvement of crude oil quality";i:3;s:34:"Natural reduction of oil viscosity";}','Precipitation that plugs rock pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000338','Mengapa simulasi reservoir membutuhkan data tekanan dan laju alir historis lapangan?','option','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:74:"Untuk melakukan history matching agar model merepresentasikan kondisi asli";i:1;s:43:"Untuk menghitung harga jual minyak saat ini";i:2;s:36:"Untuk menentukan lokasi kantor pusat";i:3;s:32:"Untuk menggantikan studi geologi";}','','Untuk melakukan history matching agar model merepresentasikan kondisi asli','Why does reservoir simulation require historical pressure and flow rate data from the field?','a:4:{i:0;s:69:"To perform history matching so the model represents actual conditions";i:1;s:45:"To calculate the current selling price of oil";i:2;s:34:"To determine headquarters location";i:3;s:29:"To replace geological studies";}','To perform history matching so the model represents actual conditions','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000339','Manakah instrumen laboratorium yang digunakan untuk menentukan mobilitas fluida dalam media berpori?','option','PFS000000034','Ujian Pelajaran','a:4:{i:0;s:23:"Core flooding apparatus";i:1;s:13:"Refraktometer";i:2;s:13:"Density meter";i:3;s:18:"Mikroskop elektron";}','','Core flooding apparatus','Which laboratory instrument is used to determine fluid mobility in porous media?','a:4:{i:0;s:23:"Core flooding apparatus";i:1;s:13:"Refractometer";i:2;s:13:"Density meter";i:3;s:19:"Electron microscope";}','Core flooding apparatus','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000340','Apa indikator ekonomi utama yang digunakan untuk mengukur nilai tambah bersih suatu proyek EOR dengan mendiskon arus kas masa depan?','option','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:23:"Net Present Value (NPV)";i:1;s:29:"Internal Rate of Return (IRR)";i:2;s:14:"Payback Period";i:3;s:28:"Operating Expenditure (OPEX)";}','','Net Present Value (NPV)','What is the primary economic indicator used to measure the net added value of an EOR project by discounting future cash flows?','a:4:{i:0;s:23:"Net Present Value (NPV)";i:1;s:29:"Internal Rate of Return (IRR)";i:2;s:14:"Payback Period";i:3;s:28:"Operating Expenditure (OPEX)";}','Net Present Value (NPV)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000341','Manakah dari faktor berikut yang secara langsung meningkatkan keuntungan ekonomi dari proyek EOR?','multi','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:55:"Peningkatan perolehan minyak tambahan (incremental oil)";i:1;s:37:"Penurunan biaya operasional per barel";i:2;s:38:"Peningkatan harga minyak mentah global";i:3;s:34:"Kenaikan biaya injeksi bahan kimia";}','','a:3:{i:0;s:55:"Peningkatan perolehan minyak tambahan (incremental oil)";i:1;s:37:"Penurunan biaya operasional per barel";i:2;s:38:"Peningkatan harga minyak mentah global";}','Which of the following factors directly increase the economic profitability of an EOR project?','a:4:{i:0;s:36:"Increase in incremental oil recovery";i:1;s:37:"Decrease in operating cost per barrel";i:2;s:34:"Increase in global crude oil price";i:3;s:32:"Rise in chemical injection costs";}','a:3:{i:0;s:36:"Increase in incremental oil recovery";i:1;s:37:"Decrease in operating cost per barrel";i:2;s:34:"Increase in global crude oil price";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000342','Dalam analisis ekonomi EOR, apa yang dimaksud dengan incremental oil?','option','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:109:"Tambahan produksi minyak yang diperoleh akibat implementasi metode EOR dibandingkan dengan skenario base case";i:1;s:48:"Total volume minyak di tempat (OOIP) sebelum EOR";i:2;s:47:"Volume air yang terproduksi selama fase injeksi";i:3;s:67:"Total cadangan minyak yang tersisa di reservoir setelah EOR selesai";}','','Tambahan produksi minyak yang diperoleh akibat implementasi metode EOR dibandingkan dengan skenario base case','In EOR economic analysis, what is meant by incremental oil?','a:4:{i:0;s:95:"Additional oil production obtained due to EOR implementation compared to the base case scenario";i:1;s:45:"Total original oil in place (OOIP) before EOR";i:2;s:51:"Volume of water produced during the injection phase";i:3;s:68:"Total oil reserves remaining in the reservoir after EOR is completed";}','Additional oil production obtained due to EOR implementation compared to the base case scenario','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000343','Parameter ekonomi mana yang menunjukkan tingkat pengembalian modal tahunan (annualized rate of return) dari investasi proyek EOR?','option','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:29:"Internal Rate of Return (IRR)";i:1;s:27:"Capital Expenditure (CAPEX)";i:2;s:28:"Operating Expenditure (OPEX)";i:3;s:20:"Break-even Oil Price";}','','Internal Rate of Return (IRR)','Which economic parameter indicates the annualized rate of return on an EOR project investment?','a:4:{i:0;s:29:"Internal Rate of Return (IRR)";i:1;s:27:"Capital Expenditure (CAPEX)";i:2;s:28:"Operating Expenditure (OPEX)";i:3;s:20:"Break-even Oil Price";}','Internal Rate of Return (IRR)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000344','Dalam analisis risiko proyek EOR, ketidakpastian apa yang paling berpengaruh terhadap volatilitas pendapatan?','option','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:28:"Fluktuasi harga minyak dunia";i:1;s:27:"Viskositas fluida reservoir";i:2;s:23:"Kedalaman sumur injeksi";i:3;s:23:"Jumlah crew di lapangan";}','','Fluktuasi harga minyak dunia','In EOR project risk analysis, which uncertainty has the most significant impact on revenue volatility?','a:4:{i:0;s:28:"World oil price fluctuations";i:1;s:25:"Reservoir fluid viscosity";i:2;s:20:"Injection well depth";i:3;s:20:"Number of field crew";}','World oil price fluctuations','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000345','Mengapa analisis sensitivitas penting dilakukan dalam perencanaan proyek EOR?','option','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:80:"Untuk memahami dampak perubahan variabel input terhadap kelayakan ekonomi proyek";i:1;s:53:"Untuk menghitung jumlah cadangan minyak secara akurat";i:2;s:45:"Untuk menentukan lokasi pengeboran sumur baru";i:3;s:49:"Untuk mengukur tekanan reservoir secara real-time";}','','Untuk memahami dampak perubahan variabel input terhadap kelayakan ekonomi proyek','Why is sensitivity analysis important in EOR project planning?','a:4:{i:0;s:90:"To understand the impact of changes in input variables on the project''s economic viability";i:1;s:36:"To calculate oil reserves accurately";i:2;s:35:"To determine new drilling locations";i:3;s:42:"To measure reservoir pressure in real-time";}','To understand the impact of changes in input variables on the project''s economic viability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000346','Biaya yang dikeluarkan untuk pengadaan fasilitas injeksi (seperti pompa, pipa, dan unit pengolahan kimia) dikategorikan sebagai:','option','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:27:"Capital Expenditure (CAPEX)";i:1;s:28:"Operating Expenditure (OPEX)";i:2;s:35:"General and Administrative Expenses";i:3;s:19:"Incremental Revenue";}','','Capital Expenditure (CAPEX)','Costs incurred for the procurement of injection facilities (such as pumps, pipelines, and chemical processing units) are categorized as:','a:4:{i:0;s:27:"Capital Expenditure (CAPEX)";i:1;s:28:"Operating Expenditure (OPEX)";i:2;s:35:"General and Administrative Expenses";i:3;s:19:"Incremental Revenue";}','Capital Expenditure (CAPEX)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000347','Manakah faktor yang mencakup biaya operasional (OPEX) dalam proyek EOR?','multi','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:29:"Pembelian bahan kimia injeksi";i:1;s:33:"Biaya listrik untuk pompa injeksi";i:2;s:28:"Biaya pemeliharaan fasilitas";i:3;s:30:"Biaya eksplorasi lapangan baru";}','','a:3:{i:0;s:29:"Pembelian bahan kimia injeksi";i:1;s:33:"Biaya listrik untuk pompa injeksi";i:2;s:28:"Biaya pemeliharaan fasilitas";}','Which factors are included in operating expenditures (OPEX) for an EOR project?','a:4:{i:0;s:31:"Purchase of injection chemicals";i:1;s:37:"Electricity costs for injection pumps";i:2;s:26:"Facility maintenance costs";i:3;s:27:"New field exploration costs";}','a:3:{i:0;s:31:"Purchase of injection chemicals";i:1;s:37:"Electricity costs for injection pumps";i:2;s:26:"Facility maintenance costs";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000348','Apa arti dari Break-even Oil Price dalam ekonomi proyek EOR?','option','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:47:"Harga minyak di mana NPV proyek sama dengan nol";i:1;s:42:"Harga minyak terendah yang pernah tercatat";i:2;s:44:"Harga minyak yang diinginkan oleh pemerintah";i:3;s:41:"Harga jual minyak setelah dikurangi pajak";}','','Harga minyak di mana NPV proyek sama dengan nol','What is the meaning of Break-even Oil Price in EOR project economics?','a:4:{i:0;s:50:"The oil price at which the project NPV equals zero";i:1;s:34:"The lowest oil price ever recorded";i:2;s:39:"The oil price desired by the government";i:3;s:45:"The selling price of oil after tax deductions";}','The oil price at which the project NPV equals zero','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000349','Risiko teknis dalam proyek EOR yang dapat menyebabkan kegagalan ekonomi meliputi:','option','PFS000000035','Ujian Pelajaran','a:4:{i:0;s:58:"Injeksi tidak mencapai zona target (poor sweep efficiency)";i:1;s:44:"Terlalu banyak cadangan minyak yang tersedia";i:2;s:31:"Harga minyak yang sangat tinggi";i:3;s:28:"Pajak pemerintah yang rendah";}','','Injeksi tidak mencapai zona target (poor sweep efficiency)','Technical risks in an EOR project that can lead to economic failure include:','a:4:{i:0;s:66:"Injection failing to reach the target zone (poor sweep efficiency)";i:1;s:31:"Too much oil reserves available";i:2;s:20:"Very high oil prices";i:3;s:20:"Low government taxes";}','Injection failing to reach the target zone (poor sweep efficiency)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000350','Metode penyuntikan air dengan salinitas rendah (Low Salinity Waterflooding) umumnya bertujuan untuk meningkatkan perolehan minyak melalui mekanisme apa?','option','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:52:"Perubahan wettability batuan menjadi lebih water-wet";i:1;s:36:"Peningkatan viskositas minyak mentah";i:2;s:35:"Penurunan densitas batuan reservoir";i:3;s:42:"Peningkatan tekanan kapiler secara drastis";}','','Perubahan wettability batuan menjadi lebih water-wet','Low Salinity Waterflooding generally aims to increase oil recovery through which mechanism?','a:4:{i:0;s:51:"Alteration of rock wettability to be more water-wet";i:1;s:31:"Increase in crude oil viscosity";i:2;s:34:"Decrease in reservoir rock density";i:3;s:38:"Drastic increase in capillary pressure";}','Alteration of rock wettability to be more water-wet','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000351','Manakah pernyataan yang benar mengenai peran utama CO2-EOR dalam hubungannya dengan CCS?','multi','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:80:"Mengurangi emisi gas rumah kaca ke atmosfer melalui penyimpanan CO2 di reservoir";i:1;s:72:"Meningkatkan perolehan minyak melalui mekanisme miscible atau immiscible";i:2;s:71:"Menambah viskositas minyak secara signifikan hingga mencapai fase padat";i:3;s:57:"Menghilangkan kebutuhan akan fasilitas produksi permukaan";}','','a:2:{i:0;s:80:"Mengurangi emisi gas rumah kaca ke atmosfer melalui penyimpanan CO2 di reservoir";i:1;s:72:"Meningkatkan perolehan minyak melalui mekanisme miscible atau immiscible";}','Which statements are correct regarding the primary role of CO2-EOR in relation to CCS?','a:4:{i:0;s:88:"Reducing greenhouse gas emissions to the atmosphere through CO2 storage in the reservoir";i:1;s:65:"Increasing oil recovery through miscible or immiscible mechanisms";i:2;s:55:"Significantly increasing oil viscosity to a solid phase";i:3;s:54:"Eliminating the need for surface production facilities";}','a:2:{i:0;s:88:"Reducing greenhouse gas emissions to the atmosphere through CO2 storage in the reservoir";i:1;s:65:"Increasing oil recovery through miscible or immiscible mechanisms";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000352','Penerapan digitalisasi dalam manajemen proyek CEOR sering melibatkan penggunaan teknologi apa?','option','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:59:"Artificial Intelligence untuk pemodelan reservoir real-time";i:1;s:43:"Penggunaan pompa manual untuk injeksi kimia";i:2;s:42:"Penyimpanan data fisik dalam bentuk kertas";i:3;s:46:"Metode penentuan saturasi minyak secara manual";}','','Artificial Intelligence untuk pemodelan reservoir real-time','The application of digitalization in CEOR project management often involves the use of which technology?','a:4:{i:0;s:56:"Artificial Intelligence for real-time reservoir modeling";i:1;s:46:"The use of manual pumps for chemical injection";i:2;s:37:"Physical data storage in paper format";i:3;s:43:"Manual oil saturation determination methods";}','Artificial Intelligence for real-time reservoir modeling','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000353','Faktor utama yang menentukan keberhasilan injeksi CO2 miscible di lapangan adalah?','option','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:43:"Mencapai Minimum Miscibility Pressure (MMP)";i:1;s:42:"Menjaga tekanan di bawah tekanan gelembung";i:2;s:39:"Menggunakan air dengan salinitas tinggi";i:3;s:36:"Menghindari penggunaan gas CO2 murni";}','','Mencapai Minimum Miscibility Pressure (MMP)','The main factor determining the success of miscible CO2 injection in the field is?','a:4:{i:0;s:44:"Achieving Minimum Miscibility Pressure (MMP)";i:1;s:43:"Maintaining pressure below the bubble point";i:2;s:25:"Using high salinity water";i:3;s:32:"Avoiding the use of pure CO2 gas";}','Achieving Minimum Miscibility Pressure (MMP)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000354','Dalam studi kasus lapangan CEOR, apa tantangan teknis utama dari implementasi polimer flooding?','option','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:60:"Degradasi polimer akibat suhu tinggi dan salinitas reservoir";i:1;s:34:"Polimer yang terlalu mudah menguap";i:2;s:50:"Peningkatan permeabilitas batuan secara berlebihan";i:3;s:31:"Harga polimer yang sangat murah";}','','Degradasi polimer akibat suhu tinggi dan salinitas reservoir','In CEOR field case studies, what is the main technical challenge of polymer flooding implementation?','a:4:{i:0;s:66:"Polymer degradation due to high reservoir temperature and salinity";i:1;s:26:"Polymer being too volatile";i:2;s:39:"Excessive increase in rock permeability";i:3;s:21:"Very low polymer cost";}','Polymer degradation due to high reservoir temperature and salinity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000355','Apa dampak positif dari integrasi CCS dengan proyek CO2-EOR dari sisi ekonomi?','option','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:64:"Pemberian kredit karbon atau insentif pajak atas penyimpanan CO2";i:1;s:37:"Penghapusan biaya operasional injeksi";i:2;s:55:"Peningkatan drastis harga minyak global secara otomatis";i:3;s:41:"Pengurangan volume minyak yang dihasilkan";}','','Pemberian kredit karbon atau insentif pajak atas penyimpanan CO2','What is the positive impact of CCS integration with CO2-EOR projects from an economic perspective?','a:4:{i:0;s:61:"Provision of carbon credits or tax incentives for CO2 storage";i:1;s:40:"Elimination of injection operating costs";i:2;s:47:"Automatic drastic increase in global oil prices";i:3;s:32:"Reduction in oil volume produced";}','Provision of carbon credits or tax incentives for CO2 storage','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000356','Teknologi digital ''Digital Twin'' dalam CEOR digunakan untuk tujuan apa?','option','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:65:"Simulasi performa reservoir secara virtual sebelum tindakan nyata";i:1;s:36:"Mengganti peran geologis di lapangan";i:2;s:44:"Meningkatkan porositas batuan secara digital";i:3;s:43:"Mengurangi laju alir fluida secara permanen";}','','Simulasi performa reservoir secara virtual sebelum tindakan nyata','What is the ''Digital Twin'' technology in CEOR used for?','a:4:{i:0;s:60:"Virtual reservoir performance simulation before real actions";i:1;s:45:"Replacing the role of geologists in the field";i:2;s:34:"Digitally increasing rock porosity";i:3;s:36:"Permanently reducing fluid flow rate";}','Virtual reservoir performance simulation before real actions','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000357','Manakah parameter yang paling dipengaruhi oleh penambahan surfaktan dalam metode CEOR?','option','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:63:"Tegangan antar muka (Interfacial Tension) antara minyak dan air";i:1;s:28:"Permeabilitas absolut batuan";i:2;s:23:"Densitas batuan sedimen";i:3;s:21:"Kedalaman total sumur";}','','Tegangan antar muka (Interfacial Tension) antara minyak dan air','Which parameter is most affected by the addition of surfactants in CEOR methods?','a:4:{i:0;s:41:"Interfacial Tension between oil and water";i:1;s:26:"Absolute rock permeability";i:2;s:24:"Sedimentary rock density";i:3;s:16:"Total well depth";}','Interfacial Tension between oil and water','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000358','Dalam konteks masa depan CEOR, mengapa pemantauan (monitoring) secara real-time menjadi krusial?','multi','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:61:"Untuk optimasi injeksi secara dinamis berdasarkan data sensor";i:1;s:60:"Mendeteksi adanya kebocoran atau masalah injeksi secara dini";i:2;s:55:"Menggantikan fungsi pengujian laboratorium secara total";i:3;s:49:"Menghilangkan kebutuhan akan personel di lapangan";}','','a:2:{i:0;s:61:"Untuk optimasi injeksi secara dinamis berdasarkan data sensor";i:1;s:60:"Mendeteksi adanya kebocoran atau masalah injeksi secara dini";}','In the context of the future of CEOR, why is real-time monitoring crucial?','a:4:{i:0;s:55:"For dynamic injection optimization based on sensor data";i:1;s:41:"Detecting leaks or injection issues early";i:2;s:49:"Completely replacing laboratory testing functions";i:3;s:47:"Eliminating the need for personnel in the field";}','a:2:{i:0;s:55:"For dynamic injection optimization based on sensor data";i:1;s:41:"Detecting leaks or injection issues early";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000359','Apa tujuan utama dari proses ''screening'' dalam pemilihan metode CEOR untuk suatu lapangan?','option','PFS000000036','Ujian Pelajaran','a:4:{i:0;s:84:"Memastikan metode yang dipilih sesuai dengan karakteristik fisik dan kimia reservoir";i:1;s:75:"Memilih metode berdasarkan biaya paling murah tanpa mempertimbangkan teknis";i:2;s:48:"Memastikan proyek selesai dalam waktu satu bulan";i:3;s:35:"Menghindari penggunaan data seismik";}','','Memastikan metode yang dipilih sesuai dengan karakteristik fisik dan kimia reservoir','What is the primary purpose of the ''screening'' process in selecting a CEOR method for a field?','a:4:{i:0;s:95:"Ensuring the selected method matches the physical and chemical characteristics of the reservoir";i:1;s:74:"Selecting the method based on lowest cost without technical considerations";i:2;s:50:"Ensuring the project is completed within one month";i:3;s:32:"Avoiding the use of seismic data";}','Ensuring the selected method matches the physical and chemical characteristics of the reservoir','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000360','Apa definisi dasar dari petrofisika dalam konteks industri migas?','option','PFC000000001','Final Test','a:4:{i:0;s:75:"Studi tentang sifat fisik dan kimia batuan serta interaksinya dengan fluida";i:1;s:46:"Studi tentang pemetaan geologi bawah permukaan";i:2;s:41:"Analisis pergerakan tektonik lempeng bumi";i:3;s:45:"Studi mengenai metode pengeboran sumur minyak";}','','Studi tentang sifat fisik dan kimia batuan serta interaksinya dengan fluida','What is the basic definition of petrophysics in the oil and gas industry context?','a:4:{i:0;s:84:"The study of physical and chemical rock properties and their interaction with fluids";i:1;s:42:"The study of subsurface geological mapping";i:2;s:36:"Analysis of tectonic plate movements";i:3;s:38:"The study of oil well drilling methods";}','The study of physical and chemical rock properties and their interaction with fluids','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000361','Parameter apa yang paling utama ditentukan melalui analisis petrofisika untuk menghitung cadangan hidrokarbon?','multi','PFC000000001','Final Test','a:4:{i:0;s:9:"Porositas";i:1;s:13:"Permeabilitas";i:2;s:12:"Saturasi air";i:3;s:15:"Tekanan kapiler";}','','a:2:{i:0;s:9:"Porositas";i:1;s:12:"Saturasi air";}','Which parameters are primary determined through petrophysical analysis to calculate hydrocarbon reserves?','a:4:{i:0;s:8:"Porosity";i:1;s:12:"Permeability";i:2;s:16:"Water saturation";i:3;s:18:"Capillary pressure";}','a:2:{i:0;s:8:"Porosity";i:1;s:16:"Water saturation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000362','Apa perbedaan utama antara batuan reservoir terkonsolidasi dan tidak terkonsolidasi?','option','PFC000000001','Final Test','a:4:{i:0;s:31:"Tingkat sementasi antar butiran";i:1;s:12:"Warna batuan";i:2;s:21:"Kedalaman pengendapan";i:3;s:28:"Jenis mineral penyusun utama";}','','Tingkat sementasi antar butiran','What is the main difference between consolidated and unconsolidated reservoir rocks?','a:4:{i:0;s:36:"Degree of cementation between grains";i:1;s:10:"Rock color";i:2;s:16:"Deposition depth";i:3;s:33:"Type of main constituent minerals";}','Degree of cementation between grains','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000363','Apa yang dimaksud dengan porositas primer dalam batuan sedimen?','option','PFC000000001','Final Test','a:4:{i:0;s:51:"Porositas yang terbentuk selama pengendapan sedimen";i:1;s:48:"Porositas yang terbentuk akibat proses pelarutan";i:2;s:48:"Porositas yang terbentuk akibat rekahan tektonik";i:3;s:44:"Porositas yang terbentuk akibat dolomitisasi";}','','Porositas yang terbentuk selama pengendapan sedimen','What is meant by primary porosity in sedimentary rocks?','a:4:{i:0;s:42:"Porosity formed during sediment deposition";i:1;s:44:"Porosity formed due to dissolution processes";i:2;s:42:"Porosity formed due to tectonic fracturing";i:3;s:37:"Porosity formed due to dolomitization";}','Porosity formed during sediment deposition','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000364','Manakah dari berikut ini yang merupakan peran petrofisika dalam fase eksplorasi?','option','PFC000000001','Final Test','a:4:{i:0;s:51:"Evaluasi kualitas reservoir dan potensi hidrokarbon";i:1;s:32:"Perencanaan desain pipa penyalur";i:2;s:25:"Optimasi laju injeksi air";i:3;s:27:"Manajemen limbah pengeboran";}','','Evaluasi kualitas reservoir dan potensi hidrokarbon','Which of the following is a role of petrophysics in the exploration phase?','a:4:{i:0;s:57:"Evaluation of reservoir quality and hydrocarbon potential";i:1;s:24:"Pipeline design planning";i:2;s:37:"Optimization of water injection rates";i:3;s:25:"Drilling waste management";}','Evaluation of reservoir quality and hydrocarbon potential','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000365','Batuan reservoir dengan porositas 20% dikategorikan sebagai apa?','option','PFC000000001','Final Test','a:4:{i:0;s:11:"Baik (Good)";i:1;s:12:"Buruk (Poor)";i:2;s:24:"Sangat Buruk (Very Poor)";i:3;s:23:"Sangat Baik (Excellent)";}','','Baik (Good)','A reservoir rock with 20% porosity is categorized as what?','a:4:{i:0;s:4:"Good";i:1;s:4:"Poor";i:2;s:9:"Very Poor";i:3;s:9:"Excellent";}','Good','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000366','Apa yang terjadi pada porositas batuan jika tingkat sementasi meningkat?','option','PFC000000001','Final Test','a:4:{i:0;s:17:"Porositas menurun";i:1;s:19:"Porositas meningkat";i:2;s:15:"Porositas tetap";i:3;s:31:"Porositas menjadi tidak terukur";}','','Porositas menurun','What happens to rock porosity if the degree of cementation increases?','a:4:{i:0;s:18:"Porosity decreases";i:1;s:18:"Porosity increases";i:2;s:25:"Porosity remains constant";i:3;s:29:"Porosity becomes unmeasurable";}','Porosity decreases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000367','Data logging sumur mana yang paling umum digunakan untuk estimasi porositas secara langsung?','multi','PFC000000001','Final Test','a:4:{i:0;s:11:"Density log";i:1;s:11:"Neutron log";i:2;s:13:"Gamma ray log";i:3;s:6:"SP log";}','','a:2:{i:0;s:11:"Density log";i:1;s:11:"Neutron log";}','Which well logging data is most commonly used for direct porosity estimation?','a:4:{i:0;s:11:"Density log";i:1;s:11:"Neutron log";i:2;s:13:"Gamma ray log";i:3;s:6:"SP log";}','a:2:{i:0;s:11:"Density log";i:1;s:11:"Neutron log";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000368','Mengapa pasir lepas (unconsolidated sand) sering menjadi tantangan dalam produksi minyak?','option','PFC000000001','Final Test','a:4:{i:0;s:53:"Mudah terikut ke dalam lubang sumur (sand production)";i:1;s:41:"Memiliki permeabilitas yang sangat rendah";i:2;s:34:"Tidak dapat mengandung hidrokarbon";i:3;s:30:"Sangat sulit dilakukan logging";}','','Mudah terikut ke dalam lubang sumur (sand production)','Why is unconsolidated sand often a challenge in oil production?','a:4:{i:0;s:51:"Easily produced into the wellbore (sand production)";i:1;s:25:"Has very low permeability";i:2;s:27:"Cannot contain hydrocarbons";i:3;s:33:"Very difficult to perform logging";}','Easily produced into the wellbore (sand production)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000369','Apa hubungan antara ukuran butir dan porositas pada batuan sedimen yang terpilah baik (well-sorted)?','option','PFC000000001','Final Test','a:4:{i:0;s:27:"Tidak ada hubungan langsung";i:1;s:50:"Ukuran butir besar memiliki porositas lebih rendah";i:2;s:50:"Ukuran butir kecil memiliki porositas lebih tinggi";i:3;s:46:"Ukuran butir berbanding lurus dengan porositas";}','','Tidak ada hubungan langsung','What is the relationship between grain size and porosity in well-sorted sedimentary rocks?','a:4:{i:0;s:31:"There is no direct relationship";i:1;s:35:"Large grain size has lower porosity";i:2;s:36:"Small grain size has higher porosity";i:3;s:47:"Grain size is directly proportional to porosity";}','There is no direct relationship','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000370','Dalam konteks reservoir, apa yang dimaksud dengan ''Net Pay''?','option','PFC000000001','Final Test','a:4:{i:0;s:55:"Bagian reservoir yang produktif mengalirkan hidrokarbon";i:1;s:32:"Total ketebalan batuan reservoir";i:2;s:38:"Ketebalan zona shale di atas reservoir";i:3;s:39:"Volume air yang terperangkap dalam pori";}','','Bagian reservoir yang produktif mengalirkan hidrokarbon','In the reservoir context, what is meant by ''Net Pay''?','a:4:{i:0;s:71:"The portion of the reservoir that is productive in flowing hydrocarbons";i:1;s:30:"Total reservoir rock thickness";i:2;s:43:"Thickness of shale zone above the reservoir";i:3;s:32:"Volume of water trapped in pores";}','The portion of the reservoir that is productive in flowing hydrocarbons','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000371','Apa fungsi utama dari analisis core laboratorium dalam petrofisika?','option','PFC000000001','Final Test','a:4:{i:0;s:24:"Kalibrasi data log sumur";i:1;s:29:"Pembuatan desain casing sumur";i:2;s:25:"Estimasi biaya pengeboran";i:3;s:29:"Peningkatan tekanan reservoir";}','','Kalibrasi data log sumur','What is the main function of laboratory core analysis in petrophysics?','a:4:{i:0;s:28:"Calibration of well log data";i:1;s:21:"Designing well casing";i:2;s:25:"Estimating drilling costs";i:3;s:29:"Increasing reservoir pressure";}','Calibration of well log data','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000372','Faktor apa saja yang memengaruhi porositas efektif?','multi','PFC000000001','Final Test','a:4:{i:0;s:16:"Geometri butiran";i:1;s:15:"Sortasi butiran";i:2;s:17:"Tingkat pemadatan";i:3;s:12:"Warna batuan";}','','a:3:{i:0;s:16:"Geometri butiran";i:1;s:15:"Sortasi butiran";i:2;s:17:"Tingkat pemadatan";}','Which factors influence effective porosity?','a:4:{i:0;s:14:"Grain geometry";i:1;s:13:"Grain sorting";i:2;s:17:"Compaction degree";i:3;s:10:"Rock color";}','a:3:{i:0;s:14:"Grain geometry";i:1;s:13:"Grain sorting";i:2;s:17:"Compaction degree";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000373','Apa perbedaan antara porositas total dan porositas efektif?','option','PFC000000001','Final Test','a:4:{i:0;s:59:"Porositas efektif hanya mencakup pori yang saling terhubung";i:1;s:40:"Porositas total lebih kecil dari efektif";i:2;s:50:"Porositas efektif tidak dipengaruhi oleh sementasi";i:3;s:28:"Tidak ada perbedaan keduanya";}','','Porositas efektif hanya mencakup pori yang saling terhubung','What is the difference between total porosity and effective porosity?','a:4:{i:0;s:53:"Effective porosity only includes interconnected pores";i:1;s:40:"Total porosity is smaller than effective";i:2;s:51:"Effective porosity is not influenced by cementation";i:3;s:35:"There is no difference between them";}','Effective porosity only includes interconnected pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000374','Mineral apa yang sering menyumbat pori-pori dan mengurangi porositas?','option','PFC000000001','Final Test','a:4:{i:0;s:14:"Lempung (Clay)";i:1;s:6:"Kuarsa";i:2;s:8:"Feldspar";i:3;s:6:"Zirkon";}','','Lempung (Clay)','Which mineral often clogs pores and reduces porosity?','a:4:{i:0;s:4:"Clay";i:1;s:6:"Quartz";i:2;s:8:"Feldspar";i:3;s:6:"Zircon";}','Clay','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000375','Mengapa petrofisika sangat krusial dalam tahap pengembangan lapangan (field development)?','option','PFC000000001','Final Test','a:4:{i:0;s:40:"Menentukan pola injeksi dan lokasi sumur";i:1;s:33:"Menentukan rute pengiriman minyak";i:2;s:22:"Mengatur pemasaran gas";i:3;s:36:"Mengelola hubungan dengan pemerintah";}','','Menentukan pola injeksi dan lokasi sumur','Why is petrophysics crucial in the field development stage?','a:4:{i:0;s:49:"Determining injection patterns and well locations";i:1;s:31:"Determining oil shipping routes";i:2;s:22:"Managing gas marketing";i:3;s:29:"Managing government relations";}','Determining injection patterns and well locations','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000376','Apa yang dimaksud dengan ''vuggy porosity''?','option','PFC000000001','Final Test','a:4:{i:0;s:65:"Porositas yang terbentuk dari lubang-lubang besar hasil pelarutan";i:1;s:27:"Porositas antar butir pasir";i:2;s:29:"Porositas dalam retakan halus";i:3;s:40:"Porositas yang seragam di seluruh batuan";}','','Porositas yang terbentuk dari lubang-lubang besar hasil pelarutan','What is meant by ''vuggy porosity''?','a:4:{i:0;s:54:"Porosity formed from large cavities due to dissolution";i:1;s:27:"Intergranular sand porosity";i:2;s:30:"Porosity within fine fractures";i:3;s:36:"Uniform porosity throughout the rock";}','Porosity formed from large cavities due to dissolution','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000377','Manakah batuan yang umumnya memiliki porositas awal tinggi namun rentan terhadap kompaksi?','option','PFC000000001','Final Test','a:4:{i:0;s:33:"Pasir lepas (Unconsolidated sand)";i:1;s:21:"Batugamping kristalin";i:2;s:11:"Batuan beku";i:3;s:23:"Batupasir tersemen kuat";}','','Pasir lepas (Unconsolidated sand)','Which rock generally has high initial porosity but is susceptible to compaction?','a:4:{i:0;s:19:"Unconsolidated sand";i:1;s:21:"Crystalline limestone";i:2;s:12:"Igneous rock";i:3;s:27:"Strongly cemented sandstone";}','Unconsolidated sand','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000378','Apa dampak keberadaan rekahan (fractures) terhadap sifat petrofisika batuan?','option','PFC000000001','Final Test','a:4:{i:0;s:41:"Meningkatkan permeabilitas secara drastis";i:1;s:44:"Menurunkan porositas total secara signifikan";i:2;s:52:"Menghilangkan kemampuan batuan menyimpan hidrokarbon";i:3;s:35:"Tidak memiliki pengaruh sama sekali";}','','Meningkatkan permeabilitas secara drastis','What is the impact of fractures on rock petrophysical properties?','a:4:{i:0;s:34:"Drastically increases permeability";i:1;s:38:"Significantly decreases total porosity";i:2;s:51:"Eliminates the rock''s ability to store hydrocarbons";i:3;s:23:"Has no influence at all";}','Drastically increases permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000379','Apa peran utama dari data tekanan dalam studi petrofisika?','option','PFC000000001','Final Test','a:4:{i:0;s:34:"Menentukan kontak fluida (WOC/GOC)";i:1;s:27:"Mengukur berat jenis batuan";i:2;s:33:"Menghitung kecepatan rambat suara";i:3;s:32:"Mengidentifikasi mineral lempung";}','','Menentukan kontak fluida (WOC/GOC)','What is the main role of pressure data in petrophysical studies?','a:4:{i:0;s:36:"Determining fluid contacts (WOC/GOC)";i:1;s:22:"Measuring rock density";i:2;s:34:"Calculating acoustic wave velocity";i:3;s:25:"Identifying clay minerals";}','Determining fluid contacts (WOC/GOC)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000380','Apa definisi porositas efektif pada batuan reservoir?','option','PFC000000002','Final Test','a:4:{i:0;s:75:"Perbandingan volume pori yang saling berhubungan dengan volume total batuan";i:1;s:52:"Perbandingan volume total pori dengan volume butiran";i:2;s:63:"Perbandingan volume pori yang terisi fluida dengan volume total";i:3;s:71:"Perbandingan volume ruang pori yang tidak terhubung dengan volume total";}','','Perbandingan volume pori yang saling berhubungan dengan volume total batuan','What is the definition of effective porosity in reservoir rocks?','a:4:{i:0;s:60:"The ratio of interconnected pore volume to total rock volume";i:1;s:46:"The ratio of total pore volume to grain volume";i:2;s:53:"The ratio of fluid-filled pore volume to total volume";i:3;s:48:"The ratio of isolated pore space to total volume";}','The ratio of interconnected pore volume to total rock volume','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000381','Faktor apa saja yang memengaruhi permeabilitas batuan reservoir?','multi','PFC000000002','Final Test','a:4:{i:0;s:24:"Ukuran butir dan sortasi";i:1;s:22:"Kompaksi dan sementasi";i:2;s:12:"Saturasi air";i:3;s:15:"Tekanan kapiler";}','','a:2:{i:0;s:24:"Ukuran butir dan sortasi";i:1;s:22:"Kompaksi dan sementasi";}','Which factors influence reservoir rock permeability?','a:4:{i:0;s:22:"Grain size and sorting";i:1;s:26:"Compaction and cementation";i:2;s:16:"Water saturation";i:3;s:18:"Capillary pressure";}','a:2:{i:0;s:22:"Grain size and sorting";i:1;s:26:"Compaction and cementation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000382','Hukum Darcy digunakan untuk menghitung laju alir fluida melalui media berpori dengan asumsi kondisi apa?','option','PFC000000002','Final Test','a:4:{i:0;s:70:"Aliran tunak (steady-state), fluida incompressible, dan aliran laminar";i:1;s:60:"Aliran tidak tunak, fluida compressible, dan aliran turbulen";i:2;s:56:"Aliran tunak, fluida incompressible, dan aliran turbulen";i:3;s:59:"Aliran tidak tunak, fluida compressible, dan aliran laminar";}','','Aliran tunak (steady-state), fluida incompressible, dan aliran laminar','Darcy''s Law is used to calculate fluid flow rate through porous media assuming which conditions?','a:4:{i:0;s:57:"Steady-state flow, incompressible fluid, and laminar flow";i:1;s:59:"Unsteady-state flow, compressible fluid, and turbulent flow";i:2;s:59:"Steady-state flow, incompressible fluid, and turbulent flow";i:3;s:57:"Unsteady-state flow, compressible fluid, and laminar flow";}','Steady-state flow, incompressible fluid, and laminar flow','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000383','Apa yang dimaksud dengan saturasi fluida (Sw)?','option','PFC000000002','Final Test','a:4:{i:0;s:39:"Fraksi volume pori yang terisi oleh air";i:1;s:47:"Perbandingan volume air terhadap volume butiran";i:2;s:46:"Fraksi volume air terhadap volume total batuan";i:3;s:41:"Jumlah air per satuan luas permukaan pori";}','','Fraksi volume pori yang terisi oleh air','What is meant by fluid saturation (Sw)?','a:4:{i:0;s:45:"The fraction of pore volume filled with water";i:1;s:41:"The ratio of water volume to grain volume";i:2;s:49:"The fraction of water volume to total rock volume";i:3;s:49:"The amount of water per unit of pore surface area";}','The fraction of pore volume filled with water','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000384','Manakah pernyataan yang benar mengenai kompresibilitas batuan?','option','PFC000000002','Final Test','a:4:{i:0;s:50:"Perubahan volume pori per satuan perubahan tekanan";i:1;s:30:"Kemampuan fluida untuk ditekan";i:2;s:38:"Perubahan permeabilitas terhadap waktu";i:3;s:37:"Perubahan saturasi terhadap kedalaman";}','','Perubahan volume pori per satuan perubahan tekanan','Which statement is correct regarding rock compressibility?','a:4:{i:0;s:53:"The change in pore volume per unit change in pressure";i:1;s:39:"The ability of a fluid to be compressed";i:2;s:36:"The change in permeability over time";i:3;s:35:"The change in saturation with depth";}','The change in pore volume per unit change in pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000385','Alat laboratorium apa yang umum digunakan untuk mengukur porositas batuan core?','option','PFC000000002','Final Test','a:4:{i:0;s:18:"Porosimeter Helium";i:1;s:11:"Permeameter";i:2;s:10:"Centrifuge";i:3;s:43:"Mercury Injection Capillary Pressure (MICP)";}','','Porosimeter Helium','Which laboratory instrument is commonly used to measure core rock porosity?','a:4:{i:0;s:18:"Helium Porosimeter";i:1;s:11:"Permeameter";i:2;s:10:"Centrifuge";i:3;s:43:"Mercury Injection Capillary Pressure (MICP)";}','Helium Porosimeter','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000386','Mengapa permeabilitas absolut hanya bergantung pada geometri pori, bukan fluida?','option','PFC000000002','Final Test','a:4:{i:0;s:88:"Karena permeabilitas absolut didefinisikan untuk satu fase fluida yang mengisi 100% pori";i:1;s:47:"Karena fluida tidak memengaruhi struktur batuan";i:2;s:37:"Karena viskositas fluida dianggap nol";i:3;s:43:"Karena batuan bersifat homogen secara total";}','','Karena permeabilitas absolut didefinisikan untuk satu fase fluida yang mengisi 100% pori','Why does absolute permeability depend only on pore geometry, not the fluid?','a:4:{i:0;s:91:"Because absolute permeability is defined for a single fluid phase filling 100% of the pores";i:1;s:43:"Because fluids do not affect rock structure";i:2;s:45:"Because fluid viscosity is assumed to be zero";i:3;s:42:"Because the rock is completely homogeneous";}','Because absolute permeability is defined for a single fluid phase filling 100% of the pores','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000387','Jika sebuah batuan memiliki porositas primer dan sekunder, manakah istilah yang tepat untuk porositas totalnya?','option','PFC000000002','Final Test','a:4:{i:0;s:14:"Porositas dual";i:1;s:17:"Porositas efektif";i:2;s:16:"Porositas primer";i:3;s:23:"Porositas intragranular";}','','Porositas dual','If a rock has primary and secondary porosity, what is the correct term for its total porosity?','a:4:{i:0;s:13:"Dual porosity";i:1;s:18:"Effective porosity";i:2;s:16:"Primary porosity";i:3;s:22:"Intragranular porosity";}','Dual porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000388','Apa dampak peningkatan tekanan overburden terhadap porositas batuan?','option','PFC000000002','Final Test','a:4:{i:0;s:17:"Porositas menurun";i:1;s:19:"Porositas meningkat";i:2;s:15:"Porositas tetap";i:3;s:21:"Porositas menjadi nol";}','','Porositas menurun','What is the impact of increased overburden pressure on rock porosity?','a:4:{i:0;s:18:"Porosity decreases";i:1;s:18:"Porosity increases";i:2;s:25:"Porosity remains the same";i:3;s:21:"Porosity becomes zero";}','Porosity decreases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000389','Sebutkan parameter yang diperlukan untuk menghitung permeabilitas menggunakan Hukum Darcy.','multi','PFC000000002','Final Test','a:4:{i:0;s:13:"Laju alir (Q)";i:1;s:22:"Viskositas fluida (μ)";i:2;s:18:"Panjang sampel (L)";i:3;s:14:"Tipe sementasi";}','','a:3:{i:0;s:13:"Laju alir (Q)";i:1;s:22:"Viskositas fluida (μ)";i:2;s:18:"Panjang sampel (L)";}','Which parameters are needed to calculate permeability using Darcy''s Law?','a:4:{i:0;s:13:"Flow rate (Q)";i:1;s:20:"Fluid viscosity (μ)";i:2;s:17:"Sample length (L)";i:3;s:16:"Cementation type";}','a:3:{i:0;s:13:"Flow rate (Q)";i:1;s:20:"Fluid viscosity (μ)";i:2;s:17:"Sample length (L)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000390','Apa itu saturasi air irreducible (Swir)?','option','PFC000000002','Final Test','a:4:{i:0;s:68:"Saturasi air maksimum yang tidak dapat dipindahkan oleh gaya kapiler";i:1;s:56:"Saturasi air minimum yang dapat dicapai saat injeksi air";i:2;s:50:"Saturasi air saat reservoir pertama kali ditemukan";i:3;s:50:"Volume air yang terperangkap dalam kristal mineral";}','','Saturasi air maksimum yang tidak dapat dipindahkan oleh gaya kapiler','What is irreducible water saturation (Swir)?','a:4:{i:0;s:73:"The maximum water saturation that cannot be displaced by capillary forces";i:1;s:61:"The minimum water saturation reachable during water injection";i:2;s:60:"The water saturation when the reservoir was first discovered";i:3;s:51:"The volume of water trapped within mineral crystals";}','The maximum water saturation that cannot be displaced by capillary forces','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000391','Apa kegunaan utama data tekanan kapiler (Pc) dalam petrofisika?','option','PFC000000002','Final Test','a:4:{i:0;s:82:"Menentukan distribusi saturasi fluida terhadap ketinggian di atas free water level";i:1;s:41:"Mengukur kecepatan rambat gelombang suara";i:2;s:36:"Menghitung nilai porositas rata-rata";i:3;s:28:"Menentukan viskositas minyak";}','','Menentukan distribusi saturasi fluida terhadap ketinggian di atas free water level','What is the primary use of capillary pressure (Pc) data in petrophysics?','a:4:{i:0;s:78:"Determining fluid saturation distribution versus height above free water level";i:1;s:29:"Measuring sonic wave velocity";i:2;s:34:"Calculating average porosity value";i:3;s:25:"Determining oil viscosity";}','Determining fluid saturation distribution versus height above free water level','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000392','Bagaimana hubungan antara ukuran butir dengan permeabilitas pada batuan sedimen?','option','PFC000000002','Final Test','a:4:{i:0;s:63:"Semakin besar butiran, cenderung semakin besar permeabilitasnya";i:1;s:63:"Semakin kecil butiran, cenderung semakin besar permeabilitasnya";i:2;s:53:"Ukuran butir tidak berpengaruh terhadap permeabilitas";i:3;s:33:"Hubungan keduanya linear terbalik";}','','Semakin besar butiran, cenderung semakin besar permeabilitasnya','How is grain size related to permeability in sedimentary rocks?','a:4:{i:0;s:46:"Larger grains tend to have higher permeability";i:1;s:47:"Smaller grains tend to have higher permeability";i:2;s:40:"Grain size has no effect on permeability";i:3;s:40:"They have an inverse linear relationship";}','Larger grains tend to have higher permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000393','Apa yang dimaksud dengan wettability dalam konteks saturasi fluida?','option','PFC000000002','Final Test','a:4:{i:0;s:53:"Preferensi batuan untuk dibasahi oleh fluida tertentu";i:1;s:34:"Kemampuan batuan untuk menahan air";i:2;s:39:"Kecepatan fluida mengalir di dalam pori";i:3;s:35:"Derajat kekasaran permukaan butiran";}','','Preferensi batuan untuk dibasahi oleh fluida tertentu','What is meant by wettability in the context of fluid saturation?','a:4:{i:0;s:55:"The preference of rock to be wetted by a specific fluid";i:1;s:35:"The ability of rock to retain water";i:2;s:36:"The speed of fluid flow within pores";i:3;s:37:"The degree of grain surface roughness";}','The preference of rock to be wetted by a specific fluid','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000394','Manakah metode laboratorium untuk menentukan saturasi fluida pada core sample?','option','PFC000000002','Final Test','a:4:{i:0;s:26:"Metode Retort Distillation";i:1;s:23:"Metode Helium Expansion";i:2;s:24:"Metode Mercury Injection";i:3;s:17:"Metode Darcy Flow";}','','Metode Retort Distillation','Which laboratory method is used to determine fluid saturation on a core sample?','a:4:{i:0;s:26:"Retort Distillation method";i:1;s:23:"Helium Expansion method";i:2;s:24:"Mercury Injection method";i:3;s:17:"Darcy Flow method";}','Retort Distillation method','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000395','Apa pengaruh gas terlarut terhadap kompresibilitas minyak?','option','PFC000000002','Final Test','a:4:{i:0;s:35:"Meningkatkan kompresibilitas minyak";i:1;s:33:"Menurunkan kompresibilitas minyak";i:2;s:18:"Tidak ada pengaruh";i:3;s:28:"Membuat minyak menjadi padat";}','','Meningkatkan kompresibilitas minyak','What is the effect of dissolved gas on oil compressibility?','a:4:{i:0;s:29:"Increases oil compressibility";i:1;s:29:"Decreases oil compressibility";i:2;s:9:"No effect";i:3;s:15:"Makes oil solid";}','Increases oil compressibility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000396','Satuan standar internasional untuk permeabilitas adalah?','option','PFC000000002','Final Test','a:4:{i:0;s:5:"Darcy";i:1;s:6:"Pascal";i:2;s:5:"Poise";i:3;s:6:"Micron";}','','Darcy','The standard international unit for permeability is?','a:4:{i:0;s:5:"Darcy";i:1;s:6:"Pascal";i:2;s:5:"Poise";i:3;s:6:"Micron";}','Darcy','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000397','Apa yang terjadi jika batuan memiliki sortasi yang buruk (poorly sorted)?','option','PFC000000002','Final Test','a:4:{i:0;s:86:"Porositas cenderung lebih rendah karena butiran kecil mengisi pori antar butiran besar";i:1;s:32:"Porositas cenderung lebih tinggi";i:2;s:35:"Permeabilitas menjadi sangat tinggi";i:3;s:32:"Batuan menjadi tidak kompresibel";}','','Porositas cenderung lebih rendah karena butiran kecil mengisi pori antar butiran besar','What happens if a rock is poorly sorted?','a:4:{i:0;s:82:"Porosity tends to be lower because smaller grains fill pores between larger grains";i:1;s:27:"Porosity tends to be higher";i:2;s:30:"Permeability becomes very high";i:3;s:31:"The rock becomes incompressible";}','Porosity tends to be lower because smaller grains fill pores between larger grains','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000398','Pilih elemen yang merupakan bagian dari perhitungan porositas total.','multi','PFC000000002','Final Test','a:4:{i:0;s:16:"Porositas primer";i:1;s:18:"Porositas sekunder";i:2;s:12:"Saturasi air";i:3;s:15:"Tekanan kapiler";}','','a:2:{i:0;s:16:"Porositas primer";i:1;s:18:"Porositas sekunder";}','Select the elements that are part of the total porosity calculation.','a:4:{i:0;s:16:"Primary porosity";i:1;s:18:"Secondary porosity";i:2;s:16:"Water saturation";i:3;s:18:"Capillary pressure";}','a:2:{i:0;s:16:"Primary porosity";i:1;s:18:"Secondary porosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000399','Mengapa pengukuran permeabilitas pada kondisi laboratorium harus dikoreksi ke kondisi reservoir?','option','PFC000000002','Final Test','a:4:{i:0;s:50:"Karena perbedaan tekanan overburden dan temperatur";i:1;s:37:"Karena alat laboratorium tidak akurat";i:2;s:41:"Karena fluida laboratorium selalu berbeda";i:3;s:51:"Karena permeabilitas tidak berubah dengan kedalaman";}','','Karena perbedaan tekanan overburden dan temperatur','Why must permeability measurements at laboratory conditions be corrected to reservoir conditions?','a:4:{i:0;s:61:"Because of differences in overburden pressure and temperature";i:1;s:42:"Because laboratory equipment is inaccurate";i:2;s:46:"Because laboratory fluids are always different";i:3;s:47:"Because permeability does not change with depth";}','Because of differences in overburden pressure and temperature','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000400','Parameter utama yang menggambarkan rasio volume minyak pada kondisi reservoir terhadap volume minyak pada kondisi standar (tangki) adalah','option','PFC000000003','Final Test','a:4:{i:0;s:33:"Faktor volume formasi minyak (Bo)";i:1;s:17:"Viskositas minyak";i:2;s:25:"Kompresibilitas isotermal";i:3;s:16:"Densitas relatif";}','','Faktor volume formasi minyak (Bo)','The main parameter describing the ratio of oil volume at reservoir conditions to oil volume at standard (tank) conditions is','a:4:{i:0;s:32:"Oil formation volume factor (Bo)";i:1;s:13:"Oil viscosity";i:2;s:26:"Isothermal compressibility";i:3;s:16:"Relative density";}','Oil formation volume factor (Bo)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000401','Faktor apa saja yang menyebabkan penurunan viskositas minyak mentah dalam reservoir?','multi','PFC000000003','Final Test','a:4:{i:0;s:22:"Peningkatan temperatur";i:1;s:19:"Peningkatan tekanan";i:2;s:38:"Kelarutan gas yang tinggi dalam minyak";i:3;s:21:"Kehadiran air formasi";}','','a:2:{i:0;s:22:"Peningkatan temperatur";i:1;s:38:"Kelarutan gas yang tinggi dalam minyak";}','Which factors cause a decrease in crude oil viscosity within the reservoir?','a:4:{i:0;s:20:"Temperature increase";i:1;s:17:"Pressure increase";i:2;s:26:"High gas solubility in oil";i:3;s:27:"Presence of formation water";}','a:2:{i:0;s:20:"Temperature increase";i:1;s:26:"High gas solubility in oil";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000402','Pada tekanan di atas tekanan titik gelembung (bubble point), perubahan faktor volume formasi minyak (Bo) terhadap tekanan adalah','option','PFC000000003','Final Test','a:4:{i:0;s:40:"Menurun seiring dengan penurunan tekanan";i:1;s:42:"Meningkat seiring dengan penurunan tekanan";i:2;s:13:"Tetap konstan";i:3;s:24:"Berfluktuasi secara acak";}','','Meningkat seiring dengan penurunan tekanan','At pressures above the bubble point, the change in oil formation volume factor (Bo) with respect to pressure is','a:4:{i:0;s:32:"Decreasing as pressure decreases";i:1;s:32:"Increasing as pressure decreases";i:2;s:8:"Constant";i:3;s:20:"Fluctuating randomly";}','Increasing as pressure decreases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000403','Kompresibilitas isotermal minyak (Co) didefinisikan sebagai perubahan volume per satuan volume akibat perubahan','option','PFC000000003','Final Test','a:4:{i:0;s:7:"Tekanan";i:1;s:10:"Temperatur";i:2;s:10:"Viskositas";i:3;s:8:"Densitas";}','','Tekanan','Oil isothermal compressibility (Co) is defined as the change in volume per unit volume due to a change in','a:4:{i:0;s:8:"Pressure";i:1;s:11:"Temperature";i:2;s:9:"Viscosity";i:3;s:7:"Density";}','Pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000404','Manakah pernyataan yang benar mengenai densitas air formasi seiring dengan kedalaman reservoir?','option','PFC000000003','Final Test','a:4:{i:0;s:50:"Meningkat karena peningkatan salinitas dan tekanan";i:1;s:37:"Menurun karena peningkatan temperatur";i:2;s:43:"Tetap konstan karena air tidak termampatkan";i:3;s:37:"Meningkat hanya jika ada gas terlarut";}','','Meningkat karena peningkatan salinitas dan tekanan','Which statement is correct regarding formation water density with increasing reservoir depth?','a:4:{i:0;s:48:"Increases due to increased salinity and pressure";i:1;s:38:"Decreases due to increased temperature";i:2;s:48:"Remains constant because water is incompressible";i:3;s:42:"Increases only if dissolved gas is present";}','Increases due to increased salinity and pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000405','Gas yang berada pada kondisi tekanan dan temperatur di atas titik kritisnya disebut sebagai','option','PFC000000003','Final Test','a:4:{i:0;s:18:"Fluida superkritis";i:1;s:9:"Gas basah";i:2;s:10:"Gas kering";i:3;s:9:"Kondensat";}','','Fluida superkritis','Gas at pressure and temperature conditions above its critical point is called','a:4:{i:0;s:19:"Supercritical fluid";i:1;s:7:"Wet gas";i:2;s:7:"Dry gas";i:3;s:10:"Condensate";}','Supercritical fluid','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000406','Faktor volume formasi gas (Bg) pada kondisi standar dinyatakan dengan satuan','option','PFC000000003','Final Test','a:4:{i:0;s:7:"bbl/SCF";i:1;s:7:"SCF/STB";i:2;s:2:"cP";i:3;s:4:"psia";}','','bbl/SCF','The gas formation volume factor (Bg) at standard conditions is expressed in units of','a:4:{i:0;s:7:"bbl/SCF";i:1;s:7:"SCF/STB";i:2;s:2:"cP";i:3;s:4:"psia";}','bbl/SCF','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000407','Apa yang terjadi pada rasio gas-minyak terlarut (Rs) ketika tekanan turun di bawah tekanan titik gelembung?','option','PFC000000003','Final Test','a:4:{i:0;s:10:"Rs menurun";i:1;s:12:"Rs meningkat";i:2;s:16:"Rs tidak berubah";i:3;s:28:"Rs menjadi nol secara instan";}','','Rs menurun','What happens to the solution gas-oil ratio (Rs) when the pressure drops below the bubble point pressure?','a:4:{i:0;s:12:"Rs decreases";i:1;s:12:"Rs increases";i:2;s:20:"Rs remains unchanged";i:3;s:25:"Rs becomes zero instantly";}','Rs decreases','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000408','Sifat fisik fluida yang sangat dipengaruhi oleh jumlah gas yang terlarut di dalam minyak adalah','multi','PFC000000003','Final Test','a:4:{i:0;s:17:"Viskositas minyak";i:1;s:26:"Faktor volume formasi (Bo)";i:2;s:15:"Densitas minyak";i:3;s:13:"Salinitas air";}','','a:3:{i:0;s:17:"Viskositas minyak";i:1;s:26:"Faktor volume formasi (Bo)";i:2;s:15:"Densitas minyak";}','Physical properties of fluids that are significantly influenced by the amount of gas dissolved in oil are','a:4:{i:0;s:13:"Oil viscosity";i:1;s:28:"Formation volume factor (Bo)";i:2;s:11:"Oil density";i:3;s:14:"Water salinity";}','a:3:{i:0;s:13:"Oil viscosity";i:1;s:28:"Formation volume factor (Bo)";i:2;s:11:"Oil density";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000409','Tekanan di mana gelembung gas pertama kali muncul dari fase cair minyak disebut','option','PFC000000003','Final Test','a:4:{i:0;s:47:"Tekanan titik gelembung (bubble point pressure)";i:1;s:40:"Tekanan titik embun (dew point pressure)";i:2;s:16:"Tekanan kritikal";i:3;s:19:"Tekanan hidrostatis";}','','Tekanan titik gelembung (bubble point pressure)','The pressure at which the first gas bubble emerges from the oil liquid phase is called','a:4:{i:0;s:21:"Bubble point pressure";i:1;s:18:"Dew point pressure";i:2;s:17:"Critical pressure";i:3;s:20:"Hydrostatic pressure";}','Bubble point pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000410','Faktor volume formasi air (Bw) umumnya bernilai','option','PFC000000003','Final Test','a:4:{i:0;s:11:"Mendekati 1";i:1;s:25:"Sangat besar (di atas 10)";i:2;s:27:"Sangat kecil (di bawah 0,1)";i:3;s:7:"Negatif";}','','Mendekati 1','The water formation volume factor (Bw) is generally','a:4:{i:0;s:10:"Close to 1";i:1;s:21:"Very large (above 10)";i:2;s:22:"Very small (below 0.1)";i:3;s:8:"Negative";}','Close to 1','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000411','Apa dampak dari peningkatan salinitas terhadap viskositas air formasi?','option','PFC000000003','Final Test','a:4:{i:0;s:23:"Meningkatkan viskositas";i:1;s:21:"Menurunkan viskositas";i:2;s:17:"Tidak berpengaruh";i:3;s:33:"Membuat air menjadi non-newtonian";}','','Meningkatkan viskositas','What is the impact of increased salinity on formation water viscosity?','a:4:{i:0;s:19:"Increases viscosity";i:1;s:19:"Decreases viscosity";i:2;s:9:"No effect";i:3;s:25:"Makes water non-newtonian";}','Increases viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000412','Dalam diagram fase P-T, daerah di mana fluida berada dalam dua fase (cair dan gas) dibatasi oleh','option','PFC000000003','Final Test','a:4:{i:0;s:37:"Kurva titik gelembung dan titik embun";i:1;s:15:"Garis isotermal";i:2;s:12:"Garis isokor";i:3;s:12:"Titik kritis";}','','Kurva titik gelembung dan titik embun','In a P-T phase diagram, the region where fluid exists in two phases (liquid and gas) is bounded by','a:4:{i:0;s:33:"Bubble point and dew point curves";i:1;s:16:"Isothermal lines";i:2;s:14:"Isochore lines";i:3;s:14:"Critical point";}','Bubble point and dew point curves','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000413','Manakah dari berikut ini yang merupakan sifat fluida yang ditentukan melalui eksperimen laboratorium PVT?','multi','PFC000000003','Final Test','a:4:{i:0;s:23:"Tekanan titik gelembung";i:1;s:21:"Rasio gas-minyak (Rs)";i:2;s:21:"Permeabilitas absolut";i:3;s:26:"Faktor volume formasi (Bo)";}','','a:3:{i:0;s:23:"Tekanan titik gelembung";i:1;s:21:"Rasio gas-minyak (Rs)";i:2;s:26:"Faktor volume formasi (Bo)";}','Which of the following are fluid properties determined through PVT laboratory experiments?','a:4:{i:0;s:21:"Bubble point pressure";i:1;s:18:"Gas-oil ratio (Rs)";i:2;s:21:"Absolute permeability";i:3;s:28:"Formation volume factor (Bo)";}','a:3:{i:0;s:21:"Bubble point pressure";i:1;s:18:"Gas-oil ratio (Rs)";i:2;s:28:"Formation volume factor (Bo)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000414','Nilai kompresibilitas air (Cw) biasanya lebih kecil daripada kompresibilitas minyak karena','option','PFC000000003','Final Test','a:4:{i:0;s:43:"Air lebih sulit dimampatkan daripada minyak";i:1;s:34:"Air memiliki densitas lebih rendah";i:2;s:33:"Air tidak mengandung gas terlarut";i:3;s:27:"Viskositas air lebih rendah";}','','Air lebih sulit dimampatkan daripada minyak','The value of water compressibility (Cw) is usually smaller than oil compressibility because','a:4:{i:0;s:36:"Water is harder to compress than oil";i:1;s:23:"Water has lower density";i:2;s:36:"Water does not contain dissolved gas";i:3;s:24:"Water viscosity is lower";}','Water is harder to compress than oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000415','Gas yang mengandung sedikit atau tidak ada hidrokarbon cair pada kondisi permukaan disebut','option','PFC000000003','Final Test','a:4:{i:0;s:10:"Gas kering";i:1;s:9:"Gas basah";i:2;s:9:"Kondensat";i:3;s:15:"Minyak volatile";}','','Gas kering','Gas that contains little or no liquid hydrocarbons at surface conditions is called','a:4:{i:0;s:7:"Dry gas";i:1;s:7:"Wet gas";i:2;s:10:"Condensate";i:3;s:12:"Volatile oil";}','Dry gas','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000416','Pengaruh kenaikan temperatur pada viskositas gas adalah','option','PFC000000003','Final Test','a:4:{i:0;s:23:"Meningkatkan viskositas";i:1;s:21:"Menurunkan viskositas";i:2;s:13:"Tetap konstan";i:3;s:23:"Bergantung pada tekanan";}','','Meningkatkan viskositas','The effect of temperature increase on gas viscosity is','a:4:{i:0;s:19:"Increases viscosity";i:1;s:19:"Decreases viscosity";i:2;s:8:"Constant";i:3;s:21:"Dependent on pressure";}','Increases viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000417','Parameter utama yang menentukan klasifikasi fluida reservoir dalam diagram fase adalah','option','PFC000000003','Final Test','a:4:{i:0;s:17:"Komposisi kimiawi";i:1;s:12:"Warna fluida";i:2;s:19:"Kedalaman reservoir";i:3;s:21:"Kecepatan alir fluida";}','','Komposisi kimiawi','The main parameter that determines the classification of reservoir fluids in a phase diagram is','a:4:{i:0;s:20:"Chemical composition";i:1;s:11:"Fluid color";i:2;s:15:"Reservoir depth";i:3;s:19:"Fluid flow velocity";}','Chemical composition','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000418','Jika tekanan reservoir turun di bawah tekanan titik embun pada reservoir gas kondensat, maka akan terjadi','option','PFC000000003','Final Test','a:4:{i:0;s:23:"Retrograde condensation";i:1;s:16:"Evaporasi cairan";i:2;s:21:"Pembentukan gas murni";i:3;s:29:"Peningkatan viskositas minyak";}','','Retrograde condensation','If the reservoir pressure drops below the dew point pressure in a gas condensate reservoir, it will result in','a:4:{i:0;s:23:"Retrograde condensation";i:1;s:18:"Liquid evaporation";i:2;s:21:"Formation of pure gas";i:3;s:25:"Increase in oil viscosity";}','Retrograde condensation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000419','Faktor volume formasi air (Bw) dipengaruhi oleh','multi','PFC000000003','Final Test','a:4:{i:0;s:7:"Tekanan";i:1;s:10:"Temperatur";i:2;s:9:"Salinitas";i:3;s:13:"Permeabilitas";}','','a:3:{i:0;s:7:"Tekanan";i:1;s:10:"Temperatur";i:2;s:9:"Salinitas";}','The water formation volume factor (Bw) is influenced by','a:4:{i:0;s:8:"Pressure";i:1;s:11:"Temperature";i:2;s:8:"Salinity";i:3;s:12:"Permeability";}','a:3:{i:0;s:8:"Pressure";i:1;s:11:"Temperature";i:2;s:8:"Salinity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000420','Log gamma ray digunakan terutama untuk menentukan karakteristik apa dari formasi?','option','PFC000000004','Final Test','a:4:{i:0;s:29:"Litologi dan kandungan serpih";i:1;s:16:"Porositas batuan";i:2;s:12:"Saturasi air";i:3;s:21:"Permeabilitas absolut";}','','Litologi dan kandungan serpih','The gamma ray log is primarily used to determine which formation characteristic?','a:4:{i:0;s:27:"Lithology and shale content";i:1;s:13:"Rock porosity";i:2;s:16:"Water saturation";i:3;s:21:"Absolute permeability";}','Lithology and shale content','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000421','Faktor apa yang dapat memengaruhi pembacaan log resistivitas dalam lingkungan lubang bor?','multi','PFC000000004','Final Test','a:4:{i:0;s:25:"Infiltrasi filtrat lumpur";i:1;s:19:"Diameter lubang bor";i:2;s:18:"Ketebalan mud cake";i:3;s:20:"Kecepatan pengeboran";}','','a:3:{i:0;s:25:"Infiltrasi filtrat lumpur";i:1;s:19:"Diameter lubang bor";i:2;s:18:"Ketebalan mud cake";}','What factors can affect resistivity log readings in the borehole environment?','a:4:{i:0;s:21:"Mud filtrate invasion";i:1;s:17:"Borehole diameter";i:2;s:18:"Mud cake thickness";i:3;s:13:"Drilling rate";}','a:3:{i:0;s:21:"Mud filtrate invasion";i:1;s:17:"Borehole diameter";i:2;s:18:"Mud cake thickness";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000422','Log neutron mengukur konsentrasi apa di dalam formasi untuk menentukan porositas?','option','PFC000000004','Final Test','a:4:{i:0;s:11:"Ion klorida";i:1;s:8:"Hidrogen";i:2;s:6:"Karbon";i:3;s:6:"Sulfur";}','','Hidrogen','The neutron log measures the concentration of what within the formation to determine porosity?','a:4:{i:0;s:13:"Chloride ions";i:1;s:8:"Hydrogen";i:2;s:6:"Carbon";i:3;s:6:"Sulfur";}','Hydrogen','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000423','Prinsip kerja log densitas didasarkan pada interaksi apa antara radiasi gamma dengan elektron batuan?','option','PFC000000004','Final Test','a:4:{i:0;s:16:"Efek fotolistrik";i:1;s:16:"Hamburan Compton";i:2;s:17:"Produksi pasangan";i:3;s:15:"Radiasi sinar-X";}','','Hamburan Compton','The density log working principle is based on what interaction between gamma radiation and rock electrons?','a:4:{i:0;s:20:"Photoelectric effect";i:1;s:18:"Compton scattering";i:2;s:15:"Pair production";i:3;s:15:"X-ray radiation";}','Compton scattering','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000424','Apa fungsi utama dari log caliper dalam operasi wireline logging?','option','PFC000000004','Final Test','a:4:{i:0;s:28:"Mengukur diameter lubang bor";i:1;s:24:"Mengukur tekanan formasi";i:2;s:24:"Mengukur suhu lubang bor";i:3;s:28:"Mengukur resistivitas lumpur";}','','Mengukur diameter lubang bor','What is the primary function of the caliper log in wireline logging operations?','a:4:{i:0;s:27:"Measuring borehole diameter";i:1;s:28:"Measuring formation pressure";i:2;s:30:"Measuring borehole temperature";i:3;s:25:"Measuring mud resistivity";}','Measuring borehole diameter','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000425','Log sonic (akustik) mengukur waktu tempuh gelombang suara untuk menentukan apa?','option','PFC000000004','Final Test','a:4:{i:0;s:18:"Porositas sekunder";i:1;s:41:"Porositas transit (interval transit time)";i:2;s:20:"Saturasi hidrokarbon";i:3;s:16:"Kekerasan batuan";}','','Porositas transit (interval transit time)','The sonic log measures sound wave travel time to determine what?','a:4:{i:0;s:18:"Secondary porosity";i:1;s:30:"Interval transit time porosity";i:2;s:22:"Hydrocarbon saturation";i:3;s:13:"Rock hardness";}','Interval transit time porosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000426','Mengapa koreksi borehole diperlukan pada data log?','multi','PFC000000004','Final Test','a:4:{i:0;s:56:"Karena pengaruh diameter lubang bor yang tidak beraturan";i:1;s:27:"Karena adanya efek mud cake";i:2;s:36:"Untuk meningkatkan kecepatan logging";i:3;s:38:"Karena efek lingkungan lumpur (invasi)";}','','a:3:{i:0;s:56:"Karena pengaruh diameter lubang bor yang tidak beraturan";i:1;s:27:"Karena adanya efek mud cake";i:2;s:38:"Karena efek lingkungan lumpur (invasi)";}','Why is borehole correction required for log data?','a:4:{i:0;s:42:"Due to irregular borehole diameter effects";i:1;s:23:"Due to mud cake effects";i:2;s:25:"To increase logging speed";i:3;s:41:"Due to mud environment (invasion) effects";}','a:3:{i:0;s:42:"Due to irregular borehole diameter effects";i:1;s:23:"Due to mud cake effects";i:2;s:41:"Due to mud environment (invasion) effects";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000427','Apa yang dimaksud dengan ''invasi'' dalam konteks lingkungan lubang bor?','option','PFC000000004','Final Test','a:4:{i:0;s:40:"Masuknya filtrat lumpur ke dalam formasi";i:1;s:38:"Keluarnya fluida formasi ke lubang bor";i:2;s:28:"Runtuhnya dinding lubang bor";i:3;s:24:"Penyumbatan alat logging";}','','Masuknya filtrat lumpur ke dalam formasi','What is meant by ''invasion'' in the context of the borehole environment?','a:4:{i:0;s:47:"Infiltration of mud filtrate into the formation";i:1;s:44:"Outflow of formation fluid into the borehole";i:2;s:29:"Collapse of the borehole wall";i:3;s:28:"Clogging of the logging tool";}','Infiltration of mud filtrate into the formation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000428','Log SP (Spontaneous Potential) paling efektif digunakan jika lumpur pengeboran bersifat apa?','option','PFC000000004','Final Test','a:4:{i:0;s:32:"Berbasis air tawar (water-based)";i:1;s:27:"Berbasis minyak (oil-based)";i:2;s:19:"Udara (air-drilled)";i:3;s:10:"Semen cair";}','','Berbasis air tawar (water-based)','The SP log is most effective when the drilling mud is of what type?','a:4:{i:0;s:11:"Water-based";i:1;s:9:"Oil-based";i:2;s:11:"Air-drilled";i:3;s:13:"Liquid cement";}','Water-based','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000429','Apa yang diukur oleh log Photoelectric Factor (PEF) yang sering menyertai log densitas?','option','PFC000000004','Final Test','a:4:{i:0;s:29:"Nomor atom efektif (litologi)";i:1;s:13:"Densitas bulk";i:2;s:15:"Porositas total";i:3;s:12:"Saturasi air";}','','Nomor atom efektif (litologi)','What does the Photoelectric Factor (PEF) log, which often accompanies the density log, measure?','a:4:{i:0;s:35:"Effective atomic number (lithology)";i:1;s:12:"Bulk density";i:2;s:14:"Total porosity";i:3;s:16:"Water saturation";}','Effective atomic number (lithology)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000430','Dalam kondisi apa log sonic sering memberikan pembacaan porositas yang terlalu tinggi?','option','PFC000000004','Final Test','a:4:{i:0;s:42:"Adanya porositas sekunder (vuggy/fracture)";i:1;s:26:"Formasi yang sangat kompak";i:2;s:24:"Adanya gas dalam formasi";i:3;s:26:"Batuan sedimen yang bersih";}','','Adanya porositas sekunder (vuggy/fracture)','Under what conditions does the sonic log often provide overly high porosity readings?','a:4:{i:0;s:47:"Presence of secondary porosity (vugs/fractures)";i:1;s:24:"Highly compact formation";i:2;s:32:"Presence of gas in the formation";i:3;s:22:"Clean sedimentary rock";}','Presence of secondary porosity (vugs/fractures)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000431','Apa perbedaan utama antara densitas bulk dan densitas matriks?','option','PFC000000004','Final Test','a:4:{i:0;s:83:"Densitas bulk mencakup pori berisi fluida, densitas matriks adalah densitas mineral";i:1;s:75:"Densitas bulk adalah densitas batuan kering, densitas matriks mencakup pori";i:2;s:37:"Densitas bulk hanya untuk batuan beku";i:3;s:19:"Tidak ada perbedaan";}','','Densitas bulk mencakup pori berisi fluida, densitas matriks adalah densitas mineral','What is the main difference between bulk density and matrix density?','a:4:{i:0;s:75:"Bulk density includes fluid-filled pores, matrix density is mineral density";i:1;s:63:"Bulk density is dry rock density, matrix density includes pores";i:2;s:38:"Bulk density is only for igneous rocks";i:3;s:22:"There is no difference";}','Bulk density includes fluid-filled pores, matrix density is mineral density','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000432','Log resistivitas dalam (Deep Resistivity) digunakan untuk apa?','option','PFC000000004','Final Test','a:4:{i:0;s:55:"Mengukur resistivitas zona formasi yang belum terinvasi";i:1;s:30:"Mengukur resistivitas mud cake";i:2;s:24:"Mengukur diameter lubang";i:3;s:36:"Mengukur resistivitas filtrat lumpur";}','','Mengukur resistivitas zona formasi yang belum terinvasi','What is the deep resistivity log used for?','a:4:{i:0;s:53:"Measuring resistivity of the uninvaded formation zone";i:1;s:30:"Measuring mud cake resistivity";i:2;s:23:"Measuring hole diameter";i:3;s:34:"Measuring mud filtrate resistivity";}','Measuring resistivity of the uninvaded formation zone','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000433','Apa dampak keberadaan gas terhadap log densitas dan log neutron?','option','PFC000000004','Final Test','a:4:{i:0;s:47:"Densitas terbaca rendah, neutron terbaca rendah";i:1;s:47:"Densitas terbaca tinggi, neutron terbaca tinggi";i:2;s:47:"Densitas terbaca rendah, neutron terbaca tinggi";i:3;s:47:"Densitas terbaca tinggi, neutron terbaca rendah";}','','Densitas terbaca rendah, neutron terbaca rendah','What is the effect of gas presence on the density and neutron logs?','a:4:{i:0;s:36:"Density reads low, neutron reads low";i:1;s:38:"Density reads high, neutron reads high";i:2;s:37:"Density reads low, neutron reads high";i:3;s:37:"Density reads high, neutron reads low";}','Density reads low, neutron reads low','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000434','Log resistivitas dangkal (Shallow Resistivity) paling sensitif terhadap apa?','option','PFC000000004','Final Test','a:4:{i:0;s:34:"Zona terinvasi oleh filtrat lumpur";i:1;s:38:"Zona formasi yang jauh dari lubang bor";i:2;s:36:"Zona formasi yang jenuh minyak murni";i:3;s:27:"Zona formasi yang jenuh gas";}','','Zona terinvasi oleh filtrat lumpur','What is the shallow resistivity log most sensitive to?','a:4:{i:0;s:28:"Zone invaded by mud filtrate";i:1;s:36:"Formation zone far from the borehole";i:2;s:38:"Formation zone saturated with pure oil";i:3;s:33:"Formation zone saturated with gas";}','Zone invaded by mud filtrate','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000435','Apa kegunaan utama dari log SP di lapangan?','multi','PFC000000004','Final Test','a:4:{i:0;s:30:"Identifikasi lapisan permeabel";i:1;s:39:"Penentuan resistivitas air formasi (Rw)";i:2;s:23:"Penentuan kandungan gas";i:3;s:20:"Korelasi antar sumur";}','','a:3:{i:0;s:30:"Identifikasi lapisan permeabel";i:1;s:39:"Penentuan resistivitas air formasi (Rw)";i:2;s:20:"Korelasi antar sumur";}','What are the primary uses of the SP log in the field?','a:4:{i:0;s:32:"Identification of permeable beds";i:1;s:49:"Determination of formation water resistivity (Rw)";i:2;s:28:"Determination of gas content";i:3;s:24:"Well-to-well correlation";}','a:3:{i:0;s:32:"Identification of permeable beds";i:1;s:49:"Determination of formation water resistivity (Rw)";i:2;s:24:"Well-to-well correlation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000436','Manakah pernyataan yang benar mengenai pengaruh mud cake pada log?','option','PFC000000004','Final Test','a:4:{i:0;s:65:"Dapat menyebabkan pembacaan log resistivitas menjadi tidak akurat";i:1;s:42:"Tidak memengaruhi alat logging sama sekali";i:2;s:31:"Hanya memengaruhi log gamma ray";i:3;s:29:"Hanya memengaruhi log neutron";}','','Dapat menyebabkan pembacaan log resistivitas menjadi tidak akurat','Which statement is correct regarding the effect of mud cake on logs?','a:4:{i:0;s:51:"Can cause resistivity log readings to be inaccurate";i:1;s:36:"Does not affect logging tools at all";i:2;s:27:"Only affects gamma ray logs";i:3;s:25:"Only affects neutron logs";}','Can cause resistivity log readings to be inaccurate','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000437','Dalam kondisi lubang bor yang tidak stabil (washout), apa yang terjadi pada pembacaan log densitas?','option','PFC000000004','Final Test','a:4:{i:0;s:60:"Pembacaan densitas menjadi lebih rendah dari yang sebenarnya";i:1;s:60:"Pembacaan densitas menjadi lebih tinggi dari yang sebenarnya";i:2;s:42:"Tidak ada pengaruh pada pembacaan densitas";i:3;s:30:"Pembacaan densitas menjadi nol";}','','Pembacaan densitas menjadi lebih rendah dari yang sebenarnya','In unstable borehole conditions (washout), what happens to the density log reading?','a:4:{i:0;s:51:"Density reading becomes lower than the actual value";i:1;s:52:"Density reading becomes higher than the actual value";i:2;s:28:"No effect on density reading";i:3;s:28:"Density reading becomes zero";}','Density reading becomes lower than the actual value','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000438','Log apa yang paling baik untuk mendeteksi mineral evaporit seperti halit?','option','PFC000000004','Final Test','a:4:{i:0;s:20:"Log densitas-neutron";i:1;s:13:"Log gamma ray";i:2;s:16:"Log resistivitas";i:3;s:6:"Log SP";}','','Log densitas-neutron','Which log is best for detecting evaporite minerals like halite?','a:4:{i:0;s:19:"Density-neutron log";i:1;s:13:"Gamma ray log";i:2;s:15:"Resistivity log";i:3;s:6:"SP log";}','Density-neutron log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000439','Apa tujuan dari melakukan ''environmental correction'' pada data log wireline?','option','PFC000000004','Final Test','a:4:{i:0;s:58:"Menghilangkan pengaruh kondisi lubang bor dari data mentah";i:1;s:35:"Meningkatkan resolusi vertikal alat";i:2;s:29:"Mengubah jenis fluida formasi";i:3;s:33:"Menambah kedalaman penetrasi alat";}','','Menghilangkan pengaruh kondisi lubang bor dari data mentah','What is the purpose of performing ''environmental correction'' on wireline log data?','a:4:{i:0;s:57:"To remove the effect of borehole conditions from raw data";i:1;s:47:"To increase the vertical resolution of the tool";i:2;s:34:"To change the formation fluid type";i:3;s:43:"To increase the tool''s depth of penetration";}','To remove the effect of borehole conditions from raw data','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000440','Parameter utama yang diperlukan dalam persamaan Archie untuk menghitung saturasi air (Sw) pada reservoir clean sand adalah','option','PFC000000005','Final Test','a:4:{i:0;s:58:"Porositas, eksponen saturasi (n), dan faktor sementasi (m)";i:1;s:33:"Salinitas lumpur dan suhu formasi";i:2;s:33:"Densitas batuan dan permeabilitas";i:3;s:39:"Tekanan reservoir dan viskositas minyak";}','','Porositas, eksponen saturasi (n), dan faktor sementasi (m)','The main parameters required in the Archie equation to calculate water saturation (Sw) in a clean sand reservoir are','a:4:{i:0;s:61:"Porosity, saturation exponent (n), and cementation factor (m)";i:1;s:38:"Mud salinity and formation temperature";i:2;s:29:"Rock density and permeability";i:3;s:36:"Reservoir pressure and oil viscosity";}','Porosity, saturation exponent (n), and cementation factor (m)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000441','Metode apa yang paling umum digunakan untuk menghitung volume shale (Vsh) dari log Gamma Ray?','option','PFC000000005','Final Test','a:4:{i:0;s:22:"Indeks Gamma Ray (Igr)";i:1;s:25:"Analisis log resistivitas";i:2;s:34:"Metode cross-plot densitas-neutron";i:3;s:24:"Analisis porositas sonic";}','','Indeks Gamma Ray (Igr)','What is the most common method used to calculate shale volume (Vsh) from the Gamma Ray log?','a:4:{i:0;s:21:"Gamma Ray Index (Igr)";i:1;s:24:"Resistivity log analysis";i:2;s:33:"Density-neutron cross-plot method";i:3;s:23:"Sonic porosity analysis";}','Gamma Ray Index (Igr)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000442','Faktor apa saja yang menyebabkan nilai porositas dari log densitas (PHID) menjadi lebih besar dari porositas sebenarnya?','multi','PFC000000005','Final Test','a:4:{i:0;s:37:"Adanya gas pada zona dekat lubang bor";i:1;s:29:"Kehadiran shale dalam matriks";i:2;s:27:"Kompaksi batuan yang tinggi";i:3;s:34:"Penebalan mud cake yang berlebihan";}','','a:2:{i:0;s:37:"Adanya gas pada zona dekat lubang bor";i:1;s:29:"Kehadiran shale dalam matriks";}','What factors cause the density log porosity (PHID) value to be larger than the actual porosity?','a:4:{i:0;s:41:"Presence of gas in the near-wellbore zone";i:1;s:31:"Presence of shale in the matrix";i:2;s:20:"High rock compaction";i:3;s:28:"Excessive mud cake thickness";}','a:2:{i:0;s:41:"Presence of gas in the near-wellbore zone";i:1;s:31:"Presence of shale in the matrix";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000443','Apa fungsi utama dari penentuan cut-off dalam evaluasi formasi?','option','PFC000000005','Final Test','a:4:{i:0;s:53:"Membedakan zona reservoir produktif dan non-produktif";i:1;s:26:"Menghitung tekanan kapiler";i:2;s:28:"Menentukan viskositas fluida";i:3;s:27:"Mengkalibrasi kedalaman log";}','','Membedakan zona reservoir produktif dan non-produktif','What is the main function of determining cut-offs in formation evaluation?','a:4:{i:0;s:61:"Differentiating productive and non-productive reservoir zones";i:1;s:30:"Calculating capillary pressure";i:2;s:27:"Determining fluid viscosity";i:3;s:21:"Calibrating log depth";}','Differentiating productive and non-productive reservoir zones','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000444','Dalam evaluasi net pay, kriteria cut-off yang umum digunakan meliputi','multi','PFC000000005','Final Test','a:4:{i:0;s:18:"Volume shale (Vsh)";i:1;s:15:"Porositas (phi)";i:2;s:17:"Saturasi air (Sw)";i:3;s:21:"Permeabilitas absolut";}','','a:3:{i:0;s:18:"Volume shale (Vsh)";i:1;s:15:"Porositas (phi)";i:2;s:17:"Saturasi air (Sw)";}','In net pay evaluation, common cut-off criteria include','a:4:{i:0;s:18:"Shale volume (Vsh)";i:1;s:14:"Porosity (phi)";i:2;s:21:"Water saturation (Sw)";i:3;s:21:"Absolute permeability";}','a:3:{i:0;s:18:"Shale volume (Vsh)";i:1;s:14:"Porosity (phi)";i:2;s:21:"Water saturation (Sw)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000445','Apa arti dari terminologi ''Net-to-Gross'' dalam zonasi reservoir?','option','PFC000000005','Final Test','a:4:{i:0;s:68:"Rasio ketebalan reservoir produktif terhadap total ketebalan formasi";i:1;s:39:"Rasio volume air terhadap volume minyak";i:2;s:48:"Rasio porositas efektif terhadap porositas total";i:3;s:26:"Rasio shale terhadap pasir";}','','Rasio ketebalan reservoir produktif terhadap total ketebalan formasi','What does the term ''Net-to-Gross'' mean in reservoir zonation?','a:4:{i:0;s:68:"Ratio of productive reservoir thickness to total formation thickness";i:1;s:35:"Ratio of water volume to oil volume";i:2;s:45:"Ratio of effective porosity to total porosity";i:3;s:22:"Ratio of shale to sand";}','Ratio of productive reservoir thickness to total formation thickness','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000446','Persamaan Archie (Sw^n = (a * Rw) / (phi^m * Rt)) mengasumsikan bahwa batuan bersifat','option','PFC000000005','Final Test','a:4:{i:0;s:22:"Clean sand (non-shaly)";i:1;s:10:"Shaly sand";i:2;s:31:"Karbonat dengan porositas vuggy";i:3;s:14:"Batuan igneous";}','','Clean sand (non-shaly)','The Archie equation (Sw^n = (a * Rw) / (phi^m * Rt)) assumes that the rock is','a:4:{i:0;s:22:"Clean sand (non-shaly)";i:1;s:10:"Shaly sand";i:2;s:29:"Carbonate with vuggy porosity";i:3;s:12:"Igneous rock";}','Clean sand (non-shaly)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000447','Porositas efektif didefinisikan sebagai','option','PFC000000005','Final Test','a:4:{i:0;s:74:"Porositas yang saling berhubungan dan berkontribusi terhadap aliran fluida";i:1;s:29:"Total ruang pori dalam batuan";i:2;s:35:"Porositas yang terisi oleh air saja";i:3;s:41:"Porositas yang diukur oleh log sonic saja";}','','Porositas yang saling berhubungan dan berkontribusi terhadap aliran fluida','Effective porosity is defined as','a:4:{i:0;s:61:"Porosity that is interconnected and contributes to fluid flow";i:1;s:28:"Total pore space in the rock";i:2;s:29:"Porosity filled only by water";i:3;s:35:"Porosity measured only by sonic log";}','Porosity that is interconnected and contributes to fluid flow','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000448','Log apa yang paling efektif untuk mendeteksi keberadaan shale (lempung) dalam formasi?','option','PFC000000005','Final Test','a:4:{i:0;s:13:"Log Gamma Ray";i:1;s:12:"Log Densitas";i:2;s:16:"Log Resistivitas";i:3;s:18:"Log Self-Potential";}','','Log Gamma Ray','Which log is most effective for detecting the presence of shale in a formation?','a:4:{i:0;s:13:"Gamma Ray log";i:1;s:11:"Density log";i:2;s:15:"Resistivity log";i:3;s:18:"Self-Potential log";}','Gamma Ray log','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000449','Nilai faktor sementasi (m) dalam persamaan Archie pada batuan pasir terkonsolidasi biasanya bernilai','option','PFC000000005','Final Test','a:4:{i:0;s:1:"2";i:1;s:1:"1";i:2;s:1:"3";i:3;s:3:"0.5";}','','2','The cementation factor (m) value in the Archie equation for consolidated sandstones is typically','a:4:{i:0;s:1:"2";i:1;s:1:"1";i:2;s:1:"3";i:3;s:3:"0.5";}','2','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000450','Apa dampak kehadiran shale terhadap resistivitas batuan?','option','PFC000000005','Final Test','a:4:{i:0;s:23:"Menurunkan resistivitas";i:1;s:25:"Meningkatkan resistivitas";i:2;s:17:"Tidak berpengaruh";i:3;s:42:"Membuat resistivitas menjadi tak terhingga";}','','Menurunkan resistivitas','What is the impact of shale presence on rock resistivity?','a:4:{i:0;s:21:"Decreases resistivity";i:1;s:21:"Increases resistivity";i:2;s:9:"No effect";i:3;s:26:"Makes resistivity infinite";}','Decreases resistivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000451','Manakah yang benar mengenai hubungan antara log porositas neutron dan densitas?','option','PFC000000005','Final Test','a:4:{i:0;s:55:"Dapat digunakan untuk mengidentifikasi litologi dan gas";i:1;s:25:"Hanya mengukur volume air";i:2;s:28:"Tidak dipengaruhi oleh shale";i:3;s:33:"Hanya akurat pada batuan karbonat";}','','Dapat digunakan untuk mengidentifikasi litologi dan gas','Which of the following is true regarding the relationship between neutron and density porosity logs?','a:4:{i:0;s:41:"Can be used to identify lithology and gas";i:1;s:26:"Only measures water volume";i:2;s:24:"Is not affected by shale";i:3;s:32:"Only accurate in carbonate rocks";}','Can be used to identify lithology and gas','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000452','Dalam interpretasi petrofisika, Rw adalah singkatan dari','option','PFC000000005','Final Test','a:4:{i:0;s:24:"Resistivitas air formasi";i:1;s:22:"Resistivitas reservoir";i:2;s:19:"Resistivitas batuan";i:3;s:19:"Resistivitas lumpur";}','','Resistivitas air formasi','In petrophysical interpretation, Rw stands for','a:4:{i:0;s:27:"Formation water resistivity";i:1;s:21:"Reservoir resistivity";i:2;s:16:"Rock resistivity";i:3;s:15:"Mud resistivity";}','Formation water resistivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000453','Pilih dua metode utama untuk menghitung porositas dari log','multi','PFC000000005','Final Test','a:4:{i:0;s:12:"Log Densitas";i:1;s:11:"Log Neutron";i:2;s:13:"Log Gamma Ray";i:3;s:6:"Log SP";}','','a:2:{i:0;s:12:"Log Densitas";i:1;s:11:"Log Neutron";}','Choose two main methods to calculate porosity from logs','a:4:{i:0;s:11:"Density Log";i:1;s:11:"Neutron Log";i:2;s:13:"Gamma Ray Log";i:3;s:6:"SP Log";}','a:2:{i:0;s:11:"Density Log";i:1;s:11:"Neutron Log";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000454','Apa yang dimaksud dengan zona ''pay''?','option','PFC000000005','Final Test','a:4:{i:0;s:67:"Bagian reservoir yang mampu mengalirkan hidrokarbon secara ekonomis";i:1;s:34:"Zona yang tidak memiliki porositas";i:2;s:26:"Zona yang hanya berisi air";i:3;s:29:"Zona dengan permeabilitas nol";}','','Bagian reservoir yang mampu mengalirkan hidrokarbon secara ekonomis','What is meant by a ''pay'' zone?','a:4:{i:0;s:70:"The part of a reservoir capable of producing hydrocarbons economically";i:1;s:23:"A zone with no porosity";i:2;s:31:"A zone that contains only water";i:3;s:29:"A zone with zero permeability";}','The part of a reservoir capable of producing hydrocarbons economically','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000455','Kenaikan saturasi air (Sw) dalam suatu zona reservoir umumnya mengindikasikan','option','PFC000000005','Final Test','a:4:{i:0;s:38:"Potensi produksi air yang lebih tinggi";i:1;s:27:"Peningkatan cadangan minyak";i:2;s:26:"Batuan menjadi lebih padat";i:3;s:22:"Penurunan volume shale";}','','Potensi produksi air yang lebih tinggi','An increase in water saturation (Sw) in a reservoir zone generally indicates','a:4:{i:0;s:37:"Higher potential for water production";i:1;s:22:"Increased oil reserves";i:2;s:20:"Rock becoming denser";i:3;s:24:"Decrease in shale volume";}','Higher potential for water production','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000456','Analisis zonasi reservoir dilakukan untuk','option','PFC000000005','Final Test','a:4:{i:0;s:81:"Membagi reservoir menjadi unit-unit dengan karakteristik petrofisika yang seragam";i:1;s:33:"Menentukan lokasi pengeboran baru";i:2;s:28:"Menghitung biaya operasional";i:3;s:25:"Menganalisis jenis minyak";}','','Membagi reservoir menjadi unit-unit dengan karakteristik petrofisika yang seragam','Reservoir zonation analysis is performed to','a:4:{i:0;s:74:"Divide the reservoir into units with uniform petrophysical characteristics";i:1;s:32:"Determine new drilling locations";i:2;s:27:"Calculate operational costs";i:3;s:17:"Analyze oil types";}','Divide the reservoir into units with uniform petrophysical characteristics','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000457','Jika nilai Gamma Ray (GR) rendah pada suatu zona, interpretasi litologi yang paling mungkin adalah','option','PFC000000005','Final Test','a:4:{i:0;s:25:"Pasir bersih (clean sand)";i:1;s:5:"Shale";i:2;s:8:"Batubara";i:3;s:15:"Batuan evaporit";}','','Pasir bersih (clean sand)','If the Gamma Ray (GR) value is low in a zone, the most likely lithology interpretation is','a:4:{i:0;s:10:"Clean sand";i:1;s:5:"Shale";i:2;s:4:"Coal";i:3;s:14:"Evaporite rock";}','Clean sand','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000458','Eksponen saturasi (n) dalam persamaan Archie biasanya dianggap bernilai','option','PFC000000005','Final Test','a:4:{i:0;s:1:"2";i:1;s:1:"1";i:2;s:3:"0.5";i:3;s:1:"4";}','','2','The saturation exponent (n) in the Archie equation is typically assumed to be','a:4:{i:0;s:1:"2";i:1;s:1:"1";i:2;s:3:"0.5";i:3;s:1:"4";}','2','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000459','Mengapa kita perlu menghitung volume shale dalam evaluasi reservoir?','multi','PFC000000005','Final Test','a:4:{i:0;s:47:"Karena shale mempengaruhi perhitungan porositas";i:1;s:50:"Karena shale mempengaruhi perhitungan saturasi air";i:2;s:42:"Karena shale selalu mengandung hidrokarbon";i:3;s:39:"Karena shale meningkatkan permeabilitas";}','','a:2:{i:0;s:47:"Karena shale mempengaruhi perhitungan porositas";i:1;s:50:"Karena shale mempengaruhi perhitungan saturasi air";}','Why do we need to calculate shale volume in reservoir evaluation?','a:4:{i:0;s:43:"Because shale affects porosity calculations";i:1;s:51:"Because shale affects water saturation calculations";i:2;s:42:"Because shale always contains hydrocarbons";i:3;s:36:"Because shale increases permeability";}','a:2:{i:0;s:43:"Because shale affects porosity calculations";i:1;s:51:"Because shale affects water saturation calculations";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000460','Apakah definisi dari tekanan kapiler dalam sistem media berpori?','option','PFC000000006','Final Test','a:4:{i:0;s:53:"Perbedaan tekanan antara fase non-wetting dan wetting";i:1;s:53:"Tekanan yang diberikan oleh fluida di dalam reservoir";i:2;s:29:"Tekanan hidrostatik kolom air";i:3;s:42:"Tekanan balik dari formasi saat pengeboran";}','','Perbedaan tekanan antara fase non-wetting dan wetting','What is the definition of capillary pressure in a porous media system?','a:4:{i:0;s:58:"Difference between non-wetting and wetting phase pressures";i:1;s:43:"Pressure exerted by fluids in the reservoir";i:2;s:40:"Hydrostatic pressure of the water column";i:3;s:48:"Back pressure from the formation during drilling";}','Difference between non-wetting and wetting phase pressures','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000461','Metode manakah yang paling umum digunakan untuk mengukur kurva tekanan kapiler di laboratorium?','option','PFC000000006','Final Test','a:4:{i:0;s:17:"Mercury Injection";i:1;s:10:"Centrifuge";i:2;s:12:"Porous Plate";i:3;s:19:"Semua jawaban benar";}','','Semua jawaban benar','Which method is most commonly used to measure capillary pressure curves in the laboratory?','a:4:{i:0;s:17:"Mercury Injection";i:1;s:10:"Centrifuge";i:2;s:12:"Porous Plate";i:3;s:16:"All of the above";}','All of the above','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000462','Faktor apa saja yang mempengaruhi besarnya tekanan kapiler?','multi','PFC000000006','Final Test','a:4:{i:0;s:41:"Tegangan antar muka (interfacial tension)";i:1;s:28:"Sudut kontak (contact angle)";i:2;s:21:"Permeabilitas absolut";i:3;s:16:"Porositas batuan";}','','a:2:{i:0;s:41:"Tegangan antar muka (interfacial tension)";i:1;s:28:"Sudut kontak (contact angle)";}','Which factors influence the magnitude of capillary pressure?','a:4:{i:0;s:19:"Interfacial tension";i:1;s:13:"Contact angle";i:2;s:21:"Absolute permeability";i:3;s:13:"Rock porosity";}','a:2:{i:0;s:19:"Interfacial tension";i:1;s:13:"Contact angle";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000463','Apa yang dimaksud dengan Irreducible Water Saturation (Swi)?','option','PFC000000006','Final Test','a:4:{i:0;s:41:"Saturasi air maksimum yang dapat bergerak";i:1;s:70:"Saturasi air di mana air tidak lagi dapat mengalir karena gaya kapiler";i:2;s:41:"Saturasi air pada saat batuan jenuh total";i:3;s:44:"Saturasi air saat terjadi water breakthrough";}','','Saturasi air di mana air tidak lagi dapat mengalir karena gaya kapiler','What is meant by Irreducible Water Saturation (Swi)?','a:4:{i:0;s:38:"Maximum water saturation that can flow";i:1;s:71:"Water saturation where water can no longer flow due to capillary forces";i:2;s:49:"Water saturation when the rock is fully saturated";i:3;s:38:"Water saturation at water breakthrough";}','Water saturation where water can no longer flow due to capillary forces','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000464','Bagaimana hubungan antara ukuran pori dan tekanan kapiler pada batuan reservoir?','option','PFC000000006','Final Test','a:4:{i:0;s:57:"Semakin kecil ukuran pori, semakin tinggi tekanan kapiler";i:1;s:57:"Semakin besar ukuran pori, semakin tinggi tekanan kapiler";i:2;s:46:"Ukuran pori tidak mempengaruhi tekanan kapiler";i:3;s:53:"Tekanan kapiler berbanding lurus dengan diameter pori";}','','Semakin kecil ukuran pori, semakin tinggi tekanan kapiler','What is the relationship between pore size and capillary pressure in reservoir rocks?','a:4:{i:0;s:60:"The smaller the pore size, the higher the capillary pressure";i:1;s:59:"The larger the pore size, the higher the capillary pressure";i:2;s:44:"Pore size does not affect capillary pressure";i:3;s:60:"Capillary pressure is directly proportional to pore diameter";}','The smaller the pore size, the higher the capillary pressure','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000465','Apa yang terjadi pada kurva tekanan kapiler jika batuan bersifat oil-wet?','option','PFC000000006','Final Test','a:4:{i:0;s:31:"Tekanan kapiler menjadi negatif";i:1;s:27:"Tekanan kapiler menjadi nol";i:2;s:33:"Tekanan kapiler meningkat drastis";i:3;s:30:"Tidak ada perubahan pada kurva";}','','Tekanan kapiler menjadi negatif','What happens to the capillary pressure curve if the rock is oil-wet?','a:4:{i:0;s:35:"Capillary pressure becomes negative";i:1;s:31:"Capillary pressure becomes zero";i:2;s:40:"Capillary pressure increases drastically";i:3;s:22:"No change in the curve";}','Capillary pressure becomes negative','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000466','Permeabilitas relatif (kr) adalah rasio antara:','option','PFC000000006','Final Test','a:4:{i:0;s:57:"Permeabilitas efektif fase terhadap permeabilitas absolut";i:1;s:40:"Permeabilitas absolut terhadap porositas";i:2;s:45:"Permeabilitas fase terhadap viskositas fluida";i:3;s:55:"Permeabilitas dua fase terhadap permeabilitas satu fase";}','','Permeabilitas efektif fase terhadap permeabilitas absolut','Relative permeability (kr) is the ratio of:','a:4:{i:0;s:53:"Effective phase permeability to absolute permeability";i:1;s:33:"Absolute permeability to porosity";i:2;s:37:"Phase permeability to fluid viscosity";i:3;s:51:"Two-phase permeability to single-phase permeability";}','Effective phase permeability to absolute permeability','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000467','Apa syarat terjadinya aliran steady-state dalam pengukuran permeabilitas relatif?','option','PFC000000006','Final Test','a:4:{i:0;s:45:"Laju alir fluida konstan dan saturasi konstan";i:1;s:35:"Tekanan berubah-ubah secara drastis";i:2;s:31:"Hanya satu fluida yang mengalir";i:3;s:36:"Saturasi terus berubah seiring waktu";}','','Laju alir fluida konstan dan saturasi konstan','What is the condition for steady-state flow in relative permeability measurement?','a:4:{i:0;s:48:"Constant fluid flow rate and constant saturation";i:1;s:28:"Pressure changes drastically";i:2;s:25:"Only one fluid is flowing";i:3;s:28:"Saturation changes over time";}','Constant fluid flow rate and constant saturation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000468','Pada titik crossover dari kurva permeabilitas relatif (krw = kro), apa yang biasanya terjadi?','option','PFC000000006','Final Test','a:4:{i:0;s:46:"Saturasi air lebih besar dari 50% jika oil-wet";i:1;s:48:"Saturasi air lebih besar dari 50% jika water-wet";i:2;s:23:"Saturasi air selalu 50%";i:3;s:30:"Saturasi air tidak berpengaruh";}','','Saturasi air lebih besar dari 50% jika oil-wet','At the crossover point of the relative permeability curve (krw = kro), what usually occurs?','a:4:{i:0;s:47:"Water saturation is greater than 50% if oil-wet";i:1;s:49:"Water saturation is greater than 50% if water-wet";i:2;s:30:"Water saturation is always 50%";i:3;s:30:"Water saturation has no effect";}','Water saturation is greater than 50% if oil-wet','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000469','Fenomena hysteresis pada kurva tekanan kapiler terjadi karena:','option','PFC000000006','Final Test','a:4:{i:0;s:38:"Perbedaan proses imbibisi dan drainase";i:1;s:40:"Kondisi temperatur reservoir yang tinggi";i:2;s:35:"Komposisi kimia fluida yang berubah";i:3;s:23:"Ketidakhomogenan batuan";}','','Perbedaan proses imbibisi dan drainase','Hysteresis phenomenon in capillary pressure curves occurs due to:','a:4:{i:0;s:52:"Difference between imbibition and drainage processes";i:1;s:37:"High reservoir temperature conditions";i:2;s:35:"Changing fluid chemical composition";i:3;s:18:"Rock heterogeneity";}','Difference between imbibition and drainage processes','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000470','Apa yang dimaksud dengan proses drainase pada tekanan kapiler?','option','PFC000000006','Final Test','a:4:{i:0;s:42:"Fase non-wetting menggantikan fase wetting";i:1;s:42:"Fase wetting menggantikan fase non-wetting";i:2;s:33:"Fase air menggantikan fase minyak";i:3;s:35:"Aliran fluida tanpa tekanan kapiler";}','','Fase non-wetting menggantikan fase wetting','What is meant by the drainage process in capillary pressure?','a:4:{i:0;s:40:"Non-wetting phase replaces wetting phase";i:1;s:40:"Wetting phase replaces non-wetting phase";i:2;s:30:"Water phase replaces oil phase";i:3;s:37:"Fluid flow without capillary pressure";}','Non-wetting phase replaces wetting phase','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000471','Manakah pernyataan yang benar mengenai wettability batuan?','multi','PFC000000006','Final Test','a:4:{i:0;s:44:"Water-wet memiliki sudut kontak < 90 derajat";i:1;s:42:"Oil-wet memiliki sudut kontak > 90 derajat";i:2;s:52:"Wettability tidak mempengaruhi permeabilitas relatif";i:3;s:59:"Intermediate-wet memiliki sudut kontak mendekati 90 derajat";}','','a:3:{i:0;s:44:"Water-wet memiliki sudut kontak < 90 derajat";i:1;s:42:"Oil-wet memiliki sudut kontak > 90 derajat";i:2;s:59:"Intermediate-wet memiliki sudut kontak mendekati 90 derajat";}','Which statements are true regarding rock wettability?','a:4:{i:0;s:40:"Water-wet has contact angle < 90 degrees";i:1;s:38:"Oil-wet has contact angle > 90 degrees";i:2;s:49:"Wettability does not affect relative permeability";i:3;s:50:"Intermediate-wet has contact angle near 90 degrees";}','a:3:{i:0;s:40:"Water-wet has contact angle < 90 degrees";i:1;s:38:"Oil-wet has contact angle > 90 degrees";i:2;s:50:"Intermediate-wet has contact angle near 90 degrees";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000472','Pada sistem tiga fase (minyak, air, gas), permeabilitas relatif gas (krg) umumnya bergantung pada:','option','PFC000000006','Final Test','a:4:{i:0;s:32:"Saturasi gas dan saturasi minyak";i:1;s:18:"Hanya saturasi gas";i:2;s:18:"Hanya saturasi air";i:3;s:18:"Tekanan overburden";}','','Saturasi gas dan saturasi minyak','In a three-phase system (oil, water, gas), the relative permeability of gas (krg) generally depends on:','a:4:{i:0;s:33:"Gas saturation and oil saturation";i:1;s:19:"Only gas saturation";i:2;s:21:"Only water saturation";i:3;s:19:"Overburden pressure";}','Gas saturation and oil saturation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000473','Apa dampak utama dari peningkatan tegangan antar muka terhadap perolehan minyak?','option','PFC000000006','Final Test','a:4:{i:0;s:50:"Menurunkan perolehan minyak karena jebakan kapiler";i:1;s:29:"Meningkatkan perolehan minyak";i:2;s:39:"Tidak berpengaruh pada perolehan minyak";i:3;s:25:"Mempercepat laju alir air";}','','Menurunkan perolehan minyak karena jebakan kapiler','What is the main impact of increased interfacial tension on oil recovery?','a:4:{i:0;s:48:"Decreases oil recovery due to capillary trapping";i:1;s:22:"Increases oil recovery";i:2;s:25:"No effect on oil recovery";i:3;s:25:"Speeds up water flow rate";}','Decreases oil recovery due to capillary trapping','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000474','Metode mercury injection adalah jenis tes:','option','PFC000000006','Final Test','a:4:{i:0;s:8:"Drainase";i:1;s:8:"Imbibisi";i:2;s:22:"Spontaneous imbibition";i:3;s:17:"Steady-state flow";}','','Drainase','The mercury injection method is a type of:','a:4:{i:0;s:8:"Drainage";i:1;s:10:"Imbibition";i:2;s:22:"Spontaneous imbibition";i:3;s:17:"Steady-state flow";}','Drainage','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000475','Mengapa kurva permeabilitas relatif penting dalam simulasi reservoir?','option','PFC000000006','Final Test','a:4:{i:0;s:44:"Untuk memprediksi perilaku aliran multi-fase";i:1;s:35:"Untuk menghitung tekanan overburden";i:2;s:33:"Untuk menentukan porositas batuan";i:3;s:30:"Untuk mengukur densitas minyak";}','','Untuk memprediksi perilaku aliran multi-fase','Why are relative permeability curves important in reservoir simulation?','a:4:{i:0;s:36:"To predict multi-phase flow behavior";i:1;s:32:"To calculate overburden pressure";i:2;s:26:"To determine rock porosity";i:3;s:22:"To measure oil density";}','To predict multi-phase flow behavior','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000476','Faktor apa yang menyebabkan harga krw (permeabilitas relatif air) mencapai nilai maksimal?','option','PFC000000006','Final Test','a:4:{i:0;s:40:"Saturasi air mendekati 100% (atau 1-Sor)";i:1;s:25:"Saturasi air mendekati 0%";i:2;s:29:"Tekanan kapiler sangat tinggi";i:3;s:25:"Permeabilitas absolut nol";}','','Saturasi air mendekati 100% (atau 1-Sor)','What factor causes the krw (relative water permeability) value to reach its maximum?','a:4:{i:0;s:43:"Water saturation approaches 100% (or 1-Sor)";i:1;s:30:"Water saturation approaches 0%";i:2;s:28:"Very high capillary pressure";i:3;s:26:"Zero absolute permeability";}','Water saturation approaches 100% (or 1-Sor)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000477','Dalam konteks reservoir, apa arti dari ''Water-wet''?','option','PFC000000006','Final Test','a:4:{i:0;s:41:"Batuan lebih menyukai air daripada minyak";i:1;s:41:"Batuan lebih menyukai minyak daripada air";i:2;s:45:"Permukaan batuan tidak bereaksi dengan fluida";i:3;s:23:"Batuan sangat kedap air";}','','Batuan lebih menyukai air daripada minyak','In the context of reservoirs, what does ''Water-wet'' mean?','a:4:{i:0;s:27:"Rock prefers water over oil";i:1;s:27:"Rock prefers oil over water";i:2;s:39:"Rock surface does not react with fluids";i:3;s:24:"Rock is very water-tight";}','Rock prefers water over oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000478','Manakah yang benar tentang karakteristik kurva permeabilitas relatif pada kondisi water-wet?','option','PFC000000006','Final Test','a:4:{i:0;s:51:"Kurva krw cenderung rendah pada saturasi air rendah";i:1;s:51:"Kurva krw cenderung tinggi pada saturasi air rendah";i:2;s:38:"Kurva kro selalu lebih tinggi dari krw";i:3;s:42:"Tidak ada hubungan antara krw dan saturasi";}','','Kurva krw cenderung rendah pada saturasi air rendah','Which is true about the characteristics of relative permeability curves under water-wet conditions?','a:4:{i:0;s:49:"krw curve tends to be low at low water saturation";i:1;s:50:"krw curve tends to be high at low water saturation";i:2;s:35:"kro curve is always higher than krw";i:3;s:42:"No relationship between krw and saturation";}','krw curve tends to be low at low water saturation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000479','Apa kegunaan utama data tekanan kapiler (Pc) dalam evaluasi formasi?','multi','PFC000000006','Final Test','a:4:{i:0;s:62:"Estimasi saturasi air pada ketinggian di atas free water level";i:1;s:23:"Penentuan zona transisi";i:2;s:33:"Perhitungan permeabilitas absolut";i:3;s:28:"Estimasi tinggi kolom minyak";}','','a:3:{i:0;s:62:"Estimasi saturasi air pada ketinggian di atas free water level";i:1;s:23:"Penentuan zona transisi";i:2;s:28:"Estimasi tinggi kolom minyak";}','What is the primary use of capillary pressure (Pc) data in formation evaluation?','a:4:{i:0;s:53:"Estimation of water saturation above free water level";i:1;s:32:"Determination of transition zone";i:2;s:36:"Calculation of absolute permeability";i:3;s:31:"Estimation of oil column height";}','a:3:{i:0;s:53:"Estimation of water saturation above free water level";i:1;s:32:"Determination of transition zone";i:2;s:31:"Estimation of oil column height";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000480','Parameter utama yang diperlukan untuk menghitung Original Oil In Place (OOIP) secara volumetrik adalah...','multi','PFC000000007','Final Test','a:4:{i:0;s:17:"Porositas efektif";i:1;s:12:"Saturasi air";i:2;s:18:"Volume bulk batuan";i:3;s:15:"Tekanan formasi";}','','a:3:{i:0;s:17:"Porositas efektif";i:1;s:12:"Saturasi air";i:2;s:18:"Volume bulk batuan";}','The main parameters required to calculate Original Oil In Place (OOIP) volumetrically are...','a:4:{i:0;s:18:"Effective porosity";i:1;s:16:"Water saturation";i:2;s:16:"Bulk rock volume";i:3;s:18:"Formation pressure";}','a:3:{i:0;s:18:"Effective porosity";i:1;s:16:"Water saturation";i:2;s:16:"Bulk rock volume";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000481','Apa dampak utama dari keterbatasan data log dalam estimasi volume cadangan?','option','PFC000000007','Final Test','a:4:{i:0;s:49:"Meningkatkan tingkat ketidakpastian (uncertainty)";i:1;s:27:"Mempercepat waktu pelaporan";i:2;s:38:"Menghilangkan kebutuhan akan core data";i:3;s:27:"Mengurangi biaya eksplorasi";}','','Meningkatkan tingkat ketidakpastian (uncertainty)','What is the main impact of limited log data on reserve volume estimation?','a:4:{i:0;s:28:"Increases uncertainty levels";i:1;s:24:"Speeds up reporting time";i:2;s:33:"Eliminates the need for core data";i:3;s:25:"Reduces exploration costs";}','Increases uncertainty levels','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000482','Integrasi data petrofisika dengan model geologi bertujuan untuk...','option','PFC000000007','Final Test','a:4:{i:0;s:49:"Mendefinisikan distribusi heterogenitas reservoir";i:1;s:30:"Menentukan harga minyak mentah";i:2;s:28:"Menggantikan peran geofisika";i:3;s:22:"Mempercepat pengeboran";}','','Mendefinisikan distribusi heterogenitas reservoir','Integrating petrophysical data with geological models aims to...','a:4:{i:0;s:43:"Define reservoir heterogeneity distribution";i:1;s:26:"Determine crude oil prices";i:2;s:30:"Replace the role of geophysics";i:3;s:19:"Accelerate drilling";}','Define reservoir heterogeneity distribution','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000483','Dalam konteks pelaporan cadangan, istilah ''lead time'' merujuk pada...','option','PFC000000007','Final Test','a:4:{i:0;s:45:"Waktu dari penemuan hingga produksi komersial";i:1;s:35:"Waktu yang dibutuhkan untuk logging";i:2;s:35:"Waktu proses pengolahan data mentah";i:3;s:35:"Waktu tunggu hasil uji laboratorium";}','','Waktu dari penemuan hingga produksi komersial','In the context of reserve reporting, the term ''lead time'' refers to...','a:4:{i:0;s:44:"Time from discovery to commercial production";i:1;s:25:"Time required for logging";i:2;s:24:"Raw data processing time";i:3;s:35:"Waiting time for laboratory results";}','Time from discovery to commercial production','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000484','Faktor apa yang dapat menyebabkan kesalahan sistematis dalam estimasi OOIP?','multi','PFC000000007','Final Test','a:4:{i:0;s:45:"Kesalahan penentuan batas kontak fluida (OWC)";i:1;s:39:"Penggunaan parameter m yang tidak tepat";i:2;s:30:"Kualitas lubang bor yang buruk";i:3;s:21:"Kenaikan harga minyak";}','','a:3:{i:0;s:45:"Kesalahan penentuan batas kontak fluida (OWC)";i:1;s:39:"Penggunaan parameter m yang tidak tepat";i:2;s:30:"Kualitas lubang bor yang buruk";}','What factors can cause systematic errors in OOIP estimation?','a:4:{i:0;s:42:"Error in fluid contact determination (OWC)";i:1;s:27:"Incorrect m parameter usage";i:2;s:21:"Poor borehole quality";i:3;s:18:"Rise in oil prices";}','a:3:{i:0;s:42:"Error in fluid contact determination (OWC)";i:1;s:27:"Incorrect m parameter usage";i:2;s:21:"Poor borehole quality";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000485','Mengapa korelasi data inti (core) sangat penting dalam estimasi petrofisika?','option','PFC000000007','Final Test','a:4:{i:0;s:35:"Untuk kalibrasi parameter model log";i:1;s:34:"Untuk menghitung biaya operasional";i:2;s:27:"Untuk menentukan lokasi rig";i:3;s:32:"Untuk estimasi viskositas minyak";}','','Untuk kalibrasi parameter model log','Why is core data correlation crucial in petrophysical estimation?','a:4:{i:0;s:33:"To calibrate log model parameters";i:1;s:30:"To calculate operational costs";i:2;s:25:"To determine rig location";i:3;s:25:"To estimate oil viscosity";}','To calibrate log model parameters','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000486','Jika saturasi air (Sw) diabaikan dalam perhitungan cadangan, maka estimasi OOIP akan menjadi...','option','PFC000000007','Final Test','a:4:{i:0;s:12:"Overestimasi";i:1;s:13:"Underestimasi";i:2;s:10:"Tetap sama";i:3;s:17:"Tidak terpengaruh";}','','Overestimasi','If water saturation (Sw) is ignored in reserve calculation, the OOIP estimate will be...','a:4:{i:0;s:13:"Overestimated";i:1;s:14:"Underestimated";i:2;s:16:"Remains the same";i:3;s:10:"Unaffected";}','Overestimated','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000487','Apa fungsi utama dari integrasi data petrofisika dalam pengembangan lapangan?','option','PFC000000007','Final Test','a:4:{i:0;s:34:"Optimasi strategi penempatan sumur";i:1;s:25:"Menentukan pajak produksi";i:2;s:37:"Meningkatkan kualitas pipa distribusi";i:3;s:26:"Mengatur jam kerja kru rig";}','','Optimasi strategi penempatan sumur','What is the primary function of integrating petrophysical data in field development?','a:4:{i:0;s:41:"Optimization of well placement strategies";i:1;s:28:"Determining production taxes";i:2;s:35:"Improving distribution pipe quality";i:3;s:33:"Regulating rig crew working hours";}','Optimization of well placement strategies','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000488','Data petrofisika apa yang paling krusial untuk menentukan batas ''Net Pay''?','multi','PFC000000007','Final Test','a:4:{i:0;s:17:"Cut-off porositas";i:1;s:20:"Cut-off saturasi air";i:2;s:12:"Volume shale";i:3;s:20:"Kecepatan pengeboran";}','','a:3:{i:0;s:17:"Cut-off porositas";i:1;s:20:"Cut-off saturasi air";i:2;s:12:"Volume shale";}','Which petrophysical data is most crucial for determining the ''Net Pay'' boundary?','a:4:{i:0;s:16:"Porosity cut-off";i:1;s:24:"Water saturation cut-off";i:2;s:12:"Shale volume";i:3;s:14:"Drilling speed";}','a:3:{i:0;s:16:"Porosity cut-off";i:1;s:24:"Water saturation cut-off";i:2;s:12:"Shale volume";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000489','Apa yang dimaksud dengan ''Net-to-Gross'' ratio dalam estimasi volume?','option','PFC000000007','Final Test','a:4:{i:0;s:75:"Perbandingan ketebalan reservoir produktif terhadap total ketebalan formasi";i:1;s:48:"Perbandingan minyak terhadap gas dalam reservoir";i:2;s:45:"Perbandingan porositas terhadap permeabilitas";i:3;s:32:"Perbandingan air terhadap minyak";}','','Perbandingan ketebalan reservoir produktif terhadap total ketebalan formasi','What is meant by the ''Net-to-Gross'' ratio in volume estimation?','a:4:{i:0;s:68:"Ratio of productive reservoir thickness to total formation thickness";i:1;s:36:"Ratio of oil to gas in the reservoir";i:2;s:33:"Ratio of porosity to permeability";i:3;s:21:"Ratio of water to oil";}','Ratio of productive reservoir thickness to total formation thickness','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000490','Bagaimana keterbatasan data petrofisika di zona eksplorasi mempengaruhi pelaporan cadangan?','option','PFC000000007','Final Test','a:4:{i:0;s:66:"Menurunkan klasifikasi cadangan menjadi ''Probable'' atau ''Possible''";i:1;s:32:"Langsung menghentikan pengeboran";i:2;s:33:"Meningkatkan nilai ekonomi proyek";i:3;s:28:"Menyederhanakan model statis";}','','Menurunkan klasifikasi cadangan menjadi ''Probable'' atau ''Possible''','How does limited petrophysical data in exploration zones affect reserve reporting?','a:4:{i:0;s:61:"Downgrades reserve classification to ''Probable'' or ''Possible''";i:1;s:26:"Immediately stops drilling";i:2;s:32:"Increases project economic value";i:3;s:27:"Simplifies the static model";}','Downgrades reserve classification to ''Probable'' or ''Possible''','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000491','Manakah pernyataan yang benar mengenai pengaruh variasi litologi terhadap estimasi volume?','option','PFC000000007','Final Test','a:4:{i:0;s:63:"Perubahan litologi mempengaruhi respon log dan parameter Archie";i:1;s:47:"Litologi tidak berpengaruh pada estimasi volume";i:2;s:47:"Estimasi volume hanya bergantung pada porositas";i:3;s:41:"Litologi hanya dihitung dari data seismik";}','','Perubahan litologi mempengaruhi respon log dan parameter Archie','Which statement is correct regarding the effect of lithology variation on volume estimation?','a:4:{i:0;s:59:"Lithology changes affect log response and Archie parameters";i:1;s:44:"Lithology has no effect on volume estimation";i:2;s:42:"Volume estimation depends only on porosity";i:3;s:46:"Lithology is calculated only from seismic data";}','Lithology changes affect log response and Archie parameters','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000492','Dalam pelaporan cadangan, mengapa audit data petrofisika diperlukan?','option','PFC000000007','Final Test','a:4:{i:0;s:55:"Untuk menjamin akurasi dan kredibilitas volume cadangan";i:1;s:28:"Untuk mengurangi beban pajak";i:2;s:36:"Untuk mempercepat penyusunan laporan";i:3;s:37:"Untuk mengganti tenaga ahli eksternal";}','','Untuk menjamin akurasi dan kredibilitas volume cadangan','In reserve reporting, why is a petrophysical data audit necessary?','a:4:{i:0;s:53:"To ensure accuracy and credibility of reserve volumes";i:1;s:20:"To reduce tax burden";i:2;s:32:"To accelerate report preparation";i:3;s:27:"To replace external experts";}','To ensure accuracy and credibility of reserve volumes','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000493','Apa peran utama log resistivitas dalam aplikasi perhitungan cadangan?','option','PFC000000007','Final Test','a:4:{i:0;s:30:"Membantu estimasi saturasi air";i:1;s:32:"Membantu estimasi volume lempung";i:2;s:32:"Menentukan kedalaman total sumur";i:3;s:33:"Membantu estimasi densitas batuan";}','','Membantu estimasi saturasi air','What is the main role of resistivity logs in reserve calculation applications?','a:4:{i:0;s:38:"Assists in water saturation estimation";i:1;s:34:"Assists in shale volume estimation";i:2;s:27:"Determines total well depth";i:3;s:34:"Assists in rock density estimation";}','Assists in water saturation estimation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000494','Kapan data petrofisika harus diintegrasikan dengan data seismik?','option','PFC000000007','Final Test','a:4:{i:0;s:52:"Saat membangun model statis 3D untuk estimasi volume";i:1;s:31:"Hanya setelah sumur berproduksi";i:2;s:32:"Hanya saat melakukan survei awal";i:3;s:31:"Setelah pelaporan akhir selesai";}','','Saat membangun model statis 3D untuk estimasi volume','When should petrophysical data be integrated with seismic data?','a:4:{i:0;s:53:"When building a 3D static model for volume estimation";i:1;s:36:"Only after the well is in production";i:2;s:40:"Only when conducting preliminary surveys";i:3;s:34:"After final reporting is completed";}','When building a 3D static model for volume estimation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000495','Apa risiko utama jika estimasi OOIP dilakukan tanpa mempertimbangkan heterogenitas reservoir?','option','PFC000000007','Final Test','a:4:{i:0;s:40:"Pola aliran fluida akan salah diprediksi";i:1;s:39:"Biaya operasional menjadi terlalu murah";i:2;s:48:"Tekanan reservoir akan meningkat secara otomatis";i:3;s:33:"Data geologi menjadi lebih akurat";}','','Pola aliran fluida akan salah diprediksi','What is the main risk if OOIP estimation is performed without considering reservoir heterogeneity?','a:4:{i:0;s:49:"Fluid flow patterns will be incorrectly predicted";i:1;s:34:"Operational costs become too cheap";i:2;s:46:"Reservoir pressure will increase automatically";i:3;s:37:"Geological data becomes more accurate";}','Fluid flow patterns will be incorrectly predicted','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000496','Untuk apa ''Formation Factor'' (F) digunakan dalam aplikasi petrofisika?','option','PFC000000007','Final Test','a:4:{i:0;s:50:"Menghubungkan porositas dengan resistivitas batuan";i:1;s:32:"Menghitung permeabilitas absolut";i:2;s:28:"Menentukan viskositas minyak";i:3;s:24:"Mengukur tekanan kapiler";}','','Menghubungkan porositas dengan resistivitas batuan','What is the ''Formation Factor'' (F) used for in petrophysical applications?','a:4:{i:0;s:37:"Relating porosity to rock resistivity";i:1;s:33:"Calculating absolute permeability";i:2;s:25:"Determining oil viscosity";i:3;s:28:"Measuring capillary pressure";}','Relating porosity to rock resistivity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000497','Manakah di antara berikut yang merupakan keterbatasan umum data logging?','multi','PFC000000007','Final Test','a:4:{i:0;s:52:"Kedalaman penyelidikan alat (depth of investigation)";i:1;s:22:"Resolusi vertikal alat";i:2;s:31:"Gangguan dari lumpur pengeboran";i:3;s:24:"Ketersediaan tenaga ahli";}','','a:3:{i:0;s:52:"Kedalaman penyelidikan alat (depth of investigation)";i:1;s:22:"Resolusi vertikal alat";i:2;s:31:"Gangguan dari lumpur pengeboran";}','Which of the following are common limitations of logging data?','a:4:{i:0;s:22:"Depth of investigation";i:1;s:24:"Tool vertical resolution";i:2;s:30:"Interference from drilling mud";i:3;s:19:"Expert availability";}','a:3:{i:0;s:22:"Depth of investigation";i:1;s:24:"Tool vertical resolution";i:2;s:30:"Interference from drilling mud";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000498','Mengapa pengujian laboratorium (core analysis) tetap penting meskipun ada data log canggih?','option','PFC000000007','Final Test','a:4:{i:0;s:53:"Sebagai dasar kalibrasi ''ground truth'' untuk data log";i:1;s:40:"Untuk menggantikan fungsi log sepenuhnya";i:2;s:37:"Untuk mempercantik presentasi laporan";i:3;s:30:"Karena biaya log terlalu murah";}','','Sebagai dasar kalibrasi ''ground truth'' untuk data log','Why is laboratory testing (core analysis) still important despite advanced log data?','a:4:{i:0;s:50:"As a ''ground truth'' calibration basis for log data";i:1;s:33:"To replace log functions entirely";i:2;s:31:"To enhance report presentations";i:3;s:31:"Because log costs are too cheap";}','As a ''ground truth'' calibration basis for log data','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000499','Pelaporan cadangan yang transparan harus mencakup hal berikut...','multi','PFC000000007','Final Test','a:4:{i:0;s:22:"Metodologi perhitungan";i:1;s:19:"Asumsi-asumsi dasar";i:2;s:21:"Analisis sensitivitas";i:3;s:23:"Nama staf pengolah data";}','','a:3:{i:0;s:22:"Metodologi perhitungan";i:1;s:19:"Asumsi-asumsi dasar";i:2;s:21:"Analisis sensitivitas";}','Transparent reserve reporting must include the following...','a:4:{i:0;s:23:"Calculation methodology";i:1;s:17:"Basic assumptions";i:2;s:20:"Sensitivity analysis";i:3;s:27:"Data processing staff names";}','a:3:{i:0;s:23:"Calculation methodology";i:1;s:17:"Basic assumptions";i:2;s:20:"Sensitivity analysis";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000500','Manakah dari tahapan produksi berikut yang mengandalkan energi alami reservoir untuk memproduksikan minyak?','option','PFC000000008','Final Test','a:4:{i:0;s:16:"Primary recovery";i:1;s:18:"Secondary recovery";i:2;s:17:"Tertiary recovery";i:3;s:10:"EOR termal";}','','Primary recovery','Which of the following production stages relies on natural reservoir energy to produce oil?','a:4:{i:0;s:16:"Primary recovery";i:1;s:18:"Secondary recovery";i:2;s:17:"Tertiary recovery";i:3;s:11:"Thermal EOR";}','Primary recovery','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000501','Faktor perolehan minyak (Recovery Factor) dipengaruhi oleh parameter fisik berikut:','multi','PFC000000008','Final Test','a:4:{i:0;s:9:"Porositas";i:1;s:13:"Permeabilitas";i:2;s:17:"Viskositas fluida";i:3;s:15:"Kedalaman sumur";}','','a:3:{i:0;s:9:"Porositas";i:1;s:13:"Permeabilitas";i:2;s:17:"Viskositas fluida";}','Oil recovery factor is influenced by the following physical parameters:','a:4:{i:0;s:8:"Porosity";i:1;s:12:"Permeability";i:2;s:15:"Fluid viscosity";i:3;s:10:"Well depth";}','a:3:{i:0;s:8:"Porosity";i:1;s:12:"Permeability";i:2;s:15:"Fluid viscosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000502','Metode secondary recovery yang paling umum diterapkan di lapangan minyak adalah:','option','PFC000000008','Final Test','a:4:{i:0;s:15:"Injeksi gas CO2";i:1;s:13:"Waterflooding";i:2;s:14:"Steam flooding";i:3;s:15:"Injeksi polimer";}','','Waterflooding','The most common secondary recovery method applied in oil fields is:','a:4:{i:0;s:17:"CO2 gas injection";i:1;s:13:"Waterflooding";i:2;s:14:"Steam flooding";i:3;s:17:"Polymer injection";}','Waterflooding','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000503','Apa tujuan utama dari penerapan metode Enhanced Oil Recovery (EOR)?','option','PFC000000008','Final Test','a:4:{i:0;s:28:"Mengurangi biaya operasional";i:1;s:53:"Meningkatkan perolehan minyak setelah tahap secondary";i:2;s:39:"Mempercepat penurunan tekanan reservoir";i:3;s:36:"Menggantikan penggunaan pompa angguk";}','','Meningkatkan perolehan minyak setelah tahap secondary','What is the main objective of applying Enhanced Oil Recovery (EOR) methods?','a:4:{i:0;s:24:"Reduce operational costs";i:1;s:47:"Increase oil recovery after the secondary stage";i:2;s:37:"Accelerate reservoir pressure decline";i:3;s:24:"Replace sucker rod pumps";}','Increase oil recovery after the secondary stage','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000504','Mekanisme pendorong utama pada tahap primary recovery meliputi:','multi','PFC000000008','Final Test','a:4:{i:0;s:21:"Ekspansi gas terlarut";i:1;s:11:"Water drive";i:2;s:16:"Gravity drainage";i:3;s:11:"Injeksi uap";}','','a:3:{i:0;s:21:"Ekspansi gas terlarut";i:1;s:11:"Water drive";i:2;s:16:"Gravity drainage";}','Primary recovery drive mechanisms include:','a:4:{i:0;s:19:"Dissolved gas drive";i:1;s:11:"Water drive";i:2;s:16:"Gravity drainage";i:3;s:15:"Steam injection";}','a:3:{i:0;s:19:"Dissolved gas drive";i:1;s:11:"Water drive";i:2;s:16:"Gravity drainage";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000505','Metode EOR yang bekerja dengan cara menurunkan interfacial tension (IFT) antara minyak dan air adalah:','option','PFC000000008','Final Test','a:4:{i:0;s:13:"Injeksi steam";i:1;s:30:"Chemical flooding (surfactant)";i:2;s:22:"Injeksi gas immiscible";i:3;s:15:"Injeksi polimer";}','','Chemical flooding (surfactant)','An EOR method that works by reducing the interfacial tension (IFT) between oil and water is:','a:4:{i:0;s:15:"Steam injection";i:1;s:30:"Chemical flooding (surfactant)";i:2;s:24:"Immiscible gas injection";i:3;s:17:"Polymer injection";}','Chemical flooding (surfactant)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000506','Pada metode EOR termal, penurunan viskositas minyak terjadi karena:','option','PFC000000008','Final Test','a:4:{i:0;s:19:"Peningkatan tekanan";i:1;s:22:"Peningkatan temperatur";i:2;s:20:"Penambahan surfaktan";i:3;s:16:"Perubahan pH air";}','','Peningkatan temperatur','In thermal EOR methods, the decrease in oil viscosity occurs due to:','a:4:{i:0;s:17:"Pressure increase";i:1;s:20:"Temperature increase";i:2;s:19:"Surfactant addition";i:3;s:15:"Water pH change";}','Temperature increase','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000507','Apa yang dimaksud dengan residual oil saturation (Sor)?','option','PFC000000008','Final Test','a:4:{i:0;s:40:"Minyak yang tersisa setelah produksi EOR";i:1;s:30:"Minyak awal di dalam reservoir";i:2;s:57:"Minyak yang tidak dapat diproduksi secara teknis/ekonomis";i:3;s:34:"Minyak yang mengalir ke lubang bor";}','','Minyak yang tidak dapat diproduksi secara teknis/ekonomis','What is meant by residual oil saturation (Sor)?','a:4:{i:0;s:34:"Oil remaining after EOR production";i:1;s:28:"Initial oil in the reservoir";i:2;s:52:"Oil that cannot be technically/economically produced";i:3;s:27:"Oil flowing to the wellbore";}','Oil that cannot be technically/economically produced','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000508','Manakah pernyataan yang benar mengenai polymer flooding?','option','PFC000000008','Final Test','a:4:{i:0;s:58:"Menurunkan viskositas air untuk memperbaiki mobility ratio";i:1;s:60:"Meningkatkan viskositas air untuk memperbaiki mobility ratio";i:2;s:32:"Menurunkan IFT secara signifikan";i:3;s:23:"Menguapkan minyak berat";}','','Meningkatkan viskositas air untuk memperbaiki mobility ratio','Which statement is true regarding polymer flooding?','a:4:{i:0;s:49:"Reduces water viscosity to improve mobility ratio";i:1;s:51:"Increases water viscosity to improve mobility ratio";i:2;s:25:"Significantly reduces IFT";i:3;s:19:"Vaporizes heavy oil";}','Increases water viscosity to improve mobility ratio','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000509','Karakteristik reservoir yang tidak mendukung keberhasilan proyek EOR adalah:','option','PFC000000008','Final Test','a:4:{i:0;s:20:"Heterogenitas tinggi";i:1;s:20:"Permeabilitas tinggi";i:2;s:23:"Kontinuitas batuan baik";i:3;s:16:"Porositas tinggi";}','','Heterogenitas tinggi','A reservoir characteristic that does not support the success of an EOR project is:','a:4:{i:0;s:18:"High heterogeneity";i:1;s:17:"High permeability";i:2;s:20:"Good rock continuity";i:3;s:13:"High porosity";}','High heterogeneity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000510','Metode EOR diklasifikasikan berdasarkan mekanisme utamanya menjadi:','multi','PFC000000008','Final Test','a:4:{i:0;s:7:"Thermal";i:1;s:8:"Chemical";i:2;s:12:"Miscible/Gas";i:3;s:7:"Gravity";}','','a:3:{i:0;s:7:"Thermal";i:1;s:8:"Chemical";i:2;s:12:"Miscible/Gas";}','EOR methods are classified based on their main mechanisms into:','a:4:{i:0;s:7:"Thermal";i:1;s:8:"Chemical";i:2;s:12:"Miscible/Gas";i:3;s:7:"Gravity";}','a:3:{i:0;s:7:"Thermal";i:1;s:8:"Chemical";i:2;s:12:"Miscible/Gas";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000511','Tekanan kapiler (Pc) dalam reservoir minyak dipengaruhi oleh:','option','PFC000000008','Final Test','a:4:{i:0;s:53:"Interfacial tension, sudut kontak, dan jari-jari pori";i:1;s:23:"Hanya viskositas minyak";i:2;s:27:"Hanya kecepatan alir fluida";i:3;s:22:"Hanya porositas batuan";}','','Interfacial tension, sudut kontak, dan jari-jari pori','Capillary pressure (Pc) in oil reservoirs is influenced by:','a:4:{i:0;s:51:"Interfacial tension, contact angle, and pore radius";i:1;s:18:"Only oil viscosity";i:2;s:24:"Only fluid flow velocity";i:3;s:18:"Only rock porosity";}','Interfacial tension, contact angle, and pore radius','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000512','Apa dampak negatif dari fenomena fingering pada proses injeksi?','option','PFC000000008','Final Test','a:4:{i:0;s:28:"Peningkatan perolehan minyak";i:1;s:68:"Terobosan (breakthrough) fluida injeksi ke sumur produksi lebih awal";i:2;s:27:"Peningkatan saturasi minyak";i:3;s:24:"Penurunan viskositas air";}','','Terobosan (breakthrough) fluida injeksi ke sumur produksi lebih awal','What is the negative impact of the fingering phenomenon in injection processes?','a:4:{i:0;s:22:"Increased oil recovery";i:1;s:56:"Early breakthrough of injection fluid to production well";i:2;s:24:"Increased oil saturation";i:3;s:25:"Decreased water viscosity";}','Early breakthrough of injection fluid to production well','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000513','Injeksi gas CO2 dapat dikategorikan sebagai:','option','PFC000000008','Final Test','a:4:{i:0;s:16:"Thermal recovery";i:1;s:38:"Miscible atau immiscible gas injection";i:2;s:17:"Chemical recovery";i:3;s:16:"Primary recovery";}','','Miscible atau immiscible gas injection','CO2 gas injection can be categorized as:','a:4:{i:0;s:16:"Thermal recovery";i:1;s:36:"Miscible or immiscible gas injection";i:2;s:17:"Chemical recovery";i:3;s:16:"Primary recovery";}','Miscible or immiscible gas injection','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000514','Faktor perolehan (RF) didefinisikan sebagai:','option','PFC000000008','Final Test','a:4:{i:0;s:71:"Perbandingan minyak yang diproduksi dengan minyak awal di tempat (OOIP)";i:1;s:27:"Laju produksi harian minyak";i:2;s:27:"Volume pori total reservoir";i:3;s:42:"Tekanan reservoir dibagi tekanan permukaan";}','','Perbandingan minyak yang diproduksi dengan minyak awal di tempat (OOIP)','Recovery factor (RF) is defined as:','a:4:{i:0;s:53:"Ratio of produced oil to original oil in place (OOIP)";i:1;s:25:"Daily oil production rate";i:2;s:27:"Total reservoir pore volume";i:3;s:46:"Reservoir pressure divided by surface pressure";}','Ratio of produced oil to original oil in place (OOIP)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000515','Metode EOR mana yang paling efektif untuk minyak berat (heavy oil)?','option','PFC000000008','Final Test','a:4:{i:0;s:16:"Polymer flooding";i:1;s:14:"Steam flooding";i:2;s:19:"Surfactant flooding";i:3;s:13:"Gas injection";}','','Steam flooding','Which EOR method is most effective for heavy oil?','a:4:{i:0;s:16:"Polymer flooding";i:1;s:14:"Steam flooding";i:2;s:19:"Surfactant flooding";i:3;s:13:"Gas injection";}','Steam flooding','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000516','Apa itu mobility ratio (M) dalam konteks pendesakan fluida?','option','PFC000000008','Final Test','a:4:{i:0;s:60:"Rasio mobilitas fluida pendesak terhadap fluida yang didesak";i:1;s:47:"Rasio viskositas minyak terhadap viskositas air";i:2;s:45:"Rasio permeabilitas relatif terhadap saturasi";i:3;s:32:"Rasio tekanan terhadap kedalaman";}','','Rasio mobilitas fluida pendesak terhadap fluida yang didesak','What is the mobility ratio (M) in the context of fluid displacement?','a:4:{i:0;s:62:"Ratio of displacing fluid mobility to displaced fluid mobility";i:1;s:41:"Ratio of oil viscosity to water viscosity";i:2;s:44:"Ratio of relative permeability to saturation";i:3;s:26:"Ratio of pressure to depth";}','Ratio of displacing fluid mobility to displaced fluid mobility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000517','Parameter utama yang diubah oleh surfaktan untuk meningkatkan perolehan minyak adalah:','option','PFC000000008','Final Test','a:4:{i:0;s:14:"Viskositas air";i:1;s:25:"Interfacial tension (IFT)";i:2;s:15:"Densitas batuan";i:3;s:17:"Tekanan reservoir";}','','Interfacial tension (IFT)','The main parameter modified by surfactants to improve oil recovery is:','a:4:{i:0;s:15:"Water viscosity";i:1;s:25:"Interfacial tension (IFT)";i:2;s:12:"Rock density";i:3;s:18:"Reservoir pressure";}','Interfacial tension (IFT)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000518','Kapan waktu yang tepat untuk memulai secondary recovery?','option','PFC000000008','Final Test','a:4:{i:0;s:32:"Segera setelah penemuan lapangan";i:1;s:70:"Saat tekanan reservoir turun di bawah tekanan gelembung (bubble point)";i:2;s:47:"Setelah produksi primer mencapai batas ekonomis";i:3;s:35:"Setelah reservoir kosong sepenuhnya";}','','Setelah produksi primer mencapai batas ekonomis','When is the right time to start secondary recovery?','a:4:{i:0;s:33:"Immediately after field discovery";i:1;s:57:"When reservoir pressure drops below bubble point pressure";i:2;s:47:"After primary production reaches economic limit";i:3;s:39:"After the reservoir is completely empty";}','After primary production reaches economic limit','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000519','Manakah yang termasuk dalam kategori EOR?','multi','PFC000000008','Final Test','a:4:{i:0;s:15:"Injeksi polimer";i:1;s:13:"Waterflooding";i:2;s:11:"Injeksi uap";i:3;s:17:"Injeksi surfaktan";}','','a:3:{i:0;s:15:"Injeksi polimer";i:1;s:11:"Injeksi uap";i:2;s:17:"Injeksi surfaktan";}','Which of the following are categorized as EOR?','a:4:{i:0;s:17:"Polymer injection";i:1;s:13:"Waterflooding";i:2;s:15:"Steam injection";i:3;s:20:"Surfactant injection";}','a:3:{i:0;s:17:"Polymer injection";i:1;s:15:"Steam injection";i:2;s:20:"Surfactant injection";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000520','Apa fungsi utama penambahan polimer ke dalam fluida injeksi pada proses Chemical EOR?','option','PFC000000009','Final Test','a:4:{i:0;s:35:"Meningkatkan viskositas air injeksi";i:1;s:30:"Menurunkan tegangan antar muka";i:2;s:25:"Mengubah kebasahan batuan";i:3;s:34:"Meningkatkan permeabilitas absolut";}','','Meningkatkan viskositas air injeksi','What is the primary function of adding polymer to the injection fluid in a Chemical EOR process?','a:4:{i:0;s:34:"Increase injection water viscosity";i:1;s:26:"Reduce interfacial tension";i:2;s:22:"Alter rock wettability";i:3;s:30:"Increase absolute permeability";}','Increase injection water viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000521','Parameter apa yang secara langsung dipengaruhi oleh penurunan mobilitas air injeksi melalui polimer flooding?','option','PFC000000009','Final Test','a:4:{i:0;s:21:"Permeabilitas relatif";i:1;s:14:"Mobility ratio";i:2;s:16:"Porositas batuan";i:3;s:15:"Tekanan kapiler";}','','Mobility ratio','Which parameter is directly affected by the decrease in injection water mobility through polymer flooding?','a:4:{i:0;s:21:"Relative permeability";i:1;s:14:"Mobility ratio";i:2;s:13:"Rock porosity";i:3;s:18:"Capillary pressure";}','Mobility ratio','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000522','Manakah di antara berikut ini yang merupakan jenis polimer yang umum digunakan dalam aplikasi EOR?','multi','PFC000000009','Final Test','a:4:{i:0;s:4:"HPAM";i:1;s:7:"Xanthan";i:2;s:12:"Asam klorida";i:3;s:17:"Surfaktan anionik";}','','a:2:{i:0;s:4:"HPAM";i:1;s:7:"Xanthan";}','Which of the following are types of polymers commonly used in EOR applications?','a:4:{i:0;s:4:"HPAM";i:1;s:7:"Xanthan";i:2;s:17:"Hydrochloric acid";i:3;s:18:"Anionic surfactant";}','a:2:{i:0;s:4:"HPAM";i:1;s:7:"Xanthan";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000523','Apa kelemahan utama penggunaan HPAM (Hydrolyzed Polyacrylamide) pada kondisi reservoir dengan salinitas tinggi?','option','PFC000000009','Final Test','a:4:{i:0;s:35:"Sensitif terhadap degradasi mekanis";i:1;s:72:"Sensitif terhadap salinitas tinggi yang menyebabkan penurunan viskositas";i:2;s:38:"Sangat mahal dibandingkan polimer lain";i:3;s:26:"Tidak bisa larut dalam air";}','','Sensitif terhadap salinitas tinggi yang menyebabkan penurunan viskositas','What is the main disadvantage of using HPAM (Hydrolyzed Polyacrylamide) in high salinity reservoir conditions?','a:4:{i:0;s:35:"Sensitive to mechanical degradation";i:1;s:49:"Sensitive to high salinity causing viscosity loss";i:2;s:41:"Very expensive compared to other polymers";i:3;s:17:"Not water soluble";}','Sensitive to high salinity causing viscosity loss','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000524','Bagaimana pengaruh peningkatan viskositas air terhadap perolehan minyak (sweep efficiency)?','option','PFC000000009','Final Test','a:4:{i:0;s:51:"Meningkatkan efisiensi penyapuan (sweep efficiency)";i:1;s:30:"Menurunkan efisiensi penyapuan";i:2;s:23:"Tidak memiliki pengaruh";i:3;s:33:"Menyebabkan fingering lebih cepat";}','','Meningkatkan efisiensi penyapuan (sweep efficiency)','How does increasing water viscosity affect oil recovery (sweep efficiency)?','a:4:{i:0;s:26:"Increases sweep efficiency";i:1;s:26:"Decreases sweep efficiency";i:2;s:13:"Has no effect";i:3;s:23:"Causes faster fingering";}','Increases sweep efficiency','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000525','Apa karakteristik utama dari biopolimer Xanthan dibandingkan dengan HPAM?','option','PFC000000009','Final Test','a:4:{i:0;s:37:"Lebih tahan terhadap salinitas tinggi";i:1;s:20:"Lebih murah harganya";i:2;s:38:"Lebih rentan terhadap degradasi termal";i:3;s:39:"Memiliki struktur linear yang sederhana";}','','Lebih tahan terhadap salinitas tinggi','What is the main characteristic of the biopolymer Xanthan compared to HPAM?','a:4:{i:0;s:31:"More resistant to high salinity";i:1;s:16:"Cheaper in price";i:2;s:39:"More susceptible to thermal degradation";i:3;s:29:"Has a simple linear structure";}','More resistant to high salinity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000526','Mengapa mobility ratio yang lebih kecil dari 1 (M < 1) diinginkan dalam proses injeksi polimer?','option','PFC000000009','Final Test','a:4:{i:0;s:32:"Untuk mencegah viscous fingering";i:1;s:49:"Untuk meningkatkan tekanan injeksi secara ekstrem";i:2;s:42:"Untuk mengurangi saturasi air irreduksibel";i:3;s:29:"Untuk mempercepat laju korosi";}','','Untuk mencegah viscous fingering','Why is a mobility ratio of less than 1 (M < 1) desirable in polymer injection processes?','a:4:{i:0;s:28:"To prevent viscous fingering";i:1;s:42:"To increase injection pressure excessively";i:2;s:38:"To reduce irreducible water saturation";i:3;s:28:"To accelerate corrosion rate";}','To prevent viscous fingering','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000527','Faktor apa saja yang membatasi efektivitas injeksi polimer di lapangan?','multi','PFC000000009','Final Test','a:4:{i:0;s:16:"Degradasi termal";i:1;s:28:"Adsorpsi polimer pada batuan";i:2;s:37:"Viskositas fluida yang terlalu rendah";i:3;s:17:"Salinitas formasi";}','','a:3:{i:0;s:16:"Degradasi termal";i:1;s:28:"Adsorpsi polimer pada batuan";i:2;s:17:"Salinitas formasi";}','What factors limit the effectiveness of polymer injection in the field?','a:4:{i:0;s:19:"Thermal degradation";i:1;s:26:"Polymer adsorption on rock";i:2;s:31:"Fluid viscosity that is too low";i:3;s:18:"Formation salinity";}','a:3:{i:0;s:19:"Thermal degradation";i:1;s:26:"Polymer adsorption on rock";i:2;s:18:"Formation salinity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000528','Pada kondisi reservoir apa injeksi polimer biasanya paling efektif diterapkan?','option','PFC000000009','Final Test','a:4:{i:0;s:37:"Reservoir dengan permeabilitas rendah";i:1;s:37:"Reservoir dengan heterogenitas tinggi";i:2;s:35:"Reservoir dengan suhu di atas 150 C";i:3;s:51:"Reservoir dengan saturasi minyak sisa sangat rendah";}','','Reservoir dengan heterogenitas tinggi','In what reservoir conditions is polymer injection usually most effectively applied?','a:4:{i:0;s:27:"Low permeability reservoirs";i:1;s:29:"High heterogeneity reservoirs";i:2;s:40:"Reservoirs with temperatures above 150 C";i:3;s:48:"Reservoirs with very low residual oil saturation";}','High heterogeneity reservoirs','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000529','Apa istilah untuk fenomena kehilangan polimer ke dalam matriks batuan selama injeksi?','option','PFC000000009','Final Test','a:4:{i:0;s:8:"Adsorpsi";i:1;s:5:"Erosi";i:2;s:10:"Infiltrasi";i:3;s:9:"Evaporasi";}','','Adsorpsi','What is the term for the phenomenon of polymer loss into the rock matrix during injection?','a:4:{i:0;s:10:"Adsorption";i:1;s:7:"Erosion";i:2;s:12:"Infiltration";i:3;s:11:"Evaporation";}','Adsorption','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000530','Dalam desain slug polimer, apa yang dimaksud dengan tapering?','option','PFC000000009','Final Test','a:4:{i:0;s:47:"Pengurangan konsentrasi polimer secara bertahap";i:1;s:34:"Peningkatan tekanan secara drastis";i:2;s:28:"Pencampuran dengan surfaktan";i:3;s:24:"Pembersihan lubang sumur";}','','Pengurangan konsentrasi polimer secara bertahap','In polymer slug design, what is meant by tapering?','a:4:{i:0;s:42:"Gradual reduction of polymer concentration";i:1;s:25:"Drastic pressure increase";i:2;s:22:"Mixing with surfactant";i:3;s:17:"Wellbore cleaning";}','Gradual reduction of polymer concentration','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000531','Apa dampak negatif dari degradasi mekanis (shear degradation) pada polimer HPAM?','option','PFC000000009','Final Test','a:4:{i:0;s:49:"Penurunan berat molekul dan kehilangan viskositas";i:1;s:37:"Peningkatan viskositas secara drastis";i:2;s:37:"Penyumbatan total pada zona produktif";i:3;s:29:"Pembentukan emulsi minyak-air";}','','Penurunan berat molekul dan kehilangan viskositas','What is the negative impact of shear degradation on HPAM polymer?','a:4:{i:0;s:51:"Reduction in molecular weight and loss of viscosity";i:1;s:29:"Drastic increase in viscosity";i:2;s:34:"Total plugging of productive zones";i:3;s:32:"Formation of oil-water emulsions";}','Reduction in molecular weight and loss of viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000532','Manakah pernyataan yang benar mengenai mobilitas fluida (lambda)?','option','PFC000000009','Final Test','a:4:{i:0;s:48:"Berbanding terbalik dengan permeabilitas relatif";i:1;s:41:"Berbanding lurus dengan viskositas fluida";i:2;s:44:"Berbanding terbalik dengan viskositas fluida";i:3;s:29:"Tidak bergantung pada tekanan";}','','Berbanding terbalik dengan viskositas fluida','Which statement is correct regarding fluid mobility (lambda)?','a:4:{i:0;s:47:"Inversely proportional to relative permeability";i:1;s:40:"Directly proportional to fluid viscosity";i:2;s:41:"Inversely proportional to fluid viscosity";i:3;s:27:"Does not depend on pressure";}','Inversely proportional to fluid viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000533','Mengapa injeksi polimer lebih unggul daripada waterflooding konvensional dalam hal perolehan minyak?','option','PFC000000009','Final Test','a:4:{i:0;s:47:"Memperbaiki vertical dan areal sweep efficiency";i:1;s:45:"Mengurangi biaya infrastruktur secara drastis";i:2;s:53:"Menghilangkan kebutuhan akan fasilitas pengolahan air";i:3;s:43:"Secara langsung melarutkan deposit paraffin";}','','Memperbaiki vertical dan areal sweep efficiency','Why is polymer injection superior to conventional waterflooding in terms of oil recovery?','a:4:{i:0;s:44:"Improves vertical and areal sweep efficiency";i:1;s:40:"Drastically reduces infrastructure costs";i:2;s:50:"Eliminates the need for water treatment facilities";i:3;s:36:"Directly dissolves paraffin deposits";}','Improves vertical and areal sweep efficiency','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000534','Apa tujuan utama dari proses pre-flush dalam desain Chemical EOR?','option','PFC000000009','Final Test','a:4:{i:0;s:50:"Menyesuaikan salinitas dan pH lingkungan reservoir";i:1;s:27:"Meningkatkan suhu reservoir";i:2;s:26:"Menambah viskositas minyak";i:3;s:43:"Membersihkan sisa bor di dekat lubang sumur";}','','Menyesuaikan salinitas dan pH lingkungan reservoir','What is the main purpose of pre-flush in Chemical EOR design?','a:4:{i:0;s:54:"Adjusting salinity and pH of the reservoir environment";i:1;s:32:"Increasing reservoir temperature";i:2;s:24:"Increasing oil viscosity";i:3;s:43:"Cleaning drilling residue near the wellbore";}','Adjusting salinity and pH of the reservoir environment','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000535','Bagaimana pengaruh suhu reservoir yang sangat tinggi terhadap stabilitas kimiawi HPAM?','option','PFC000000009','Final Test','a:4:{i:0;s:44:"Mempercepat hidrolisis dan degradasi polimer";i:1;s:32:"Meningkatkan efektivitas polimer";i:2;s:29:"Tidak berpengaruh sama sekali";i:3;s:37:"Mengubah polimer menjadi bentuk padat";}','','Mempercepat hidrolisis dan degradasi polimer','How does very high reservoir temperature affect the chemical stability of HPAM?','a:4:{i:0;s:46:"Accelerates hydrolysis and polymer degradation";i:1;s:31:"Increases polymer effectiveness";i:2;s:20:"Has no effect at all";i:3;s:32:"Converts polymer into solid form";}','Accelerates hydrolysis and polymer degradation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000536','Dalam konteks polimer flooding, apa yang dimaksud dengan ''resistance factor''?','option','PFC000000009','Final Test','a:4:{i:0;s:54:"Rasio mobilitas air terhadap mobilitas larutan polimer";i:1;s:48:"Rasio viskositas polimer terhadap viskositas air";i:2;s:54:"Rasio permeabilitas batuan setelah dan sebelum injeksi";i:3;s:24:"Faktor biaya operasional";}','','Rasio mobilitas air terhadap mobilitas larutan polimer','In the context of polymer flooding, what is meant by ''resistance factor''?','a:4:{i:0;s:52:"Ratio of water mobility to polymer solution mobility";i:1;s:45:"Ratio of polymer viscosity to water viscosity";i:2;s:53:"Ratio of rock permeability after and before injection";i:3;s:23:"Operational cost factor";}','Ratio of water mobility to polymer solution mobility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000537','Manakah yang benar tentang karakteristik Xanthan Gum?','multi','PFC000000009','Final Test','a:4:{i:0;s:20:"Merupakan biopolimer";i:1;s:24:"Tahan terhadap salinitas";i:2;s:42:"Sangat sensitif terhadap degradasi bakteri";i:3;s:33:"Sintetis dari turunan minyak bumi";}','','a:3:{i:0;s:20:"Merupakan biopolimer";i:1;s:24:"Tahan terhadap salinitas";i:2;s:42:"Sangat sensitif terhadap degradasi bakteri";}','Which of the following are true about the characteristics of Xanthan Gum?','a:4:{i:0;s:18:"It is a biopolymer";i:1;s:21:"Resistant to salinity";i:2;s:39:"Very sensitive to bacterial degradation";i:3;s:36:"Synthetic from petroleum derivatives";}','a:3:{i:0;s:18:"It is a biopolymer";i:1;s:21:"Resistant to salinity";i:2;s:39:"Very sensitive to bacterial degradation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000538','Apa tantangan utama dalam implementasi lapangan injeksi polimer yang berkaitan dengan sumur injeksi?','option','PFC000000009','Final Test','a:4:{i:0;s:44:"Penyumbatan formasi akibat viskositas tinggi";i:1;s:37:"Kerusakan pompa injeksi akibat korosi";i:2;s:31:"Penguapan polimer di dalam pipa";i:3;s:33:"Kesulitan dalam memonitor tekanan";}','','Penyumbatan formasi akibat viskositas tinggi','What is the main challenge in field implementation of polymer injection related to injection wells?','a:4:{i:0;s:40:"Formation plugging due to high viscosity";i:1;s:38:"Injection pump damage due to corrosion";i:2;s:32:"Polymer evaporation inside pipes";i:3;s:33:"Difficulty in monitoring pressure";}','Formation plugging due to high viscosity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000539','Apa keuntungan menggunakan polimer dibandingkan dengan waterflooding saja pada reservoir heterogen?','option','PFC000000009','Final Test','a:4:{i:0;s:72:"Mengurangi aliran melalui zona dengan permeabilitas tinggi (thief zones)";i:1;s:34:"Meningkatkan permeabilitas absolut";i:2;s:50:"Menggantikan seluruh volume minyak dalam reservoir";i:3;s:30:"Menurunkan harga minyak mentah";}','','Mengurangi aliran melalui zona dengan permeabilitas tinggi (thief zones)','What is the advantage of using polymer compared to waterflooding alone in heterogeneous reservoirs?','a:4:{i:0;s:58:"Reduces flow through high permeability zones (thief zones)";i:1;s:31:"Increases absolute permeability";i:2;s:47:"Replaces the entire oil volume in the reservoir";i:3;s:23:"Lowers crude oil prices";}','Reduces flow through high permeability zones (thief zones)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000540','Apa fungsi utama dari penambahan surfaktan dalam metode Chemical EOR?','option','PFC000000010','Final Test','a:4:{i:0;s:27:"Meningkatkan viskositas air";i:1;s:35:"Menurunkan tegangan antarmuka (IFT)";i:2;s:25:"Menambah porositas batuan";i:3;s:28:"Meningkatkan tekanan injeksi";}','','Menurunkan tegangan antarmuka (IFT)','What is the primary function of adding surfactants in Chemical EOR methods?','a:4:{i:0;s:24:"Increase water viscosity";i:1;s:32:"Reduce interfacial tension (IFT)";i:2;s:22:"Increase rock porosity";i:3;s:27:"Increase injection pressure";}','Reduce interfacial tension (IFT)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000541','Manakah mekanisme berikut yang terjadi saat alkaline diinjeksikan ke dalam reservoir?','multi','PFC000000010','Final Test','a:4:{i:0;s:28:"Perubahan wettability batuan";i:1;s:29:"Pembentukan surfaktan in-situ";i:2;s:27:"Peningkatan saturasi minyak";i:3;s:24:"Penurunan pH air formasi";}','','a:2:{i:0;s:28:"Perubahan wettability batuan";i:1;s:29:"Pembentukan surfaktan in-situ";}','Which of the following mechanisms occur when alkaline is injected into a reservoir?','a:4:{i:0;s:27:"Rock wettability alteration";i:1;s:29:"In-situ surfactant generation";i:2;s:26:"Increase in oil saturation";i:3;s:30:"Decrease in formation water pH";}','a:2:{i:0;s:27:"Rock wettability alteration";i:1;s:29:"In-situ surfactant generation";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000542','Apa yang dimaksud dengan proses solubilisasi dalam konteks surfaktan?','option','PFC000000010','Final Test','a:4:{i:0;s:30:"Pembentukan emulsi makroskopis";i:1;s:42:"Pengikatan minyak ke dalam misel surfaktan";i:2;s:27:"Penguapan minyak oleh panas";i:3;s:27:"Pencucian garam dari batuan";}','','Pengikatan minyak ke dalam misel surfaktan','What is meant by the solubilization process in the context of surfactants?','a:4:{i:0;s:34:"Formation of macroscopic emulsions";i:1;s:45:"Incorporation of oil into surfactant micelles";i:2;s:26:"Evaporation of oil by heat";i:3;s:27:"Washing of salts from rocks";}','Incorporation of oil into surfactant micelles','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000543','Apa kepanjangan dari ASP dalam formulasi Chemical EOR?','option','PFC000000010','Final Test','a:4:{i:0;s:27:"Alkaline Surfactant Polymer";i:1;s:24:"Active Solution Pressure";i:2;s:27:"Advanced Surfactant Process";i:3;s:22:"Acidic Solvent Process";}','','Alkaline Surfactant Polymer','What does ASP stand for in Chemical EOR formulations?','a:4:{i:0;s:27:"Alkaline Surfactant Polymer";i:1;s:24:"Active Solution Pressure";i:2;s:27:"Advanced Surfactant Process";i:3;s:22:"Acidic Solvent Process";}','Alkaline Surfactant Polymer','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000544','Mengapa perubahan wettability batuan dari oil-wet menjadi water-wet sangat penting dalam EOR?','option','PFC000000010','Final Test','a:4:{i:0;s:29:"Untuk memperbesar ukuran pori";i:1;s:54:"Untuk melepas minyak yang terjebak di permukaan batuan";i:2;s:47:"Untuk menurunkan tekanan kapiler secara drastis";i:3;s:31:"Untuk meningkatkan densitas air";}','','Untuk melepas minyak yang terjebak di permukaan batuan','Why is the change of rock wettability from oil-wet to water-wet important in EOR?','a:4:{i:0;s:21:"To increase pore size";i:1;s:42:"To release oil trapped on the rock surface";i:2;s:40:"To drastically reduce capillary pressure";i:3;s:25:"To increase water density";}','To release oil trapped on the rock surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000545','Apa dampak negatif utama dari adsorpsi surfaktan pada matriks batuan?','option','PFC000000010','Final Test','a:4:{i:0;s:38:"Kehilangan konsentrasi surfaktan aktif";i:1;s:33:"Peningkatan permeabilitas absolut";i:2;s:28:"Penurunan pH larutan injeksi";i:3;s:30:"Peningkatan tegangan antarmuka";}','','Kehilangan konsentrasi surfaktan aktif','What is the main negative impact of surfactant adsorption on the rock matrix?','a:4:{i:0;s:39:"Loss of active surfactant concentration";i:1;s:33:"Increase in absolute permeability";i:2;s:33:"Decrease in injection solution pH";i:3;s:31:"Increase in interfacial tension";}','Loss of active surfactant concentration','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000546','Faktor apa yang paling mempengaruhi efisiensi surfaktan dalam menurunkan IFT?','option','PFC000000010','Final Test','a:4:{i:0;s:17:"Salinitas formasi";i:1;s:17:"Viskositas minyak";i:2;s:16:"Porositas batuan";i:3;s:19:"Kedalaman reservoir";}','','Salinitas formasi','Which factor most influences surfactant efficiency in reducing IFT?','a:4:{i:0;s:18:"Formation salinity";i:1;s:13:"Oil viscosity";i:2;s:13:"Rock porosity";i:3;s:15:"Reservoir depth";}','Formation salinity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000547','Dalam formulasi ASP, apa peran utama dari polimer?','option','PFC000000010','Final Test','a:4:{i:0;s:29:"Menurunkan tegangan antarmuka";i:1;s:27:"Mengontrol mobilitas fluida";i:2;s:15:"Meningkatkan pH";i:3;s:20:"Mengubah wettability";}','','Mengontrol mobilitas fluida','In an ASP formulation, what is the primary role of the polymer?','a:4:{i:0;s:26:"Reduce interfacial tension";i:1;s:22:"Control fluid mobility";i:2;s:11:"Increase pH";i:3;s:18:"Change wettability";}','Control fluid mobility','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000548','Apa yang terjadi pada sistem surfaktan jika suhu reservoir terlalu tinggi?','option','PFC000000010','Final Test','a:4:{i:0;s:25:"Degradasi kimia surfaktan";i:1;s:35:"Peningkatan kelarutan secara instan";i:2;s:18:"Penurunan adsorpsi";i:3;s:36:"Peningkatan efisiensi secara drastis";}','','Degradasi kimia surfaktan','What happens to the surfactant system if the reservoir temperature is too high?','a:4:{i:0;s:38:"Chemical degradation of the surfactant";i:1;s:30:"Instant increase in solubility";i:2;s:22:"Decrease in adsorption";i:3;s:30:"Drastic increase in efficiency";}','Chemical degradation of the surfactant','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000549','Kondisi reservoir mana yang paling tidak cocok untuk aplikasi alkaline flooding?','option','PFC000000010','Final Test','a:4:{i:0;s:34:"Reservoir minyak asam (acidic oil)";i:1;s:48:"Batuan karbonat dengan kandungan anhidrit tinggi";i:2;s:37:"Reservoir dengan permeabilitas tinggi";i:3;s:46:"Reservoir dengan saturasi minyak residu tinggi";}','','Batuan karbonat dengan kandungan anhidrit tinggi','Which reservoir condition is least suitable for alkaline flooding applications?','a:4:{i:0;s:21:"Acidic oil reservoirs";i:1;s:43:"Carbonate rocks with high anhydrite content";i:2;s:28:"High permeability reservoirs";i:3;s:44:"Reservoirs with high residual oil saturation";}','Carbonate rocks with high anhydrite content','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000550','Pilih dua keuntungan utama dari penggunaan Alkaline-Surfactant (AS) flooding dibandingkan surfaktan saja:','multi','PFC000000010','Final Test','a:4:{i:0;s:28:"Biaya kimia yang lebih murah";i:1;s:37:"Sinergi penurunan IFT yang lebih baik";i:2;s:42:"Pengurangan adsorpsi surfaktan pada batuan";i:3;s:41:"Peningkatan viskositas air secara spontan";}','','a:2:{i:0;s:28:"Biaya kimia yang lebih murah";i:1;s:42:"Pengurangan adsorpsi surfaktan pada batuan";}','Choose two main advantages of using Alkaline-Surfactant (AS) flooding compared to surfactants alone:','a:4:{i:0;s:22:"Cheaper chemical costs";i:1;s:28:"Better IFT reduction synergy";i:2;s:43:"Reduction of surfactant adsorption on rocks";i:3;s:36:"Spontaneous water viscosity increase";}','a:2:{i:0;s:22:"Cheaper chemical costs";i:1;s:43:"Reduction of surfactant adsorption on rocks";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000551','Apa tujuan dari tahap pre-flush dalam proyek Chemical EOR?','option','PFC000000010','Final Test','a:4:{i:0;s:25:"Menyesuaikan pH reservoir";i:1;s:57:"Mengurangi salinitas untuk mencegah presipitasi surfaktan";i:2;s:27:"Meningkatkan suhu reservoir";i:3;s:35:"Membersihkan debris dari lubang bor";}','','Mengurangi salinitas untuk mencegah presipitasi surfaktan','What is the purpose of the pre-flush stage in a Chemical EOR project?','a:4:{i:0;s:19:"Adjust reservoir pH";i:1;s:51:"Reduce salinity to prevent surfactant precipitation";i:2;s:30:"Increase reservoir temperature";i:3;s:30:"Clean debris from the wellbore";}','Reduce salinity to prevent surfactant precipitation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000552','Bagaimana pengaruh tegangan antarmuka (IFT) terhadap recovery factor minyak?','option','PFC000000010','Final Test','a:4:{i:0;s:42:"Semakin tinggi IFT, semakin besar recovery";i:1;s:42:"Semakin rendah IFT, semakin besar recovery";i:2;s:42:"Tidak ada korelasi antara IFT dan recovery";i:3;s:44:"IFT hanya berpengaruh pada viskositas minyak";}','','Semakin rendah IFT, semakin besar recovery','How does interfacial tension (IFT) affect the oil recovery factor?','a:4:{i:0;s:38:"Higher IFT results in greater recovery";i:1;s:37:"Lower IFT results in greater recovery";i:2;s:48:"There is no correlation between IFT and recovery";i:3;s:30:"IFT only affects oil viscosity";}','Lower IFT results in greater recovery','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000553','Apa yang dimaksud dengan kondisi ''ultra-low IFT'' dalam Chemical EOR?','option','PFC000000010','Final Test','a:4:{i:0;s:26:"IFT di bawah 10^-3 dyne/cm";i:1;s:22:"IFT di atas 10 dyne/cm";i:2;s:25:"IFT sama dengan air murni";i:3;s:17:"IFT tidak terukur";}','','IFT di bawah 10^-3 dyne/cm','What is meant by ''ultra-low IFT'' conditions in Chemical EOR?','a:4:{i:0;s:23:"IFT below 10^-3 dyne/cm";i:1;s:20:"IFT above 10 dyne/cm";i:2;s:23:"IFT equal to pure water";i:3;s:19:"IFT is immeasurable";}','IFT below 10^-3 dyne/cm','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000554','Mengapa pH tinggi pada alkaline flooding dapat menyebabkan masalah kerak (scaling)?','option','PFC000000010','Final Test','a:4:{i:0;s:54:"Reaksi antara alkali dengan ion kalsium di air formasi";i:1;s:30:"Polimer bereaksi dengan batuan";i:2;s:17:"Surfaktan membeku";i:3;s:27:"Perubahan tekanan reservoir";}','','Reaksi antara alkali dengan ion kalsium di air formasi','Why can high pH in alkaline flooding cause scaling problems?','a:4:{i:0;s:59:"Reaction between alkali and calcium ions in formation water";i:1;s:28:"Polymer reacts with the rock";i:2;s:18:"Surfactant freezes";i:3;s:29:"Changes in reservoir pressure";}','Reaction between alkali and calcium ions in formation water','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000555','Apa parameter utama yang diamati saat melakukan uji laboratorium ''bottle test'' untuk surfaktan?','option','PFC000000010','Final Test','a:4:{i:0;s:44:"Waktu pemisahan fase dan kejelasan antarmuka";i:1;s:16:"Kekerasan batuan";i:2;s:13:"Laju alir gas";i:3;s:22:"Tekanan kapiler batuan";}','','Waktu pemisahan fase dan kejelasan antarmuka','What is the main parameter observed during ''bottle test'' laboratory trials for surfactants?','a:4:{i:0;s:43:"Phase separation time and interface clarity";i:1;s:13:"Rock hardness";i:2;s:13:"Gas flow rate";i:3;s:23:"Rock capillary pressure";}','Phase separation time and interface clarity','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000556','Faktor apa yang menentukan pemilihan jenis surfaktan untuk reservoir tertentu?','multi','PFC000000010','Final Test','a:4:{i:0;s:20:"Temperatur reservoir";i:1;s:31:"Kandungan salinitas air formasi";i:2;s:22:"Jenis batuan reservoir";i:3;s:25:"Harga pasar minyak mentah";}','','a:3:{i:0;s:20:"Temperatur reservoir";i:1;s:31:"Kandungan salinitas air formasi";i:2;s:22:"Jenis batuan reservoir";}','What factors determine the selection of surfactant type for a specific reservoir?','a:4:{i:0;s:21:"Reservoir temperature";i:1;s:32:"Formation water salinity content";i:2;s:19:"Reservoir rock type";i:3;s:22:"Crude oil market price";}','a:3:{i:0;s:21:"Reservoir temperature";i:1;s:32:"Formation water salinity content";i:2;s:19:"Reservoir rock type";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000557','Apa efek utama dari penambahan alkali pada minyak mentah yang mengandung asam naphthenic?','option','PFC000000010','Final Test','a:4:{i:0;s:32:"Pembentukan sabun (soap) in-situ";i:1;s:41:"Penurunan viskositas minyak secara termal";i:2;s:25:"Peningkatan kejenuhan air";i:3;s:21:"Pembentukan gas alami";}','','Pembentukan sabun (soap) in-situ','What is the primary effect of adding alkali to crude oil containing naphthenic acids?','a:4:{i:0;s:22:"In-situ soap formation";i:1;s:34:"Thermal reduction of oil viscosity";i:2;s:28:"Increase in water saturation";i:3;s:24:"Formation of natural gas";}','In-situ soap formation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000558','Manakah dari berikut ini yang merupakan kelemahan utama dari chemical flooding?','option','PFC000000010','Final Test','a:4:{i:0;s:29:"Biaya bahan kimia yang tinggi";i:1;s:34:"Produksi minyak yang terlalu cepat";i:2;s:49:"Kebutuhan akan tekanan injeksi yang sangat rendah";i:3;s:48:"Sifatnya yang tidak ramah lingkungan sama sekali";}','','Biaya bahan kimia yang tinggi','Which of the following is a major disadvantage of chemical flooding?','a:4:{i:0;s:22:"High cost of chemicals";i:1;s:31:"Oil production that is too fast";i:2;s:43:"Requirement for very low injection pressure";i:3;s:55:"Its nature which is not environmentally friendly at all";}','High cost of chemicals','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000559','Pada grafik ternary phase diagram untuk sistem surfaktan, area apa yang menunjukkan pembentukan mikroemulsi optimum?','option','PFC000000010','Final Test','a:4:{i:0;s:27:"Area tiga fase (Winsor III)";i:1;s:21:"Area air-dalam-minyak";i:2;s:21:"Area minyak-dalam-air";i:3;s:31:"Area di luar batas solubilisasi";}','','Area tiga fase (Winsor III)','On a ternary phase diagram for surfactant systems, which area indicates the formation of optimum microemulsion?','a:4:{i:0;s:29:"Three-phase area (Winsor III)";i:1;s:17:"Water-in-oil area";i:2;s:17:"Oil-in-water area";i:3;s:40:"Area outside the solubilization boundary";}','Three-phase area (Winsor III)','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000560','Apa mekanisme utama penurunan viskositas minyak pada metode steamflooding?','option','PFC000000011','Final Test','a:4:{i:0;s:16:"Pemanasan termal";i:1;s:12:"Ekspansi gas";i:2;s:24:"Pengurangan saturasi air";i:3;s:29:"Peningkatan tekanan reservoir";}','','Pemanasan termal','What is the primary mechanism for oil viscosity reduction in steamflooding?','a:4:{i:0;s:15:"Thermal heating";i:1;s:13:"Gas expansion";i:2;s:26:"Water saturation reduction";i:3;s:30:"Increase in reservoir pressure";}','Thermal heating','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000561','Manakah dari berikut ini yang merupakan karakteristik utama dari proses SAGD?','multi','PFC000000011','Final Test','a:4:{i:0;s:36:"Penggunaan sumur horizontal pasangan";i:1;s:33:"Gravitasi sebagai pendorong utama";i:2;s:15:"Injeksi gas CO2";i:3;s:23:"Pemanasan terus-menerus";}','','a:3:{i:0;s:36:"Penggunaan sumur horizontal pasangan";i:1;s:33:"Gravitasi sebagai pendorong utama";i:2;s:23:"Pemanasan terus-menerus";}','Which of the following are key characteristics of the SAGD process?','a:4:{i:0;s:30:"Use of paired horizontal wells";i:1;s:29:"Gravity as the primary driver";i:2;s:17:"CO2 gas injection";i:3;s:18:"Continuous heating";}','a:3:{i:0;s:30:"Use of paired horizontal wells";i:1;s:29:"Gravity as the primary driver";i:2;s:18:"Continuous heating";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000562','Metode cyclic steam stimulation (CSS) sering disebut juga dengan istilah?','option','PFC000000011','Final Test','a:4:{i:0;s:13:"Huff and puff";i:1;s:11:"Steam drive";i:2;s:16:"Combustion front";i:3;s:13:"Gas cap drive";}','','Huff and puff','The cyclic steam stimulation (CSS) method is also known as?','a:4:{i:0;s:13:"Huff and puff";i:1;s:11:"Steam drive";i:2;s:16:"Combustion front";i:3;s:13:"Gas cap drive";}','Huff and puff','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000563','Pada in-situ combustion, zona apa yang terletak tepat di belakang zona pembakaran?','option','PFC000000011','Final Test','a:4:{i:0;s:27:"Zona terbakar (burned zone)";i:1;s:22:"Zona kokas (coke zone)";i:2;s:21:"Zona uap (steam zone)";i:3;s:18:"Zona minyak dingin";}','','Zona kokas (coke zone)','In in-situ combustion, which zone is located immediately behind the combustion front?','a:4:{i:0;s:11:"Burned zone";i:1;s:9:"Coke zone";i:2;s:10:"Steam zone";i:3;s:13:"Cold oil zone";}','Coke zone','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000564','Manakah gas yang paling umum digunakan dalam miscible gas injection untuk meningkatkan perolehan minyak?','option','PFC000000011','Final Test','a:4:{i:0;s:3:"CO2";i:1;s:8:"Nitrogen";i:2;s:5:"Udara";i:3;s:7:"Oksigen";}','','CO2','Which gas is most commonly used in miscible gas injection to enhance oil recovery?','a:4:{i:0;s:3:"CO2";i:1;s:8:"Nitrogen";i:2;s:3:"Air";i:3;s:6:"Oxygen";}','CO2','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000565','Apa tujuan utama dari teknik WAG (Water-Alternating-Gas) dalam injeksi gas?','option','PFC000000011','Final Test','a:4:{i:0;s:24:"Mengontrol mobilitas gas";i:1;s:28:"Menambah tekanan hidrostatik";i:2;s:25:"Mengurangi viskositas air";i:3;s:20:"Mencegah korosi pipa";}','','Mengontrol mobilitas gas','What is the primary purpose of the WAG (Water-Alternating-Gas) technique in gas injection?','a:4:{i:0;s:20:"Gas mobility control";i:1;s:29:"Increase hydrostatic pressure";i:2;s:22:"Reduce water viscosity";i:3;s:22:"Prevent pipe corrosion";}','Gas mobility control','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000566','Faktor apa yang paling membatasi penerapan in-situ combustion di lapangan?','option','PFC000000011','Final Test','a:4:{i:0;s:42:"Kompleksitas operasional dan kontrol front";i:1;s:16:"Ketersediaan air";i:2;s:19:"Biaya material baja";i:3;s:32:"Kedalaman reservoir yang dangkal";}','','Kompleksitas operasional dan kontrol front','What is the most limiting factor for the application of in-situ combustion in the field?','a:4:{i:0;s:40:"Operational complexity and front control";i:1;s:18:"Water availability";i:2;s:19:"Steel material cost";i:3;s:23:"Shallow reservoir depth";}','Operational complexity and front control','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000567','Metode thermal mana yang paling efektif untuk reservoir minyak berat yang sangat kental dan tebal?','option','PFC000000011','Final Test','a:4:{i:0;s:4:"SAGD";i:1;s:13:"Gas injection";i:2;s:13:"Waterflooding";i:3;s:17:"Chemical flooding";}','','SAGD','Which thermal method is most effective for thick, highly viscous heavy oil reservoirs?','a:4:{i:0;s:4:"SAGD";i:1;s:13:"Gas injection";i:2;s:13:"Waterflooding";i:3;s:17:"Chemical flooding";}','SAGD','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000568','Dalam injeksi CO2 misibel, mekanisme utama peningkatan recovery adalah?','multi','PFC000000011','Final Test','a:4:{i:0;s:15:"Swelling minyak";i:1;s:22:"Pengurangan viskositas";i:2;s:25:"Ekstraksi komponen ringan";i:3;s:33:"Peningkatan permeabilitas absolut";}','','a:3:{i:0;s:15:"Swelling minyak";i:1;s:22:"Pengurangan viskositas";i:2;s:25:"Ekstraksi komponen ringan";}','In miscible CO2 injection, the primary recovery mechanisms are?','a:4:{i:0;s:12:"Oil swelling";i:1;s:19:"Viscosity reduction";i:2;s:30:"Extraction of light components";i:3;s:33:"Increase in absolute permeability";}','a:3:{i:0;s:12:"Oil swelling";i:1;s:19:"Viscosity reduction";i:2;s:30:"Extraction of light components";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000569','Apa yang dimaksud dengan Minimum Miscibility Pressure (MMP)?','option','PFC000000011','Final Test','a:4:{i:0;s:57:"Tekanan minimum agar gas bercampur sempurna dengan minyak";i:1;s:24:"Tekanan maksimum injeksi";i:2;s:21:"Tekanan pecah formasi";i:3;s:23:"Tekanan saturasi minyak";}','','Tekanan minimum agar gas bercampur sempurna dengan minyak','What is meant by Minimum Miscibility Pressure (MMP)?','a:4:{i:0;s:52:"Minimum pressure for gas to become miscible with oil";i:1;s:26:"Maximum injection pressure";i:2;s:28:"Formation breakdown pressure";i:3;s:23:"Oil saturation pressure";}','Minimum pressure for gas to become miscible with oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000570','Keuntungan utama menggunakan injeksi gas hidrokarbon dibandingkan CO2 adalah?','option','PFC000000011','Final Test','a:4:{i:0;s:58:"Ketersediaan dan biaya yang lebih murah di lokasi tertentu";i:1;s:36:"Tidak memerlukan fasilitas kompresor";i:2;s:20:"Lebih berat dari CO2";i:3;s:26:"Tidak bisa menjadi misibel";}','','Ketersediaan dan biaya yang lebih murah di lokasi tertentu','The main advantage of using hydrocarbon gas injection compared to CO2 is?','a:4:{i:0;s:48:"Availability and lower cost in certain locations";i:1;s:38:"Does not require compressor facilities";i:2;s:16:"Heavier than CO2";i:3;s:18:"Cannot be miscible";}','Availability and lower cost in certain locations','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000571','Dalam steamflooding, kehilangan panas di dalam sumur dapat dikurangi dengan menggunakan?','option','PFC000000011','Final Test','a:4:{i:0;s:18:"Tubing berinsulasi";i:1;s:18:"Casing baja karbon";i:2;s:20:"Cementing yang tipis";i:3;s:18:"Injeksi air dingin";}','','Tubing berinsulasi','In steamflooding, heat loss inside the wellbore can be reduced by using?','a:4:{i:0;s:16:"Insulated tubing";i:1;s:19:"Carbon steel casing";i:2;s:14:"Thin cementing";i:3;s:20:"Cold water injection";}','Insulated tubing','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000572','Manakah kriteria reservoir yang umum untuk metode thermal EOR?','multi','PFC000000011','Final Test','a:4:{i:0;s:31:"Minyak dengan viskositas tinggi";i:1;s:39:"Kedalaman reservoir tidak terlalu dalam";i:2;s:16:"Porositas tinggi";i:3;s:49:"Batuan reservoir dengan kandungan karbonat tinggi";}','','a:3:{i:0;s:31:"Minyak dengan viskositas tinggi";i:1;s:39:"Kedalaman reservoir tidak terlalu dalam";i:2;s:16:"Porositas tinggi";}','Which are the common reservoir criteria for thermal EOR methods?','a:4:{i:0;s:18:"High oil viscosity";i:1;s:23:"Shallow reservoir depth";i:2;s:13:"High porosity";i:3;s:37:"High carbonate content reservoir rock";}','a:3:{i:0;s:18:"High oil viscosity";i:1;s:23:"Shallow reservoir depth";i:2;s:13:"High porosity";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000573','Fenomena ''gravity override'' pada injeksi gas disebabkan oleh?','option','PFC000000011','Final Test','a:4:{i:0;s:40:"Perbedaan densitas antara gas dan minyak";i:1;s:35:"Tekanan injeksi yang terlalu rendah";i:2;s:26:"Permeabilitas yang seragam";i:3;s:29:"Peningkatan viskositas minyak";}','','Perbedaan densitas antara gas dan minyak','The ''gravity override'' phenomenon in gas injection is caused by?','a:4:{i:0;s:38:"Density difference between gas and oil";i:1;s:34:"Injection pressure that is too low";i:2;s:20:"Uniform permeability";i:3;s:23:"Increased oil viscosity";}','Density difference between gas and oil','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000574','In-situ combustion dikategorikan sebagai metode thermal karena?','option','PFC000000011','Final Test','a:4:{i:0;s:37:"Menghasilkan panas di dalam reservoir";i:1;s:31:"Menggunakan boiler di permukaan";i:2;s:21:"Menginjeksi uap panas";i:3;s:27:"Menggunakan pemanas listrik";}','','Menghasilkan panas di dalam reservoir','In-situ combustion is categorized as a thermal method because?','a:4:{i:0;s:38:"It generates heat within the reservoir";i:1;s:30:"It uses boilers at the surface";i:2;s:20:"It injects hot steam";i:3;s:24:"It uses electric heaters";}','It generates heat within the reservoir','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000575','Apa dampak negatif injeksi CO2 yang harus diwaspadai di dalam pipa produksi?','option','PFC000000011','Final Test','a:4:{i:0;s:39:"Korosi akibat pembentukan asam karbonat";i:1;s:29:"Peningkatan viskositas minyak";i:2;s:19:"Endapan lilin (wax)";i:3;s:31:"Penurunan permeabilitas absolut";}','','Korosi akibat pembentukan asam karbonat','What is a negative impact of CO2 injection that must be monitored in production tubing?','a:4:{i:0;s:40:"Corrosion due to carbonic acid formation";i:1;s:25:"Increase in oil viscosity";i:2;s:14:"Wax deposition";i:3;s:33:"Decrease in absolute permeability";}','Corrosion due to carbonic acid formation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000576','Proses injeksi gas yang dilakukan dengan tekanan di atas MMP disebut?','option','PFC000000011','Final Test','a:4:{i:0;s:17:"Miscible flooding";i:1;s:19:"Immiscible flooding";i:2;s:13:"Waterflooding";i:3;s:12:"Cyclic steam";}','','Miscible flooding','A gas injection process carried out at a pressure above MMP is called?','a:4:{i:0;s:17:"Miscible flooding";i:1;s:19:"Immiscible flooding";i:2;s:13:"Waterflooding";i:3;s:12:"Cyclic steam";}','Miscible flooding','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000577','Apa kelemahan utama dari metode Cyclic Steam Stimulation (CSS)?','option','PFC000000011','Final Test','a:4:{i:0;s:27:"Recovery factor yang rendah";i:1;s:35:"Hanya efisien untuk reservoir dalam";i:2;s:28:"Membutuhkan air yang sedikit";i:3;s:23:"Biaya operasional murah";}','','Recovery factor yang rendah','What is the main disadvantage of the Cyclic Steam Stimulation (CSS) method?','a:4:{i:0;s:19:"Low recovery factor";i:1;s:34:"Only efficient for deep reservoirs";i:2;s:21:"Requires little water";i:3;s:20:"Low operational cost";}','Low recovery factor','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000578','Dalam injeksi gas, apa fungsi dari ''slug'' gas?','option','PFC000000011','Final Test','a:4:{i:0;s:39:"Mendorong minyak ke arah sumur produksi";i:1;s:26:"Menambah viskositas minyak";i:2;s:28:"Mengurangi tekanan reservoir";i:3;s:23:"Menghentikan aliran air";}','','Mendorong minyak ke arah sumur produksi','In gas injection, what is the function of the gas ''slug''?','a:4:{i:0;s:39:"To push oil towards the production well";i:1;s:25:"To increase oil viscosity";i:2;s:28:"To reduce reservoir pressure";i:3;s:18:"To stop water flow";}','To push oil towards the production well','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000579','Parameter utama yang menentukan keberhasilan injeksi thermal adalah?','multi','PFC000000011','Final Test','a:4:{i:0;s:38:"Efisiensi penyapuan (sweep efficiency)";i:1;s:27:"Efisiensi perpindahan panas";i:2;s:32:"Kondisi keekonomian harga minyak";i:3;s:15:"Kedalaman sumur";}','','a:3:{i:0;s:38:"Efisiensi penyapuan (sweep efficiency)";i:1;s:27:"Efisiensi perpindahan panas";i:2;s:32:"Kondisi keekonomian harga minyak";}','The main parameters that determine the success of thermal injection are?','a:4:{i:0;s:16:"Sweep efficiency";i:1;s:24:"Heat transfer efficiency";i:2;s:32:"Economic conditions of oil price";i:3;s:10:"Well depth";}','a:3:{i:0;s:16:"Sweep efficiency";i:1;s:24:"Heat transfer efficiency";i:2;s:32:"Economic conditions of oil price";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000580','Apa tujuan utama dari pelaksanaan proyek pilot EOR sebelum penerapan skala penuh?','option','PFC000000012','Final Test','a:4:{i:0;s:55:"Mengurangi ketidakpastian teknis dan risiko operasional";i:1;s:48:"Meningkatkan harga minyak mentah secara langsung";i:2;s:41:"Mengurangi biaya eksplorasi di sumur baru";i:3;s:47:"Menghilangkan kebutuhan akan studi laboratorium";}','','Mengurangi ketidakpastian teknis dan risiko operasional','What is the primary objective of implementing an EOR pilot project before full-field application?','a:4:{i:0;s:52:"Reducing technical uncertainty and operational risks";i:1;s:36:"Directly increasing crude oil prices";i:2;s:39:"Reducing exploration costs in new wells";i:3;s:43:"Eliminating the need for laboratory studies";}','Reducing technical uncertainty and operational risks','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000581','Parameter ekonomi mana yang paling umum digunakan untuk mengevaluasi profitabilitas proyek EOR?','multi','PFC000000012','Final Test','a:4:{i:0;s:23:"Net Present Value (NPV)";i:1;s:29:"Internal Rate of Return (IRR)";i:2;s:36:"Total biaya operasional tanpa diskon";i:3;s:26:"Kecepatan pengeboran sumur";}','','a:2:{i:0;s:23:"Net Present Value (NPV)";i:1;s:29:"Internal Rate of Return (IRR)";}','Which economic parameters are most commonly used to evaluate the profitability of EOR projects?','a:4:{i:0;s:23:"Net Present Value (NPV)";i:1;s:29:"Internal Rate of Return (IRR)";i:2;s:34:"Total undiscounted operating costs";i:3;s:19:"Well drilling speed";}','a:2:{i:0;s:23:"Net Present Value (NPV)";i:1;s:29:"Internal Rate of Return (IRR)";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000582','Faktor risiko teknis yang paling signifikan dalam penerapan injeksi polimer adalah?','option','PFC000000012','Final Test','a:4:{i:0;s:39:"Degradasi polimer akibat suhu reservoir";i:1;s:34:"Kurangnya ketersediaan air injeksi";i:2;s:23:"Kenaikan harga gas alam";i:3;s:33:"Peningkatan permeabilitas formasi";}','','Degradasi polimer akibat suhu reservoir','The most significant technical risk factor in polymer injection application is?','a:4:{i:0;s:48:"Polymer degradation due to reservoir temperature";i:1;s:36:"Lack of injection water availability";i:2;s:26:"Natural gas price increase";i:3;s:31:"Formation permeability increase";}','Polymer degradation due to reservoir temperature','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000583','Dalam konteks HSE, aspek apa yang menjadi perhatian utama pada injeksi CO2 EOR?','option','PFC000000012','Final Test','a:4:{i:0;s:30:"Kebocoran gas CO2 ke permukaan";i:1;s:27:"Polusi suara dari kompresor";i:2;s:26:"Tingginya konsumsi listrik";i:3;s:24:"Karat pada pipa produksi";}','','Kebocoran gas CO2 ke permukaan','In the context of HSE, what is the primary concern during CO2 EOR injection?','a:4:{i:0;s:33:"Leakage of CO2 gas to the surface";i:1;s:32:"Noise pollution from compressors";i:2;s:28:"High electricity consumption";i:3;s:33:"Corrosion in production pipelines";}','Leakage of CO2 gas to the surface','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000584','Mengapa proyek EOR seringkali membutuhkan harga minyak yang tinggi untuk layak secara ekonomi?','option','PFC000000012','Final Test','a:4:{i:0;s:44:"Biaya bahan kimia dan operasional yang mahal";i:1;s:37:"Penurunan produksi yang terlalu cepat";i:2;s:35:"Kebutuhan akan alat pengeboran baru";i:3;s:34:"Pajak pemerintah yang lebih rendah";}','','Biaya bahan kimia dan operasional yang mahal','Why do EOR projects often require high oil prices to be economically viable?','a:4:{i:0;s:37:"High cost of chemicals and operations";i:1;s:35:"Excessively fast production decline";i:2;s:31:"Need for new drilling equipment";i:3;s:22:"Lower government taxes";}','High cost of chemicals and operations','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000585','Apa yang dimaksud dengan ''screen analysis'' pada tahap perencanaan proyek EOR?','option','PFC000000012','Final Test','a:4:{i:0;s:57:"Penyaringan reservoir berdasarkan kriteria kesesuaian EOR";i:1;s:33:"Pemilihan lokasi sumur pengeboran";i:2;s:41:"Pemeriksaan kesehatan pekerja di lapangan";i:3;s:29:"Penyaringan air untuk injeksi";}','','Penyaringan reservoir berdasarkan kriteria kesesuaian EOR','What is meant by ''screen analysis'' in the EOR project planning phase?','a:4:{i:0;s:57:"Screening of reservoirs based on EOR suitability criteria";i:1;s:36:"Selection of well drilling locations";i:2;s:30:"Checking field workers'' health";i:3;s:29:"Filtering water for injection";}','Screening of reservoirs based on EOR suitability criteria','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000586','Manakah pernyataan yang benar mengenai masa depan teknologi EOR?','multi','PFC000000012','Final Test','a:4:{i:0;s:46:"Integrasi dengan teknologi digitalisasi dan AI";i:1;s:42:"Fokus pada pengurangan emisi karbon (CCUS)";i:2;s:41:"Penghentian total penggunaan metode kimia";i:3;s:39:"Peningkatan efisiensi biaya operasional";}','','a:3:{i:0;s:46:"Integrasi dengan teknologi digitalisasi dan AI";i:1;s:42:"Fokus pada pengurangan emisi karbon (CCUS)";i:2;s:39:"Peningkatan efisiensi biaya operasional";}','Which statements are correct regarding the future of EOR technology?','a:4:{i:0;s:51:"Integration with digitalization and AI technologies";i:1;s:41:"Focus on carbon emission reduction (CCUS)";i:2;s:40:"Total cessation of chemical method usage";i:3;s:42:"Improvement of operational cost efficiency";}','a:3:{i:0;s:51:"Integration with digitalization and AI technologies";i:1;s:41:"Focus on carbon emission reduction (CCUS)";i:2;s:42:"Improvement of operational cost efficiency";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000587','Apa dampak negatif dari ''breakthrough'' fluida injeksi pada sumur produksi?','option','PFC000000012','Final Test','a:4:{i:0;s:45:"Penurunan efisiensi sapuan (sweep efficiency)";i:1;s:29:"Peningkatan tekanan reservoir";i:2;s:27:"Penurunan viskositas minyak";i:3;s:33:"Peningkatan permeabilitas relatif";}','','Penurunan efisiensi sapuan (sweep efficiency)','What is the negative impact of injection fluid ''breakthrough'' at the production well?','a:4:{i:0;s:29:"Reduction in sweep efficiency";i:1;s:30:"Increase in reservoir pressure";i:2;s:25:"Decrease in oil viscosity";i:3;s:33:"Increase in relative permeability";}','Reduction in sweep efficiency','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000588','Dalam evaluasi ekonomi, apa arti dari Discounted Cash Flow (DCF)?','option','PFC000000012','Final Test','a:4:{i:0;s:51:"Nilai uang masa depan yang disesuaikan ke masa kini";i:1;s:40:"Total pendapatan sebelum dikurangi pajak";i:2;s:34:"Jumlah minyak yang akan diproduksi";i:3;s:23:"Biaya modal awal proyek";}','','Nilai uang masa depan yang disesuaikan ke masa kini','In economic evaluation, what is the meaning of Discounted Cash Flow (DCF)?','a:4:{i:0;s:45:"Future value of money adjusted to the present";i:1;s:26:"Total revenue before taxes";i:2;s:28:"Amount of oil to be produced";i:3;s:35:"Initial project capital expenditure";}','Future value of money adjusted to the present','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000589','Mengapa penentuan heterogenitas reservoir sangat krusial dalam perencanaan EOR?','option','PFC000000012','Final Test','a:4:{i:0;s:52:"Karena mempengaruhi pola aliran dan efisiensi sapuan";i:1;s:47:"Untuk menentukan jumlah pekerja yang dibutuhkan";i:2;s:34:"Untuk menghitung harga jual minyak";i:3;s:42:"Untuk memprediksi cuaca di lokasi lapangan";}','','Karena mempengaruhi pola aliran dan efisiensi sapuan','Why is the determination of reservoir heterogeneity crucial in EOR planning?','a:4:{i:0;s:53:"Because it affects flow patterns and sweep efficiency";i:1;s:41:"To determine the number of workers needed";i:2;s:34:"To calculate the oil selling price";i:3;s:36:"To predict weather at the field site";}','Because it affects flow patterns and sweep efficiency','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000590','Apa tanggung jawab utama tim HSE dalam proyek EOR yang menggunakan bahan kimia berbahaya?','option','PFC000000012','Final Test','a:4:{i:0;s:52:"Memastikan prosedur penanganan dan mitigasi tumpahan";i:1;s:39:"Menghitung keuntungan harian perusahaan";i:2;s:33:"Meningkatkan laju produksi minyak";i:3;s:34:"Mempercepat pengiriman bahan kimia";}','','Memastikan prosedur penanganan dan mitigasi tumpahan','What is the main responsibility of the HSE team in EOR projects using hazardous chemicals?','a:4:{i:0;s:49:"Ensuring handling procedures and spill mitigation";i:1;s:33:"Calculating daily company profits";i:2;s:31:"Increasing oil production rates";i:3;s:29:"Expediting chemical shipments";}','Ensuring handling procedures and spill mitigation','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000591','Manakah yang merupakan tantangan utama dalam transisi dari pilot EOR ke skala penuh?','option','PFC000000012','Final Test','a:4:{i:0;s:45:"Skalabilitas fasilitas permukaan dan logistik";i:1;s:25:"Ketersediaan data geologi";i:2;s:24:"Kurangnya minat investor";i:3;s:25:"Penurunan harga teknologi";}','','Skalabilitas fasilitas permukaan dan logistik','Which is the main challenge in transitioning from an EOR pilot to full-field scale?','a:4:{i:0;s:47:"Scalability of surface facilities and logistics";i:1;s:31:"Availability of geological data";i:2;s:25:"Lack of investor interest";i:3;s:29:"Decrease in technology prices";}','Scalability of surface facilities and logistics','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000592','Apa yang dimaksud dengan ''sensitivity analysis'' dalam evaluasi ekonomi EOR?','option','PFC000000012','Final Test','a:4:{i:0;s:54:"Menguji pengaruh perubahan variabel input terhadap NPV";i:1;s:37:"Mengukur tingkat kebahagiaan karyawan";i:2;s:31:"Analisis komposisi kimia minyak";i:3;s:34:"Uji ketahanan alat di laboratorium";}','','Menguji pengaruh perubahan variabel input terhadap NPV','What is meant by ''sensitivity analysis'' in EOR economic evaluation?','a:4:{i:0;s:51:"Testing the impact of input variable changes on NPV";i:1;s:34:"Measuring employee happiness level";i:2;s:36:"Analysis of oil chemical composition";i:3;s:36:"Laboratory equipment durability test";}','Testing the impact of input variable changes on NPV','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000593','Faktor apa yang dapat membatalkan keberhasilan proyek EOR secara teknis?','multi','PFC000000012','Final Test','a:4:{i:0;s:48:"Ketidakmampuan menjaga viskositas fluida injeksi";i:1;s:51:"Adanya jalur aliran pintas (channelling) yang parah";i:2;s:27:"Kenaikan harga minyak dunia";i:3;s:29:"Kesalahan desain pola injeksi";}','','a:3:{i:0;s:48:"Ketidakmampuan menjaga viskositas fluida injeksi";i:1;s:51:"Adanya jalur aliran pintas (channelling) yang parah";i:2;s:29:"Kesalahan desain pola injeksi";}','Which factors can technically invalidate the success of an EOR project?','a:4:{i:0;s:47:"Inability to maintain injection fluid viscosity";i:1;s:34:"Presence of severe flow channeling";i:2;s:24:"Rise in world oil prices";i:3;s:31:"Injection pattern design errors";}','a:3:{i:0;s:47:"Inability to maintain injection fluid viscosity";i:1;s:34:"Presence of severe flow channeling";i:2;s:31:"Injection pattern design errors";}','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000594','Dalam perencanaan EOR, apa kegunaan utama dari simulasi reservoir?','option','PFC000000012','Final Test','a:4:{i:0;s:53:"Memprediksi performa reservoir dan optimasi perolehan";i:1;s:53:"Mengukur kedalaman sumurusi administrasi kantor pusat";i:2;s:34:"Mempromosikan perusahaan ke publik";i:3;s:24:"Mengganti peran geologis";}','','Memprediksi performa reservoir dan optimasi perolehan','In EOR planning, what is the primary use of reservoir simulation?','a:4:{i:0;s:58:"Predicting reservoir performance and recovery optimization";i:1;s:35:"Handling head office administration";i:2;s:35:"Promoting the company to the public";i:3;s:30:"Replacing the geologist''s role";}','Predicting reservoir performance and recovery optimization','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000595','Apa yang dimaksud dengan *CapEx* dalam anggaran proyek EOR?','option','PFC000000012','Final Test','a:4:{i:0;s:41:"Biaya modal untuk fasilitas dan peralatan";i:1;s:24:"Biaya operasional harian";i:2;s:28:"Pajak penghasilan perusahaan";i:3;s:22:"Biaya perjalanan dinas";}','','Biaya modal untuk fasilitas dan peralatan','What is meant by *CapEx* in EOR project budgets?','a:4:{i:0;s:48:"Capital expenditure for facilities and equipment";i:1;s:24:"Daily operating expenses";i:2;s:20:"Corporate income tax";i:3;s:24:"Business travel expenses";}','Capital expenditure for facilities and equipment','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000596','Mengapa pemilihan metode EOR harus disesuaikan dengan karakteristik reservoir?','option','PFC000000012','Final Test','a:4:{i:0;s:57:"Karena setiap metode memiliki batasan teknis yang berbeda";i:1;s:50:"Agar terlihat lebih canggih di mata pemegang saham";i:2;s:39:"Karena aturan pemerintah selalu berubah";i:3;s:45:"Agar tidak perlu melakukan studi laboratorium";}','','Karena setiap metode memiliki batasan teknis yang berbeda','Why must the choice of EOR method be tailored to reservoir characteristics?','a:4:{i:0;s:55:"Because each method has different technical limitations";i:1;s:54:"To look more sophisticated in the eyes of shareholders";i:2;s:44:"Because government regulations always change";i:3;s:40:"So that no laboratory studies are needed";}','Because each method has different technical limitations','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000597','Apa risiko dari ''poor sweep efficiency'' dalam proyek EOR?','option','PFC000000012','Final Test','a:4:{i:0;s:42:"Banyak minyak yang tertinggal di reservoir";i:1;s:33:"Produksi air yang terlalu sedikit";i:2;s:40:"Tekanan reservoir menjadi terlalu tinggi";i:3;s:25:"Kerusakan mesin kompresor";}','','Banyak minyak yang tertinggal di reservoir','What is the risk of ''poor sweep efficiency'' in an EOR project?','a:4:{i:0;s:44:"A lot of oil is left behind in the reservoir";i:1;s:27:"Too little water production";i:2;s:35:"Reservoir pressure becomes too high";i:3;s:25:"Compressor machine damage";}','A lot of oil is left behind in the reservoir','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000598','Mengapa keterlibatan pemangku kepentingan (stakeholders) penting dalam proyek EOR?','option','PFC000000012','Final Test','a:4:{i:0;s:46:"Untuk memastikan dukungan sosial dan perizinan";i:1;s:41:"Untuk menambah jumlah teknisi di lapangan";i:2;s:38:"Untuk mengurangi biaya produksi minyak";i:3;s:34:"Untuk mengubah hukum termodinamika";}','','Untuk memastikan dukungan sosial dan perizinan','Why is stakeholder involvement important in EOR projects?','a:4:{i:0;s:36:"To ensure social support and permits";i:1;s:50:"To increase the number of technicians in the field";i:2;s:30:"To reduce oil production costs";i:3;s:36:"To change the laws of thermodynamics";}','To ensure social support and permits','2026-09-23 02:08:17','2026-09-23 02:08:17');
INSERT INTO final_exam(id, question, type, lid, excerpt, options, image, correct_option, question_en, options_en, correct_option_en, created, updated) VALUES ('FQT00000000009200000599','Apa peran data laboratorium dalam tahap perencanaan EOR?','option','PFC000000012','Final Test','a:4:{i:0;s:32:"Validasi interaksi fluida-batuan";i:1;s:31:"Menggantikan kebutuhan simulasi";i:2;s:28:"Mengurangi harga jual minyak";i:3;s:33:"Menentukan lokasi kantor lapangan";}','','Validasi interaksi fluida-batuan','What is the role of laboratory data in the EOR planning phase?','a:4:{i:0;s:37:"Validation of fluid-rock interactions";i:1;s:33:"Replacing the need for simulation";i:2;s:26:"Reducing oil selling price";i:3;s:34:"Determining field office locations";}','Validation of fluid-rock interactions','2026-09-23 02:08:17','2026-09-23 02:08:17');
